//  Relative time helper 
function _relativeAge(iso) {
  if (!iso) return "";
  const diff = (Date.now() - new Date(iso)) / 1000;
  if (diff < 60)    return "just now";
  if (diff < 3600)  return `${Math.round(diff/60)}m ago`;
  if (diff < 86400) return `${Math.round(diff/3600)}h ago`;
  return `${Math.round(diff/86400)}d ago`;
}

//  API data-load functions 
async function apiLoadBasins() {
  try {
    const data = await apiFetch("/api/basins?limit=500");
    return data.items.map(normaliseBasin);
  } catch (e) {
    console.warn("apiLoadBasins failed — using seed data:", e.message);
    return null;
  }
}

async function apiLoadAnalogues() {
  try {
    const data = await apiFetch("/api/analogues/search?limit=500");
    return data.results.map(normaliseAnalogue);
  } catch (e) {
    console.warn("apiLoadAnalogues failed — using seed data:", e.message);
    return null;
  }
}

async function apiLoadProspects() {
  try {
    // Prospects come from multiple basins — load top 50
    const data = await apiFetch("/api/basins?limit=500");
    const prospects = [];
    for (const basin of (data.items || []).slice(0, 10)) {
      try {
        const p = await apiFetch(`/api/basins/${basin.id}/wpc/prospect`);
        (p.records || []).forEach(r => prospects.push(normaliseProspect({
          ...r, basin_name: basin.name
        })));
      } catch (_) {}
    }
    return prospects.length ? prospects : null;
  } catch (e) {
    return null;
  }
}

async function apiLoadIngestedFiles() {
  try {
    const data = await apiFetch("/api/ingest/files?limit=100");
    return data.map(normaliseIngestedFile);
  } catch (e) {
    console.warn("apiLoadIngestedFiles failed:", e.message);
    return [];
  }
}

async function apiLoadGovQueue() {
  try {
    const data = await apiFetch("/api/ingest/gov-queue?status=open&limit=100");
    return data.map(normaliseGovItem);
  } catch (e) {
    console.warn("apiLoadGovQueue failed:", e.message);
    return [];
  }
}

async function apiLoadAuditLog() {
  try {
    const data = await apiFetch("/api/governance/audit-log?limit=100");
    return data.map(normaliseAuditEntry);
  } catch (e) {
    console.warn("apiLoadAuditLog failed:", e.message);
    return null;
  }
}

async function apiLoadConnectors() {
  try {
    const data = await apiFetch("/api/connectors");
    return data.map(normaliseConnector);
  } catch (e) {
    console.warn("apiLoadConnectors failed:", e.message);
    return null;
  }
}

async function apiLoadDedupQueue() {
  try {
    const data = await apiFetch("/api/ingest/gov-queue?status=open");
    // Dedup items returned in gov-queue when flag contains "duplicate"
    return data
      .filter(g => g.flag?.toLowerCase().includes("duplicate"))
      .map(normaliseDedupItem);
  } catch (e) {
    return null;
  }
}

//  API write helpers (replace in-memory mutations) 
async function apiPublishFile(fileId) {
  return apiFetch(`/api/ingest/files/${fileId}/publish`, { method: "POST" });
}

async function apiRejectFile(fileId) {
  return apiFetch(`/api/ingest/files/${fileId}/reject`, { method: "POST" });
}

async function apiResolveGovItem(itemId, action) {
  return apiFetch(`/api/ingest/gov-queue/${itemId}/resolve?action=${action}`, { method: "POST" });
}

async function apiTriggerSync(connectorKey) {
  return apiFetch(`/api/connectors/${connectorKey}/sync`, { method: "POST" });
}

async function apiSaveConnectorConfig(key, credentials, freq, schedEnabled) {
  return apiFetch(`/api/connectors/${key}/config`, {
    method: "PUT",
    body: JSON.stringify({ credentials, freq, sched_enabled: schedEnabled }),
  });
}

async function apiUploadFile(file, datasetType) {
  const formData = new FormData();
  formData.append("file", file);
  if (datasetType) formData.append("dataset_type", datasetType);
  const res = await fetch(EDAFY_API_BASE + "/api/ingest/upload", {
    method: "POST",
    body: formData,
  });
  if (!res.ok) throw new Error(`Upload failed: HTTP ${res.status}`);
  return res.json();
}

async function apiRefreshGovQueue() {
  const [files, govItems] = await Promise.all([
    apiLoadIngestedFiles(),
    apiLoadGovQueue(),
  ]);
  INGESTED_FILES.length = 0;
  INGESTED_FILES.push(...files);
  // Merge backend gov items then rebuild quality-derived items on top
  GOV_QUEUE.length = 0;
  GOV_QUEUE.push(...govItems);
  _refreshGovQueue();
}

async function apiRefreshAuditLog() {
  const entries = await apiLoadAuditLog();
  if (entries) {
    AUDIT_ENTRIES.length = 0;
    AUDIT_ENTRIES.push(...entries);
    renderAuditLog(AUDIT_ENTRIES);
  }
}

//  Backend status indicator in sidebar 
function _renderApiStatus(online) {
  const dot  = document.getElementById("api-status-dot");
  const text = document.getElementById("api-status-text");
  if (dot)  dot.style.background = online ? "#2db774" : "#f0a500";
  if (text) text.textContent = online
    ? `OK ${EDAFY_API_BASE.replace("http://","").replace("https://","")}`
    : "Backend offline";
  const bar = document.getElementById("api-status-bar");
  if (bar) bar.title = online
    ? `Connected: ${EDAFY_API_BASE}`
    : "Backend offline — running on seed data";
  // Show/hide user pill based on auth state
  const pill = document.getElementById("elp-user-pill");
  if (pill) pill.style.display = online ? "flex" : "none";
  // If going offline (sign out) remove the pill entirely so it rebuilds fresh on next login
  if (!online && pill) pill.remove();
}

