// GOV_QUEUE is computed dynamically from real data quality checks.
// Populated by _buildGovQueue() which scans BASINS, ANALOGUES, WELLS,
// PETROLEUM_SYSTEMS and DISCOVERIES for actual data quality issues.
let GOV_QUEUE = [];

function _buildGovQueue() {
  const issues = [];
  let seq = 1;

  // ── Basin checks ────────────────────────────────────────────────────
  BASINS.forEach(b => {
    if (!b.country || b.country === "") {
      issues.push({ id: `BAS-${String(seq++).padStart(5,"0")}`, dataset: `Basin: ${b.name}`,
        flag: "Missing mandatory: country field", flagType: "error", source: "Basin Catalogue", age: "now" });
    }
    if (!b.score || b.score === 0) {
      issues.push({ id: `BAS-${String(seq++).padStart(5,"0")}`, dataset: `Basin: ${b.name}`,
        flag: "Prospectivity score is zero — needs geologist review", flagType: "warn", source: "Basin Catalogue", age: "now" });
    }
    if (!b.region || b.region === "") {
      issues.push({ id: `BAS-${String(seq++).padStart(5,"0")}`, dataset: `Basin: ${b.name}`,
        flag: "Missing region classification", flagType: "warn", source: "Basin Catalogue", age: "now" });
    }
    if (!b.area || b.area === 0) {
      issues.push({ id: `BAS-${String(seq++).padStart(5,"0")}`, dataset: `Basin: ${b.name}`,
        flag: "Basin area (km²) not populated", flagType: "warn", source: "Basin Catalogue", age: "now" });
    }
  });

  // ── Analogue checks ─────────────────────────────────────────────────
  ANALOGUES.forEach(a => {
    if (!a.por || a.por === 0) {
      issues.push({ id: `ANA-${String(seq++).padStart(5,"0")}`, dataset: `Analogue: ${a.name}`,
        flag: "Missing porosity — analogue excluded from similarity scoring", flagType: "error", source: "Analogue Engine", age: "now" });
    }
    if (!a.depth || a.depth === 0) {
      issues.push({ id: `ANA-${String(seq++).padStart(5,"0")}`, dataset: `Analogue: ${a.name}`,
        flag: "Reservoir depth not populated", flagType: "warn", source: "Analogue Engine", age: "now" });
    }
    if (a.sim && a.sim > 95) {
      issues.push({ id: `ANA-${String(seq++).padStart(5,"0")}`, dataset: `Analogue: ${a.name}`,
        flag: `Near-duplicate — similarity ${a.sim}% exceeds 95% threshold`, flagType: "warn", source: "Analogue Engine", age: "now" });
    }
    if (a.geochem && (!a.geochem.toc || a.geochem.toc === 0)) {
      issues.push({ id: `ANA-${String(seq++).padStart(5,"0")}`, dataset: `Analogue: ${a.name}`,
        flag: "Missing mandatory: TOC% in geochemistry sub-record", flagType: "warn", source: "Analogue Engine", age: "now" });
    }
    if (a.geochem && (!a.geochem.ro_vitrinite || a.geochem.ro_vitrinite === 0)) {
      issues.push({ id: `ANA-${String(seq++).padStart(5,"0")}`, dataset: `Analogue: ${a.name}`,
        flag: "Missing mandatory: Ro% (vitrinite reflectance) field", flagType: "warn", source: "Analogue Engine", age: "now" });
    }
  });

  // ── Well checks ─────────────────────────────────────────────────────
  (WELLS||[]).forEach(w => {
    if (!w.lat || !w.lon) {
      issues.push({ id: `WEL-${String(seq++).padStart(5,"0")}`, dataset: `Well: ${w.name}`,
        flag: "Well location coordinates missing — cannot plot on map", flagType: "error", source: "Well Registry", age: "now" });
    }
    if (!w.tdM || w.tdM === 0) {
      issues.push({ id: `WEL-${String(seq++).padStart(5,"0")}`, dataset: `Well: ${w.name}`,
        flag: "Total depth (TD) not recorded", flagType: "warn", source: "Well Registry", age: "now" });
    }
    if (w.lat && w.lon) {
      // Check coord is plausible (not 0,0)
      if (Math.abs(w.lat) < 0.01 && Math.abs(w.lon) < 0.01) {
        issues.push({ id: `WEL-${String(seq++).padStart(5,"0")}`, dataset: `Well: ${w.name}`,
          flag: "Coordinate is 0°N 0°E — likely null island, needs review", flagType: "error", source: "Well Registry", age: "now" });
      }
    }
  });

  // ── Petroleum system checks ─────────────────────────────────────────
  (PETROLEUM_SYSTEMS||[]).forEach(ps => {
    if (!ps.tocPct || ps.tocPct === 0) {
      issues.push({ id: `PSY-${String(seq++).padStart(5,"0")}`, dataset: `PetSys: ${ps.name}`,
        flag: "Source rock TOC% not populated", flagType: "warn", source: "Petroleum Systems", age: "now" });
    }
    if (!ps.roPct || ps.roPct === 0) {
      issues.push({ id: `PSY-${String(seq++).padStart(5,"0")}`, dataset: `PetSys: ${ps.name}`,
        flag: "Ro% maturity indicator missing", flagType: "warn", source: "Petroleum Systems", age: "now" });
    }
    if (!ps.chargeRisk || ps.chargeRisk === 0) {
      issues.push({ id: `PSY-${String(seq++).padStart(5,"0")}`, dataset: `PetSys: ${ps.name}`,
        flag: "Charge risk probability not set", flagType: "warn", source: "Petroleum Systems", age: "now" });
    }
  });

  // ── Discovery checks ────────────────────────────────────────────────
  (DISCOVERIES||[]).forEach(d => {
    if (!d.eurMmboe || d.eurMmboe === 0) {
      issues.push({ id: `DIS-${String(seq++).padStart(5,"0")}`, dataset: `Discovery: ${d.name}`,
        flag: "EUR (recoverable resources) not estimated", flagType: "warn", source: "Discoveries", age: "now" });
    }
    if (d.hcType === "Oil" && (!d.stoiipMmbbl || d.stoiipMmbbl === 0)) {
      issues.push({ id: `DIS-${String(seq++).padStart(5,"0")}`, dataset: `Discovery: ${d.name}`,
        flag: "Oil discovery missing STOIIP estimate", flagType: "error", source: "Discoveries", age: "now" });
    }
    if (d.hcType === "Gas" && (!d.giipBcf || d.giipBcf === 0)) {
      issues.push({ id: `DIS-${String(seq++).padStart(5,"0")}`, dataset: `Discovery: ${d.name}`,
        flag: "Gas discovery missing GIIP estimate", flagType: "error", source: "Discoveries", age: "now" });
    }
  });

  // ── Cross-entity referential integrity ──────────────────────────────
  (PLAYS||[]).forEach(pl => {
    const hasPS = (PETROLEUM_SYSTEMS||[]).some(ps => ps.id === pl.petSysId);
    if (!hasPS && pl.petSysId) {
      issues.push({ id: `REF-${String(seq++).padStart(5,"0")}`, dataset: `Play: ${pl.name}`,
        flag: `Orphaned: petSysId "${pl.petSysId}" not found in Petroleum Systems`, flagType: "error", source: "Referential Integrity", age: "now" });
    }
  });
  (WELLS||[]).forEach(w => {
    const hasPlay = !w.playId || (PLAYS||[]).some(pl => pl.id === w.playId);
    if (!hasPlay) {
      issues.push({ id: `REF-${String(seq++).padStart(5,"0")}`, dataset: `Well: ${w.name}`,
        flag: `Orphaned: playId "${w.playId}" not found in Plays`, flagType: "error", source: "Referential Integrity", age: "now" });
    }
  });

  return issues;
}

// Build on first load; re-run after data mutations
function _refreshGovQueue() {
  const live = _buildGovQueue();
  GOV_QUEUE.length = 0;
  GOV_QUEUE.push(...live);
  if (typeof renderGovQueue === "function") renderGovQueue();
  if (typeof renderIngOverview === "function") renderIngOverview();
}

