// Recently ingested files awaiting governance approval
let INGESTED_FILES = [];

let AUDIT_ENTRIES = [];
function _buildAuditEntries() {
  const entries = [];
  const _ts = (offsetMin) => {
    const d = new Date(Date.now() - offsetMin * 60000);
    return d.toISOString().replace("T"," ").slice(0,16);
  };

  // System boot — always first
  entries.push({
    time:   _ts(0),
    user:   "SYS",
    action: `Platform initialised · ${BASINS.length} basins · ${ANALOGUES.length} analogues · ${(PETROLEUM_SYSTEMS||[]).length} petroleum systems loaded (offline seed)`,
    status: "SUCCESS",
    type:   "System",
  });

  // Data quality summary
  const govIssues = typeof _buildGovQueue === "function" ? _buildGovQueue() : [];
  const errors    = govIssues.filter(g => g.flagType === "error").length;
  const warns     = govIssues.filter(g => g.flagType === "warn").length;
  if (errors + warns > 0) {
    entries.push({
      time:   _ts(1),
      user:   "SYS-DQ",
      action: `Data quality scan complete · ${errors} errors · ${warns} warnings flagged for governance review`,
      status: errors > 0 ? "PARTIAL" : "SUCCESS",
      type:   "Governance",
    });
  } else if (BASINS.length > 0) {
    entries.push({
      time:   _ts(1),
      user:   "SYS-DQ",
      action: `Data quality scan complete · All ${BASINS.length} basins and ${ANALOGUES.length} analogues passed checks`,
      status: "SUCCESS",
      type:   "Governance",
    });
  }

  // Basin catalogue summary
  if (BASINS.length > 0) {
    const regions = [...new Set(BASINS.map(b => b.region).filter(Boolean))];
    const topBasin = BASINS.reduce((t,b) => b.score > (t.score||0) ? b : t, BASINS[0]);
    entries.push({
      time:   _ts(2),
      user:   "SYS",
      action: `Basin catalogue loaded · ${BASINS.length} basins across ${regions.length} regions · Top: ${topBasin.name} (score ${topBasin.score})`,
      status: "SUCCESS",
      type:   "Data Access",
    });
  }

  // Analogue engine
  if (ANALOGUES.length > 0) {
    const avgSim = (ANALOGUES.reduce((s,a) => s+(a.sim||0),0)/ANALOGUES.length).toFixed(0);
    entries.push({
      time:   _ts(3),
      user:   "SYS",
      action: `Analogue engine ready · ${ANALOGUES.length} reservoir intervals · avg similarity index ${avgSim}%`,
      status: "SUCCESS",
      type:   "Data Access",
    });
  }

  // Petroleum systems
  if ((PETROLEUM_SYSTEMS||[]).length > 0) {
    const proven = (PETROLEUM_SYSTEMS||[]).filter(p => p.status === "Proven").length;
    entries.push({
      time:   _ts(5),
      user:   "SYS",
      action: `Petroleum systems indexed · ${(PETROLEUM_SYSTEMS||[]).length} total · ${proven} proven`,
      status: "SUCCESS",
      type:   "System",
    });
  }

  // Wells and discoveries
  if ((WELLS||[]).length > 0) {
    const disc = (DISCOVERIES||[]).length;
    entries.push({
      time:   _ts(8),
      user:   "SYS",
      action: `Well registry loaded · ${(WELLS||[]).length} wells · ${disc} discovery records`,
      status: "SUCCESS",
      type:   "Data Access",
    });
  }

  // KG edges
  if ((KG_EDGES||[]).length > 0) {
    entries.push({
      time:   _ts(10),
      user:   "SYS-KG",
      action: `Knowledge graph built · ${(KG_EDGES||[]).length} ontology edges across ${[...new Set((KG_EDGES||[]).map(e=>e.srcType))].length} entity types`,
      status: "SUCCESS",
      type:   "System",
    });
  }

  return entries;
}

