// CONNECTORS — live view derived from CONNECTOR_STATE (no static copy)
// Legacy callers that use CONNECTORS[i].last, .status, .color are served
// the same live data that _hydrateConnectorState() maintains.
const CONNECTORS = new Proxy([], {
  get(_, prop) {
    if (prop === 'length') return CONNECTOR_STATE.length;
    if (typeof prop === 'string' && !isNaN(prop)) {
      const c = CONNECTOR_STATE[+prop];
      if (!c) return undefined;
      const statusMap = { connected:"LIVE", error:"AUTH ERROR", pending:"PENDING", not_configured:"NOT CONFIGURED" };
      return { name: c.name, status: statusMap[c.status] || c.status, color: c.color || "var(--t3)", last: c.lastSync || "—" };
    }
    return [][prop];
  }
});
// MAP_BASINS — derived live from the BASINS array (no static copy)
// Access via getMapBasin(name) instead of MAP_BASINS[key]
function getMapBasin(name) {
  return (typeof BASINS !== "undefined") ? BASINS.find(b => b.name === name) || null : null;
}

// ACTIVITIES — built dynamically from real data state
function _buildActivities() {
  const acts = [];
  const _ago = (min) => {
    if (min < 60)   return `${min}m ago`;
    if (min < 1440) return `${Math.floor(min/60)}h ago`;
    return `${Math.floor(min/1440)}d ago`;
  };

  // Basin load
  if ((typeof BASINS !== "undefined") && BASINS.length) {
    const regions = [...new Set(BASINS.map(b=>b.region).filter(Boolean))].length;
    acts.push({ dot:"var(--cyan)",
      text: `Basin catalogue active — <strong>${BASINS.length} basins</strong> across ${regions} regions`,
      time: `${_ago(0)} · System` });
  }

  // Analogue engine
  if ((typeof ANALOGUES !== "undefined") && ANALOGUES.length) {
    const avgSim = (ANALOGUES.reduce((s,a)=>s+(a.sim||0),0)/ANALOGUES.length).toFixed(0);
    acts.push({ dot:"var(--green)",
      text: `Analogue engine ready — <strong>${ANALOGUES.length} intervals</strong> · avg similarity ${avgSim}%`,
      time: `${_ago(1)} · Analogue Engine` });
  }

  // Top screening candidate
  if ((typeof BASINS !== "undefined") && BASINS.length) {
    const top = [...BASINS].sort((a,b)=>b.score-a.score)[0];
    if (top) acts.push({ dot:"var(--green)",
      text: `Top prospectivity: <strong>${top.name}</strong> (${top.country||top.region}) — Score ${top.score}`,
      time: `${_ago(2)} · Screening` });
  }

  // Governance issues
  if ((typeof GOV_QUEUE !== "undefined") && GOV_QUEUE.length) {
    const errs = GOV_QUEUE.filter(g=>g.flagType==="error").length;
    const warns= GOV_QUEUE.filter(g=>g.flagType==="warn").length;
    acts.push({ dot: errs>0?"var(--red)":"var(--amber)",
      text: `<strong>${errs} errors · ${warns} warnings</strong> in governance queue — review needed`,
      time: `${_ago(3)} · Data QC` });
  }

  // KG connectivity
  if ((typeof KG_EDGES !== "undefined") && KG_EDGES.length) {
    const types = [...new Set(KG_EDGES.map(e=>e.srcType))].length;
    acts.push({ dot:"var(--cyan)",
      text: `Knowledge graph: <strong>${KG_EDGES.length} edges</strong> across ${types} entity types`,
      time: `${_ago(5)} · KG Engine` });
  }

  // Discoveries
  if ((typeof DISCOVERIES !== "undefined") && DISCOVERIES.length) {
    const producing = (DISCOVERIES||[]).filter(d=>d.fieldStatus==="Producing").length;
    acts.push({ dot:"var(--green)",
      text: `<strong>${DISCOVERIES.length} discovery records</strong> · ${producing} producing fields`,
      time: `${_ago(8)} · System` });
  }

  return acts;
}

