// ═══════════════════════════════════════════════════════════════════════
//  PHYSICAL CONSTANTS & DATA-READER HELPERS
//
//  These replace the old static config store entirely.
//  Physical conversion factors are immutable SI standards.
//  All other "defaults" are read live from whatever the user has
//  entered in the module inputs — no separate config store.
// ═══════════════════════════════════════════════════════════════════════

// ── Immutable physical conversion factors ─────────────────────────────
const BBL_PER_M3     = 6.2898e-6;   // MMstb per m³  (oil/condensate)
const SCF_PER_M3     = 35.3147e-6;  // Bcf  per m³   (gas)

// ── P10/P90 lognormal spread approximations ───────────────────────────
// Industry-standard lognormal ratios for single-prospect resource ranges.
// These are physical/statistical constants, not user configuration.
const P10_OF_P50     = 0.37;   // low case  = P50 × 0.37
const P90_OF_P50     = 2.38;   // high case = P50 × 2.38
const BASIN_P10      = 0.40;   // basin aggregation low proxy
const BASIN_P90      = 2.20;   // basin aggregation high proxy

// ── Newton breakeven solver step damper ───────────────────────────────
const BREAKEVEN_DAMPER = 0.5;

// ── Regional country-risk GCoS defaults ──────────────────────────────
// Used by basin screening engine. Values are risk multipliers (0–1).
// These are geopolitical assessments, not user configuration.
const REGIONAL_GCOS = {
  "North America":  0.95,
  "Europe":         0.92,
  "Australasia":    0.90,
  "Southeast Asia": 0.82,
  "South America":  0.78,
  "Middle East":    0.75,
  "North Africa":   0.68,
  "West Africa":    0.65,
  "Arctic":         0.60,
};

// ── Read volumetric defaults from live module inputs ──────────────────
// Returns the values currently entered in vi-* / vol-* inputs.
// Falls back to sensible geological defaults if inputs are not yet rendered.
function _getVolDefaults(hcType) {
  const isGas = (hcType || 'oil').toLowerCase() === 'gas';
  const gv = (ids) => {
    for (const id of ids) {
      const el = document.getElementById(id);
      if (el && parseFloat(el.value) > 0) return parseFloat(el.value);
    }
    return null;
  };
  return {
    grv: gv(['vi-grv','vol-grv']) || (isGas ? 800  : 500),
    ntg: gv(['vi-ntg','vol-ntg']) || (isGas ? 0.70 : 0.65),
    por: gv(['vi-phi','vol-por']) || (isGas ? 0.18 : 0.22),
    sw:  gv(['vi-sw', 'vol-sw'])  || (isGas ? 0.20 : 0.25),
    fvf: gv(['vi-bo', 'vol-fvf']) || (isGas ? 0.004: 1.25),
    rf:  gv(['vi-rf', 'vol-rf'])  || (isGas ? 0.70 : 0.35),
  };
}

// ── Read Monte Carlo parameters from live mc-* inputs ─────────────────
function _getMCParams() {
  const gv = (id, def) => { const e = document.getElementById(id); return (e && parseFloat(e.value) > 0) ? parseFloat(e.value) : def; };
  const ntgP50 = gv('mc-ntg-p50', 0.55);
  const rfP50  = gv('mc-rf-p50',  0.35);
  return {
    grv: { lo: 0.60, hi: 1.50 },
    ntg: { lo: +(ntgP50 * 0.70).toFixed(3), hi: +(ntgP50 * 1.30).toFixed(3), min: 0.15, max: 0.95 },
    phi: { std: 0.035, min: 0.05, max: 0.40 },
    rf:  { lo: +(rfP50  * 0.65).toFixed(3), hi: +(rfP50  * 1.45).toFixed(3), min: 0.05, max: 0.75 },
    sw:  { std: 0.06,  min: 0.10, max: 0.65 },
    bo:  { std: 0.05,  min: 1.05, max: 2.50 },
    simpleGRV: { lo: 0.60, hi: 1.50 },
  };
}

// ── Read economics defaults from live econ-* inputs ───────────────────
function _getEconDefaults() {
  const gv = (id, def) => { const e = document.getElementById(id); const v = parseFloat(e?.value); return (!isNaN(v) && v > 0) ? v : def; };
  return {
    price:    gv('econ-price',    75),
    opex:     gv('econ-opex',     12),
    discount: gv('econ-discount', 10),
    royalty:  gv('econ-royalty',  12.5),
    tax:      gv('econ-tax',      30),
    rf:       gv('econ-rf',       35),
    volume:   gv('econ-volume',   150),
    capex:    gv('econ-capex',    450),
    years:    gv('econ-years',    20),
    decline:  gv('econ-decline',  8),
    buildup:  gv('econ-buildup',  3),
    plateau:  gv('econ-plateau',  25),
    govtake:  gv('econ-govtake',  45),
    abandon:  gv('econ-abandon',  45),
    sustcapex:gv('econ-sustcapex',15),
    BREAKEVEN_STEP_DAMPER: BREAKEVEN_DAMPER,
  };
}

