// INIT
// ============================================================
//  Post-ingestion API sync (called after every local ingest) 
async function _postIngestSync(fileName, detectedType, rawData) {
  if (!_backendOnline || !rawData) return;
  try {
    // Re-encode the parsed data as a virtual CSV for the backend pipeline
    const keys = Object.keys(rawData[0] || {});
    const csv = [
      keys.join(","),
      ...rawData.map(row =>
        keys.map(k => JSON.stringify(row[k] ?? "")).join(",")
      )
    ].join("\n");
    const blob = new Blob([csv], { type: "text/csv" });
    const file = new File([blob], fileName, { type: "text/csv" });
    const result = await apiUploadFile(file, detectedType);
    if (result.gov_flags > 0 || result.dedup_candidates > 0) {
      toast(`Backend: ${result.valid_rows} valid · ${result.gov_flags} flags · ${result.dedup_candidates} dupes`, "info");
    }
    // Refresh governance views from backend
    setTimeout(() => {
      apiRefreshGovQueue();
      apiRefreshAuditLog();
    }, 500);
  } catch (e) {
    console.warn("Backend sync after upload failed:", e.message);
  }
}

//  _elpBootstrapData: called after successful login OR on page load
//    if a valid token is already stored in sessionStorage 
async function _elpBootstrapData() {
  const loadingEl = document.createElement("div");
  loadingEl.id = "api-loading-banner";
  loadingEl.style.cssText = "position:fixed;top:0;left:0;right:0;z-index:9999;background:var(--bg3,#1a2332);color:var(--t2,#8896a5);font-size:11px;padding:6px 16px;text-align:center;border-bottom:1px solid var(--bdr,#243448)";
  loadingEl.textContent = " Loading basin data…";
  document.body.appendChild(loadingEl);

  try {
    const [apiBasins, apiAnalogues, apiConnectors, apiAudit, apiFiles, apiGovItems] =
      await Promise.allSettled([
        apiLoadBasins(),
        apiLoadAnalogues(),
        apiLoadConnectors(),
        apiLoadAuditLog(),
        apiLoadIngestedFiles(),
        apiLoadGovQueue(),
      ]);

    if (apiBasins.value) {
      BASINS.length = 0;
      BASINS.push(...apiBasins.value);
      _backendOnline = true;
    }
    if (apiAnalogues.value) {
      ANALOGUES.length = 0;
      ANALOGUES.push(...apiAnalogues.value);
    }
    if (apiConnectors.value) {
      CONNECTOR_STATE.length = 0;
      CONNECTOR_STATE.push(...apiConnectors.value);
    }
    // Always re-hydrate from localStorage after backend update —
    // localStorage credentials/timestamps take precedence over backend seed values
    if (typeof _hydrateConnectorState === "function") _hydrateConnectorState();
    if (apiAudit.value) {
      AUDIT_ENTRIES.length = 0;
      AUDIT_ENTRIES.push(...apiAudit.value);
    } else {
      // Backend offline — rebuild audit from real data state
      const fresh = _buildAuditEntries();
      AUDIT_ENTRIES.length = 0;
      AUDIT_ENTRIES.push(...fresh);
    }
    if (apiFiles.value?.length) {
      INGESTED_FILES.length = 0;
      INGESTED_FILES.push(...apiFiles.value);
    }
    if (apiGovItems.value?.length) {
      GOV_QUEUE.length = 0;
      GOV_QUEUE.push(...apiGovItems.value);
    }

    loadingEl.style.background = _backendOnline ? "rgba(45,183,116,.15)" : "rgba(255,165,0,.1)";
    loadingEl.style.color = _backendOnline ? "var(--green,#2db774)" : "var(--amber,#f0a500)";
    loadingEl.textContent = _backendOnline
      ? `OK Backend connected — ${BASINS.length} basins, ${ANALOGUES.length} analogues loaded`
      : `! Backend offline — running on seed data (${BASINS.length} basins)`;
    setTimeout(() => loadingEl.remove(), 3500);
  } catch (e) {
    loadingEl.textContent = `! Backend offline — running on seed data`;
    loadingEl.style.color = "var(--amber,#f0a500)";
    setTimeout(() => loadingEl.remove(), 3000);
  }

  _renderApiStatus(_backendOnline);
  // Re-render tables/charts with live backend data
  renderBasinTable(BASINS);
  if (ANALOGUES.length) renderActivity();
  renderTopBasins();
  refreshPortfolioKPIs();
  if (typeof renderConnectorCards === "function") renderConnectorCards();
  // Rebuild governance queue from live data quality checks
  _refreshGovQueue();
  // Rebuild activities feed from live data
  const freshActs = _buildActivities();
  ACTIVITIES.length = 0;
  ACTIVITIES.push(...freshActs);
  // Rebuild notifications from live data
  if (typeof _buildNotifications === "function") {
    const freshNotifs = _buildNotifications();
    notifications.length = 0;
    notifications.push(...freshNotifs);
    if (typeof updateNotifBadge === "function") updateNotifBadge();
  }
}

//  New window.onload: auth-first 
window.onload = async () => {
  // Export data for hub (cross-script access)
  window.BASINS=BASINS; window.PETROLEUM_SYSTEMS=PETROLEUM_SYSTEMS;
  window.PLAYS=PLAYS; window.WELLS=WELLS; window.DISCOVERIES=DISCOVERIES;
  window.KG_EDGES=KG_EDGES; window.PROSPECTS=PROSPECTS;

  // Always render UI immediately with seed data.
  // Wrapped in try/catch so any render error cannot prevent the login page appearing.
  try {
    _renderApiStatus(false);
    animateCounters();
    renderActivity();
    renderTopBasins();
    renderDQSummary();
    renderResourceDistChart();
    refreshPortfolioKPIs();
    renderBasinTable(BASINS);
    populateProspectDropdown();
    renderGCoS();
    _refreshGovQueue();
    setupMap();
  } catch(e) {
    console.warn('[EDAFY] Initial render error (non-fatal):', e);
  }

  // Initialise Economics unit labels to match default HC type (Oil)
  setTimeout(() => { if (typeof updateEconHCType === 'function') updateEconHCType(); }, 300);

  // Handle URL hash or default to portfolio
  const initHash = location.hash.replace("#", "");
  if (initHash && document.getElementById("sec-" + initHash)) {
    goTo(initHash, null);
  } else {
    // Default: activate portfolio and Strategy nav-group
    goTo('portfolio', null);
  }

  // Check backend health (for the status badge on the login page)
  try { elpCheckBackend(); } catch(e) {}

  // If a valid token is already in sessionStorage, skip the login page
  // and go straight to loading live data
  const existingToken = elpGetToken();
  if (existingToken) {
    // Verify token is still valid
    try {
      const res = await fetch(EDAFY_API_BASE + "/api/auth/me", {
        headers: { Authorization: "Bearer " + existingToken },
        signal: AbortSignal.timeout(5000),
      });
      if (res.ok) {
        const user = await res.json();
        elpSetUser(user);
        elpRenderUserBadge(user);
        elpHide();
        _backendOnline = true;
        _renderApiStatus(true);
        await _elpBootstrapData();
        return;
      } else {
        elpClearToken();  // token expired
      }
    } catch {
      elpClearToken();    // network error — fall through to login page
    }
  }

  // No valid token — show the login page
  elpShow();
};

// Hard fallback: if login page is still showing after 4s (onload threw before elpShow),
// force-show it so the user is never stuck on a blank screen.
setTimeout(function() {
  const lp = document.getElementById('edafy-login-page');
  if (lp && !lp.classList.contains('hidden')) {
    // Already visible — nothing to do
  } else if (lp && lp.classList.contains('hidden')) {
    // Already dismissed by successful login/offline — nothing to do
  } else if (lp) {
    lp.classList.remove('hidden');
  }
}, 4000);

// ============================================================
// LIVE DATA TICKER
// Runs every 30 s to keep KPIs, governance queue, and map
// markers in sync with whatever data is currently loaded.
// Also detects changes in BASINS/ANALOGUES length so the UI
// responds immediately when records are added or removed.
// ============================================================
(function _startLiveTicker() {
  let _prevBasinCount    = -1;
  let _prevAnalogueCount = -1;
  let _prevGovCount      = -1;

  function _tick() {
    const bc = (typeof BASINS    !== "undefined") ? BASINS.length    : 0;
    const ac = (typeof ANALOGUES !== "undefined") ? ANALOGUES.length : 0;

    const dataChanged = (bc !== _prevBasinCount) || (ac !== _prevAnalogueCount);
    _prevBasinCount    = bc;
    _prevAnalogueCount = ac;

    // KPIs — always refresh so bars animate smoothly
    if (typeof refreshPortfolioKPIs === "function") refreshPortfolioKPIs();

    // Governance queue — rebuild when data changes
    if (dataChanged && typeof _refreshGovQueue === "function") {
      _refreshGovQueue();
    }

    // Dedup queue — rebuild when data changes
    if (dataChanged && typeof _buildDedupQueue === "function") {
      const fresh = _buildDedupQueue();
      DEDUP_QUEUE.length = 0;
      DEDUP_QUEUE.push(...fresh);
      if (typeof renderDedupQueue === "function") renderDedupQueue();
    }

    // Notifications — rebuild when data changes
    if (dataChanged && typeof _buildNotifications === "function") {
      const freshNotifs = _buildNotifications();
      // Preserve user-added notifications (id is a Date.now() large number)
      const userNotifs = notifications.filter(n => n.id > 100);
      notifications.length = 0;
      notifications.push(...freshNotifs, ...userNotifs);
      if (typeof updateNotifBadge === "function") updateNotifBadge();
    }

    // Login-page basin counter — update while login page is visible
    const basinStatEl = document.getElementById("elp-stat-basins");
    if (basinStatEl && bc > 0) basinStatEl.textContent = bc + "+";

    // Re-export window globals so hub/KG modules always see latest
    if (typeof BASINS !== "undefined") {
      window.BASINS = BASINS;
      window.ANALOGUES = ANALOGUES;
      window.PLAYS = PLAYS;
      window.WELLS = WELLS;
      window.DISCOVERIES = DISCOVERIES;
      window.PETROLEUM_SYSTEMS = PETROLEUM_SYSTEMS;
    }

    // Update governance badge count in nav
    const govCount = (typeof GOV_QUEUE !== "undefined") ? GOV_QUEUE.length : 0;
    if (govCount !== _prevGovCount) {
      _prevGovCount = govCount;
      document.querySelectorAll(".gov-badge-count").forEach(el => {
        el.textContent = govCount;
        el.style.display = govCount > 0 ? "inline-flex" : "none";
      });
    }
  }

  // Run once immediately after load, then every 30 s
  setTimeout(_tick, 1500);
  setInterval(_tick, 30000);
})();

