// ═══════════════════════════════════════════════════════════════════════
// BASIN SCREENING SCORE (BSS) — COMPLETE ENGINE
// Basin-scoped formula builder, custom JS editor, save/load, apply
// ═══════════════════════════════════════════════════════════════════════

// ── Persistent basin-scoped stores ────────────────────────────────────
// Structure: { [basinKey]: { [vid]: state } }
// basinKey is "__global__" or basin name
let _bssCurrentBasin    = "__global__";
let _bssBasinState      = {};
let _bssBasinMode       = {};   // { [basinKey]: { [vid]: "builder"|"custom" } }
let _bssBasinSaved      = {};   // { [basinKey]: { [vid]: [{name,mode,state}] } }
let _bssBasinActiveVars = {};   // { [basinKey]: { [vid]: bool } }
let _bssActive          = false;

try { _bssBasinState      = JSON.parse(localStorage.getItem("bss_basin_state")  || "{}"); } catch(e){}
try { _bssBasinMode       = JSON.parse(localStorage.getItem("bss_basin_mode")   || "{}"); } catch(e){}
try { _bssBasinSaved      = JSON.parse(localStorage.getItem("bss_basin_saved")  || "{}"); } catch(e){}
try { _bssBasinActiveVars = JSON.parse(localStorage.getItem("bss_basin_active") || "{}"); } catch(e){}

// ── Low-level accessors ───────────────────────────────────────────────
function _bssKey() { return _bssCurrentBasin; }

function _bssGetState(vid) {
  const k = _bssKey();
  if (!_bssBasinState[k])      _bssBasinState[k] = {};
  if (!_bssBasinState[k][vid]) _bssInitVarStateFor(k, vid);
  return _bssBasinState[k][vid];
}
function _bssSetStateField(vid, field, val) {
  _bssGetState(vid)[field] = val;
  _bssPersist();
}
function _bssGetMode(vid) {
  return ((_bssBasinMode[_bssKey()] || {})[vid]) || "builder";
}
function _bssSetMode(vid, mode) {
  const k = _bssKey();
  if (!_bssBasinMode[k]) _bssBasinMode[k] = {};
  _bssBasinMode[k][vid] = mode;
  _bssPersist();
}
function _bssGetSaved(vid) {
  return ((_bssBasinSaved[_bssKey()] || {})[vid]) || [];
}
function _bssGetActive(vid) {
  return !!((_bssBasinActiveVars[_bssKey()] || {})[vid]);
}
function _bssSetActive(vid, val) {
  const k = _bssKey();
  if (!_bssBasinActiveVars[k]) _bssBasinActiveVars[k] = {};
  _bssBasinActiveVars[k][vid] = val;
  _bssActive = Object.values(_bssBasinActiveVars[k]).some(Boolean);
  _bssPersist();
}
function _bssPersist() {
  try { localStorage.setItem("bss_basin_state",  JSON.stringify(_bssBasinState));  } catch(e){}
  try { localStorage.setItem("bss_basin_mode",   JSON.stringify(_bssBasinMode));   } catch(e){}
  try { localStorage.setItem("bss_basin_saved",  JSON.stringify(_bssBasinSaved));  } catch(e){}
  try { localStorage.setItem("bss_basin_active", JSON.stringify(_bssBasinActiveVars)); } catch(e){}
}
function _bssInitVarStateFor(basinKey, vid) {
  const def = _bssVarDefs[vid];
  if (!def) return;
  if (!_bssBasinState[basinKey]) _bssBasinState[basinKey] = {};
  const equalWt = def.params ? Math.round(100 / def.params.length) : 0;
  const st = { fn:{}, weight:{}, val:{}, params:{}, customExpr:"" };
  if (def.params) def.params.forEach(p => {
    st.fn[p.id]     = p.inv ? "inv_linear" : "linear";
    st.weight[p.id] = equalWt;
    st.val[p.id]    = p.def;
    st.params[p.id] = {};
  });
  _bssBasinState[basinKey][vid] = st;
}

