// ── Init & basin switch ───────────────────────────────────────────────
function bssInit() {
  const sel = document.getElementById("bss-basin-select");
  if (sel) {
    // Populate if empty (first call)
    if (sel.options.length <= 1) {
      BASINS.forEach(b => {
        const opt = document.createElement("option");
        opt.value = b.name;
        opt.textContent = `${b.name}  —  ${b.country}  (${b.region})`;
        sel.appendChild(opt);
      });
    }
    sel.value = _bssCurrentBasin;
  }
  Object.keys(_bssVarDefs).forEach(vid => _bssGetState(vid));
  bssUpdateBasinInfo();
  bssRebuildAllPanels();
  bssBuildVarPanel("source");
}

function bssOnBasinChange(basinKey) {
  _bssCurrentBasin = basinKey;
  Object.keys(_bssVarDefs).forEach(vid => _bssGetState(vid));
  bssUpdateBasinInfo();
  bssRebuildAllPanels();
  bssBuildVarPanel("source");
  document.querySelectorAll("#bss-var-tabs .tab").forEach((t,i) => t.classList.toggle("on", i===0));
}

function switchBssTab(vid, el) {
  Object.keys(_bssVarDefs).forEach(v => {
    const p = document.getElementById("bss-var-" + v);
    if (p) p.style.display = v === vid ? "block" : "none";
  });
  if (el) {
    el.closest("#bss-var-tabs").querySelectorAll(".tab").forEach(t => t.classList.remove("on"));
    el.classList.add("on");
  }
  bssBuildVarPanel(vid);
}

function bssRebuildAllPanels() {
  Object.keys(_bssVarDefs).forEach(vid => {
    const cont = document.getElementById("bss-var-" + vid);
    if (cont) { cont._built = false; cont.innerHTML = ""; cont.style.display = "none"; }
  });
  const src = document.getElementById("bss-var-source");
  if (src) src.style.display = "block";
}

// ── Basin info bar ────────────────────────────────────────────────────
function bssUpdateBasinInfo() {
  const k       = _bssKey();
  const infoEl  = document.getElementById("bss-basin-info");
  const badgeEl = document.getElementById("bss-basin-formula-badge");
  const libEl   = document.getElementById("bss-basin-library");

  if (k === "__global__") {
    if (infoEl)  infoEl.textContent = "Formulas here apply to all basins unless a basin-specific override is saved";
    if (badgeEl) badgeEl.style.display = "none";
  } else {
    const b = BASINS.find(x => x.name === k);
    if (infoEl && b) infoEl.textContent = `${b.country} · ${b.region} · ${b.tectonic} · Score ${b.score}`;
    const hasSaved = Object.values(_bssBasinSaved[k] || {}).some(a => a.length > 0);
    if (badgeEl) badgeEl.style.display = hasSaved ? "inline-block" : "none";
  }

  // Basin library — chips for all basins with saved formulas
  if (!libEl) return;
  const keys = Object.keys(_bssBasinSaved).filter(bk =>
    Object.values(_bssBasinSaved[bk] || {}).some(a => a.length > 0)
  );
  if (!keys.length) {
    libEl.innerHTML = '<span style="font-size:10px;color:var(--t3)">No basin-specific formulas yet — select a basin above and save formulas to build a library</span>';
    return;
  }
  libEl.innerHTML = keys.map(bk => {
    const isGlobal  = bk === "__global__";
    const isActive  = Object.values(_bssBasinActiveVars[bk] || {}).some(Boolean);
    const isCurrent = bk === k;
    const label     = isGlobal ? "🌐 Global" : `🗺 ${bk}`;
    const varCount  = Object.values(_bssBasinSaved[bk] || {}).reduce((s,a) => s + a.length, 0);
    return `<span style="display:inline-flex;align-items:center;gap:5px;font-size:10px;padding:3px 9px;
      border-radius:3px;cursor:pointer;border:1px solid;transition:all .15s;
      ${isCurrent
        ? "background:rgba(124,58,237,.15);color:var(--purple);border-color:rgba(124,58,237,.4);"
        : "background:var(--bg3);color:var(--t2);border-color:var(--b1);"
      }${isActive ? "outline:2px solid rgba(0,200,130,.35);" : ""}"
      title="Switch to ${bk} — ${varCount} formula(s) saved"
      onclick="document.getElementById('bss-basin-select').value='${bk.replace(/'/g,"\\'")}';bssOnBasinChange('${bk.replace(/'/g,"\\'")}')">
      ${label}
      <span style="font-size:7px;opacity:.7">${varCount}f</span>
      ${isActive ? '<span style="color:var(--green);font-size:10px">✓</span>' : ''}
      <span onclick="event.stopPropagation();bssDeleteBasinAll('${bk.replace(/'/g,"\\'")}');"
        style="color:var(--red);font-weight:700;opacity:.7;margin-left:1px;font-size:10px;line-height:1">×</span>
    </span>`;
  }).join("");
}

function bssCopyFromGlobal() {
  const k = _bssKey();
  if (k === "__global__") { toast("Already on Global", "warn"); return; }
  const gs = _bssBasinState["__global__"];
  if (!gs || !Object.keys(gs).length) { toast("No global formula built yet", "warn"); return; }
  _bssBasinState[k] = JSON.parse(JSON.stringify(gs));
  if (_bssBasinMode["__global__"]) _bssBasinMode[k] = JSON.parse(JSON.stringify(_bssBasinMode["__global__"]));
  _bssPersist();
  bssRebuildAllPanels();
  bssBuildVarPanel("source");
  toast(`Global formula copied to "${k}"`, "success");
}

function bssClearBasinFormulas() {
  const k = _bssKey();
  const label = k === "__global__" ? "Global" : k;
  if (!confirm(`Clear all formula data for ${label}?`)) return;
  delete _bssBasinState[k];
  delete _bssBasinMode[k];
  delete _bssBasinSaved[k];
  delete _bssBasinActiveVars[k];
  Object.keys(_bssVarDefs).forEach(vid => _bssGetState(vid));
  _bssActive = false;
  _bssPersist();
  bssRebuildAllPanels();
  bssBuildVarPanel("source");
  bssUpdateBasinInfo();
  toast(`Cleared all formula data for "${label}"`, "info");
}

function bssDeleteBasinAll(basinKey) {
  delete _bssBasinSaved[basinKey];
  delete _bssBasinActiveVars[basinKey];
  _bssPersist();
  bssUpdateBasinInfo();
  toast(`Deleted saved formulas for "${basinKey}"`, "info");
}

// ── Panel builder ─────────────────────────────────────────────────────
function bssBuildVarPanel(vid) {
  const cont = document.getElementById("bss-var-" + vid);
  if (!cont || cont._built) { bssUpdateScore(vid); return; }
  cont._built = true;

  const def  = _bssVarDefs[vid];
  const st   = _bssGetState(vid);
  const col  = _bssColors[vid] || "var(--brand)";
  const mode = _bssGetMode(vid);
  const k    = _bssKey();
  const basinLabel = k === "__global__" ? "Global" : k;

  let html = "";

  // ── Basin context banner ──────────────────────────────────────
  html += `<div style="display:flex;align-items:center;gap:8px;padding:5px 10px;background:${
    k==="__global__"?"rgba(124,58,237,.06)":"rgba(8,145,178,.06)"
  };border-radius:5px;border:1px solid ${
    k==="__global__"?"rgba(124,58,237,.2)":"rgba(8,145,178,.2)"
  };margin-bottom:10px;font-size:10px;flex-wrap:wrap">
    <span style="color:var(--t3)">Editing <strong style="color:${col}">${def.label}</strong> formula for:</span>
    <strong style="color:${k==="__global__"?"var(--purple)":"var(--cyan)"}">${basinLabel}</strong>
    ${_bssGetActive(vid) ? `<span style="margin-left:auto;font-size:7px;padding:1px 6px;border-radius:3px;background:rgba(0,200,130,.12);color:var(--green);font-weight:700">✓ ACTIVE ON LEADERBOARD</span>` : ""}
  </div>`;

  // ── Mode toggle (not for gcos/composite) ─────────────────────
  if (vid !== "gcos" && vid !== "composite") {
    html += `<div style="display:flex;align-items:center;gap:0;margin-bottom:12px;border:1px solid var(--b1);border-radius:6px;overflow:hidden;width:fit-content">
      <button onclick="bssSwitchMode('${vid}','builder')"
        style="font-size:10px;padding:5px 14px;border:none;cursor:pointer;font-weight:600;transition:all .2s;
        ${mode==="builder" ? `background:${col};color:#fff` : "background:var(--bg4);color:var(--t2)"}">
        ⚙ Builder
      </button>
      <button onclick="bssSwitchMode('${vid}','custom')"
        style="font-size:10px;padding:5px 14px;border:none;cursor:pointer;font-weight:600;transition:all .2s;border-left:1px solid var(--b1);
        ${mode==="custom"  ? `background:${col};color:#fff` : "background:var(--bg4);color:var(--t2)"}">
        ƒ Custom Formula
      </button>
    </div>`;
  }

  // ── Builder panel ─────────────────────────────────────────────
  html += `<div id="bss-builder-panel-${vid}" style="display:${mode==="builder"||vid==="gcos"||vid==="composite"?"block":"none"}">`;
  if (vid === "gcos") {
    html += bssBuildGcosPanel(col, st);
  } else if (vid === "composite") {
    html += bssBuildCompositePanel(col, st);
  } else {
    html += `<div style="display:grid;grid-template-columns:repeat(2,1fr);gap:10px;margin-bottom:12px">`;
    def.params.forEach(p => {
      const fn  = st.fn?.[p.id]  || (p.inv ? "inv_linear" : "linear");
      const wt  = st.weight?.[p.id] ?? Math.round(100/def.params.length);
      const val = st.val?.[p.id]  ?? p.def;
      html += `<div style="background:var(--bg4);border:1px solid var(--b1);border-radius:7px;padding:10px 12px">
        <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:5px">
          <div>
            <span style="font-size:11px;font-weight:700;color:${col}">${p.label}</span>
            <span style="font-size:10px;color:var(--t3);margin-left:4px">${p.unit}</span>
            ${p.inv ? `<span style="font-size:7px;padding:1px 4px;border-radius:2px;background:rgba(239,68,68,.1);color:var(--red);margin-left:3px">INV</span>` : ""}
          </div>
          <div style="display:flex;align-items:center;gap:4px">
            <span style="font-size:10px;color:var(--t3)">Wt</span>
            <input type="number" min="0" max="100" step="1" value="${wt}"
              style="width:38px;font-size:10px;padding:2px 3px;background:var(--bg3);border:1px solid var(--b1);border-radius:3px;color:var(--t1);text-align:center"
              oninput="_bssGetState('${vid}').weight['${p.id}']=+this.value;_bssPersist();bssUpdateScore('${vid}')">
            <span style="font-size:10px;color:var(--t3)">%</span>
          </div>
        </div>
        <div style="font-size:10px;color:var(--t3);margin-bottom:6px;line-height:1.4">${p.tip}</div>
        <div style="display:grid;grid-template-columns:1fr 1fr;gap:5px;margin-bottom:6px">
          <div>
            <div style="font-size:10px;color:var(--t3);margin-bottom:2px">Scoring Function</div>
            <select style="width:100%;font-size:10px;padding:3px 4px;background:var(--bg3);border:1px solid var(--b1);border-radius:3px;color:var(--t1)"
              onchange="_bssGetState('${vid}').fn['${p.id}']=this.value;_bssPersist();bssRenderFnParams('${vid}','${p.id}');bssUpdateScore('${vid}')"
              id="bss-fn-${vid}-${p.id}">
              ${_bssFunctions.map(f=>`<option value="${f.id}"${fn===f.id?" selected":""}>${f.label}</option>`).join("")}
            </select>
          </div>
          <div>
            <div style="font-size:10px;color:var(--t3);margin-bottom:2px">Preview Value</div>
            <div style="display:flex;align-items:center;gap:3px">
              <input type="range" min="${p.min}" max="${p.max}" step="${p.step}" value="${val}"
                style="flex:1;accent-color:${col}"
                oninput="this.nextElementSibling.textContent=this.value;_bssGetState('${vid}').val['${p.id}']=+this.value;_bssPersist();bssUpdateScore('${vid}')"
                id="bss-val-${vid}-${p.id}">
              <span style="font-size:10px;color:${col};min-width:28px;text-align:right;font-weight:700">${val}</span>
            </div>
          </div>
        </div>
        <div id="bss-fp-${vid}-${p.id}" style="margin-bottom:5px"></div>
        <div style="display:flex;align-items:center;gap:5px;padding:3px 6px;background:var(--bg3);border-radius:3px">
          <span style="font-size:10px;color:var(--t3)">Sub-score:</span>
          <div style="flex:1;background:rgba(0,0,0,.18);border-radius:2px;height:4px;overflow:hidden">
            <div id="bss-bar-${vid}-${p.id}" style="height:100%;background:${col};width:50%;transition:width .3s"></div>
          </div>
          <span id="bss-sub-${vid}-${p.id}" style="font-size:10px;font-weight:700;color:${col};min-width:26px;text-align:right">—</span>
        </div>
      </div>`;
    });
    html += `</div>`;
  }
  html += `</div>`; // end builder-panel

  // ── Custom formula panel ──────────────────────────────────────
  if (vid !== "gcos" && vid !== "composite") {
    const savedCustom = st.customExpr || "";
    const exampleExpr = _bssCustomExampleFor(vid);
    html += `<div id="bss-custom-panel-${vid}" style="display:${mode==="custom"?"block":"none"}">
      <!-- Variable reference grid -->
      <div style="margin-bottom:10px;padding:9px 12px;background:var(--bg4);border-radius:6px;border:1px solid var(--b1)">
        <div style="font-size:10px;letter-spacing:1px;text-transform:uppercase;color:var(--t3);margin-bottom:7px">
          Variables for <span style="color:${col}">${def.label}</span>
          <span style="font-size:10px;color:var(--t3);margin-left:6px;font-weight:400;letter-spacing:0;text-transform:none">— click to insert at cursor</span>
        </div>
        <div style="display:grid;grid-template-columns:repeat(4,1fr);gap:5px;margin-bottom:8px">
          ${(def.params||[]).map(p=>`<div style="padding:5px 7px;background:var(--bg3);border:1px solid var(--b1);border-radius:4px;cursor:pointer"
            title="${p.tip} range: ${p.min}–${p.max} ${p.unit}"
            onclick="bssInsertVar('${vid}','${p.id}')">
            <div style="font-family:monospace;font-size:10px;font-weight:700;color:${col}">${p.id}</div>
            <div style="font-size:7px;color:var(--t3);overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${p.label}</div>
            <div style="font-size:7px;color:var(--t3)">[${p.min}–${p.max}]</div>
          </div>`).join("")}
        </div>
        <div style="display:flex;flex-wrap:wrap;gap:4px;margin-bottom:6px">
          <span style="font-size:10px;color:var(--t3);align-self:center">Insert:</span>
          ${[["+ ","+"],["- ","-"],["* ","×"],["/ ","÷"],["Math.pow(x,2)","x²"],["Math.sqrt(x)","√x"],
              ["Math.log(x)","ln x"],["Math.min(a,b)","min"],["Math.max(a,b)","max"],
              ["clamp(x,0,100)","clamp"],["normalise(x,0,100)","norm"],
              ["sigmoid(x,0.1,50)","sigmoid"],["gaussian(x,50,10)","gaussian"],
              ["step(x,50)","step"],["? : ","ternary"]
            ].map(([ins,lbl])=>`<button onclick="bssInsertSnippet('${vid}','${ins.replace(/'/g,"\\'").replace(/"/g,"&quot;")}')"
              style="font-size:10px;padding:2px 7px;background:var(--bg3);border:1px solid var(--b1);border-radius:3px;cursor:pointer;color:var(--t2);font-family:monospace">${lbl}</button>`).join("")}
        </div>
        <div style="font-size:10px;color:var(--t3);line-height:1.7">
          <strong style="color:var(--t2)">Helpers:</strong>
          <code style="background:var(--bg3);padding:1px 4px;border-radius:2px">clamp(v,lo,hi)</code>
          <code style="background:var(--bg3);padding:1px 4px;border-radius:2px">normalise(v,min,max)</code>
          <code style="background:var(--bg3);padding:1px 4px;border-radius:2px">sigmoid(v,k,mid)</code>
          <code style="background:var(--bg3);padding:1px 4px;border-radius:2px">gaussian(v,peak,σ)</code>
          <code style="background:var(--bg3);padding:1px 4px;border-radius:2px">step(v,threshold)</code>
          — Formula must return 0–100.
        </div>
      </div>
      <!-- Code editor -->
      <div style="margin-bottom:10px">
        <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:5px">
          <div style="font-size:10px;font-weight:700;color:var(--t2)">Custom Formula — <span style="color:${col}">${def.label}</span> for <span style="color:${k==="__global__"?"var(--purple)":"var(--cyan)"}">${basinLabel}</span></div>
          <div style="display:flex;gap:5px">
            <button onclick="bssLoadExample('${vid}')" style="font-size:10px;padding:2px 8px;background:var(--bg4);border:1px solid var(--b1);border-radius:3px;cursor:pointer;color:var(--t2)">Load Example</button>
            <button onclick="bssClearCustom('${vid}')" style="font-size:10px;padding:2px 8px;background:var(--bg4);border:1px solid var(--b1);border-radius:3px;cursor:pointer;color:var(--red)">✕ Clear</button>
          </div>
        </div>
        <textarea id="bss-custom-expr-${vid}" spellcheck="false" autocorrect="off"
          placeholder="${exampleExpr}"
          style="width:100%;min-height:160px;padding:10px 12px;background:#0f1117;color:#e2e8f0;
            border:1px solid rgba(124,58,237,.3);border-radius:6px;
            font-family:'Fira Code',Consolas,'Courier New',monospace;font-size:11px;
            line-height:1.8;resize:vertical;box-sizing:border-box;outline:none;tab-size:2"
          oninput="bssValidateCustom('${vid}')"
          onkeydown="bssHandleEditorKey(event,'${vid}')"
        >${savedCustom}</textarea>
        <div style="display:flex;align-items:center;gap:8px;margin-top:6px;flex-wrap:wrap">
          <div id="bss-custom-err-${vid}" style="display:none;font-size:10px;color:var(--red);padding:3px 8px;background:rgba(239,68,68,.08);border-radius:4px;border:1px solid rgba(239,68,68,.2);flex:1"></div>
          <div id="bss-custom-ok-${vid}"  style="display:none;font-size:10px;color:var(--green);padding:3px 8px;background:rgba(0,200,130,.08);border-radius:4px;border:1px solid rgba(0,200,130,.2);flex:1">✓ Valid — score: <strong id="bss-custom-result-${vid}">—</strong></div>
          <button onclick="bssValidateCustom('${vid}',true)" style="font-size:10px;padding:4px 10px;background:var(--bg4);border:1px solid var(--b1);border-radius:4px;cursor:pointer;color:var(--t2)">▶ Test (Ctrl+↵)</button>
        </div>
        <!-- Test inputs -->
        <div style="margin-top:8px;padding:8px 10px;background:var(--bg4);border-radius:5px;border:1px solid var(--b1)">
          <div style="font-size:10px;color:var(--t3);margin-bottom:6px;letter-spacing:.5px;text-transform:uppercase">Test with values</div>
          <div style="display:grid;grid-template-columns:repeat(4,1fr);gap:5px">
            ${(def.params||[]).map(p=>`<div>
              <div style="font-size:7px;color:var(--t3);margin-bottom:2px">${p.id} [${p.min}–${p.max}]</div>
              <input type="number" min="${p.min}" max="${p.max}" step="${p.step}" value="${p.def}"
                id="bss-test-val-${vid}-${p.id}"
                style="width:100%;font-size:10px;padding:2px 5px;background:var(--bg3);border:1px solid var(--b1);border-radius:3px;color:var(--t1)"
                oninput="bssValidateCustom('${vid}')">
            </div>`).join("")}
          </div>
        </div>
      </div>
    </div>`; // end custom-panel
  }

  // ── Formula preview + score ───────────────────────────────────
  const previewLabel = _bssCurrentBasin === "__global__"
    ? "Preview (Global — slider values as-is)"
    : `Preview for <strong style="color:${k==="__global__"?"var(--purple)":"var(--cyan)"}">${basinLabel}</strong> ${leaderboardData.find(b=>b.name===k) ? "— matches leaderboard" : "— run screening first to calibrate"}`;
  html += `<div style="margin-bottom:12px;padding:9px 12px;background:rgba(0,0,0,.1);border-radius:6px;border:1px solid var(--b1)">
    <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:5px;flex-wrap:wrap;gap:4px">
      <div style="font-size:10px;letter-spacing:1px;text-transform:uppercase;color:var(--t3)">Live Score Preview</div>
      <div style="font-size:10px;color:var(--t3)">${previewLabel}</div>
    </div>
    <div id="bss-formula-${vid}" style="font-family:monospace;font-size:10px;color:${col};line-height:1.7;word-break:break-all;max-height:56px;overflow:hidden">—</div>
    <div style="display:flex;align-items:center;gap:10px;margin-top:8px;flex-wrap:wrap">
      <span style="font-size:10px;color:var(--t2)">${def.label}:</span>
      <span id="bss-score-${vid}" style="font-size:26px;font-weight:900;color:${col};line-height:1">—</span>
      <span style="font-size:10px;color:var(--t3)">/100</span>
      <div style="flex:1"></div>
      ${vid!=="gcos"&&vid!=="composite" ? `<button class="btn2" style="font-size:10px;padding:3px 9px" onclick="bssEqualWeights('${vid}')"> Equal Wt</button>` : ""}
      <button class="btn2" style="font-size:10px;padding:3px 9px" onclick="bssResetVar('${vid}')">↺ Reset</button>
    </div>
  </div>

  <!-- Save formula -->
  <div style="margin-bottom:12px;padding:9px 12px;background:var(--bg4);border-radius:6px;border:1px solid var(--b1)">
    <div style="font-size:10px;letter-spacing:1px;text-transform:uppercase;color:var(--t2);margin-bottom:7px">
      Saved Formulas — ${def.label}
      <span style="font-size:10px;color:var(--t3);font-weight:400;text-transform:none;letter-spacing:0;margin-left:4px">(for ${basinLabel})</span>
    </div>
    <div style="display:flex;gap:6px;align-items:center;margin-bottom:7px;flex-wrap:wrap">
      <input id="bss-save-name-${vid}" class="fc" placeholder="Formula name…" style="flex:1;min-width:140px;font-size:10px;padding:4px 8px">
      <button class="btn2" style="font-size:10px;padding:4px 10px" onclick="bssSaveFormula('${vid}')">💾 Save</button>
    </div>
    <div id="bss-chips-${vid}" style="display:flex;flex-wrap:wrap;gap:5px;min-height:20px"></div>
  </div>

  <!-- Apply to screening -->
  <div style="padding:8px 12px;background:linear-gradient(135deg,rgba(124,58,237,.05),rgba(8,145,178,.05));border:1px solid rgba(124,58,237,.18);border-radius:6px;display:flex;align-items:center;gap:8px;flex-wrap:wrap">
    <div style="flex:1;min-width:140px">
      <div style="font-size:10px;font-weight:700;color:var(--t1)">Apply ${def.label} formula</div>
      <div style="font-size:10px;color:var(--t3);margin-top:1px">
        ${k==="__global__" ? "Overrides default scoring for all basins in leaderboard." : `Overrides default scoring specifically for <strong>${k}</strong>.`}
      </div>
    </div>
    <span id="bss-var-active-${vid}" style="display:${_bssGetActive(vid)?"inline-block":"none"};font-size:10px;padding:1px 7px;border-radius:3px;background:rgba(0,200,130,.12);color:var(--green);font-weight:700">✓ ACTIVE</span>
    <button class="btn2" style="font-size:10px;padding:4px 10px;color:var(--red)" onclick="bssDeactivateVar('${vid}')">Detach</button>
    <button class="btn" style="font-size:10px;padding:5px 12px;background:linear-gradient(135deg,${col},var(--brand));border:none" onclick="bssActivateVar('${vid}')">✓ Use This Formula</button>
  </div>`;

  cont.innerHTML = html;

  // Post-render
  if (def.params && mode === "builder") def.params.forEach(p => bssRenderFnParams(vid, p.id));
  bssRenderChips(vid);
  bssUpdateScore(vid);
  if (st.customExpr && mode === "custom") bssValidateCustom(vid);
}

// ── Mode switch ───────────────────────────────────────────────────────
function bssSwitchMode(vid, mode) {
  _bssSetMode(vid, mode);
  const bPanel = document.getElementById("bss-builder-panel-"+vid);
  const cPanel = document.getElementById("bss-custom-panel-"+vid);
  if (bPanel) bPanel.style.display = mode === "builder" ? "block" : "none";
  if (cPanel) cPanel.style.display  = mode === "custom"  ? "block" : "none";
  // Update button styles
  const cont = document.getElementById("bss-var-"+vid);
  if (cont) {
    const btns = cont.querySelectorAll("[onclick^='bssSwitchMode']");
    const col  = _bssColors[vid];
    btns.forEach(b => {
      const isActive = b.getAttribute("onclick").includes(`'${mode}'`);
      b.style.background = isActive ? col : "var(--bg4)";
      b.style.color      = isActive ? "#fff" : "var(--t2)";
    });
  }
  bssUpdateScore(vid);
}

// ── GCoS / Composite special panels ──────────────────────────────────
function bssBuildGcosPanel(col, st) {
  const params = _bssVarDefs.gcos.params;
  return `<div style="background:var(--bg4);border:1px solid var(--b1);border-radius:7px;padding:12px;margin-bottom:12px">
    <div style="font-size:10px;color:var(--t3);margin-bottom:10px;line-height:1.5">
      GCoS = P(Source) × P(Reservoir) × P(Seal) × P(Trap) × P(Migration) × Multiplier
      <br><strong style="color:${col}">Result expressed as % (0–100)</strong>
    </div>
    <div style="display:grid;grid-template-columns:repeat(3,1fr);gap:10px">
      ${params.map(p => {
        const val = st?.val?.[p.id] ?? p.def;
        return `<div style="padding:8px 10px;background:var(--bg3);border-radius:5px;border:1px solid var(--b1)">
          <div style="font-size:10px;font-weight:700;color:${col};margin-bottom:4px">${p.label}</div>
          <div style="font-size:10px;color:var(--t3);margin-bottom:6px">${p.tip}</div>
          <div style="display:flex;align-items:center;gap:4px">
            <input type="range" min="${p.min}" max="${p.max}" step="${p.step}" value="${val}"
              style="flex:1;accent-color:${col}"
              oninput="this.nextElementSibling.textContent=(+this.value).toFixed(2);_bssGetState('gcos').val['${p.id}']=+this.value;_bssPersist();bssUpdateScore('gcos')"
              id="bss-val-gcos-${p.id}">
            <span style="font-size:10px;color:${col};min-width:32px;text-align:right;font-weight:700">${typeof val==="number"?val.toFixed(2):val}</span>
          </div>
        </div>`;
      }).join("")}
    </div>
  </div>`;
}

function bssBuildCompositePanel(col, st) {
  const params = _bssVarDefs.composite.params;
  const colMap = {source:"var(--green)",reservoir:"var(--blue)",seal:"var(--cyan)",charge:"var(--purple)",commercial:"var(--amber)",country:"var(--red)"};
  return `<div style="background:var(--bg4);border:1px solid var(--b1);border-radius:7px;padding:12px;margin-bottom:12px">
    <div style="font-size:10px;color:var(--t3);margin-bottom:10px;line-height:1.5">
      Set element weights — <strong style="color:${col}">auto-normalised to 100%</strong>. Overrides Criteria & Weights sliders.
    </div>
    <div style="display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-bottom:8px">
      ${params.map(p => {
        const key = p.id.replace("wt_","");
        const val = st?.val?.[p.id] ?? p.def;
        const c   = colMap[key] || col;
        return `<div style="padding:8px 10px;background:var(--bg3);border-radius:5px;border:1px solid var(--b1)">
          <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:5px">
            <span style="font-size:10px;font-weight:700;color:${c}">${p.label.replace("Weight: ","")}</span>
            <span style="font-size:11px;font-weight:700;color:${c}" id="bss-vl-composite-${p.id}">${val}%</span>
          </div>
          <input type="range" min="0" max="50" step="1" value="${val}"
            style="width:100%;accent-color:${c}"
            oninput="document.getElementById('bss-vl-composite-${p.id}').textContent=this.value+'%';_bssGetState('composite').val['${p.id}']=+this.value;_bssPersist();bssUpdateScore('composite')"
            id="bss-val-composite-${p.id}">
        </div>`;
      }).join("")}
    </div>
    <div id="bss-composite-norm" style="font-size:10px;color:var(--t3);padding:5px 8px;background:rgba(0,0,0,.08);border-radius:4px"></div>
  </div>`;
}

// ── Function param sub-panels ─────────────────────────────────────────
function bssRenderFnParams(vid, pid) {
  const cont = document.getElementById(`bss-fp-${vid}-${pid}`);
  if (!cont) return;
  const st  = _bssGetState(vid);
  const fn  = st?.fn?.[pid] || "linear";
  const def = (_bssVarDefs[vid]?.params || []).find(p => p.id === pid);
  if (!def) return;
  const col = _bssColors[vid];
  const prm = st?.params?.[pid] || {};
  let h = "";
  if (fn === "sigmoid") {
    const k=prm.k||0.1, mid=prm.mid||((def.max+def.min)/2);
    h = `<div style="display:grid;grid-template-columns:1fr 1fr;gap:4px">
      <div><div style="font-size:7px;color:var(--t3)">Steepness k</div>
        <input type="range" min="0.01" max="1" step="0.01" value="${k}" style="width:100%;accent-color:${col}"
          oninput="this.nextElementSibling.textContent=(+this.value).toFixed(2);_bssGetState('${vid}').params['${pid}'].k=+this.value;_bssPersist();bssUpdateScore('${vid}')">
        <span style="font-size:10px;color:${col}">${k.toFixed?k.toFixed(2):k}</span></div>
      <div><div style="font-size:7px;color:var(--t3)">Midpoint</div>
        <input type="range" min="${def.min}" max="${def.max}" step="${def.step}" value="${mid}" style="width:100%;accent-color:${col}"
          oninput="this.nextElementSibling.textContent=this.value;_bssGetState('${vid}').params['${pid}'].mid=+this.value;_bssPersist();bssUpdateScore('${vid}')">
        <span style="font-size:10px;color:${col}">${mid}</span></div>
    </div>`;
  } else if (fn === "step") {
    const t = prm.thresh || ((def.max+def.min)/2);
    h = `<div><div style="font-size:7px;color:var(--t3)">Threshold</div>
      <input type="range" min="${def.min}" max="${def.max}" step="${def.step}" value="${t}" style="width:100%;accent-color:${col}"
        oninput="this.nextElementSibling.textContent=this.value;_bssGetState('${vid}').params['${pid}'].thresh=+this.value;_bssPersist();bssUpdateScore('${vid}')">
      <span style="font-size:10px;color:${col}">${t}</span></div>`;
  } else if (fn === "gaussian") {
    const pk=prm.peak||((def.max+def.min)/2), sg=prm.sigma||((def.max-def.min)/6)||1;
    h = `<div style="display:grid;grid-template-columns:1fr 1fr;gap:4px">
      <div><div style="font-size:7px;color:var(--t3)">Peak μ</div>
        <input type="range" min="${def.min}" max="${def.max}" step="${def.step}" value="${pk}" style="width:100%;accent-color:${col}"
          oninput="this.nextElementSibling.textContent=this.value;_bssGetState('${vid}').params['${pid}'].peak=+this.value;_bssPersist();bssUpdateScore('${vid}')">
        <span style="font-size:10px;color:${col}">${pk}</span></div>
      <div><div style="font-size:7px;color:var(--t3)">Width σ</div>
        <input type="range" min="0.1" max="${def.max-def.min}" step="${def.step}" value="${sg}" style="width:100%;accent-color:${col}"
          oninput="this.nextElementSibling.textContent=(+this.value).toFixed(1);_bssGetState('${vid}').params['${pid}'].sigma=+this.value;_bssPersist();bssUpdateScore('${vid}')">
        <span style="font-size:10px;color:${col}">${typeof sg==="number"?sg.toFixed(1):sg}</span></div>
    </div>`;
  } else if (fn === "clamp") {
    const r = def.max-def.min;
    const clo=prm.clo||(def.min+r*.3), chi=prm.chi||(def.min+r*.8);
    h = `<div style="display:grid;grid-template-columns:1fr 1fr;gap:4px">
      <div><div style="font-size:7px;color:var(--t3)">Range Low</div>
        <input type="range" min="${def.min}" max="${def.max}" step="${def.step}" value="${clo}" style="width:100%;accent-color:${col}"
          oninput="this.nextElementSibling.textContent=this.value;_bssGetState('${vid}').params['${pid}'].clo=+this.value;_bssPersist();bssUpdateScore('${vid}')">
        <span style="font-size:10px;color:${col}">${clo}</span></div>
      <div><div style="font-size:7px;color:var(--t3)">Range High</div>
        <input type="range" min="${def.min}" max="${def.max}" step="${def.step}" value="${chi}" style="width:100%;accent-color:${col}"
          oninput="this.nextElementSibling.textContent=this.value;_bssGetState('${vid}').params['${pid}'].chi=+this.value;_bssPersist();bssUpdateScore('${vid}')">
        <span style="font-size:10px;color:${col}">${chi}</span></div>
    </div>`;
  }
  cont.innerHTML = h;
}

// ── Sub-score calculator ──────────────────────────────────────────────
function _bssCalcSubScore(fn, val, def, prm) {
  const range = def.max - def.min || 1;
  const n = Math.max(0, Math.min(1, (val - def.min) / range));
  switch(fn) {
    case "linear":     return n * 100;
    case "log":        return Math.log(val - def.min + 1) / Math.log(range + 1) * 100;
    case "sqrt":       return Math.sqrt(n) * 100;
    case "power2":     return n * n * 100;
    case "inv_linear": return (1 - n) * 100;
    case "sigmoid": {
      const k = prm?.k || 0.1, mid = prm?.mid ?? ((def.max+def.min)/2);
      return 100 / (1 + Math.exp(-k * (val - mid)));
    }
    case "step":       return val >= (prm?.thresh ?? (def.max+def.min)/2) ? 100 : 0;
    case "gaussian": {
      const pk = prm?.peak ?? (def.max+def.min)/2;
      const sg = prm?.sigma || (range/6) || 1;
      return 100 * Math.exp(-Math.pow(val-pk,2) / (2*sg*sg));
    }
    case "clamp": {
      const r = range;
      const clo = prm?.clo ?? (def.min + r*.3);
      const chi = prm?.chi ?? (def.min + r*.8);
      if (val >= clo && val <= chi) return 100;
      if (val < clo) return 100 * Math.max(0, (val-def.min)/(clo-def.min||1));
      return 100 * Math.max(0, (def.max-val)/(def.max-chi||1));
    }
    default: return n * 100;
  }
}

// ── Live score updater ────────────────────────────────────────────────
function bssUpdateScore(vid) {
  const def       = _bssVarDefs[vid];
  const st        = _bssGetState(vid);
  const col       = _bssColors[vid];
  const formulaEl = document.getElementById("bss-formula-"+vid);
  const scoreEl   = document.getElementById("bss-score-"+vid);
  if (!st || !def) return;

  const mode = _bssGetMode(vid);

  // Custom formula mode
  if (mode === "custom" && vid !== "gcos" && vid !== "composite") {
    const expr = st.customExpr || "";
    if (!expr.trim()) {
      if (formulaEl) formulaEl.textContent = "(no formula yet — switch to ƒ Custom Formula and write one)";
      if (scoreEl)   scoreEl.textContent   = "—";
      return;
    }
    // Resolve param values: use slider vals, scaled to selected basin quality if applicable
    const selectedBasin2 = _bssCurrentBasin !== "__global__"
      ? leaderboardData.find(b => b.name === _bssCurrentBasin)
      : null;
    const basinPrior2 = selectedBasin2
      ? (selectedBasin2._basinPrior?.[vid] || selectedBasin2.scores?.[vid] || 50)
      : 50;
    const qRatio = basinPrior2 / 50;
    const testVals = {};
    (def.params||[]).forEach(p => {
      const inp = document.getElementById(`bss-test-val-${vid}-${p.id}`);
      const sliderVal = inp ? +inp.value : (st.val?.[p.id] ?? p.def);
      if (_bssCurrentBasin === "__global__") {
        testVals[p.id] = sliderVal;
      } else {
        const mid = (p.max + p.min) / 2;
        testVals[p.id] = Math.max(p.min, Math.min(p.max, mid + (sliderVal - mid) * qRatio));
      }
    });
    try {
      const result = _bssEvalCustom(expr, def.params||[], testVals);
      const clamped = Math.max(0, Math.min(100, result)).toFixed(1);
      if (scoreEl)   scoreEl.textContent   = clamped;
      const lines = expr.split("\n").filter(l=>l.trim()&&!l.trim().startsWith("//"));
      if (formulaEl) { formulaEl.textContent = lines.slice(-2).join(" ").replace(/\s+/g," ").slice(0,120); formulaEl.style.color=col; }
    } catch(e) {
      if (scoreEl)   scoreEl.textContent   = "err";
      if (formulaEl) { formulaEl.textContent = "⚠ "+e.message; formulaEl.style.color="var(--red)"; }
    }
    return;
  }

  if (vid === "gcos") {
    const ps=st.val.ps??0.55, pr=st.val.pr??0.65, pse=st.val.pse??0.60, pt=st.val.pt??0.55, pm=st.val.pm??0.60, mult=st.val.mult??1;
    const gcos = Math.min(100, Math.round(ps*pr*pse*pt*pm*mult*100));
    if (formulaEl) formulaEl.textContent = `GCoS = ${ps}×${pr}×${pse}×${pt}×${pm}×${mult} = ${(ps*pr*pse*pt*pm*mult*100).toFixed(1)}%`;
    if (scoreEl)   scoreEl.textContent   = gcos;
    return;
  }

  if (vid === "composite") {
    const keys = ["wt_source","wt_reservoir","wt_seal","wt_charge","wt_commercial","wt_country"];
    let total = keys.reduce((s,k2)=>s+(st.val[k2]||0),0) || 1;
    const norm = keys.map(k2=>({k2, w:(st.val[k2]||0)/total*100}));
    const normEl = document.getElementById("bss-composite-norm");
    if (normEl) normEl.textContent = "Normalised: " + norm.filter(x=>x.w>0).map(x=>`${x.k2.replace("wt_","")}:${x.w.toFixed(1)}%`).join(" + ");
    if (formulaEl) formulaEl.textContent = norm.filter(x=>x.w>0).map(x=>`${x.w.toFixed(1)}%×${x.k2.replace("wt_","")}`).join(" + ");
    if (scoreEl)   scoreEl.textContent   = "—";
    return;
  }

  // Builder mode — compute score using slider values.
  // If a specific basin is selected AND it has leaderboard data, use its prior
  // to show what score that basin will actually get in the leaderboard.
  const selectedBasin = _bssCurrentBasin !== "__global__"
    ? leaderboardData.find(b => b.name === _bssCurrentBasin)
    : null;
  const basinPriorScore = selectedBasin
    ? (selectedBasin._basinPrior?.[vid] || selectedBasin.scores?.[vid] || 50)
    : 50;
  const qualityRatio = basinPriorScore / 50;

  let totalWt=0, weightedSum=0, parts=[];
  def.params.forEach(p => {
    const fn        = st.fn?.[p.id]  || "linear";
    const wt        = st.weight?.[p.id] ?? 0;
    const sliderVal = st.val?.[p.id]  ?? p.def;
    const prm       = st.params?.[p.id] || {};
    // For global mode (qualityRatio=1), use slider values as-is.
    // For a specific basin, scale around midpoint to match leaderboard computation.
    const mid     = (p.max + p.min) / 2;
    const evalVal = _bssCurrentBasin === "__global__"
      ? sliderVal
      : Math.max(p.min, Math.min(p.max, mid + (sliderVal - mid) * qualityRatio));
    totalWt += wt;
    const sub = Math.max(0, Math.min(100, _bssCalcSubScore(fn, evalVal, p, prm)));
    const bar = document.getElementById(`bss-bar-${vid}-${p.id}`);
    const lbl = document.getElementById(`bss-sub-${vid}-${p.id}`);
    if (bar) bar.style.width = sub + "%";
    if (lbl) lbl.textContent = sub.toFixed(1);
    weightedSum += sub * wt;
    parts.push(`${wt}%·${(_bssFunctions.find(f=>f.id===fn)||{}).label||fn}(${p.id})`);
  });
  const finalScore = totalWt > 0 ? weightedSum / totalWt : 0;
  if (scoreEl)   scoreEl.textContent   = finalScore.toFixed(1);
  if (formulaEl) { formulaEl.textContent = parts.join(" + ") || "—"; formulaEl.style.color = col; }
  if (typeof bssRefreshScoreSummary === "function") bssRefreshScoreSummary();
}

// ── Custom formula evaluation helper ──────────────────────────────────
function _bssEvalCustom(expr, params, testVals) {
  const helperCode = `
    function clamp(v,lo,hi){return Math.max(lo,Math.min(hi,v));}
    function normalise(v,mn,mx){return mn===mx?0:Math.max(0,Math.min(1,(v-mn)/(mx-mn)));}
    function sigmoid(v,k,mid){return 100/(1+Math.exp(-(k||0.1)*(v-(mid??50))));}
    function gaussian(v,peak,sigma){var s=sigma||10;return 100*Math.exp(-Math.pow(v-peak,2)/(2*s*s));}
    function step(v,t){return v>=t?100:0;}
  `;
  const argNames = params.map(p => p.id);
  const argVals  = argNames.map(n => testVals?.[n] ?? 0);
  const fn = new Function(...argNames, helperCode + "return (" + expr + ");");
  const result = fn(...argVals);
  if (typeof result !== "number" || isNaN(result) || !isFinite(result))
    throw new Error("Expression must return a finite number (got " + result + ")");
  return result;
}

// ── Editor helpers ────────────────────────────────────────────────────
function bssInsertVar(vid, varName) {
  const ta = document.getElementById("bss-custom-expr-"+vid);
  if (!ta) return;
  const s = ta.selectionStart, e = ta.selectionEnd;
  ta.value = ta.value.slice(0,s) + varName + ta.value.slice(e);
  ta.selectionStart = ta.selectionEnd = s + varName.length;
  ta.focus();
  _bssGetState(vid).customExpr = ta.value;
  _bssPersist();
  bssValidateCustom(vid);
}
function bssInsertSnippet(vid, snippet) {
  const ta = document.getElementById("bss-custom-expr-"+vid);
  if (!ta) return;
  const s = ta.selectionStart, e = ta.selectionEnd;
  ta.value = ta.value.slice(0,s) + snippet + ta.value.slice(e);
  ta.selectionStart = ta.selectionEnd = s + snippet.length;
  ta.focus();
  _bssGetState(vid).customExpr = ta.value;
  _bssPersist();
  bssValidateCustom(vid);
}
function bssHandleEditorKey(e, vid) {
  if (e.key === "Tab") { e.preventDefault(); bssInsertSnippet(vid, "  "); }
  if ((e.ctrlKey||e.metaKey) && e.key === "Enter") { e.preventDefault(); bssValidateCustom(vid, true); }
}
function bssLoadExample(vid) {
  const ta = document.getElementById("bss-custom-expr-"+vid);
  if (!ta) return;
  ta.value = _bssCustomExampleFor(vid);
  _bssGetState(vid).customExpr = ta.value;
  _bssPersist();
  bssValidateCustom(vid);
}
function bssClearCustom(vid) {
  const ta = document.getElementById("bss-custom-expr-"+vid);
  if (ta) ta.value = "";
  _bssGetState(vid).customExpr = "";
  _bssPersist();
  const errEl = document.getElementById("bss-custom-err-"+vid);
  const okEl  = document.getElementById("bss-custom-ok-"+vid);
  if (errEl) errEl.style.display = "none";
  if (okEl)  okEl.style.display  = "none";
  bssUpdateScore(vid);
}
function bssValidateCustom(vid, showToast) {
  const ta    = document.getElementById("bss-custom-expr-"+vid);
  const errEl = document.getElementById("bss-custom-err-"+vid);
  const okEl  = document.getElementById("bss-custom-ok-"+vid);
  const resEl = document.getElementById("bss-custom-result-"+vid);
  if (!ta || !errEl || !okEl) return;
  const expr = ta.value.trim();
  _bssGetState(vid).customExpr = expr;
  _bssPersist();
  if (!expr) { errEl.style.display="none"; okEl.style.display="none"; bssUpdateScore(vid); return; }
  const def = _bssVarDefs[vid];
  const testVals = {};
  (def.params||[]).forEach(p => {
    const inp = document.getElementById(`bss-test-val-${vid}-${p.id}`);
    testVals[p.id] = inp ? +inp.value : p.def;
  });
  try {
    const result  = _bssEvalCustom(expr, def.params||[], testVals);
    const clamped = Math.round(Math.max(0, Math.min(100, result)));
    errEl.style.display = "none";
    okEl.style.display  = "block";
    if (resEl) resEl.textContent = clamped + " / 100";
    if (showToast) toast(`Formula valid → score ${clamped}`, "success");
    bssUpdateScore(vid);
  } catch(e) {
    errEl.textContent   = "⚠ " + e.message;
    errEl.style.display = "block";
    okEl.style.display  = "none";
  }
}

// ── Equal weights / Reset ─────────────────────────────────────────────
function bssEqualWeights(vid) {
  const def = _bssVarDefs[vid];
  if (!def?.params) return;
  const w = Math.round(100/def.params.length);
  const st = _bssGetState(vid);
  def.params.forEach(p => { st.weight[p.id] = w; });
  _bssPersist();
  const cont = document.getElementById("bss-var-"+vid);
  if (cont) { cont._built=false; cont.innerHTML=""; }
  bssBuildVarPanel(vid);
  toast("Equal weights applied", "success");
}
function bssResetVar(vid) {
  const k = _bssKey();
  if (_bssBasinState[k]) delete _bssBasinState[k][vid];
  if (_bssBasinMode[k])  delete _bssBasinMode[k][vid];
  _bssGetState(vid); // re-init defaults
  _bssPersist();
  _bssSetActive(vid, false);
  const cont = document.getElementById("bss-var-"+vid);
  if (cont) { cont._built=false; cont.innerHTML=""; }
  bssBuildVarPanel(vid);
  bssUpdateGlobalActiveBadge();
  toast(`${_bssVarDefs[vid]?.label} formula reset`, "info");
}
function bssResetAll() {
  const k = _bssKey();
  delete _bssBasinState[k];
  delete _bssBasinMode[k];
  delete _bssBasinActiveVars[k];
  Object.keys(_bssVarDefs).forEach(vid => _bssGetState(vid));
  _bssActive = false;
  _bssPersist();
  bssRebuildAllPanels();
  bssBuildVarPanel("source");
  bssUpdateGlobalActiveBadge();
  toast("All BSS formulas reset", "info");
}

// ── Save / Load ───────────────────────────────────────────────────────
function bssSaveFormula(vid) {
  const nameEl = document.getElementById("bss-save-name-"+vid);
  const name   = nameEl?.value?.trim();
  if (!name) { toast("Enter a formula name first", "warn"); return; }
  const k = _bssKey();
  if (!_bssBasinSaved[k])      _bssBasinSaved[k] = {};
  if (!_bssBasinSaved[k][vid]) _bssBasinSaved[k][vid] = [];
  _bssBasinSaved[k][vid] = _bssBasinSaved[k][vid].filter(f => f.name !== name);
  _bssBasinSaved[k][vid].push({
    name,
    mode:  _bssGetMode(vid),
    state: JSON.parse(JSON.stringify(_bssGetState(vid))),
    basin: k,
    ts:    Date.now()
  });
  _bssPersist();
  bssRenderChips(vid);
  bssUpdateBasinInfo();
  if (nameEl) nameEl.value = "";
  const label = k === "__global__" ? "Global" : k;
  toast(`"${name}" saved for ${_bssVarDefs[vid]?.label} (${label})`, "success");
}
function bssLoadFormula(vid, name) {
  const k   = _bssKey();
  const f   = (_bssBasinSaved[k]?.[vid] || []).find(x => x.name === name);
  if (!f) return;
  if (!_bssBasinState[k]) _bssBasinState[k] = {};
  _bssBasinState[k][vid] = JSON.parse(JSON.stringify(f.state));
  if (f.mode) { if(!_bssBasinMode[k]) _bssBasinMode[k]={}; _bssBasinMode[k][vid]=f.mode; }
  _bssPersist();
  const cont = document.getElementById("bss-var-"+vid);
  if (cont) { cont._built=false; cont.innerHTML=""; }
  bssBuildVarPanel(vid);
  toast(`"${name}" loaded`, "success");
}
function bssDeleteFormula(vid, name) {
  const k = _bssKey();
  if (_bssBasinSaved[k]?.[vid])
    _bssBasinSaved[k][vid] = _bssBasinSaved[k][vid].filter(f => f.name !== name);
  _bssPersist();
  bssRenderChips(vid);
  bssUpdateBasinInfo();
}
function bssRenderChips(vid) {
  const cont = document.getElementById("bss-chips-"+vid);
  if (!cont) return;
  const saved = _bssGetSaved(vid);
  if (!saved.length) {
    const label = _bssCurrentBasin === "__global__" ? "Global" : _bssCurrentBasin;
    cont.innerHTML = `<span style="font-size:10px;color:var(--t3)">No saved formulas for ${label} yet</span>`;
    return;
  }
  cont.innerHTML = saved.map(f => `
    <span style="display:inline-flex;align-items:center;gap:4px;font-size:10px;padding:2px 8px;
      border-radius:3px;background:rgba(124,58,237,.1);color:var(--purple);cursor:pointer;border:1px solid rgba(124,58,237,.2)"
      title="Mode: ${f.mode||"builder"} · Saved ${f.ts?new Date(f.ts).toLocaleDateString():""}"
      onclick="bssLoadFormula('${vid}','${f.name.replace(/'/g,"\\'")}')">
      ${f.mode==="custom"?"ƒ":"⚙"} ${f.name}
      <span onclick="event.stopPropagation();bssDeleteFormula('${vid}','${f.name.replace(/'/g,"\\'")}');"
        style="margin-left:3px;color:var(--red);font-weight:700;line-height:1">×</span>
    </span>`).join("");
}

// ── Activate / Deactivate ─────────────────────────────────────────────
function bssActivateVar(vid) {
  _bssSetActive(vid, true);
  const badge = document.getElementById("bss-var-active-"+vid);
  if (badge) badge.style.display = "inline-block";
  bssUpdateGlobalActiveBadge();
  const k = _bssKey();
  const label = k === "__global__" ? "Global" : k;
  toast(`${_bssVarDefs[vid]?.label} formula activated (${label})`, "success");
}
function bssDeactivateVar(vid) {
  _bssSetActive(vid, false);
  const badge = document.getElementById("bss-var-active-"+vid);
  if (badge) badge.style.display = "none";
  bssUpdateGlobalActiveBadge();
}
function bssUpdateGlobalActiveBadge() {
  const k = _bssKey();
  _bssActive = Object.values(_bssBasinActiveVars[k] || {}).some(Boolean);
  const globalBadge = document.getElementById("bss-active-badge");
  if (globalBadge) globalBadge.style.display = _bssActive ? "inline-block" : "none";
  bssRefreshScoreSummary();
}

// Show live scores for all active variables so user can verify leaderboard will match
function bssRefreshScoreSummary() {
  const cont = document.getElementById("bss-score-summary");
  if (!cont) return;
  const k = _bssKey();
  const vids = ["source","reservoir","seal","charge","commercial","country","gcos","composite"];
  const active = vids.filter(vid => _bssGetActive(vid));
  if (!active.length) { cont.innerHTML = ""; return; }

  const cols = {source:"var(--green)",reservoir:"var(--blue)",seal:"var(--cyan)",
                charge:"var(--purple)",commercial:"var(--amber)",country:"var(--red)",
                gcos:"var(--gold)",composite:"var(--brand)"};
  cont.innerHTML = active.map(vid => {
    const scoreEl = document.getElementById("bss-score-"+vid);
    const score   = scoreEl ? scoreEl.textContent : "—";
    const col     = cols[vid] || "var(--t2)";
    const label   = _bssVarDefs[vid]?.label?.replace(" Quality","").replace(" Integrity","").replace(" Efficiency","").replace(" Attractiveness","").replace(" / Political Risk","") || vid;
    return `<span style="font-size:10px;padding:2px 7px;border-radius:3px;background:rgba(0,0,0,.12);border:1px solid ${col};color:${col}">
      ${label}: <strong>${score}</strong>
    </span>`;
  }).join("") + `<span style="font-size:10px;color:var(--t3);align-self:center;margin-left:2px">→ leaderboard will use these scores</span>`;
}

// ── Compute score for a basin in the leaderboard ──────────────────────
// Resolves: basin-specific formula first, then global fallback
function bssComputeVarScore(vid, basin) {
  // Find which basin key has an active formula for this variable
  const basinName = basin.name;
  let targetKey   = null;
  // 1. Prefer exact basin match
  if (_bssBasinActiveVars[basinName]?.[vid]) targetKey = basinName;
  // 2. Fall back to global
  else if (_bssBasinActiveVars["__global__"]?.[vid]) targetKey = "__global__";
  if (!targetKey) return null;

  const def = _bssVarDefs[vid];
  if (!def) return null;
  const st = (_bssBasinState[targetKey] || {})[vid];
  if (!st) return null;
  const mode = (_bssBasinMode[targetKey] || {})[vid] || "builder";

  const elementScore = (basin._basinPrior || basin.scores || {})[def.scoreKey] || 50;

  if (vid === "gcos") {
    const scores = basin._basinPrior || basin.scores || {};
    const ps  = Math.min(0.95,(scores.source   ||50)/100);
    const pr  = Math.min(0.95,(scores.reservoir||50)/100);
    const pse = Math.min(0.95,(scores.seal      ||50)/100);
    const pt  = Math.min(0.95,(scores.charge    ||50)/100);
    const pm  = Math.min(0.95,(scores.commercial||50)/100*0.9);
    const mult = st.val?.mult || 1;
    return Math.min(100, Math.round(ps*pr*pse*pt*pm*mult*100));
  }

  if (vid === "composite") {
    const scores = basin.scores || {};
    const keys = ["source","reservoir","seal","charge","commercial","country"];
    let total = keys.reduce((s,k2)=>s+(st.val?.["wt_"+k2]||0),0) || 1;
    return Math.round(keys.reduce((s,k2)=>s+(scores[k2]||0)*(st.val?.["wt_"+k2]||0)/total, 0));
  }

  // Custom formula
  if (mode === "custom" && st.customExpr?.trim()) {
    try {
      const argVals = (def.params||[]).map(p => {
        const synVal = p.def * (elementScore / 70);
        return Math.max(p.min, Math.min(p.max, synVal));
      });
      const testVals = {};
      (def.params||[]).forEach((p,i) => testVals[p.id] = argVals[i]);
      const result = _bssEvalCustom(st.customExpr, def.params||[], testVals);
      return Math.round(Math.max(0, Math.min(100, result)));
    } catch(e) { return Math.round(elementScore); }
  }

  // Builder mode
  let totalWt=0, weightedSum=0;
  (def.params||[]).forEach(p => {
    const fn  = st.fn?.[p.id]  || "linear";
    const wt  = st.weight?.[p.id] ?? 0;
    const prm = st.params?.[p.id] || {};
    const synVal = Math.max(p.min, Math.min(p.max, p.def * (elementScore/70)));
    const sub = Math.max(0, Math.min(100, _bssCalcSubScore(fn, synVal, p, prm)));
    totalWt += wt; weightedSum += sub * wt;
  });
  return totalWt > 0 ? Math.round(weightedSum/totalWt) : Math.round(elementScore);
}

// ── Apply all active formulas → re-run screening ──────────────────────
function bssApplyToScreening() {
  // Check any basin has active formulas
  const hasAny = Object.values(_bssBasinActiveVars).some(bv => Object.values(bv).some(Boolean));
  if (!hasAny) {
    toast("Activate at least one variable formula first (click '✓ Use This Formula')", "warn");
    return;
  }
  const btn    = document.getElementById("screen-btn");
  const status = document.getElementById("screen-status");
  if (btn)    { btn.textContent = "Running BSS Screening…"; btn.disabled = true; }
  if (status)  status.textContent = "Applying custom BSS formulas to all basins…";
  loadBar?.();

  setTimeout(() => {

    // ── For each basin: compute element scores using BSS formulas ──
    // The BSS formula is defined with specific param defaults (e.g. TOC=3.5).
    // For other basins we scale the param values proportionally to their quality score,
    // so that the formula shape is preserved but calibrated to each basin's relative quality.
    leaderboardData = BASINS.map(b => {
      const seed = b.name.length + b.score;
      const R = (base, off) => Math.max(10, Math.min(100, Math.round(base + ((seed*17+off*31)%21) - 10)));

      // Baseline prior scores (used for non-BSS elements and as quality scale)
      const basinPrior = {
        source:     R(b.score*0.95, 1),
        reservoir:  R(b.score*0.98, 2),
        seal:       R(b.score*0.88, 3),
        charge:     R(b.score*0.92, 4),
        commercial: R(b.score*0.85, 5),
        country:    R(b.score*0.96, 6),
      };

      // Start from prior, override with BSS formula results per element
      const finalScores = { ...basinPrior };
      const elementVids = ["source","reservoir","seal","charge","commercial","country"];

      elementVids.forEach(vid => {
        let targetKey = null;
        if (_bssBasinActiveVars[b.name]?.[vid])            targetKey = b.name;
        else if (_bssBasinActiveVars["__global__"]?.[vid]) targetKey = "__global__";
        if (!targetKey) return;

        const def  = _bssVarDefs[vid];
        const st   = (_bssBasinState[targetKey] || {})[vid];
        const mode = (_bssBasinMode[targetKey]  || {})[vid] || "builder";
        if (!def || !st) return;

        // Use the actual slider values the user set.
        // For other basins, scale each param proportionally around the range midpoint
        // using (basinPrior / 50) so a basin scoring 50 gets slider values unchanged,
        // high-quality basins get better params, low-quality basins get worse params.
        const qualityRatio = (basinPrior[vid] || 50) / 50;

        if (mode === "custom" && st.customExpr?.trim()) {
          try {
            const testVals = {};
            (def.params||[]).forEach(p => {
              const sliderVal = st.val?.[p.id] ?? p.def;
              const mid = (p.max + p.min) / 2;
              const scaled = mid + (sliderVal - mid) * qualityRatio;
              testVals[p.id] = Math.max(p.min, Math.min(p.max, scaled));
            });
            const result = _bssEvalCustom(st.customExpr, def.params||[], testVals);
            finalScores[vid] = Math.round(Math.max(0, Math.min(100, result)));
          } catch(e) { /* keep prior */ }
        } else {
          // Builder mode — same slider values, scaled to basin quality
          let totalWt = 0, weightedSum = 0;
          (def.params||[]).forEach(p => {
            const fn        = st.fn?.[p.id] || (p.inv ? "inv_linear" : "linear");
            const wt        = st.weight?.[p.id] ?? 0;
            const prm       = st.params?.[p.id] || {};
            const sliderVal = st.val?.[p.id] ?? p.def;
            const mid       = (p.max + p.min) / 2;
            const scaled    = Math.max(p.min, Math.min(p.max, mid + (sliderVal - mid) * qualityRatio));
            const sub       = Math.max(0, Math.min(100, _bssCalcSubScore(fn, scaled, p, prm)));
            totalWt        += wt;
            weightedSum    += sub * wt;
          });
          if (totalWt > 0) finalScores[vid] = Math.round(weightedSum / totalWt);
        }
      });

      // ── Composite score ──
      let composite;
      // Check if composite BSS formula is active for this basin
      let compKey = null;
      if (_bssBasinActiveVars[b.name]?.composite)          compKey = b.name;
      else if (_bssBasinActiveVars["__global__"]?.composite) compKey = "__global__";

      if (compKey) {
        const compSt = (_bssBasinState[compKey] || {}).composite;
        if (compSt) {
          const keys = ["source","reservoir","seal","charge","commercial","country"];
          let total = keys.reduce((s,k2)=>s+(compSt.val?.["wt_"+k2]||0),0) || 1;
          composite = Math.round(keys.reduce((s,k2)=>s+(finalScores[k2]||0)*(compSt.val?.["wt_"+k2]||0)/total, 0));
        }
      }
      if (composite == null) {
        // Use screenVals weights (Criteria & Weights panel)
        const w   = screenVals;
        const tot = Object.values(w).reduce((s,v)=>s+v,0) || 1;
        composite = Math.round(Object.entries(finalScores).reduce((s,[k2,v])=>s+(v*(w[k2]||15))/tot, 0));
      }

      const hasBespoke = !!_bssBasinActiveVars[b.name] && Object.values(_bssBasinActiveVars[b.name]).some(Boolean);
      return { ...b, scores: finalScores, composite, _basinPrior: basinPrior, _bssApplied: true, _bssBespoke: hasBespoke };
    })
      .sort((a,b2) => b2.composite - a.composite)
      .map((b,i) => ({...b, rank: i+1}));

    if (btn) { btn.textContent = "Re-run Screening"; btn.disabled = false; }
    const activeCount   = Object.values(_bssBasinActiveVars).reduce((s,bv)=>s+Object.values(bv).filter(Boolean).length, 0);
    const bespokeBasins = leaderboardData.filter(b => b._bssBespoke).length;
    if (status) status.textContent = `${leaderboardData.length} basins scored · ${activeCount} BSS formula(s) active · ${bespokeBasins} basin-specific`;
    document.getElementById("lb-not-run").style.display   = "none";
    document.getElementById("screen-results").style.display = "block";
    renderLeaderboard();
    const descEl = document.getElementById("bss-apply-desc");
    if (descEl) descEl.textContent = `✓ Applied ${new Date().toLocaleTimeString()} · ${activeCount} formula(s) · ${bespokeBasins} basin-specific override(s)`;
    toast(`BSS Screening complete — ${leaderboardData.length} basins ranked`, "success");
    switchScreenTab("leaderboard", document.querySelectorAll("#screen-tabs .tab")[1]);
  }, 800);
}

// ── Example formulas ──────────────────────────────────────────────────
function _bssCustomExampleFor(vid) {
  const examples = {
    source:`// Source Rock Quality — custom formula for ${_bssCurrentBasin === "__global__" ? "all basins" : _bssCurrentBasin}
// Variables: toc (0–20%), ro (0–3%), hi (0–800), thickness (0–500m), heatflow, expulsion, s2, tmax

const tocScore   = normalise(toc, 0, 10) * 100;
const roScore    = (ro >= 0.6 && ro <= 1.3) ? 100 : (ro >= 0.4 && ro <= 1.8) ? 60 : 20;
const hiScore    = normalise(hi, 50, 600) * 100;
const thickScore = normalise(thickness, 0, 200) * 100;
const expScore   = normalise(expulsion, 0, 100) * 100;
const s2Score    = normalise(s2, 0, 300) * 100;

clamp(
tocScore   * 0.25 +
roScore    * 0.20 +
hiScore    * 0.15 +
thickScore * 0.15 +
expScore   * 0.10 +
s2Score    * 0.15,
0, 100)`,
    reservoir:`// Reservoir Quality
// Variables: porosity (0–40%), perm (0–1000mD), ntg, depth, sw, fractures, api, compress

const porScore  = normalise(porosity, 0, 35) * 100;
const permScore = Math.log10(Math.max(1, perm)) / Math.log10(1000) * 100;
const ntgScore  = normalise(ntg, 0, 100) * 100;
const depScore  = clamp(100 - normalise(depth, 500, 5000) * 100, 0, 100);
const swScore   = clamp(100 - normalise(sw, 0, 80) * 100, 0, 100);
const apiScore  = api >= 30 ? 100 : api >= 22 ? 60 : 30;

clamp(porScore*0.25 + permScore*0.25 + ntgScore*0.15 + depScore*0.15 + swScore*0.10 + apiScore*0.10, 0, 100)`,
    seal:`// Seal Integrity
// Variables: thickness, capillary, ductility, fault, paleo, column, lateral, overpres

const thickGate = thickness >= 20 ? 1.0 : thickness / 20;
const capScore  = normalise(capillary, 0, 40) * 100;
const ductScore = normalise(ductility, 0, 10) * 100;
const faultScore= normalise(fault, 0, 10) * 100;
const colScore  = normalise(column, 0, 400) * 100;
const latScore  = normalise(lateral, 0, 100) * 100;

clamp(thickGate * (capScore*0.25 + ductScore*0.20 + faultScore*0.20 + colScore*0.20 + latScore*0.15), 0, 100)`,
    charge:`// Charge Efficiency
// Variables: proximity (inv), timing, volume, migration, phase, dhi, pathways, trapfill

const proxScore = clamp(100 - normalise(proximity, 0, 200)*100, 0, 100);
const timScore  = normalise(timing, 0, 10) * 100;
const migScore  = normalise(migration, 0, 100) * 100;
const dhiScore  = normalise(dhi, 0, 10) * 100;
const fillScore = normalise(trapfill, 0, 100) * 100;

clamp(proxScore*0.20 + timScore*0.20 + migScore*0.20 + dhiScore*0.20 + fillScore*0.20, 0, 100)`,
    commercial:`// Commercial Attractiveness
// Variables: fiscal, breakeven (inv), infra, waterdepth (inv), mfs (inv), esg, irr, market

const beScore   = clamp(100 - normalise(breakeven, 10, 100)*100, 0, 100);
const fiscalGate= fiscal >= 3 ? 1.0 : fiscal / 3;
const infraScore= normalise(infra, 0, 10) * 100;
const wdScore   = clamp(100 - normalise(waterdepth, 0, 3000)*100, 0, 100);
const esgScore  = normalise(esg, 0, 10) * 100;
const irrScore  = normalise(irr, 0, 50) * 100;

clamp(fiscalGate * (beScore*0.25 + infraScore*0.20 + wdScore*0.15 + esgScore*0.15 + irrScore*0.25), 0, 100)`,
    country:`// Country / Political Risk
// Variables: stability, cpi, contract, expropr, security, edb, forex, sanctions

if (sanctions < 5) return 0;  // hard block

const stabScore = normalise(stability, 0, 10) * 100;
const cpiScore  = normalise(cpi, 0, 100) * 100;
const contScore = normalise(contract, 0, 10) * 100;
const secScore  = normalise(security, 0, 10) * 100;
const edbScore  = normalise(edb, 0, 100) * 100;

clamp(stabScore*0.25 + cpiScore*0.20 + contScore*0.20 + secScore*0.20 + edbScore*0.15, 0, 100)`,
  };
  return examples[vid] || `// Write your ${_bssVarDefs[vid]?.label} formula\n// Variables: ${(_bssVarDefs[vid]?.params||[]).map(p=>p.id).join(", ")}\n// Return 0–100\n\nnormalise(${(_bssVarDefs[vid]?.params||[{id:"x"}])[0].id}, 0, 100) * 100`;
}


// ═══════════════════════════════════════════════════════════════════════
// AVAILABLE FORMULAS (AF) — Formula Assignment Table
// Lists all saved BSS formulas; lets user assign per basin+element; apply
// ═══════════════════════════════════════════════════════════════════════

// Persisted assignments: { basinKey: { vid: {name, formulaKey} } }
// formulaKey = basinKey where formula was saved (e.g. "__global__" or basin name)
let _afAssignments = {};
try { _afAssignments = JSON.parse(localStorage.getItem("af_assignments") || "{}"); } catch(e){}

const _afVids = ["source","reservoir","seal","charge","commercial","gcos","composite"];
const _afVidColors = {
  source:"var(--green)", reservoir:"var(--blue)", seal:"var(--cyan)",
  charge:"var(--purple)", commercial:"var(--amber)", gcos:"var(--gold)", composite:"var(--brand)"
};

function _afPersist() {
  try { localStorage.setItem("af_assignments", JSON.stringify(_afAssignments)); } catch(e){}
}

// Collect ALL saved formulas across all basin keys, per vid
// Returns: { vid: [ {label, basinKey, name, mode} ] }
function _afGetAllFormulas() {
  const result = {};
  _afVids.forEach(vid => { result[vid] = []; });
  Object.keys(_bssBasinSaved || {}).forEach(basinKey => {
    const basinSaved = _bssBasinSaved[basinKey] || {};
    _afVids.forEach(vid => {
      (basinSaved[vid] || []).forEach(f => {
        const basinLabel = basinKey === "__global__" ? "Global" : basinKey;
        result[vid].push({
          label:    `[${basinLabel}] ${f.name}`,
          basinKey: basinKey,
          name:     f.name,
          mode:     f.mode || "builder",
          state:    f.state
        });
      });
    });
  });
  return result;
}

function afInit() {
  // Populate basin filter dropdown
  const filterSel = document.getElementById("af-filter-basin");
  if (filterSel && filterSel.options.length <= 1) {
    BASINS.forEach(b => {
      const opt = document.createElement("option");
      opt.value = b.name;
      opt.textContent = b.name;
      filterSel.appendChild(opt);
    });
  }
  afRefresh();
}

function afRefresh() {
  const allFormulas = _afGetAllFormulas();
  const totalCount  = Object.values(allFormulas).reduce((s,a) => s + a.length, 0);

  // Update badge
  const badge = document.getElementById("af-formula-count-badge");
  if (badge) badge.textContent = `${totalCount} formula${totalCount!==1?"s":""}`;

  // Filter
  const filterVal = document.getElementById("af-filter-basin")?.value || "";

  // Build row data — Global row first, then each basin
  const basinRows = [
    { key: "__global__", label: "🌐 Global (all basins)", isGlobal: true, basin: null },
    ...BASINS.map(b => ({ key: b.name, label: b.name, isGlobal: false, basin: b }))
  ].filter(row => !filterVal || row.key === "__global__" || row.key === filterVal);

  const tbody = document.getElementById("af-tbody");
  if (!tbody) return;

  if (totalCount === 0) {
    tbody.innerHTML = `<tr><td colspan="8" style="padding:24px;text-align:center;font-size:10px;color:var(--t3)">
      No saved formulas yet.<br>
      Go to <strong style="color:var(--purple)">Basin Screening Score</strong> tab,
      build a formula, and click <strong>Save</strong> to populate this table.
    </td></tr>`;
    return;
  }

  tbody.innerHTML = basinRows.map((row, ri) => {
    const rowBg = ri % 2 === 0 ? "var(--bg3)" : "var(--bg4)";
    const isGlobalRow = row.isGlobal;
    const rowAssignments = _afAssignments[row.key] || {};

    const cells = _afVids.map(vid => {
      const formulas   = allFormulas[vid];
      const col        = _afVidColors[vid];
      const assigned   = rowAssignments[vid];  // {name, basinKey}
      const isActive   = !!(_bssBasinActiveVars[row.key]?.[vid]);

      if (formulas.length === 0) {
        return `<td style="padding:6px 8px;background:${rowBg};border-bottom:1px solid var(--b1)">
          <span style="font-size:10px;color:var(--t3)">—</span>
        </td>`;
      }

      const selId = `af-sel-${row.key.replace(/[^a-z0-9]/gi,"_")}-${vid}`;
      const currentVal = assigned ? `${assigned.basinKey}|||${assigned.name}` : "";

      return `<td style="padding:6px 8px;background:${rowBg};border-bottom:1px solid var(--b1)">
        <div style="display:flex;align-items:center;gap:4px">
          <select id="${selId}"
            style="flex:1;font-size:10px;padding:3px 5px;background:var(--bg3);
              border:1px solid ${assigned ? col : "var(--b1)"};
              border-radius:4px;color:${assigned ? col : "var(--t2)"};
              font-weight:${assigned ? "700" : "400"}"
            onchange="afOnSelect('${row.key}','${vid}',this.value,'${selId}')">
            <option value="">— none —</option>
            ${formulas.map(f => {
              const val = `${f.basinKey}|||${f.name}`;
              const modeIcon = f.mode === "custom" ? "ƒ" : "⚙";
              return `<option value="${val}"${val===currentVal?" selected":""}>${modeIcon} ${f.label}</option>`;
            }).join("")}
          </select>
          ${isActive
            ? `<span title="Active on leaderboard" style="font-size:10px;color:var(--green)">✓</span>`
            : `<span style="font-size:10px;color:transparent">✓</span>`
          }
        </div>
      </td>`;
    }).join("");

    const basinScore = row.basin ? row.basin.score : null;
    const assignedCount = Object.values(rowAssignments).filter(Boolean).length;
    const activeCount   = _afVids.filter(v => _bssBasinActiveVars[row.key]?.[v]).length;

    return `<tr>
      <td style="padding:7px 10px;background:${rowBg};border-bottom:1px solid var(--b1);
        position:sticky;left:0;z-index:1;min-width:140px">
        <div style="font-size:10px;font-weight:700;color:${isGlobalRow ? "var(--purple)" : "var(--t1)"}">
          ${row.label}
        </div>
        ${row.basin ? `<div style="font-size:7px;color:var(--t3)">${row.basin.country} · ${row.basin.region}</div>` : ""}
        <div style="display:flex;gap:4px;margin-top:3px;flex-wrap:wrap">
          ${basinScore != null ? `<span style="font-size:7px;padding:1px 5px;border-radius:2px;background:var(--bg3);color:var(--t3)">Score ${basinScore}</span>` : ""}
          ${assignedCount > 0 ? `<span style="font-size:7px;padding:1px 5px;border-radius:2px;background:rgba(124,58,237,.1);color:var(--purple)">${assignedCount} assigned</span>` : ""}
          ${activeCount > 0   ? `<span style="font-size:7px;padding:1px 5px;border-radius:2px;background:rgba(0,200,130,.1);color:var(--green)">${activeCount} active</span>` : ""}
        </div>
      </td>
      ${cells}
    </tr>`;
  }).join("");

  afUpdateSummary();
}

function afOnSelect(basinKey, vid, value, selId) {
  if (!_afAssignments[basinKey]) _afAssignments[basinKey] = {};

  const selEl = document.getElementById(selId);
  if (!value) {
    // Deselect — remove assignment and deactivate BSS
    delete _afAssignments[basinKey][vid];
    _bssSetActive_forKey(basinKey, vid, false);
    if (selEl) {
      selEl.style.borderColor = "var(--b1)";
      selEl.style.color = "var(--t2)";
      selEl.style.fontWeight = "400";
    }
  } else {
    const [srcBasinKey, name] = value.split("|||");
    _afAssignments[basinKey][vid] = { basinKey: srcBasinKey, name };

    // Load the formula state into the target basin slot
    const srcSaved = (_bssBasinSaved[srcBasinKey] || {})[vid] || [];
    const f = srcSaved.find(x => x.name === name);
    if (f) {
      if (!_bssBasinState[basinKey])       _bssBasinState[basinKey] = {};
      if (!_bssBasinMode[basinKey])         _bssBasinMode[basinKey]  = {};
      _bssBasinState[basinKey][vid] = JSON.parse(JSON.stringify(f.state));
      _bssBasinMode[basinKey][vid]  = f.mode || "builder";
      _bssSetActive_forKey(basinKey, vid, true);
      _bssPersist();
    }

    const col = _afVidColors[vid];
    if (selEl) {
      selEl.style.borderColor = col;
      selEl.style.color = col;
      selEl.style.fontWeight = "700";
    }
  }
  _afPersist();
  afUpdateSummary();
}

// Set active flag for a specific basin key (not current basin)
function _bssSetActive_forKey(basinKey, vid, val) {
  if (!_bssBasinActiveVars[basinKey]) _bssBasinActiveVars[basinKey] = {};
  _bssBasinActiveVars[basinKey][vid] = val;
  _bssPersist();
  // Also update the ACTIVE badge in BSS panel if it's the current basin
  if (basinKey === _bssCurrentBasin) {
    const badge = document.getElementById("bss-var-active-"+vid);
    if (badge) badge.style.display = val ? "inline-block" : "none";
    bssUpdateGlobalActiveBadge();
  }
}

function afUpdateSummary() {
  const summaryEl = document.getElementById("af-active-summary");
  if (!summaryEl) return;
  const totalAssigned = Object.values(_afAssignments)
    .reduce((s, bv) => s + Object.values(bv).filter(Boolean).length, 0);
  const basinCount = Object.keys(_afAssignments)
    .filter(k => Object.values(_afAssignments[k]||{}).some(Boolean)).length;
  if (totalAssigned === 0) {
    summaryEl.textContent = "No formulas assigned yet";
  } else {
    summaryEl.textContent = `${totalAssigned} formula assignment${totalAssigned!==1?"s":""} across ${basinCount} basin${basinCount!==1?"s":""}`;
    summaryEl.style.color = "var(--green)";
  }
  // Update apply button state
  const applyBtn = document.getElementById("af-apply-btn");
  if (applyBtn) {
    applyBtn.disabled = totalAssigned === 0;
    applyBtn.style.opacity = totalAssigned === 0 ? "0.5" : "1";
  }
}

function afClearAll() {
  // Remove all AF assignments and deactivate corresponding BSS vars
  Object.keys(_afAssignments).forEach(basinKey => {
    Object.keys(_afAssignments[basinKey] || {}).forEach(vid => {
      _bssSetActive_forKey(basinKey, vid, false);
    });
  });
  _afAssignments = {};
  _afPersist();
  _bssPersist();
  afRefresh();
  toast("All formula assignments cleared", "info");
}

function afApplyAndRun() {
  const totalAssigned = Object.values(_afAssignments)
    .reduce((s, bv) => s + Object.values(bv).filter(Boolean).length, 0);
  if (totalAssigned === 0) {
    toast("Assign at least one formula to a basin first", "warn");
    return;
  }
  // Ensure all assigned formulas are activated in BSS state
  Object.keys(_afAssignments).forEach(basinKey => {
    Object.entries(_afAssignments[basinKey] || {}).forEach(([vid, assignment]) => {
      if (!assignment) return;
      const srcSaved = (_bssBasinSaved[assignment.basinKey] || {})[vid] || [];
      const f = srcSaved.find(x => x.name === assignment.name);
      if (f) {
        if (!_bssBasinState[basinKey]) _bssBasinState[basinKey] = {};
        if (!_bssBasinMode[basinKey])  _bssBasinMode[basinKey]  = {};
        _bssBasinState[basinKey][vid] = JSON.parse(JSON.stringify(f.state));
        _bssBasinMode[basinKey][vid]  = f.mode || "builder";
        _bssSetActive_forKey(basinKey, vid, true);
      }
    });
  });
  _bssPersist();

  // Update apply description
  const descEl = document.getElementById("af-apply-desc");
  if (descEl) descEl.textContent = `Applying ${totalAssigned} formula assignment(s)…`;

  // Delegate to BSS screening engine
  bssApplyToScreening();
}

// ── Basin Scoring Formula (BSF) Logic ─────────────────────────────
