// Default sub-variable weights (how much each sub-var contributes to its element score)
const _bsfSubWeightDefaults = {
  src:  { toc:30, ro:25, hi:20, thickness:10, heat_flow:8, expulsion:7 },
  res:  { porosity:28, perm:25, ntg:18, depth:12, sw:10, fractures:7 },
  seal: { thickness:20, capillary:25, ductility:18, fault:15, paleo:12, op_margin:10 },
  chg:  { proximity:22, timing:22, volume:20, migration:18, phase:10, direct:8 },
  com:  { fiscal:22, breakeven:22, infra:18, water_d:14, mfs:14, esg:10 },
  cty:  { stability:22, cpi:18, contract:18, expropr:17, security:15, edb:10 },
};
let _bsfSubWeights = JSON.parse(JSON.stringify(_bsfSubWeightDefaults));

// Current sub-variable values used for live preview
const _bsfSubVals = {};
Object.keys(_bsfSubVars).forEach(eid => {
  _bsfSubVals[eid] = {};
  _bsfSubVars[eid].forEach(sv => { _bsfSubVals[eid][sv.id] = sv.def; });
});

// Whether sub-variable mode is active (drives element scores from sub-vars)
let _bsfSubVarMode = false;

let _bsfMode = "weighted";
let _bsfWeights = { src:25, res:25, seal:15, chg:15, com:10, cty:10 };
let _bsfTransforms = { src:"linear", res:"linear", seal:"linear", chg:"linear", com:"linear", cty:"linear" };
let _bsfPreviewVals = { src:70, res:65, seal:55, chg:60, com:50, cty:45 };
let _bsfInited = false;
let _bsfSaved = JSON.parse(localStorage.getItem?.("bsf_saved") || "[]") || [];

function bsfInit() {
  if (_bsfInited) { bsfUpdatePreview(); return; }
  _bsfInited = true;
  // Build weight sliders
  const grid = document.getElementById("bsf-sliders-grid");
  if (grid) {
    grid.innerHTML = _bsfElements.map(e => `
      <div style="background:var(--bg4);border:1px solid var(--b1);border-radius:6px;padding:10px 12px">
        <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px">
          <span style="font-size:10px;letter-spacing:1px;text-transform:uppercase;color:${e.color}">${e.label}</span>
          <span style="font-size:13px;font-weight:700;color:${e.color}" id="bsf-wt-lbl-${e.id}">${e.defaultWt}%</span>
        </div>
        <input type="range" class="slider" min="0" max="60" step="1" value="${e.defaultWt}" id="bsf-wt-${e.id}"
          oninput="_bsfWeights['${e.id}']=+this.value;document.getElementById('bsf-wt-lbl-${e.id}').textContent=this.value+'%';bsfUpdatePreview()">
      </div>`).join("");
  }
  // Build transforms
  const tGrid = document.getElementById("bsf-transforms");
  if (tGrid) {
    tGrid.innerHTML = _bsfElements.map(e => `
      <div style="background:var(--bg4);border:1px solid var(--b1);border-radius:5px;padding:7px 9px">
        <div style="font-size:10px;color:${e.color};text-transform:uppercase;letter-spacing:1px;margin-bottom:4px">${e.label}</div>
        <select class="fc" style="width:100%;font-size:10px;padding:3px 6px" id="bsf-tr-${e.id}"
          onchange="_bsfTransforms['${e.id}']=this.value;bsfUpdatePreview()">
          <option value="linear">Linear</option>
          <option value="sqrt">√ Square Root</option>
          <option value="square">² Square</option>
          <option value="log">log₁₀</option>
        </select>
      </div>`).join("");
  }
  // Build preview input sliders
  const pGrid = document.getElementById("bsf-preview-inputs");
  if (pGrid) {
    pGrid.innerHTML = _bsfElements.map(e => `
      <div style="background:var(--bg4);border:1px solid var(--b1);border-radius:5px;padding:7px 10px">
        <div style="display:flex;justify-content:space-between;margin-bottom:4px">
          <span style="font-size:10px;color:${e.color}">${e.label}</span>
          <span style="font-size:11px;font-weight:700;color:${e.color}" id="bsf-pv-lbl-${e.id}">${_bsfPreviewVals[e.id]}</span>
        </div>
        <input type="range" class="slider" min="0" max="100" step="1" value="${_bsfPreviewVals[e.id]}" id="bsf-pv-${e.id}"
          oninput="_bsfPreviewVals['${e.id}']=+this.value;document.getElementById('bsf-pv-lbl-${e.id}').textContent=this.value;bsfUpdatePreview()">
      </div>`).join("");
  }
  // Country risk penalty mode listener
  const ctyMode = document.getElementById("bsf-cty-mode");
  if (ctyMode) {
    ctyMode.addEventListener("change", function() {
      const gw = document.getElementById("bsf-cty-gate-wrap");
      if (gw) gw.style.display = this.value === "gate" ? "block" : "none";
      bsfUpdatePreview();
    });
  }
  // Build Sub-Variable panels
  bsfBuildSubVarPanels();
  bsfLoadSavedChips();
  bsfUpdatePreview();
}

// ── Compute a single element score from its sub-variables ──────────
function bsfComputeElementFromSubVars(eid) {
  const svList = _bsfSubVars[eid];
  if (!svList) return 50;
  const wts = _bsfSubWeights[eid];
  let totalWt = svList.reduce((s,sv) => s + (wts[sv.id]||0), 0) || 1;
  let score = 0;
  svList.forEach(sv => {
    const rawVal = _bsfSubVals[eid][sv.id] ?? sv.def;
    // Normalise each sub-var to 0–100 scale
    let norm = ((rawVal - sv.min) / (sv.max - sv.min || 1)) * 100;
    // For depth/breakeven/water_depth/proximity: invert (lower = better)
    if (["depth","breakeven","water_d","proximity"].includes(sv.id)) norm = 100 - norm;
    norm = Math.max(0, Math.min(100, norm));
    score += (wts[sv.id]||0) / totalWt * norm;
  });
  return Math.max(0, Math.min(100, score));
}

// ── Build sub-variable accordion panels ──────────────────────────
function bsfBuildSubVarPanels() {
  const cont = document.getElementById("bsf-subvar-panels");
  if (!cont) return;
  cont.innerHTML = _bsfElements.map(e => {
    const svList = _bsfSubVars[e.id] || [];
    const wts = _bsfSubWeights[e.id];
    const rows = svList.map(sv => `
      <div style="display:grid;grid-template-columns:1fr 36px 80px 40px;gap:6px;align-items:center;padding:5px 0;border-bottom:1px solid var(--b1)">
        <div>
          <div style="font-size:10px;font-weight:600;color:var(--t1)">${sv.label}
            <span style="font-size:10px;color:var(--t3);font-weight:400">(${sv.unit})</span>
          </div>
          <div style="font-size:10px;color:var(--t3)">${sv.tip}</div>
        </div>
        <div style="font-size:10px;color:${e.color};font-weight:700;text-align:right" id="bsf-sv-wt-lbl-${e.id}-${sv.id}">${wts[sv.id]||0}%</div>
        <input type="range" class="slider" min="0" max="50" step="1" value="${wts[sv.id]||0}"
          id="bsf-sv-wt-${e.id}-${sv.id}"
          oninput="_bsfSubWeights['${e.id}']['${sv.id}']=+this.value;document.getElementById('bsf-sv-wt-lbl-${e.id}-${sv.id}').textContent=this.value+'%';bsfSyncSubVarPreview()">
        <div style="font-size:10px;font-weight:700;color:var(--t2);text-align:right" id="bsf-sv-val-${e.id}-${sv.id}">${sv.def}</div>
      </div>`).join("");

    const previewRows = svList.map(sv => `
      <div style="display:grid;grid-template-columns:110px 1fr 32px;gap:8px;align-items:center;margin-bottom:3px">
        <span style="font-size:10px;color:var(--t2)">${sv.label}</span>
        <input type="range" class="slider" min="${sv.min}" max="${sv.max}" step="${sv.step}" value="${sv.def}"
          id="bsf-sv-pv-${e.id}-${sv.id}"
          oninput="_bsfSubVals['${e.id}']['${sv.id}']=+this.value;document.getElementById('bsf-sv-val-${e.id}-${sv.id}').textContent=(+this.value).toFixed(1);bsfSyncSubVarPreview()">
        <span style="font-size:10px;font-weight:700;color:${e.color}" id="bsf-sv-pv-lbl-${e.id}-${sv.id}">${sv.def}</span>
      </div>`).join("");

    return `
    <div style="border:1px solid ${e.color.replace('var(--','rgba(').replace(')',',0.25)')};border-radius:7px;margin-bottom:10px;overflow:hidden">
      <div style="display:flex;align-items:center;gap:8px;padding:9px 12px;background:${e.color.replace('var(--','rgba(').replace(')',',0.07)')};cursor:pointer"
        onclick="bsfToggleSubVarPanel('${e.id}')">
        <span style="font-size:10px;font-weight:700;color:${e.color}">${e.label}</span>
        <span style="font-size:10px;color:var(--t3);flex:1">${svList.length} sub-variables</span>
        <span style="font-size:11px;color:var(--t3);font-weight:700;transition:transform 0.2s" id="bsf-sv-chev-${e.id}">▾</span>
        <span style="font-size:11px;font-weight:900;color:${e.color}" id="bsf-sv-el-score-${e.id}">—</span>
      </div>
      <div id="bsf-sv-panel-${e.id}" style="display:none;padding:10px 13px">
        <div style="font-size:10px;letter-spacing:1px;text-transform:uppercase;color:var(--t3);margin-bottom:8px">Sub-Variable Weights (contribution to ${e.label} score)</div>
        ${rows}
        <div style="margin-top:12px;padding-top:10px;border-top:1px solid var(--b1)">
          <div style="font-size:10px;letter-spacing:1px;text-transform:uppercase;color:var(--t3);margin-bottom:8px">Preview Inputs</div>
          ${previewRows}
        </div>
      </div>
    </div>`;
  }).join("");
  bsfSyncSubVarPreview();
}

function bsfToggleSubVarPanel(eid) {
  const panel = document.getElementById("bsf-sv-panel-" + eid);
  const chev  = document.getElementById("bsf-sv-chev-" + eid);
  if (!panel) return;
  const open = panel.style.display !== "none";
  panel.style.display = open ? "none" : "block";
  if (chev) chev.style.transform = open ? "" : "rotate(180deg)";
}

function bsfSyncSubVarPreview() {
  // Update element scores derived from sub-vars
  _bsfElements.forEach(e => {
    const score = bsfComputeElementFromSubVars(e.id);
    const lbl = document.getElementById("bsf-sv-el-score-" + e.id);
    if (lbl) lbl.textContent = score.toFixed(1);
    // If sub-var mode active, propagate to main preview vals
    if (_bsfSubVarMode) {
      _bsfPreviewVals[e.id] = score;
      const pvEl = document.getElementById("bsf-pv-" + e.id);
      if (pvEl) { pvEl.value = score; document.getElementById("bsf-pv-lbl-" + e.id).textContent = score.toFixed(1); }
    }
  });
  if (_bsfSubVarMode) bsfUpdatePreview();
}

function bsfApplyTransform(val, tr) {
  const v = Math.max(0, Math.min(100, val));
  if (tr === "sqrt")   return Math.sqrt(v / 100) * 100;
  if (tr === "square") return (v / 100) * (v / 100) * 100;
  if (tr === "log")    return v > 0 ? Math.log10(v + 1) / Math.log10(101) * 100 : 0;
  return v; // linear
}

function bsfComputeScore(vals) {
  const tv = {};
  _bsfElements.forEach(e => { tv[e.id] = bsfApplyTransform(vals[e.id], _bsfTransforms[e.id]); });
  const ctyModeVal = document.getElementById("bsf-cty-mode")?.value || "additive";

  if (_bsfMode === "custom") {
    try {
      const expr = document.getElementById("bsf-custom-expr")?.value || "";
      const fn = new Function("src","res","seal","chg","com","cty",
        "return " + expr + ";");
      const raw = fn(tv.src, tv.res, tv.seal, tv.chg, tv.com, tv.cty);
      return Math.max(0, Math.min(100, +raw || 0));
    } catch(e) { return NaN; }
  }

  let totalWt = _bsfElements.reduce((s,e) => s + (_bsfWeights[e.id]||0), 0) || 1;
  // For multiplier/gate cty modes, remove cty from weighted sum
  let elems = [..._bsfElements];
  if (ctyModeVal !== "additive") {
    elems = elems.filter(e => e.id !== "cty");
    totalWt = elems.reduce((s,e) => s + (_bsfWeights[e.id]||0), 0) || 1;
  }

  let score;
  if (_bsfMode === "geometric") {
    const logSum = elems.reduce((s,e) => {
      const w = (_bsfWeights[e.id]||0) / totalWt;
      return s + w * Math.log(Math.max(0.01, tv[e.id]));
    }, 0);
    score = Math.exp(logSum);
  } else {
    score = elems.reduce((s,e) => s + (_bsfWeights[e.id]||0) / totalWt * tv[e.id], 0);
  }

  if (ctyModeVal === "multiplier") {
    score = score * (tv.cty / 100);
  } else if (ctyModeVal === "gate") {
    const gate = +(document.getElementById("bsf-cty-gate-val")?.value||30);
    if (vals.cty < gate) score = 0;
  }

  return Math.max(0, Math.min(100, score));
}

function bsfBuildFormulaStr() {
  if (_bsfMode === "custom") return document.getElementById("bsf-custom-expr")?.value || "custom";
  const totalWt = _bsfElements.reduce((s,e) => s + (_bsfWeights[e.id]||0), 0) || 1;
  const ctyMode = document.getElementById("bsf-cty-mode")?.value || "additive";
  let parts = _bsfElements
    .filter(e => ctyMode === "additive" || e.id !== "cty")
    .filter(e => _bsfWeights[e.id] > 0)
    .map(e => {
      const wf = ((_bsfWeights[e.id]||0)/totalWt).toFixed(2);
      const tr = _bsfTransforms[e.id] !== "linear" ? `${_bsfTransforms[e.id]}(${e.id})` : e.id;
      return `${wf}·${tr}`;
    });
  let formula = (_bsfMode === "geometric" ? "exp(Σ wᵢ·log(xᵢ))" : parts.join(" + "));
  if (ctyMode === "multiplier") formula = `(${formula}) × (cty/100)`;
  if (ctyMode === "gate") {
    const g = document.getElementById("bsf-cty-gate-val")?.value || 30;
    formula = `(${formula})  [cty ≥ ${g} required]`;
  }
  return "Score = " + formula;
}

function bsfUpdatePreview() {
  const score = bsfComputeScore(_bsfPreviewVals);
  const scoreEl = document.getElementById("bsf-preview-score");
  if (scoreEl) {
    scoreEl.textContent = isNaN(score) ? "Err" : score.toFixed(1);
    scoreEl.style.color = score >= 70 ? "var(--green)" : score >= 40 ? "var(--amber)" : "var(--red)";
  }
  const dispEl = document.getElementById("bsf-formula-display");
  if (dispEl) dispEl.textContent = bsfBuildFormulaStr();
}

function bsfSetMode(mode, btn) {
  _bsfMode = mode;
  document.querySelectorAll(".btn2[id^='bsf-mode-']").forEach(b => {
    b.style.background = ""; b.style.color = "";
  });
  if (btn) { btn.style.background = "var(--brand)"; btn.style.color = "#fff"; }
  const customWrap = document.getElementById("bsf-custom-expr-wrap");
  const slidersGrid = document.getElementById("bsf-sliders-grid");
  if (customWrap) customWrap.style.display = mode === "custom" ? "block" : "none";
  if (slidersGrid) slidersGrid.style.display = mode === "custom" ? "none" : "grid";
  bsfUpdatePreview();
}

function bsfSaveFormula() {
  const name = prompt("Name this formula:");
  if (!name) return;
  const formula = {
    name, mode: _bsfMode,
    weights: {..._bsfWeights},
    transforms: {..._bsfTransforms},
    customExpr: document.getElementById("bsf-custom-expr")?.value || "",
    ctyMode: document.getElementById("bsf-cty-mode")?.value || "additive",
    ctyGate: document.getElementById("bsf-cty-gate-val")?.value || 30,
    savedAt: new Date().toLocaleDateString()
  };
  // Remove duplicate names
  _bsfSaved = _bsfSaved.filter(f => f.name !== name);
  _bsfSaved.push(formula);
  try { localStorage.setItem("bsf_saved", JSON.stringify(_bsfSaved)); } catch(e){}
  bsfLoadSavedChips();
  // Update saved indicator
  const ind = document.getElementById("bsf-last-saved-lbl");
  if (ind) ind.textContent = "Last saved: " + name + " · " + new Date().toLocaleTimeString();
  toast("Formula saved: " + name + " — click \u25b6 Apply to Leaderboard to re-rank", "success");
}

function bsfResetFormula() {
  _bsfWeights = { src:25, res:25, seal:15, chg:15, com:10, cty:10 };
  _bsfTransforms = { src:"linear", res:"linear", seal:"linear", chg:"linear", com:"linear", cty:"linear" };
  _bsfMode = "weighted";
  _bsfElements.forEach(e => {
    const s = document.getElementById("bsf-wt-" + e.id);
    if (s) { s.value = e.defaultWt; document.getElementById("bsf-wt-lbl-" + e.id).textContent = e.defaultWt + "%"; }
    const tr = document.getElementById("bsf-tr-" + e.id);
    if (tr) tr.value = "linear";
  });
  bsfSetMode("weighted", document.getElementById("bsf-mode-weighted"));
  bsfUpdatePreview();
  toast("Formula reset to EDAFY defaults", "success");
}

function bsfLoadFormula(f) {
  _bsfMode = f.mode || "weighted";
  if (f.weights) Object.assign(_bsfWeights, f.weights);
  if (f.transforms) Object.assign(_bsfTransforms, f.transforms);
  _bsfElements.forEach(e => {
    const s = document.getElementById("bsf-wt-" + e.id);
    if (s) { s.value = _bsfWeights[e.id]; document.getElementById("bsf-wt-lbl-" + e.id).textContent = _bsfWeights[e.id] + "%"; }
    const tr = document.getElementById("bsf-tr-" + e.id);
    if (tr) tr.value = _bsfTransforms[e.id] || "linear";
  });
  if (f.customExpr) { const ce = document.getElementById("bsf-custom-expr"); if (ce) ce.value = f.customExpr; }
  const cm = document.getElementById("bsf-cty-mode"); if (cm && f.ctyMode) { cm.value = f.ctyMode; cm.dispatchEvent(new Event("change")); }
  const cg = document.getElementById("bsf-cty-gate-val"); if (cg && f.ctyGate) { cg.value = f.ctyGate; document.getElementById("bsf-cty-gate-lbl").textContent = f.ctyGate; }
  bsfSetMode(_bsfMode, document.getElementById("bsf-mode-" + _bsfMode));
  toast("Loaded formula: " + f.name, "success");
}

function bsfDeleteFormula(idx) {
  _bsfSaved.splice(idx, 1);
  try { localStorage.setItem("bsf_saved", JSON.stringify(_bsfSaved)); } catch(e){}
  bsfLoadSavedChips();
}

