let _vscoreInited = false;
// Working values for vscore tab (start from sub-var defaults)
const _vscoreVals = {};

function switchBsfInnerTab(tab, el) {
  ["builder","scoring","source","reservoir","seal","charge","commercial","cntry"].forEach(t => {
    const p = document.getElementById("bsf-inner-" + t);
    if (p) p.style.display = t === tab ? "block" : "none";
  });
  if (el) {
    el.closest("#bsf-inner-tabs").querySelectorAll(".tab")
      .forEach(t => t.classList.remove("on"));
    el.classList.add("on");
  }
  if (tab === "scoring") vscoreInit();
  const vfMap = {source:"src",reservoir:"res",seal:"seal",charge:"chg",commercial:"com",cntry:"cty"};
  if (vfMap[tab]) bsfVfInit(vfMap[tab], tab);
}

