// State store for VF tab configs
const _vfState = {};
const _vfColors = { src:"var(--green)", res:"var(--blue)", seal:"var(--cyan)", chg:"var(--purple)", com:"var(--amber)", cty:"var(--red)" };
const _vfTabIds  = { src:"source", res:"reservoir", seal:"seal", chg:"charge", com:"commercial", cty:"cntry" };

function bsfVfInit(eid, tabId) {
  const cont = document.getElementById("bsf-vf-" + tabId);
  if (!cont || cont._vfBuilt) { bsfVfComputeAll(eid, tabId); return; }
  cont._vfBuilt = true;

  const vars = _vfExtended[eid] || [];
  if (!_vfState[eid]) {
    _vfState[eid] = {};
    vars.forEach(sv => {
      _vfState[eid][sv.id] = { fn: sv.inv ? "inv_linear" : "linear", weight: Math.round(100/vars.length), val: sv.def, params: {} };
    });
  }

  let html = `<div style="display:grid;grid-template-columns:repeat(2,1fr);gap:10px;margin-bottom:12px">`;
  vars.forEach(sv => {
    const st = _vfState[eid][sv.id];
    const color = _vfColors[eid];
    html += `
    <div style="background:var(--bg4);border:1px solid var(--b1);border-radius:7px;padding:10px 12px">
      <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:6px">
        <div>
          <span style="font-size:11px;font-weight:700;color:${color}">${sv.label}</span>
          <span style="font-size:10px;color:var(--t3);margin-left:5px">${sv.unit}</span>
          ${sv.inv ? `<span style="font-size:10px;padding:1px 5px;border-radius:2px;background:rgba(239,68,68,0.1);color:var(--red);margin-left:4px">INV</span>` : ''}
        </div>
        <div style="display:flex;align-items:center;gap:5px">
          <span style="font-size:10px;color:var(--t3)">Wt:</span>
          <input type="number" min="0" max="100" step="1" value="${st.weight}"
            style="width:40px;font-size:10px;padding:2px 4px;background:var(--bg3);border:1px solid var(--b1);border-radius:3px;color:var(--t1);text-align:center"
            onchange="_vfState['${eid}']['${sv.id}'].weight=+this.value;bsfVfComputeAll('${eid}','${tabId}')">
          <span style="font-size:10px;color:var(--t3)">%</span>
        </div>
      </div>
      <div style="font-size:10px;color:var(--t3);margin-bottom:7px;line-height:1.4">${sv.tip}</div>
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:6px;margin-bottom:7px">
        <div>
          <div style="font-size:10px;color:var(--t3);margin-bottom:3px">Scoring Function</div>
          <select style="width:100%;font-size:10px;padding:3px 5px;background:var(--bg3);border:1px solid var(--b1);border-radius:3px;color:var(--t1)"
            onchange="_vfState['${eid}']['${sv.id}'].fn=this.value;bsfVfUpdateParamPanel('${eid}','${sv.id}','${tabId}');bsfVfComputeAll('${eid}','${tabId}')"
            id="vf-fn-${eid}-${sv.id}">
            ${_vfFunctions.map(f => `<option value="${f.id}" ${st.fn===f.id?'selected':''}>${f.label}</option>`).join('')}
          </select>
        </div>
        <div>
          <div style="font-size:10px;color:var(--t3);margin-bottom:3px">Preview Value</div>
          <div style="display:flex;align-items:center;gap:4px">
            <input type="range" min="${sv.min}" max="${sv.max}" step="${sv.step}" value="${sv.def}"
              style="flex:1;accent-color:${color}"
              oninput="this.nextElementSibling.textContent=this.value;_vfState['${eid}']['${sv.id}'].val=+this.value;bsfVfComputeAll('${eid}','${tabId}')"
              id="vf-val-${eid}-${sv.id}">
            <span style="font-size:10px;color:${color};min-width:30px;text-align:right;font-weight:700" id="vf-val-lbl-${eid}-${sv.id}">${sv.def}</span>
          </div>
        </div>
      </div>
      <!-- Advanced params panel -->
      <div id="vf-params-${eid}-${sv.id}" style="margin-bottom:6px"></div>
      <!-- Per-variable score output -->
      <div style="display:flex;align-items:center;gap:6px;padding:4px 6px;background:var(--bg3);border-radius:4px">
        <span style="font-size:10px;color:var(--t3)">Sub-score:</span>
        <div style="flex:1;background:rgba(0,0,0,0.2);border-radius:3px;height:5px;overflow:hidden">
          <div id="vf-bar-${eid}-${sv.id}" style="height:100%;background:${color};width:50%;transition:width 0.3s"></div>
        </div>
        <span id="vf-sub-${eid}-${sv.id}" style="font-size:10px;font-weight:700;color:${color};min-width:28px;text-align:right">—</span>
      </div>
    </div>`;
  });
  html += `</div>`;

  // Weight normalisation notice + function reference
  html += `
  <div style="padding:8px 10px;background:rgba(8,145,178,0.04);border:1px dashed rgba(8,145,178,0.2);border-radius:5px;margin-bottom:10px;display:flex;align-items:center;gap:10px;flex-wrap:wrap">
    <span style="font-size:10px;color:var(--t3);flex:1">Weights are <strong style="color:var(--cyan)">auto-normalised</strong> to sum to 100%. Individual sub-scores are combined as a weighted average → element score 0–100.</span>
    <span id="vf-wt-total-${eid}" style="font-size:10px;font-weight:700;color:var(--amber)">Σ wt = ?</span>
    <button class="btn2" style="font-size:10px;padding:3px 9px" onclick="bsfVfEqualWeights('${eid}','${tabId}')">= Equal</button>
  </div>

  <!-- Function Reference Panel -->
  <div style="margin-bottom:10px">
    <div style="font-size:10px;letter-spacing:1px;text-transform:uppercase;color:var(--t2);margin-bottom:6px">Scoring Function Reference</div>
    <div style="display:grid;grid-template-columns:repeat(3,1fr);gap:5px">
      ${_vfFunctions.map(f => `
      <div style="padding:5px 7px;background:var(--bg4);border:1px solid var(--b1);border-radius:4px">
        <div style="font-size:10px;font-weight:700;color:${_vfColors[eid]}">${f.label}</div>
        <div style="font-size:10px;color:var(--t3);font-family:monospace;margin-top:2px">${f.desc}</div>
      </div>`).join('')}
    </div>
  </div>`;

  cont.innerHTML = html;
  vars.forEach(sv => bsfVfUpdateParamPanel(eid, sv.id, tabId));
  bsfVfComputeAll(eid, tabId);
}

function bsfVfUpdateParamPanel(eid, svId, tabId) {
  const cont = document.getElementById(`vf-params-${eid}-${svId}`);
  if (!cont) return;
  const fn = _vfState[eid][svId].fn;
  const sv = (_vfExtended[eid]||[]).find(s=>s.id===svId);
  if (!sv) return;
  const params = _vfState[eid][svId].params || {};
  const color = _vfColors[eid];
  let html = '';
  if (fn === 'sigmoid') {
    const k = params.k || 0.1, mid = params.mid || ((sv.max+sv.min)/2);
    html = `<div style="display:grid;grid-template-columns:1fr 1fr;gap:5px">
      <div><div style="font-size:10px;color:var(--t3)">Steepness k</div>
      <input type="range" min="0.01" max="1" step="0.01" value="${k}" style="width:100%;accent-color:${color}"
        oninput="this.nextElementSibling.textContent=this.value;_vfState['${eid}']['${svId}'].params.k=+this.value;bsfVfComputeAll('${eid}','${tabId}')">
      <span style="font-size:10px;color:${color}">${k}</span></div>
      <div><div style="font-size:10px;color:var(--t3)">Midpoint</div>
      <input type="range" min="${sv.min}" max="${sv.max}" step="${sv.step}" value="${mid}" style="width:100%;accent-color:${color}"
        oninput="this.nextElementSibling.textContent=this.value;_vfState['${eid}']['${svId}'].params.mid=+this.value;bsfVfComputeAll('${eid}','${tabId}')">
      <span style="font-size:10px;color:${color}">${mid}</span></div>
    </div>`;
  } else if (fn === 'step') {
    const thresh = params.thresh || ((sv.max+sv.min)/2);
    html = `<div><div style="font-size:10px;color:var(--t3)">Threshold</div>
      <input type="range" min="${sv.min}" max="${sv.max}" step="${sv.step}" value="${thresh}" style="width:100%;accent-color:${color}"
        oninput="this.nextElementSibling.textContent=this.value;_vfState['${eid}']['${svId}'].params.thresh=+this.value;bsfVfComputeAll('${eid}','${tabId}')">
      <span style="font-size:10px;color:${color}">${thresh}</span></div>`;
  } else if (fn === 'trapezoid') {
    const lo1=params.lo1||sv.min, lo2=params.lo2||(sv.min+(sv.max-sv.min)*0.25),
          hi1=params.hi1||(sv.min+(sv.max-sv.min)*0.75), hi2=params.hi2||sv.max;
    html = `<div style="display:grid;grid-template-columns:1fr 1fr;gap:5px">
      ${[['lo1','Ramp Start',lo1],['lo2','Plateau Lo',lo2],['hi1','Plateau Hi',hi1],['hi2','Ramp End',hi2]].map(([k,lbl,v])=>`
      <div><div style="font-size:10px;color:var(--t3)">${lbl}</div>
      <input type="range" min="${sv.min}" max="${sv.max}" step="${sv.step}" value="${v}" style="width:100%;accent-color:${color}"
        oninput="this.nextElementSibling.textContent=this.value;_vfState['${eid}']['${svId}'].params.${k}=+this.value;bsfVfComputeAll('${eid}','${tabId}')">
      <span style="font-size:10px;color:${color}">${v}</span></div>`).join('')}
    </div>`;
  } else if (fn === 'gaussian') {
    const peak=params.peak||((sv.max+sv.min)/2), sigma=params.sigma||((sv.max-sv.min)/6);
    html = `<div style="display:grid;grid-template-columns:1fr 1fr;gap:5px">
      <div><div style="font-size:10px;color:var(--t3)">Peak (μ)</div>
      <input type="range" min="${sv.min}" max="${sv.max}" step="${sv.step}" value="${peak}" style="width:100%;accent-color:${color}"
        oninput="this.nextElementSibling.textContent=this.value;_vfState['${eid}']['${svId}'].params.peak=+this.value;bsfVfComputeAll('${eid}','${tabId}')">
      <span style="font-size:10px;color:${color}">${peak}</span></div>
      <div><div style="font-size:10px;color:var(--t3)">Width (σ)</div>
      <input type="range" min="0.1" max="${(sv.max-sv.min)}" step="${sv.step}" value="${sigma}" style="width:100%;accent-color:${color}"
        oninput="this.nextElementSibling.textContent=this.value;_vfState['${eid}']['${svId}'].params.sigma=+this.value;bsfVfComputeAll('${eid}','${tabId}')">
      <span style="font-size:10px;color:${color}">${sigma.toFixed(1)}</span></div>
    </div>`;
  } else if (fn === 'clamp') {
    const clo=params.clo||(sv.min+(sv.max-sv.min)*0.3), chi=params.chi||(sv.min+(sv.max-sv.min)*0.8);
    html = `<div style="display:grid;grid-template-columns:1fr 1fr;gap:5px">
      <div><div style="font-size:10px;color:var(--t3)">Range Low</div>
      <input type="range" min="${sv.min}" max="${sv.max}" step="${sv.step}" value="${clo}" style="width:100%;accent-color:${color}"
        oninput="this.nextElementSibling.textContent=this.value;_vfState['${eid}']['${svId}'].params.clo=+this.value;bsfVfComputeAll('${eid}','${tabId}')">
      <span style="font-size:10px;color:${color}">${clo}</span></div>
      <div><div style="font-size:10px;color:var(--t3)">Range High</div>
      <input type="range" min="${sv.min}" max="${sv.max}" step="${sv.step}" value="${chi}" style="width:100%;accent-color:${color}"
        oninput="this.nextElementSibling.textContent=this.value;_vfState['${eid}']['${svId}'].params.chi=+this.value;bsfVfComputeAll('${eid}','${tabId}')">
      <span style="font-size:10px;color:${color}">${chi}</span></div>
    </div>`;
  }
  cont.innerHTML = html;
}

function bsfVfScore(fn, val, sv, params) {
  const range = sv.max - sv.min;
  const n = range > 0 ? (val - sv.min) / range : 0;
  const nc = Math.max(0, Math.min(1, n));
  switch (fn) {
    case 'linear':    return nc * 100;
    case 'log':       return (range>0 ? Math.log(val-sv.min+1)/Math.log(range+1) : 0) * 100;
    case 'sqrt':      return Math.sqrt(nc) * 100;
    case 'power2':    return nc * nc * 100;
    case 'inv_linear':return (1-nc) * 100;
    case 'inv_log':   return (1 - (range>0 ? Math.log(val-sv.min+1)/Math.log(range+1) : 0)) * 100;
    case 'sigmoid': {
      const k = params.k||0.1, mid = params.mid||((sv.max+sv.min)/2);
      return 100/(1+Math.exp(-k*(val-mid)));
    }
    case 'step': {
      const t = params.thresh||((sv.max+sv.min)/2);
      return val >= t ? 100 : 0;
    }
    case 'trapezoid': {
      const lo1=params.lo1||sv.min, lo2=params.lo2||(sv.min+range*0.25),
            hi1=params.hi1||(sv.min+range*0.75), hi2=params.hi2||sv.max;
      if (val<=lo1||val>=hi2) return 0;
      if (val>=lo2&&val<=hi1) return 100;
      if (val<lo2) return 100*(val-lo1)/(lo2-lo1||1);
      return 100*(hi2-val)/(hi2-hi1||1);
    }
    case 'gaussian': {
      const peak=params.peak||((sv.max+sv.min)/2), sigma=params.sigma||range/6||1;
      return 100*Math.exp(-Math.pow(val-peak,2)/(2*sigma*sigma));
    }
    case 'clamp': {
      const clo=params.clo||(sv.min+range*0.3), chi=params.chi||(sv.min+range*0.8);
      if (val>=clo&&val<=chi) return 100;
      if (val<clo) return 100*Math.max(0,(val-sv.min)/(clo-sv.min||1));
      return 100*Math.max(0,(sv.max-val)/(sv.max-chi||1));
    }
    case 'percentile': return nc * 100; // approximation
    default: return nc * 100;
  }
}

function bsfVfComputeAll(eid, tabId) {
  const vars = _vfExtended[eid] || [];
  const state = _vfState[eid] || {};
  let totalWt = 0, weightedSum = 0;
  vars.forEach(sv => {
    const st = state[sv.id]; if (!st) return;
    totalWt += st.weight;
  });
  let formulaParts = [];
  vars.forEach(sv => {
    const st = state[sv.id]; if (!st) return;
    const rawScore = Math.max(0, Math.min(100, bsfVfScore(st.fn, st.val, sv, st.params||{})));
    const normWt = totalWt > 0 ? st.weight / totalWt : 1/vars.length;
    weightedSum += rawScore * normWt;
    const bar = document.getElementById(`vf-bar-${eid}-${sv.id}`);
    const lbl = document.getElementById(`vf-sub-${eid}-${sv.id}`);
    if (bar) bar.style.width = rawScore + '%';
    if (lbl) lbl.textContent = rawScore.toFixed(1);
    const fnLabel = (_vfFunctions.find(f=>f.id===st.fn)||{}).label || st.fn;
    formulaParts.push(`${(normWt*100).toFixed(0)}%·${fnLabel}(${sv.id})`);
  });
  const wt = document.getElementById(`vf-wt-total-${eid}`);
  if (wt) { wt.textContent = 'Σ wt = '+totalWt; wt.style.color = Math.abs(totalWt-100)<2 ? 'var(--green)' : 'var(--amber)'; }
  const scoreEl = document.getElementById(`bsf-vf-${tabId}-score`);
  const formulaEl = document.getElementById(`bsf-vf-${tabId}-formula`);
  if (scoreEl) scoreEl.textContent = weightedSum.toFixed(1);
  if (formulaEl) formulaEl.innerHTML = formulaParts.join(' + ') || '—';
}

function bsfVfEqualWeights(eid, tabId) {
  const vars = _vfExtended[eid] || [];
  const w = Math.round(100/vars.length);
  vars.forEach(sv => { if (_vfState[eid] && _vfState[eid][sv.id]) _vfState[eid][sv.id].weight = w; });
  // Update all weight inputs
  vars.forEach(sv => {
    const inp = document.querySelector(`#bsf-vf-${tabId} input[type=number]`);
  });
  // Re-render
  const cont = document.getElementById("bsf-vf-" + tabId);
  if (cont) { cont._vfBuilt = false; }
  bsfVfInit(eid, tabId);
  toast("Equal weights applied", "success");
}

function bsfVfReset(tabId) {
  const eidMap = { source:"src", reservoir:"res", seal:"seal", charge:"chg", commercial:"com", cntry:"cty" };
  const eid = eidMap[tabId];
  if (eid) {
    delete _vfState[eid];
    const cont = document.getElementById("bsf-vf-" + tabId);
    if (cont) { cont._vfBuilt = false; cont.innerHTML = ''; }
    bsfVfInit(eid, tabId);
    toast("Formula reset to defaults", "info");
  }
}

function bsfVfApply(tabId) {
  const eidMap = { source:"src", reservoir:"res", seal:"seal", charge:"chg", commercial:"com", cntry:"cty" };
  const eid = eidMap[tabId];
  if (!eid || !_vfState[eid]) return;
  // Push weights into _bsfSubWeights so the main BSF engine picks them up
  const vars = _vfExtended[eid] || [];
  let total = 0;
  vars.forEach(sv => { total += (_vfState[eid][sv.id]||{}).weight||0; });
  vars.forEach(sv => {
    const svId = sv.id;
    const normWt = total>0 ? Math.round((_vfState[eid][svId].weight/total)*100) : Math.round(100/vars.length);
    if (_bsfSubWeights[eid] && svId in _bsfSubWeights[eid]) {
      _bsfSubWeights[eid][svId] = normWt;
    }
  });
  bsfUpdatePreview();
  toast(`${tabId.charAt(0).toUpperCase()+tabId.slice(1)} formula applied to BSF`, "success");
}

function vscoreInit() {
  if (_vscoreInited) { vscoreCompute(); return; }
  _vscoreInited = true;

  // Seed working values from _bsfSubVars defaults
  Object.keys(_bsfSubVars).forEach(eid => {
    _vscoreVals[eid] = {};
    _bsfSubVars[eid].forEach(sv => { _vscoreVals[eid][sv.id] = sv.def; });
  });

  // Populate basin selector from leaderboardData / BASINS
  const sel = document.getElementById("vscore-basin-sel");
  if (sel) {
    const basins = (typeof leaderboardData !== "undefined" && leaderboardData.length)
      ? leaderboardData : (typeof BASINS !== "undefined" ? BASINS : []);
    basins.forEach(b => {
      const opt = document.createElement("option");
      opt.value = b.name; opt.textContent = b.name;
      sel.appendChild(opt);
    });
  }

  vscoreBuildElementPanels();
  vscoreCompute();
}

function vscoreBuildElementPanels() {
  const cont = document.getElementById("vscore-element-panels");
  if (!cont) return;

  cont.innerHTML = _bsfElements.map(e => {
    const svList = _bsfSubVars[e.id] || [];
    const rows = svList.map(sv => {
      const val = _vscoreVals[e.id]?.[sv.id] ?? sv.def;
      const isInverted = ["depth","breakeven","water_d","proximity"].includes(sv.id);
      return `
      <div style="display:grid;grid-template-columns:1fr 180px 46px 54px;gap:8px;align-items:center;padding:7px 0;border-bottom:1px solid rgba(255,255,255,0.04)">
        <div>
          <div style="font-size:10px;font-weight:600;color:var(--t1)">
            ${sv.label}
            <span style="font-size:10px;color:var(--t3);font-weight:400;margin-left:3px">${sv.unit}</span>
            ${isInverted ? '<span style="font-size:10px;color:var(--amber);margin-left:3px" title="Lower is better">↓ inv</span>' : ''}
          </div>
          <div style="font-size:10px;color:var(--t3);margin-top:1px">${sv.tip}</div>
        </div>
        <div style="display:flex;align-items:center;gap:6px">
          <input type="range" class="slider" min="${sv.min}" max="${sv.max}" step="${sv.step}" value="${val}"
            id="vs-slider-${e.id}-${sv.id}"
            style="flex:1"
            oninput="
              _vscoreVals['${e.id}']['${sv.id}']=+this.value;
              document.getElementById('vs-num-${e.id}-${sv.id}').value=(+this.value).toFixed(sv && sv.step<1?2:1);
              vscoreComputeAndRefresh();
            ">
        </div>
        <input type="number" class="fc" id="vs-num-${e.id}-${sv.id}"
          value="${val}" min="${sv.min}" max="${sv.max}" step="${sv.step}"
          style="font-size:10px;padding:3px 5px;text-align:right;width:100%"
          oninput="
            const v=Math.max(${sv.min},Math.min(${sv.max},+this.value||0));
            _vscoreVals['${e.id}']['${sv.id}']=v;
            document.getElementById('vs-slider-${e.id}-${sv.id}').value=v;
            vscoreComputeAndRefresh();
          ">
        <div id="vs-score-${e.id}-${sv.id}"
          style="font-size:11px;font-weight:700;text-align:right;color:${e.color}">—</div>
      </div>`;
    }).join("");

    return `
    <div style="border:1px solid ${e.color.replace('var(--','rgba(').replace(')',',0.3)')};border-radius:8px;margin-bottom:10px;overflow:hidden">
      <div style="display:flex;align-items:center;gap:10px;padding:10px 14px;background:${e.color.replace('var(--','rgba(').replace(')',',0.07)')};cursor:pointer"
        onclick="vsTogglePanel('${e.id}')">
        <span style="font-size:11px;font-weight:700;color:${e.color}">${e.label}</span>
        <span style="font-size:10px;color:var(--t3);flex:1">${svList.length} variables</span>
        <!-- Mini sub-score bars -->
        <div style="display:flex;gap:3px;align-items:flex-end;height:20px" id="vs-minibars-${e.id}"></div>
        <div style="display:flex;align-items:center;gap:6px">
          <div style="width:70px;height:5px;background:rgba(255,255,255,0.1);border-radius:3px">
            <div id="vs-el-bar-${e.id}" style="height:100%;background:${e.color};border-radius:3px;width:0%;transition:width 0.4s"></div>
          </div>
          <span id="vs-el-score-${e.id}" style="font-size:14px;font-weight:900;color:${e.color};min-width:32px;text-align:right">—</span>
        </div>
        <span id="vs-chev-${e.id}" style="font-size:10px;color:var(--t3);transition:transform 0.2s">▾</span>
      </div>
      <div id="vs-panel-${e.id}" style="display:none;padding:10px 16px">
        <!-- Column headers -->
        <div style="display:grid;grid-template-columns:1fr 180px 46px 54px;gap:8px;margin-bottom:6px;padding-bottom:6px;border-bottom:1px solid var(--b1)">
          <span style="font-size:10px;letter-spacing:1px;text-transform:uppercase;color:var(--t3)">Variable</span>
          <span style="font-size:10px;letter-spacing:1px;text-transform:uppercase;color:var(--t3)">Value</span>
          <span style="font-size:10px;letter-spacing:1px;text-transform:uppercase;color:var(--t3);text-align:right">Input</span>
          <span style="font-size:10px;letter-spacing:1px;text-transform:uppercase;color:var(--t3);text-align:right">Score</span>
        </div>
        ${rows}
        <!-- Element subtotal -->
        <div style="margin-top:10px;padding:8px 10px;background:${e.color.replace('var(--','rgba(').replace(')',',0.08)')};border-radius:5px;display:flex;justify-content:space-between;align-items:center">
          <span style="font-size:10px;font-weight:700;color:${e.color}">${e.label} Element Score</span>
          <div style="display:flex;align-items:center;gap:8px">
            <div style="width:100px;height:6px;background:rgba(255,255,255,0.1);border-radius:3px">
              <div id="vs-el-bar2-${e.id}" style="height:100%;background:${e.color};border-radius:3px;width:0%;transition:width 0.4s"></div>
            </div>
            <span id="vs-el-score2-${e.id}" style="font-size:18px;font-weight:900;color:${e.color}">—</span>
            <span style="font-size:10px;color:var(--t3)">/100</span>
          </div>
        </div>
      </div>
    </div>`;
  }).join("");
}

function vsTogglePanel(eid) {
  const p = document.getElementById("vs-panel-" + eid);
  const c = document.getElementById("vs-chev-" + eid);
  if (!p) return;
  const open = p.style.display !== "none";
  p.style.display = open ? "none" : "block";
  if (c) c.style.transform = open ? "" : "rotate(180deg)";
}

function vscoreNormaliseSV(sv, rawVal) {
  let norm = ((rawVal - sv.min) / ((sv.max - sv.min) || 1)) * 100;
  if (["depth","breakeven","water_d","proximity"].includes(sv.id)) norm = 100 - norm;
  return Math.max(0, Math.min(100, norm));
}

function vscoreComputeElementScore(eid) {
  const svList = _bsfSubVars[eid] || [];
  const wts = _bsfSubWeights[eid];
  const totalWt = svList.reduce((s,sv) => s + (wts[sv.id]||0), 0) || 1;
  let score = 0;
  const subScores = {};
  svList.forEach(sv => {
    const raw = _vscoreVals[eid]?.[sv.id] ?? sv.def;
    const norm = vscoreNormaliseSV(sv, raw);
    const transformed = bsfApplyTransform(norm, _bsfTransforms[eid] || "linear");
    subScores[sv.id] = { raw, norm, transformed, contribution: (wts[sv.id]||0) / totalWt * transformed };
    score += subScores[sv.id].contribution;
  });
  return { score: Math.max(0, Math.min(100, score)), subScores };
}

function vscoreCompute() {
  const elementResults = {};
  _bsfElements.forEach(e => {
    elementResults[e.id] = vscoreComputeElementScore(e.id);
  });

  // Build mapped vals for composite formula
  const mappedVals = {};
  _bsfElements.forEach(e => { mappedVals[e.id] = elementResults[e.id].score; });
  const composite = bsfComputeScore(mappedVals);

  // Update composite display
  const compEl = document.getElementById("vscore-composite");
  const tierEl = document.getElementById("vscore-tier");
  if (compEl) {
    compEl.textContent = isNaN(composite) ? "Err" : composite.toFixed(1);
    compEl.style.color = composite >= 70 ? "var(--green)" : composite >= 40 ? "var(--amber)" : "var(--red)";
  }
  if (tierEl) {
    tierEl.textContent = composite >= 70 ? "🟢 HIGH PRIORITY" : composite >= 40 ? "🟡 MEDIUM PRIORITY" : "🔴 LOW PRIORITY";
  }

  // Update element gauges
  vscoreUpdateElementGauges(elementResults, composite);

  // Update per-variable score cells and element bars
  _bsfElements.forEach(e => {
    const res = elementResults[e.id];
    const sv_score_lbl = document.getElementById("vs-el-score-" + e.id);
    const sv_score_lbl2 = document.getElementById("vs-el-score2-" + e.id);
    const bar = document.getElementById("vs-el-bar-" + e.id);
    const bar2 = document.getElementById("vs-el-bar2-" + e.id);
    if (sv_score_lbl) sv_score_lbl.textContent = res.score.toFixed(1);
    if (sv_score_lbl2) sv_score_lbl2.textContent = res.score.toFixed(1);
    if (bar) bar.style.width = res.score + "%";
    if (bar2) bar2.style.width = res.score + "%";

    // Per-sub-var score cells
    const svList = _bsfSubVars[e.id] || [];
    svList.forEach(sv => {
      const cell = document.getElementById("vs-score-" + e.id + "-" + sv.id);
      if (cell && res.subScores[sv.id]) {
        const ns = res.subScores[sv.id].norm;
        cell.textContent = ns.toFixed(0);
        cell.style.color = ns >= 70 ? "var(--green)" : ns >= 40 ? "var(--amber)" : "var(--red)";
      }
    });

    // Mini bars in header
    const minibarsCont = document.getElementById("vs-minibars-" + e.id);
    if (minibarsCont) {
      minibarsCont.innerHTML = svList.map(sv => {
        const ns = res.subScores[sv.id]?.norm ?? 0;
        const h = Math.max(2, Math.round(ns / 100 * 18));
        const col = ns >= 70 ? "var(--green)" : ns >= 40 ? "var(--amber)" : "var(--red)";
        return `<div title="${sv.label}: ${ns.toFixed(0)}" style="width:5px;height:${h}px;background:${col};border-radius:1px;opacity:0.8"></div>`;
      }).join("");
    }
  });

  // Waterfall
  vscoreRenderWaterfall(elementResults, composite);

  // Sensitivity
  vscoreRenderSensitivity(elementResults, composite);

  return { elementResults, composite };
}

function vscoreUpdateElementGauges(elementResults, composite) {
  const cont = document.getElementById("vscore-element-gauges");
  if (!cont) return;
  cont.innerHTML = _bsfElements.map(e => {
    const score = elementResults[e.id].score;
    const wt = _bsfWeights[e.id] || 0;
    const totalWt = _bsfElements.reduce((s,el) => s + (_bsfWeights[el.id]||0), 0) || 1;
    const contribution = (wt / totalWt * score).toFixed(1);
    const col = score >= 70 ? "var(--green)" : score >= 40 ? "var(--amber)" : "var(--red)";
    const arc = Math.round(score * 1.8); // 0-180 degrees
    return `
    <div onclick="vsTogglePanel('${e.id}')" style="background:var(--bg4);border:1px solid ${e.color.replace('var(--','rgba(').replace(')',',0.25)')};border-radius:8px;padding:10px 8px;text-align:center;cursor:pointer;transition:box-shadow 0.2s" onmouseover="this.style.boxShadow='0 0 0 1px ${e.color}'" onmouseout="this.style.boxShadow=''">
      <!-- Semi-circle gauge -->
      <div style="position:relative;width:64px;height:32px;margin:0 auto 6px;overflow:hidden">
        <svg width="64" height="32" viewBox="0 0 64 32">
          <path d="M4,32 A28,28 0 0,1 60,32" fill="none" stroke="rgba(255,255,255,0.07)" stroke-width="6" stroke-linecap="round"/>
          <path d="M4,32 A28,28 0 0,1 60,32" fill="none" stroke="${e.color}" stroke-width="6" stroke-linecap="round"
            stroke-dasharray="${arc * 0.98} 999" opacity="0.85"/>
        </svg>
        <div style="position:absolute;bottom:0;left:50%;transform:translateX(-50%);font-size:13px;font-weight:900;color:${col}">${score.toFixed(0)}</div>
      </div>
      <div style="font-size:10px;font-weight:700;color:${e.color};margin-bottom:2px">${e.label}</div>
      <div style="font-size:10px;color:var(--t3)">wt ${wt}% · +${contribution}</div>
    </div>`;
  }).join("");
}

function vscoreRenderWaterfall(elementResults, composite) {
  const cont = document.getElementById("vscore-waterfall");
  if (!cont) return;
  const totalWt = _bsfElements.reduce((s,e) => s + (_bsfWeights[e.id]||0), 0) || 1;
  const maxContrib = Math.max(..._bsfElements.map(e => (_bsfWeights[e.id]||0) / totalWt * elementResults[e.id].score));

  cont.innerHTML = `
  <div style="display:flex;flex-direction:column;gap:6px">
    ${_bsfElements.map(e => {
      const score = elementResults[e.id].score;
      const wt = (_bsfWeights[e.id]||0);
      const contrib = wt / totalWt * score;
      const barPct = maxContrib > 0 ? contrib / maxContrib * 100 : 0;
      const col = score >= 70 ? "var(--green)" : score >= 40 ? "var(--amber)" : "var(--red)";
      return `
      <div style="display:grid;grid-template-columns:100px 1fr 50px 55px;gap:8px;align-items:center">
        <span style="font-size:10px;font-weight:600;color:${e.color}">${e.label}</span>
        <div style="background:rgba(255,255,255,0.06);border-radius:3px;height:12px;overflow:hidden">
          <div style="width:${barPct}%;height:100%;background:${e.color};border-radius:3px;opacity:0.8;transition:width 0.4s"></div>
        </div>
        <span style="font-size:10px;font-weight:700;color:${col};text-align:right">${score.toFixed(0)}</span>
        <span style="font-size:10px;color:var(--t3);text-align:right">+${contrib.toFixed(1)} pts</span>
      </div>`;
    }).join("")}
    <div style="border-top:1px solid var(--b1);margin-top:4px;padding-top:8px;display:flex;justify-content:flex-end;align-items:center;gap:10px">
      <span style="font-size:10px;color:var(--t2);font-weight:600">Composite Total:</span>
      <span style="font-size:20px;font-weight:900;color:${composite>=70?"var(--green)":composite>=40?"var(--amber)":"var(--red)"}">${isNaN(composite)?"—":composite.toFixed(1)}</span>
      <span style="font-size:10px;color:var(--t3)">/100</span>
    </div>
  </div>`;
}

function vscoreRenderSensitivity(elementResults, composite) {
  const tbody = document.getElementById("vscore-sensitivity-tbody");
  if (!tbody) return;
  const rows = [];
  _bsfElements.forEach(e => {
    const svList = _bsfSubVars[e.id] || [];
    svList.forEach(sv => {
      const originalVal = _vscoreVals[e.id]?.[sv.id] ?? sv.def;
      const delta = (sv.max - sv.min) * 0.1;

      // +10% scenario
      _vscoreVals[e.id][sv.id] = Math.min(sv.max, originalVal + delta);
      const upResult = vscoreComputeElementScore(e.id);
      const mappedUp = {}; _bsfElements.forEach(el => mappedUp[el.id] = el.id === e.id ? upResult.score : elementResults[el.id].score);
      const upComposite = bsfComputeScore(mappedUp);

      // −10% scenario
      _vscoreVals[e.id][sv.id] = Math.max(sv.min, originalVal - delta);
      const downResult = vscoreComputeElementScore(e.id);
      const mappedDown = {}; _bsfElements.forEach(el => mappedDown[el.id] = el.id === e.id ? downResult.score : elementResults[el.id].score);
      const downComposite = bsfComputeScore(mappedDown);

      // Restore
      _vscoreVals[e.id][sv.id] = originalVal;

      const upImpact = upComposite - composite;
      const downImpact = downComposite - composite;
      const sensitivity = Math.abs(upImpact) + Math.abs(downImpact);
      const currentNorm = elementResults[e.id].subScores[sv.id]?.norm ?? 0;

      rows.push({ e, sv, currentNorm, originalVal, upImpact, downImpact, sensitivity });
    });
  });

  // Sort by sensitivity descending
  rows.sort((a,b) => b.sensitivity - a.sensitivity);

  const maxSens = rows[0]?.sensitivity || 1;
  tbody.innerHTML = rows.map(r => {
    const sensBarW = (r.sensitivity / maxSens * 100).toFixed(0);
    const upCol = r.upImpact >= 0 ? "var(--green)" : "var(--red)";
    const dnCol = r.downImpact >= 0 ? "var(--green)" : "var(--red)";
    return `<tr style="border-bottom:1px solid var(--b1)">
      <td style="padding:5px 10px;font-size:10px;font-weight:600;color:${r.e.color}">${r.e.label}</td>
      <td style="padding:5px 10px;font-size:10px;color:var(--t1)">${r.sv.label} <span style="color:var(--t3);font-size:10px">(${r.sv.unit})</span></td>
      <td style="padding:5px 10px;font-size:10px;color:var(--t2);text-align:right">${(+r.originalVal).toFixed(r.sv.step<1?2:1)}</td>
      <td style="padding:5px 10px;font-size:10px;font-weight:700;color:${r.currentNorm>=70?"var(--green)":r.currentNorm>=40?"var(--amber)":"var(--red)"};text-align:right">${r.currentNorm.toFixed(0)}</td>
      <td style="padding:5px 10px;font-size:10px;font-weight:700;color:${upCol};text-align:right">${r.upImpact>=0?"+":""}${r.upImpact.toFixed(2)}</td>
      <td style="padding:5px 10px;font-size:10px;font-weight:700;color:${dnCol};text-align:right">${r.downImpact>=0?"+":""}${r.downImpact.toFixed(2)}</td>
      <td style="padding:5px 10px">
        <div style="display:flex;align-items:center;gap:5px">
          <div style="width:60px;height:4px;background:rgba(255,255,255,0.07);border-radius:2px">
            <div style="width:${sensBarW}%;height:100%;background:var(--amber);border-radius:2px;opacity:0.8"></div>
          </div>
          <span style="font-size:10px;color:var(--t3)">${r.sensitivity.toFixed(2)}</span>
        </div>
      </td>
    </tr>`;
  }).join("");
}

function vscoreComputeAndRefresh() {
  vscoreCompute();
}

function vscoreReset() {
  Object.keys(_bsfSubVars).forEach(eid => {
    _bsfSubVars[eid].forEach(sv => {
      _vscoreVals[eid][sv.id] = sv.def;
      const slider = document.getElementById("vs-slider-" + eid + "-" + sv.id);
      const num    = document.getElementById("vs-num-" + eid + "-" + sv.id);
      if (slider) slider.value = sv.def;
      if (num)    num.value    = sv.def;
    });
  });
  vscoreCompute();
  toast("Variable Scoring reset to defaults", "success");
}

function vscoreLoadBasin(name) {
  if (!name) { vscoreReset(); return; }
  const basin = (typeof leaderboardData !== "undefined" && leaderboardData.length)
    ? leaderboardData.find(b => b.name === name)
    : (typeof BASINS !== "undefined" ? BASINS.find(b => b.name === name) : null);
  if (!basin) return;

  // Map basin scores back to sub-variable estimates using basin score as a proxy
  const baseScore = (basin.scores?.source ?? basin.score ?? 50) / 100;
  Object.keys(_bsfSubVars).forEach(eid => {
    const elScore = basin.scores ? (Object.values(basin.scores)[_bsfElements.findIndex(e=>e.id===eid)] ?? 50) : (basin.score ?? 50);
    _bsfSubVars[eid].forEach(sv => {
      // Interpolate between min and max based on element score
      const ratio = Math.max(0, Math.min(1, elScore / 100));
      const isInv = ["depth","breakeven","water_d","proximity"].includes(sv.id);
      const r = isInv ? (1 - ratio) : ratio;
      const v = sv.min + r * (sv.max - sv.min);
      _vscoreVals[eid][sv.id] = +v.toFixed(sv.step < 1 ? 2 : 1);
      const slider = document.getElementById("vs-slider-" + eid + "-" + sv.id);
      const num    = document.getElementById("vs-num-" + eid + "-" + sv.id);
      if (slider) slider.value = _vscoreVals[eid][sv.id];
      if (num)    num.value    = _vscoreVals[eid][sv.id];
    });
  });
  vscoreCompute();
  toast("Loaded estimates for: " + name, "success");
}

      // ── Apply BSF formula to leaderboard & re-rank ───────────────────────
function bsfApplyToLeaderboard() {
  if (typeof leaderboardData === "undefined" || !leaderboardData.length) {
    // Auto-run screening first
    toast("Running screening first…", "info");
    runScreening();
    setTimeout(() => {
      _bsfAppliedToLb = true;
      lbReapplyFormula();
      switchScreenTab("leaderboard", document.querySelectorAll("#screen-tabs .tab")[1]);
      toast("BSF formula applied — leaderboard re-ranked ✓", "success");
    }, 4500);
    return;
  }
  _bsfAppliedToLb = true;
  lbReapplyFormula();
  // Visual badge
  const badge = document.getElementById("bsf-lb-badge");
  if (badge) { badge.style.display = "inline-block"; badge.textContent = "✓ Active on Leaderboard"; }
  toast("BSF formula applied — leaderboard re-ranked ✓", "success");
  // Switch to leaderboard tab so user sees result
  switchScreenTab("leaderboard", document.querySelectorAll("#screen-tabs .tab")[1]);
}

function bsfDetachFromLeaderboard() {
  _bsfAppliedToLb = false;
  const badge = document.getElementById("bsf-lb-badge");
  if (badge) badge.style.display = "none";
  if (typeof lbReapplyFormula === "function" && leaderboardData?.length) lbReapplyFormula();
  toast("Leaderboard reverted to its own formula", "info");
}

function bsfSaveAndRerun() {
  bsfSaveFormula();
  bsfApplyToLeaderboard();
}

