function setupPortfolioMap() {
  const el = document.getElementById("portfolio-leaflet-map");
  if (!el) return;
  if (_portfolioMap) {
    _portfolioMap.remove();
    _portfolioMap = null;
  }
  _portfolioMap = L.map("portfolio-leaflet-map", {
    center: [20, 20],
    zoom: 2,
    minZoom: 2,
    maxZoom: 8,
    zoomControl: true,
    attributionControl: false,
  });
  L.tileLayer("https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png", {
    maxZoom: 19,
  }).addTo(_portfolioMap);
  L.control
    .attribution({ position: "bottomright" })
    .addTo(_portfolioMap)
    .setPrefix("© OpenStreetMap | EDAFY");
  renderPortfolioMapMarkers();
}

function renderPortfolioMapMarkers() {
  if (!_portfolioMap) return;
  _portfolioMarkers.forEach((m) => _portfolioMap.removeLayer(m));
  _portfolioMarkers = [];
  BASINS.forEach((basin) => {
    const coords = getBasinCoords(basin);
    const score = basin.score || 50;
    const color =
      score >= 70 ? "#1A7F5A" : score >= 40 ? "#C07800" : "#C62828";
    const r = Math.max(7, Math.min(18, score / 5.5));
    const icon = L.divIcon({
      className: "",
      html: `<div style="width:${r * 2}px;height:${r * 2}px;border-radius:50%;background:${color};border:2.5px solid #fff;box-shadow:0 2px 8px rgba(0,0,0,.4);cursor:pointer;transition:transform .15s" title="${basin.name}: ${score}/100"></div>`,
      iconSize: [r * 2, r * 2],
      iconAnchor: [r, r],
    });
    const m = L.marker(coords, { icon }).addTo(_portfolioMap);
    const sc =
      { Mature: "#1A7F5A", Active: "#0D4C92", Frontier: "#C07800" }[
        basin.status
      ] || "#8896A5";
    m.bindPopup(
      `<div style="font-family:Segoe UI,sans-serif;min-width:180px"><div style="font-size:12px;font-weight:700;color:#0A2E5C;margin-bottom:5px">${basin.name}</div><table style="width:100%;font-size:10px;border-collapse:collapse"><tr><td style="color:#8896A5">Country</td><td style="font-weight:600">${basin.country}</td></tr><tr><td style="color:#8896A5">HC Phase</td><td style="color:#0D4C92;font-weight:600">${basin.hc}</td></tr><tr><td style="color:#8896A5">Score</td><td style="font-weight:700;color:${color}">${score}/100</td></tr><tr><td style="color:#8896A5">Status</td><td><span style="background:${sc}18;color:${sc};padding:1px 6px;border-radius:8px;font-weight:600;font-size:10px">${basin.status}</span></td></tr></table><div style="margin-top:6px"><button onclick="closeModal();goTo('basins',null)" style="background:#0A2E5C;color:#fff;border:none;padding:3px 8px;border-radius:4px;font-size:10px;cursor:pointer">View Basin</button></div></div>`,
    );
    _portfolioMarkers.push(m);
  });
}

// Basin coordinate lookup (lat/lng) — extended for all basins
const BASIN_COORDS = {
  "Zagros Fold Belt": [32.0, 47.5],
  "Permian Basin": [31.5, -102.5],
  "North Sea": [56.5, 3.5],
  "Kutei Basin": [-1.0, 117.0],
  "Nile Delta": [31.0, 31.0],
  "Murzuq Basin": [26.0, 14.0],
  "Sergipe-Alagoas": [-11.0, -37.0],
  "Malay Basin": [6.0, 104.0],
  "Browse Basin": [-16.0, 122.0],
  "Barents Sea": [74.0, 30.0],
  "East Greenland": [72.0, -25.0],
  "Vaca Muerta": [-38.0, -69.0],
  "Permian Basin (China)": [39.0, 85.0],
  "Tarim Basin": [39.5, 83.0],
  "Niger Delta": [4.5, 6.5],
  "Anadarko Basin": [35.5, -98.5],
  "Cooper Basin": [-28.0, 140.0],
  "Williston Basin": [47.0, -103.0],
  "Rub al Khali": [21.0, 54.0],
  "Sirte Basin": [29.0, 20.0],
};

function getBasinCoords(basin) {
  if (BASIN_COORDS[basin.name]) return BASIN_COORDS[basin.name];
  // Fallback by region
  const regionFallbacks = {
    "Middle East": [28, 45],
    "North America": [40, -100],
    Europe: [52, 15],
    "Southeast Asia": [5, 115],
    "North Africa": [25, 20],
    "South America": [-15, -55],
    Australia: [-25, 135],
    Russia: [60, 80],
    "West Africa": [5, 5],
  };
  return regionFallbacks[basin.region] || [0, 20];
}

function focusBasinOnMap(name) {
  if (_focusedBasin === name) return;
  _focusedBasin = name;
  const b = BASINS.find((x) => x.name === name);
  if (!b || !_leafletMap) return;
  const coords = getBasinCoords(b);
  if (!coords) return;
  document
    .getElementById("world-map")
    ?.scrollIntoView({ behavior: "smooth", block: "start" });
  _leafletMap.once("moveend", () => {
    const target = L.latLng(coords[0], coords[1]);
    const marker = _leafletMarkers.find(
      (m) => m.getLatLng().distanceTo(target) < 5000,
    );
    if (marker) marker.openPopup();
  });
  _leafletMap.flyTo(coords, 6, { duration: 1.2 });
}

// ══════════════════════════════════════════════════════════════════
//  GLOBAL BASIN CONTEXT  —  setGlobalBasin(name)
//  Call this whenever a basin is selected anywhere in the app.
//  Propagates the selection to every module selector silently,
//  and shows a persistent context bar so the user always knows
//  which basin is active and can change it at any time.
// ══════════════════════════════════════════════════════════════════

window._globalBasin = null;  // the currently active basin name

// Map of selector IDs → their change handler function names
const _BASIN_SELECTORS = [
  { id: "strat-basin-select",  fn: (v) => { initStratTab(); const s = document.getElementById("strat-basin-select"); if(s) s.value = v; renderStratColumn(v); } },
  { id: "econ-basin-select",   fn: (v) => { const s = document.getElementById("econ-basin-select"); if(s){ s.value = "basin:" + v; loadEconFromDatabase("basin:" + v); } } },
  { id: "bp-basin-select",     fn: (v) => { const s = document.getElementById("bp-basin-select"); if(s){ s.value = v; if(typeof renderBasinProfile==="function") renderBasinProfile(v); } } },
  { id: "bss-basin-select",    fn: (v) => { const s = document.getElementById("bss-basin-select"); if(s){ s.value = "basin:" + v; if(typeof bssOnBasinChange==="function") bssOnBasinChange("basin:" + v); } } },
  { id: "hub-sel-basin",       fn: (v) => { const s = document.getElementById("hub-sel-basin"); if(s){ s.value = v; if(typeof hubOnBasinChange==="function") hubOnBasinChange(); } } },
  { id: "mat-basin",           fn: (v) => { const s = document.getElementById("mat-basin"); if(s){ s.value = v; if(typeof hubMaturationRender==="function") hubMaturationRender(); } } },
  { id: "strat-basin",         fn: (v) => { const s = document.getElementById("strat-basin"); if(s){ s.value = v; if(typeof hubStratRender==="function") hubStratRender(); } } },
  { id: "hier-basin-select",   fn: (v) => { const s = document.getElementById("hier-basin-select"); if(s){ s.value = v; if(typeof hierRender==="function") hierRender(); } } },
  { id: "pse-basin-select",    fn: (v) => { const s = document.getElementById("pse-basin-select"); if(s){ s.value = v; if(typeof pse_loadBasin==="function") pse_loadBasin(v); } } },
  { id: "sens-basin-select",   fn: (v) => { const s = document.getElementById("sens-basin-select"); if(s){ s.value = v; if(typeof loadSensFromBasin==="function") loadSensFromBasin(v); } } },
  { id: "pf-basin",             fn: (v) => { if(typeof pfBasinInit==="function") pfBasinInit(); const s = document.getElementById("pf-basin"); if(s){ s.value = v; if(typeof updateDists==="function") updateDists(); } } },
  { id: "af-filter-basin",      fn: (v) => { const s = document.getElementById("af-filter-basin"); if(s){ s.value = v; if(typeof afRefresh==="function") afRefresh(); } } },
  // Volumetrics: when basin changes, load the first prospect in that basin.
  // If no prospect exists for the basin, fall back to basin-proxy resolution
  // via loadParamsFromData(null) which reads _hubCtx.basin / _globalBasin.
  { id: "vol-prospect-select",  fn: (v) => {
    if (typeof PROSPECTS === 'undefined' || typeof loadParamsFromData !== 'function') return;
    // Find the first prospect whose basin matches the newly selected basin
    const basinProspect = PROSPECTS.find(p => p.basin === v);
    if (basinProspect) {
      // Update both prospect selectors and fire loadProspect which
      // updates GCoS sliders, currentProspect, and loadParamsFromData
      if (typeof loadProspect === 'function') {
        loadProspect(basinProspect.name);
      }
    } else {
      // No prospect for this basin — push basin-proxy params into Volumetrics.
      // resolveParams() will use ANALOGUES.find(a => a.basin === v) as fallback.
      // Temporarily set _hubCtx.basin so resolveParams picks it up.
      if (typeof _hubCtx !== 'undefined') _hubCtx.basin = v;
      loadParamsFromData(null, { volumetrics: true, monteCarlo: true, notify: false });
    }
  }},
];

function setGlobalBasin(name, opts) {
  if (!name) return;
  opts = opts || {};
  const prev = window._globalBasin;
  window._globalBasin = name;
  _lastSelectedBasin  = name;

  // Update context bar
  _renderGlobalBasinBar(name);
  adjustMainLayout();

  // Propagate to all selectors (with small stagger so DOM is ready)
  _BASIN_SELECTORS.forEach(({ id, fn }, i) => {
    const el = document.getElementById(id);
    if (!el) return;
    // Only fire if the selector exists and value differs
    if (el.value === name || el.value === "basin:" + name) return;
    setTimeout(() => { try { fn(name); } catch(e) { console.warn("[EDAFY] setGlobalBasin selector error:", id, e); } }, i * 40);
  });

  // Also pre-load strat panel if it's currently visible
  _preloadStratForBasin(name);

  if (!opts.silent) toast("Basin context → " + name, "info");
}

function adjustMainLayout() {
  const bar = document.getElementById("_global-basin-bar");
  const main = document.querySelector(".main");
  const map = document.querySelector(".map-area");
  const sidebar = document.querySelector(".sb");
  const fab = document.getElementById("emonk-fab");

  const RESIZER_HEIGHT = 6; // ✅ your draggable bar height

  if (bar && main && map && sidebar) {
    const barHeight =
      window.getComputedStyle(bar).display === "none"
        ? 0
        : bar.offsetHeight;

    const mapHeight = map.offsetHeight;

    // ✅ subtract resizer height too
    const remainingHeight = Math.floor(
      window.innerHeight - mapHeight - barHeight - RESIZER_HEIGHT
    );

    // Main fills remaining space
    main.style.height = remainingHeight + "px";
    main.style.overflow = "hidden";

    // Sidebar stops above bar (no resizer here)
    sidebar.style.height = Math.floor(
      window.innerHeight - barHeight
    ) + "px";

    // Move FAB above the bar
    if (fab) {
      fab.style.bottom = 28 + barHeight + "px";
    }
  }
}

window.addEventListener("resize", adjustMainLayout);

// ── Context bar ────────────────────────────────────────────────────────
function _renderGlobalBasinBar(name) {
  let bar = document.getElementById("_global-basin-bar");

  // ✅ FIX: hide if no basin selected
  if (!name) {
    if (bar) {
      bar.style.display = "none";
      adjustMainLayout();
    }
    return;
  }
  if (!bar) {
    // Create bar if it doesn’t exist
    bar = document.createElement("div");
    bar.id = "_global-basin-bar";
    document.body.appendChild(bar);
  } else {
    // ✅ Make sure it is visible again
    bar.style.display = "flex";
    bar.style.transform = "";

    setTimeout(() => {
      adjustMainLayout(); // ✅ correct height now
    }, 0); // reset translateY
  }

  const b = (window.BASINS || []).find(x => x.name === name) || {};
  const hcColor = b.hc === "Gas" ? "#2fb87a" : b.hc === "Oil & Gas" ? "#f0a500" : "#00aaff";
  const scoreColor = (b.score||50) >= 70 ? "#2fb87a" : (b.score||50) >= 40 ? "#f0a500" : "#ff4d4d";

  bar.innerHTML = `
    <span style="font-size:10px;color:rgba(255,255,255,.4);text-transform:uppercase;letter-spacing:.7px;white-space:nowrap">Active Basin</span>
    <span style="font-weight:700;color:#fff;font-size:12px;white-space:nowrap">${name}</span>
    ${b.hc ? `<span style="font-size:10px;font-weight:700;padding:2px 8px;border-radius:10px;background:${hcColor}22;color:${hcColor}">${b.hc}</span>` : ""}
    ${b.country ? `<span style="font-size:10px;color:rgba(255,255,255,.5)">${b.country}</span>` : ""}
    ${b.score != null ? `<span style="font-size:10px;font-weight:700;color:${scoreColor}">Score ${b.score}</span>` : ""}
    <div style="flex:1"></div>
    <span style="font-size:10px;color:rgba(255,255,255,.35)">Change basin:</span>
    <select id="_global-basin-bar-select" style="font-size:10px;padding:3px 8px;background:rgba(255,255,255,.07);border:1px solid rgba(255,255,255,.15);color:#fff;border-radius:5px;font-family:inherit;cursor:pointer;max-width:200px" onchange="setGlobalBasin(this.value,{silent:true})">
      <option value="">— select —</option>
      ${(window.BASINS||[]).map(bx => `<option value="${bx.name}" ${bx.name===name?"selected":""}>${bx.name}</option>`).join("")}
    </select>
    <button onclick="
      const bar=document.getElementById('_global-basin-bar');
      bar.style.transform='translateY(100%)';
      setTimeout(()=>{
        bar.style.display='none';
        adjustMainLayout();
      }, 200)
    " style="font-size:10px;padding:2px 8px;background:transparent;border:1px solid rgba(255,255,255,.15);color:rgba(255,255,255,.4);border-radius:4px;cursor:pointer;font-family:inherit" title="Dismiss for 4s">
      ✕
    </button>
  `;

  // ✅ recalc main/sidebar layout
  adjustMainLayout();
}

function setupMap() {
  const mapEl = document.getElementById("leaflet-map");
  if (!mapEl) return;

  // Init Leaflet map
  if (_leafletMap) {
    _leafletMap.remove();
    _leafletMap = null;
  }
  _basinLayer = null; // clear orphaned reference from destroyed map
  _leafletMap = L.map("leaflet-map", {
    center: [0, 0],
    zoom: 2,
    minZoom: 2,
    maxZoom: 10,
    zoomControl: true,
    attributionControl: false,
  });

  // Tile layer — dark or light based on current theme
  _leafletTileLayer = L.tileLayer(_mapTileUrl(), {
    maxZoom: 19,
  }).addTo(_leafletMap);

  // Add attribution discretely
  L.control
    .attribution({ position: "bottomright" })
    .addTo(_leafletMap)
    .setPrefix("© Esri | EDAFY");

  renderMapMarkers();
  loadBasinLayer();
}

let isDragging = false;

const resizer = document.getElementById("map-resizer");
const map = document.querySelector(".map-area");

resizer.addEventListener("mousedown", () => {
  isDragging = true;
  document.body.style.cursor = "row-resize";
});

document.addEventListener("mouseup", () => {
  isDragging = false;
  document.body.style.cursor = "default";
});

document.addEventListener("mousemove", (e) => {
  if (!isDragging) return;

  const map = document.querySelector(".map-area");

  // current mouse position = new height
  let newHeight = e.clientY;

  // convert vh limits to px
  const minHeight = window.innerHeight * 0.15; // 15vh
  const maxHeight = window.innerHeight * 0.5;  // ✅ 50vh

  // clamp value
  if (newHeight < minHeight) newHeight = minHeight;
  if (newHeight > maxHeight) newHeight = maxHeight;

  map.style.height = newHeight + "px";

  // update layout
  // adjustMainLayout();
});

function loadBasinLayer() {
  if (!_leafletMap || !window._basinsData) return;

  // Remove any previous layer instance (e.g. from prior map reinit)
  if (_basinLayer) {
    _leafletMap.removeLayer(_basinLayer);
    _basinLayer = null;
  }

  _basinLayer = L.geoJSON(window._basinsData, {
    style: () => ({
      color: "#6B46C1",
      weight: 1.5,
      opacity: 0.8,
      fillColor: "#6B46C1",
      fillOpacity: 0.2,
    }),
    onEachFeature(feature, layer) {
      const p = feature.properties;
      const countries = (p.country_names || "").replace(/~/g, ", ");
      const area = p.basin_sqkm
        ? Math.round(p.basin_sqkm).toLocaleString() + " km²"
        : "—";
      layer.bindPopup(
        `<div style="font-family:Segoe UI,sans-serif;min-width:190px">
    <div style="font-size:12px;font-weight:700;color:#2D1B69;margin-bottom:6px">${p.basin_name || "—"}</div>
    <table style="width:100%;font-size:10px;border-collapse:collapse">
      <tr><td style="color:#8896A5;padding:2px 6px 2px 0">Countries</td><td style="font-weight:600">${countries || "—"}</td></tr>
      <tr><td style="color:#8896A5;padding:2px 6px 2px 0">Type</td><td style="font-weight:600">${p.basin_type || "—"}</td></tr>
      <tr><td style="color:#8896A5;padding:2px 6px 2px 0">Area</td><td style="font-weight:600">${area}</td></tr>
    </table>
  </div>`,
        {
          maxWidth: 250,
          className: "edafy-popup",
          offset: [0, 50],
          autoPan: false,
        },
      );
      layer.on({
        mouseover(e) {
          e.target.setStyle({ weight: 3, fillOpacity: 0.45, opacity: 1 });
          e.target.bringToFront();
        },
        mouseout(e) {
          _basinLayer.resetStyle(e.target);
        },
        click(e) {
          const center = e.target.getBounds().getCenter();
          e.target.closePopup();
          _leafletMap.once("moveend", () => e.target.openPopup(center));
          _leafletMap.flyTo(center, 5, { duration: 0.8 });
        },
      });
    },
  }).addTo(_leafletMap);

  if (_basinLayer.getBounds().isValid()) {
    _leafletMap.fitBounds(_basinLayer.getBounds(), { padding: [20, 20] });
  }
}

function renderMapMarkers() {
  if (!_leafletMap) return;
  // Remove old markers
  _leafletMarkers.forEach((m) => _leafletMap.removeLayer(m));
  _leafletMarkers = [];

  BASINS.forEach((basin) => {
    const coords = getBasinCoords(basin);
    const score = basin.score || 50;
    const color =
      score >= 70 ? "#1A7F5A" : score >= 40 ? "#C07800" : "#C62828";
    const r = Math.max(8, Math.min(20, score / 5));

    // Custom SVG circle marker
    const svgIcon = L.divIcon({
      className: "",
      html: `<div style="width:${r * 2}px;height:${r * 2}px;border-radius:50%;background:${color};border:2.5px solid #fff;box-shadow:0 2px 8px rgba(0,0,0,.35);cursor:pointer;opacity:0.9;transition:transform .15s" onmouseover="this.style.transform='scale(1.3)'" onmouseout="this.style.transform='scale(1)'"></div>`,
      iconSize: [r * 2, r * 2],
      iconAnchor: [r, r],
    });

    const marker = L.marker(coords, { icon: svgIcon }).addTo(_leafletMap);

    const statusColor =
      { Mature: "#1A7F5A", Active: "#0D4C92", Frontier: "#C07800" }[
        basin.status
      ] || "#8896A5";
    marker.bindPopup(
      `
<div style="font-family:Segoe UI,sans-serif;min-width:200px">
  <div style="font-size:13px;font-weight:700;color:#0A2E5C;margin-bottom:6px">${basin.name}</div>
  <table style="width:100%;font-size:11px;border-collapse:collapse">
    <tr><td style="color:#8896A5;padding:2px 0">Country</td><td style="font-weight:600">${basin.country}</td></tr>
    <tr><td style="color:#8896A5;padding:2px 0">Region</td><td style="font-weight:600">${basin.region}</td></tr>
    <tr><td style="color:#8896A5;padding:2px 0">HC Phase</td><td style="font-weight:600;color:#0D4C92">${basin.hc}</td></tr>
    <tr><td style="color:#8896A5;padding:2px 0">Prospectivity</td><td style="font-weight:700;color:${color}">${score}/100</td></tr>
    <tr><td style="color:#8896A5;padding:2px 0">Status</td><td><span style="background:${statusColor}18;color:${statusColor};padding:1px 7px;border-radius:8px;font-weight:600;font-size:10px">${basin.status}</span></td></tr>
  </table>
  <div style="margin-top:8px;display:flex;gap:5px">
    <button onclick="closeModal();goTo('basins',null)" style="flex:1;padding:5px;background:#0D4C92;color:#fff;border:none;border-radius:4px;font-size:10px;cursor:pointer;font-family:inherit">Open Record</button>
    <button onclick="closeModal();goTo('analogues',null)" style="flex:1;padding:5px;background:#0D4C9218;color:#0D4C92;border:1px solid #0D4C9244;border-radius:4px;font-size:10px;cursor:pointer;font-family:inherit">Analogues</button>
  </div>
</div>`,
      { maxWidth: 260, className: "edafy-popup" },
    );

    _leafletMarkers.push(marker);
  });
  // Also refresh portfolio map if open
  renderPortfolioMapMarkers();
}

function openBasinModal(d) {
  if (!d) return;
  openModal(`
<div class="modal-title">${d.name}</div>
<div class="modal-sub">Region: ${d.region} &nbsp;·&nbsp; Status: ${d.status}</div>
<div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:16px">
<div style="background:var(--bg4);border-radius:5px;padding:11px">
  <div style="font-size:10px;color:var(--t3);text-transform:uppercase;letter-spacing:1px;margin-bottom:4px">Prospectivity Score</div>
  <div style="font-size:28px;font-weight:700;color:var(--green)">${d.score}</div>
</div>
<div style="background:var(--bg4);border-radius:5px;padding:11px">
  <div style="font-size:10px;color:var(--t3);text-transform:uppercase;letter-spacing:1px;margin-bottom:4px">HC Phase</div>
  <div style="font-size:16px;font-weight:700;color:var(--cyan)">${d.hc}</div>
</div>
</div>
<div style="display:flex;gap:8px">
<button class="btn" onclick="closeModal();goTo('analogues',null)">Run Analogue Search →</button>
<button class="btn2" onclick="closeModal();goTo('risk',null)">Risk Assessment →</button>
</div>
`);
}

