const AI_INSIGHTS = [
  `Your portfolio shows <strong>3 high-prospectivity basins</strong> (score ≥70) concentrated in the Middle East and SE Asia. Consider diversifying into the Browse Basin (score 63) for geographic risk reduction.`,
  `Data quality is currently <strong>${BASINS.filter((b) => b.score > 0).length > 5 ? "above" : "below"} target</strong>. The Geochemistry dataset has the most incomplete records — uploading TOC% and Ro% data would improve analogue matching accuracy by ~18%.`,
  `The <strong>Kutei Basin</strong> and <strong>Malay Basin</strong> show a high analogue similarity (87%). Consider running a joint volumetric analysis using Miocene deltaic sandstone parameters from both basins.`,
  `Based on current GCoS estimates, your portfolio has an expected discovery rate of <strong>~23%</strong> — consistent with industry benchmarks for a mixed mature/frontier portfolio.`,
  `<strong>Geopressure data</strong> is missing for 6 of your high-priority analogues. Overpressure prediction is a key uncertainty in your SE Asia plays — consider uploading pore pressure gradient data from offset wells.`,
  `The <strong>Analogue Engine</strong> has identified Zagros Fold Belt carbonates as the highest-scoring match (89%) for your Prospect Alpha target reservoir. GCoS for this prospect type averages 28% in the analogue database.`,
];
let _aiInsightIdx = 0;

// ============================================================
// AI ENGINE — Anthropic Claude API integration
// ============================================================
async function callClaudeAI(prompt, systemPrompt) {
  try {
    const res = await fetch("https://api.anthropic.com/v1/messages", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "anthropic-version": "2023-06-01",
        "anthropic-dangerous-direct-browser-access": "true",
        "x-api-key": (typeof _aiCfg !== "undefined" ? (_aiCfg.claudeKey || _aiCfg.key || "") : ""),
      },
      body: JSON.stringify({
        model: "claude-sonnet-4-20250514",
        max_tokens: 800,
        system:
          systemPrompt ||
          "You are an expert petroleum exploration geologist AI assistant embedded in the EDAFY Geo-Basin Intelligence Platform. Provide concise, technical, actionable insights. Use HTML bold tags for emphasis. Keep responses to 3-4 sentences.",
        messages: [{ role: "user", content: prompt }],
      }),
    });
    const data = await res.json();
    if (data.content && data.content[0]) return data.content[0].text;
    if (data.error) return null;
    return null;
  } catch (e) {
    return null;
  }
}

async function getAIPortfolioInsight() {
  const topBasin = [...BASINS].sort((a, b) => b.score - a.score)[0];
  const avgScore = BASINS.length
    ? (
        BASINS.reduce((s, b) => s + (b.score || 0), 0) / BASINS.length
      ).toFixed(0)
    : 50;
  const highCount = BASINS.filter((b) => b.score >= 70).length;
  const regionBreakdown = [
    ...BASINS.reduce((m, b) => {
      m.set(b.region, (m.get(b.region) || 0) + 1);
      return m;
    }, new Map()),
  ]
    .map(([r, c]) => `${r}:${c}`)
    .join(", ");

  // Show loading state
  openModal(`
<div class="modal-title" style="display:flex;align-items:center;gap:10px">
<span style="background:linear-gradient(135deg,#0D4C92,#0D4C92);color:#fff;padding:5px 10px;border-radius:6px;font-size:11px;font-weight:700;letter-spacing:1px">AI</span>
Portfolio Intelligence
</div>
<div id="ai-insight-content" style="padding:16px;background:linear-gradient(135deg,rgba(13,76,146,.06),rgba(0,136,204,.04));border:1px solid rgba(13,76,146,.15);border-radius:8px;margin:10px 0;font-size:12px;line-height:1.7;color:var(--t2)">
<div style="display:flex;align-items:center;gap:8px;color:var(--purple)">
  <div style="width:8px;height:8px;border-radius:50%;background:var(--purple);animation:pulse 1s infinite"></div>
  Analysing portfolio data…
</div>
</div>
<div id="ai-insight-footer" style="font-size:10px;color:var(--t3);margin-bottom:12px">Powered by Claude — AFED Digital AI</div>
<div style="display:flex;gap:7px">
<button class="btn" onclick="getAIPortfolioInsight()">New Insight</button>
<button class="btn2" onclick="closeModal()">Close</button>
</div>`);

  const portfolioSummary = `Portfolio: ${BASINS.length} basins, ${ANALOGUES.length} analogues. Top basin: ${topBasin?.name || "N/A"} (score ${topBasin?.score || 0}/100). Avg score: ${avgScore}. High-prospectivity (≥70): ${highCount}. Regions: ${regionBreakdown}. HC phases: ${[...new Set(BASINS.map((b) => b.hc))].join(", ")}.`;

  const aiText = await callClaudeAI(
    `Analyse this exploration portfolio and provide one key strategic insight: ${portfolioSummary}`,
    "You are an expert petroleum exploration geologist. Provide a concise (3-4 sentence) strategic insight about this portfolio. Be specific, reference the data provided, and suggest one concrete next action. Use <strong> tags for key terms.",
  );

  const content = document.getElementById("ai-insight-content");
  if (content) {
    if (aiText) {
      content.innerHTML = aiText;
      document.getElementById("ai-insight-footer").textContent =
        `AI analysis based on ${BASINS.length} basins and ${ANALOGUES.length} analogues · Powered by Claude`;
    } else {
      // Fallback to local insights
      const localInsights = [
        `Your top basin is <strong>${topBasin?.name}</strong> with a prospectivity score of <strong>${topBasin?.score}/100</strong>. Average portfolio score is ${avgScore}/100 — ${avgScore >= 65 ? "above" : "below"} the industry benchmark of 65.`,
        `You have <strong>${highCount} high-prospectivity basins</strong> (score ≥70). Consider running Basin Screening to rank them by weighted criteria before committing exploration budget.`,
        `Portfolio spans <strong>${regionBreakdown}</strong>. Geographic diversification can reduce portfolio risk — ensure no single region holds more than 40% of your exploration commitment.`,
      ];
      content.innerHTML =
        localInsights[Math.floor(Math.random() * localInsights.length)];
    }
  }
}

async function getAIAnalogueInsight() {
  if (!searchResults || !searchResults.length) {
    toast("Run an analogue search first", "warning");
    return;
  }
  const top5 = searchResults
    .slice(0, 5)
    .map(
      (a) =>
        `${a.name} (${a.sim}% match, φ=${a.por}%, k=${a.perm}mD, RF=${a.rf}%)`,
    )
    .join("; ");
  const insight = await callClaudeAI(
    `Top 5 analogues: ${top5}. Provide a brief technical summary of what these analogues suggest about expected reservoir performance.`,
    "You are a reservoir geologist. Provide a concise 3-sentence interpretation of these analogue results. Comment on consistency of reservoir quality and what the spread implies for risk. Use HTML <strong> tags.",
  );
  if (insight) {
    openModal(`
<div class="modal-title" style="display:flex;align-items:center;gap:8px">
  <span style="background:linear-gradient(135deg,#0D4C92,#0D4C92);color:#fff;padding:4px 9px;border-radius:5px;font-size:10px;font-weight:700">AI</span>
  Analogue Interpretation
</div>
<div style="padding:14px;background:linear-gradient(135deg,rgba(13,76,146,.05),rgba(0,136,204,.03));border:1px solid rgba(13,76,146,.15);border-radius:8px;margin:10px 0;font-size:12px;line-height:1.7;color:var(--t2)">${insight}</div>
<div style="font-size:10px;color:var(--t3);margin-bottom:10px">Powered by Claude · AFED Digital AI</div>
<button class="btn2" onclick="closeModal()">Close</button>`);
  } else {
    toast(
      "AI interpretation not available — check connection",
      "warning",
    );
  }
}

async function getAIBasinRisk(basin) {
  if (!basin) return;
  const insight = await callClaudeAI(
    `Basin: ${basin.name}, ${basin.country}, ${basin.region}. Tectonic: ${basin.tectonic}. HC Phase: ${basin.hc}. Prospectivity: ${basin.score}/100. Status: ${basin.status}. Provide a brief risk assessment.`,
    "You are a basin risk analyst. In 2-3 sentences, comment on key exploration risks and opportunities for this basin. Be specific and technical. Use <strong> tags for key terms.",
  );
  return insight;
}

function _getAIPortfolioInsight_legacy() {
  const bar = document.getElementById("ai-insight-bar");
  const txt = document.getElementById("ai-insight-text");
  if (!bar || !txt) return;
  bar.style.display = "block";
  txt.innerHTML =
    '<span style="color:var(--purple)">Analysing portfolio data…</span>';
  setTimeout(() => {
    txt.innerHTML = AI_INSIGHTS[_aiInsightIdx % AI_INSIGHTS.length];
    _aiInsightIdx++;
  }, 800);
}

// ============================================================
// ACTIVITY FEED
// ============================================================
function renderActivity() {
  // Generate real activity feed from actual data
  const acts = [];

  // Basin catalogue stats
  const regions = {};
  BASINS.forEach((b) => {
    regions[b.region] = (regions[b.region] || 0) + 1;
  });
  const topRegion = Object.entries(regions).sort(
    (a, b) => b[1] - a[1],
  )[0];
  acts.push({
    dot: "var(--cyan)",
    text: `Basin catalogue loaded — <strong>${BASINS.length} basins</strong> across ${Object.keys(regions).length} regions`,
    time: "On load · System",
  });

  // Analogue data
  if (ANALOGUES.length > 0) {
    const avgSim = (
      ANALOGUES.reduce((s, a) => s + (a.sim || 0), 0) / ANALOGUES.length
    ).toFixed(0);
    acts.push({
      dot: "var(--green)",
      text: `<strong>${ANALOGUES.length} analogue intervals</strong> loaded · Avg similarity: ${avgSim}%`,
      time: "On load · Analogue Engine",
    });
  }

  // Top-scored basin
  const top = [...BASINS].sort((a, b) => b.score - a.score)[0];
  if (top)
    acts.push({
      dot: "var(--green)",
      text: `Top basin: <strong>${top.name}</strong> (${top.country}) — Score: ${top.score}`,
      time: "Portfolio ranking · System",
    });

  // Frontier basins needing attention
  const frontier = BASINS.filter((b) => b.status === "Frontier");
  if (frontier.length)
    acts.push({
      dot: "var(--amber)",
      text: `<strong>${frontier.length} frontier basins</strong> flagged for further evaluation`,
      time: "Screening alert · System",
    });

  // Low-score basins
  const lowScore = BASINS.filter((b) => b.score < 40);
  if (lowScore.length)
    acts.push({
      dot: "var(--red)",
      text: `<strong>${lowScore.length} basins</strong> below threshold (score &lt; 40) — review recommended`,
      time: "Quality check · System",
    });

  // Data quality check
  const incomplete = ANALOGUES.filter((a) => !a.por || !a.perm || !a.rf);
  if (incomplete.length > 0) {
    acts.push({
      dot: "var(--amber)",
      text: `<strong>${incomplete.length} analogue records</strong> with missing properties — governance review needed`,
      time: "Data QC · System",
    });
  } else {
    acts.push({
      dot: "var(--green)",
      text: `All ${ANALOGUES.length} analogue records pass completeness check`,
      time: "Data QC · System",
    });
  }

  // Region concentration
  if (topRegion)
    acts.push({
      dot: "var(--cyan)",
      text: `Highest basin concentration: <strong>${topRegion[0]}</strong> (${topRegion[1]} basins)`,
      time: "Portfolio analysis · System",
    });

  // GCoS saved
  const gcos = Object.keys(riskVals).length
    ? Object.values(riskVals).reduce((p, v) => (p * v) / 100, 1) * 100
    : null;
  if (gcos)
    acts.push({
      dot: "var(--green)",
      text: `GCoS estimate active: <strong>${gcos.toFixed(1)}%</strong> (${Object.keys(riskVals).length} risk elements)`,
      time: "Risk module · User",
    });

  // Template data stores
  if (PETROLEUM_SYSTEMS.length)
    acts.push({
      dot: "var(--cyan)",
      text: `<strong>${PETROLEUM_SYSTEMS.length} petroleum systems</strong> loaded from template`,
      time: "XLSX Import · System",
    });
  if (PLAYS.length)
    acts.push({
      dot: "var(--cyan)",
      text: `<strong>${PLAYS.length} plays</strong> ingested — ${PLAYS.reduce((s, p) => s + p.num_fields, 0)} total fields`,
      time: "XLSX Import · System",
    });
  if (RESOURCES_PROB.length)
    acts.push({
      dot: "var(--purple)",
      text: `<strong>${RESOURCES_PROB.length} assessment units</strong> with probabilistic resource estimates`,
      time: "XLSX Import · USGS",
    });
  if (RESERVES_PRODUCTION.length) {
    const totRes = RESERVES_PRODUCTION.reduce(
      (s, r) => s + r.reserves_recoverable_mbl,
      0,
    );
    acts.push({
      dot: "var(--green)",
      text: `Reserves data: <strong>${(totRes / 1000).toFixed(1)} Bn bbl</strong> recoverable across ${RESERVES_PRODUCTION.length} basins`,
      time: "XLSX Import · IHS/WoodMac",
    });
  }
  if (PROSPECTS_DATA.length)
    acts.push({
      dot: "var(--amber)",
      text: `<strong>${PROSPECTS_DATA.length} prospects</strong> loaded — ${PROSPECTS_DATA.filter((p) => p.technical_cos_pct > 0).length} with CoS data`,
      time: "XLSX Import · WoodMac",
    });
  if (RISK_PROBABILITIES.length)
    acts.push({
      dot: "var(--red)",
      text: `<strong>${RISK_PROBABILITIES.length} risk assessments</strong> (charge/rocks/timing/access)`,
      time: "XLSX Import · USGS",
    });
  if (wtCustom) {
    const customCount = Object.keys(WT_DEFAULTS).filter(
      (k) => WT[k] !== WT_DEFAULTS[k],
    ).length;
    acts.push({
      dot: "#9333EA",
      text: `<strong>⚖ Custom Penalty Weights active</strong> — ${customCount} of ${Object.keys(WT_DEFAULTS).length} weights modified from defaults`,
      time: "XLSX Import · Screening",
    });
  }

  const _afEl = document.getElementById("activity-feed");
  if (_afEl) _afEl.innerHTML =
    acts
      .map(
        (a) => `
<div style="display:flex;gap:9px;padding:8px 0;border-bottom:1px solid rgba(0,200,255,.05)">
<div style="width:7px;height:7px;border-radius:50%;background:${a.dot};margin-top:4px;flex-shrink:0"></div>
<div>
  <div style="font-size:11px;color:var(--t2);line-height:1.5">${a.text}</div>
  <div style="font-size:10px;color:var(--t3);margin-top:1px">${a.time}</div>
</div>
</div>`,
      )
      .join("") + '<div style="height:4px"></div>';
}

