function renderTopBasins() {
  const sorted = [...BASINS]
    .sort((a, b) => b.score - a.score)
    .slice(0, 5);
  document.getElementById("top-basins-table").innerHTML = `
<table><thead><tr><th>#</th><th>Basin</th><th>Region</th><th>Score</th><th>Status</th></tr></thead>
<tbody>${sorted
.map((b, i) => {
  const c =
    b.score >= 70
      ? "var(--green)"
      : b.score >= 40
        ? "var(--amber)"
        : "var(--red)";
  const tl = b.score >= 70 ? "tl-g" : b.score >= 40 ? "tl-a" : "tl-r";
  const tlText = b.score >= 70 ? "HIGH" : b.score >= 40 ? "MED" : "LOW";
  return `<tr style="cursor:pointer" onclick="openBasinModal(BASINS.find(x=>x.name==='${b.name}'))">
  <td style="color:${i === 0 ? "var(--gold)" : "var(--t3)"};font-weight:700">${i + 1}</td>
  <td style="color:var(--t1);font-weight:600">${b.name}</td>
  <td>${b.region}</td>
  <td>
    <div class="sbar" style="width:100%">
      <div class="sbar-track">
        <div class="sbar-fill" style="width:${b.score}%;background:${c}">
        </div>
      </div>
      <span class="sval" style="color:${c}">${b.score}</span>
    </div>
  </td>
  <td>
    <span class="tl ${tl}">${tlText}</span>
  </td>
</tr>`;
})
.join("")}</tbody></table>`;
}

// ============================================================
// DQ SUMMARY
// ============================================================
function renderDQSummary() {
  // Compute real data quality from BASINS + ANALOGUES
  const basinFields = [
    "name",
    "country",
    "region",
    "tectonic",
    "age",
    "hc",
    "area",
    "plays",
    "score",
    "status",
  ];
  const anaFields = [
    "name",
    "basin",
    "age",
    "lith",
    "dep",
    "depth",
    "hc",
    "por",
    "perm",
    "rf",
  ];
  const sourceFields = ["geochem"];
  const commercialFields = ["area", "plays", "status"];

  // Basin record completeness
  const basinFilled = BASINS.reduce(
    (s, b) =>
      s +
      basinFields.filter((f) => b[f] != null && b[f] !== "" && b[f] !== 0)
        .length,
    0,
  );
  const basinTotal = BASINS.length * basinFields.length;
  const basinPct =
    basinTotal > 0 ? +((basinFilled / basinTotal) * 100).toFixed(1) : 0;

  // Reservoir property completeness
  const resFilled = ANALOGUES.reduce(
    (s, a) =>
      s +
      ["por", "perm", "rf", "ntg", "depth", "sw"].filter(
        (f) => a[f] != null && a[f] !== "" && a[f] !== 0,
      ).length,
    0,
  );
  const resTotal = ANALOGUES.length * 6;
  // Also add lithostratigraphy reservoir data
  const lithResFilled = LITHOSTRATIGRAPHY.reduce(
    (s, r) =>
      s +
      [
        "porosity_avg_pct",
        "permeability_avg_md",
        "gross_thickness_avg_m",
      ].filter((f) => r[f] > 0).length,
    0,
  );
  const lithResTotal = LITHOSTRATIGRAPHY.length * 3;
  const resPct =
    resTotal + lithResTotal > 0
      ? +(
          ((resFilled + lithResFilled) / (resTotal + lithResTotal)) *
          100
        ).toFixed(1)
      : 0;

  // Source rock data completeness — includes PETROLEUM_SYSTEMS and GEOCHEMISTRY_FLUIDS
  const srcFilled =
    ANALOGUES.reduce(
      (s, a) =>
        s +
        (a.geochem
          ? [
              "toc",
              "ro_vitrinite",
              "hindex",
              "tmax",
              "kerogen_type",
            ].filter((f) => a.geochem[f] != null).length
          : 0),
      0,
    ) +
    PETROLEUM_SYSTEMS.reduce(
      (s, r) =>
        s +
        [
          "source_rock_toc_pct",
          "source_rock_hi",
          "source_rock_ro",
          "kerogen_type",
        ].filter((f) => r[f] && r[f] !== 0).length,
      0,
    ) +
    GEOCHEMISTRY_FLUIDS.reduce(
      (s, r) =>
        s +
        [
          "api_gravity_med",
          "gor_mode_scf_bbl",
          "viscosity_med_cp",
        ].filter((f) => r[f] > 0).length,
      0,
    );
  const srcTotal =
    ANALOGUES.length * 5 +
    PETROLEUM_SYSTEMS.length * 4 +
    GEOCHEMISTRY_FLUIDS.length * 3;
  const srcPct =
    srcTotal > 0 ? +((srcFilled / srcTotal) * 100).toFixed(1) : 0;

  // Commercial data — includes RESERVES_PRODUCTION
  const comFilled =
    BASINS.reduce(
      (s, b) =>
        s +
        commercialFields.filter(
          (f) => b[f] != null && b[f] !== "" && b[f] !== 0,
        ).length,
      0,
    ) +
    RESERVES_PRODUCTION.reduce(
      (s, r) =>
        s +
        [
          "reserves_recoverable_mbl",
          "production_total_kboed",
          "ytf_total_mmboe",
          "num_fields",
        ].filter((f) => r[f] > 0).length,
      0,
    );
  const comTotal =
    BASINS.length * commercialFields.length +
    RESERVES_PRODUCTION.length * 4;
  const comPct =
    comTotal > 0 ? +((comFilled / comTotal) * 100).toFixed(1) : 0;

  const items = [
    { label: "Basin Records", val: basinPct },
    { label: "Reservoir Properties", val: resPct },
    { label: "Source Rock Data", val: srcPct },
    { label: "Commercial Data", val: comPct },
  ];
  const overall = items.length
    ? +(items.reduce((s, i) => s + i.val, 0) / items.length).toFixed(1)
    : 0;

  // Flagged records
  const flagged =
    BASINS.filter((b) => !b.country || !b.score).length +
    ANALOGUES.filter((a) => !a.por || !a.depth).length;
  const pending = ANALOGUES.filter((a) => !a.geochem).length;

  // Draw Chart.js doughnut
  const canvas = document.getElementById("dq-chart-canvas");
  if (canvas && typeof Chart !== "undefined") {
    if (window._dqDoughnut) {
      try {
        window._dqDoughnut.destroy();
      } catch (e) {}
    }
    window._dqDoughnut = new Chart(canvas, {
      type: "doughnut",
      data: {
        labels: items.map((i) => i.label),
        datasets: [
          {
            data: items.map((i) => i.val),
            backgroundColor: items.map((i) =>
              i.val >= 90
                ? "rgba(0,135,90,.7)"
                : i.val >= 70
                  ? "rgba(192,120,0,.7)"
                  : "rgba(217,48,37,.7)",
            ),
            borderWidth: 2,
            borderColor: "#fff",
          },
        ],
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        cutout: "62%",
        plugins: {
          legend: { display: false },
          tooltip: {
            backgroundColor: "rgba(26,29,46,.93)",
            titleFont: { size: 12, weight: "bold" },
            bodyFont: { size: 11 },
            padding: 12,
            cornerRadius: 8,
            callbacks: {
              label: function (ctx) {
                const it = items[ctx.dataIndex];
                const grade =
                  it.val >= 90
                    ? "Excellent"
                    : it.val >= 70
                      ? "Acceptable"
                      : "Needs improvement";
                return [
                  "  Completeness: " + it.val + "%",
                  "  Grade: " + grade,
                ];
              },
            },
          },
        },
      },
      plugins: [
        {
          id: "dqCenter",
          afterDraw(chart) {
            const {
              ctx,
              chartArea: { width, height, top, left },
            } = chart;
            const cx = left + width / 2,
              cy = top + height / 2;
            ctx.save();
            ctx.fillStyle =
              overall >= 90
                ? "#1A7F5A"
                : overall >= 70
                  ? "#C07800"
                  : "#C62828";
            ctx.font = "bold 22px Arial";
            ctx.textAlign = "center";
            ctx.fillText(overall + "%", cx, cy - 2);
            ctx.fillStyle = "#8896A5";
            ctx.font = "9px Arial";
            ctx.fillText("Overall DQ", cx, cy + 14);
            ctx.restore();
          },
        },
      ],
    });
  }

  // Render bar breakdown below chart
  const barsEl = document.getElementById("dq-summary-bars");
  if (barsEl) {
    barsEl.innerHTML =
      items
        .map((it) => {
          const c =
            it.val >= 90
              ? "var(--green)"
              : it.val >= 70
                ? "var(--amber)"
                : "var(--red)";
          return `<div style="margin-bottom:8px">
  <div style="display:flex;justify-content:space-between;margin-bottom:2px">
    <span style="font-size:10px;color:var(--t2)">${it.label}</span>
    <span style="font-size:10px;font-weight:700;color:${c}">${it.val}%</span>
  </div>
  <div class="sbar-track" style="height:4px"><div class="sbar-fill" style="width:${it.val}%;background:${c}"></div></div>
</div>`;
        })
        .join("") +
      `<div style="margin-top:8px;padding:6px 10px;background:rgba(0,200,255,.04);border:1px solid var(--b1);border-radius:4px;font-size:10px">
<span style="color:var(--t3);font-size:10px;text-transform:uppercase;letter-spacing:1px">GOVERNANCE</span><br>
<span style="color:var(--t1)">${pending} records pending</span>${flagged > 0 ? ' · <span style="color:var(--amber)">' + flagged + " flagged</span>" : ' · <span style="color:var(--green)">All clean</span>'}
</div>`;
  }
}

// ============================================================
// RESOURCE DISTRIBUTION CHART — Real P10/P50/P90 from BASINS
// ============================================================
function renderResourceDistChart() {
  const canvas = document.getElementById("resource-dist-canvas");
  if (!canvas || typeof Chart === "undefined") return;

  // === Compute totals ===
  let totalP10 = 100, totalP50 = 200, totalP90 = 400; // Example, replace with your real computation

  // === Generate bins and distribution ===
  const BINS = 30;
  const minV = totalP10 * 0.4;
  const maxV = totalP90 * 1.3;
  const mu = Math.log(totalP50);
  const sig = 0.5;

  const labels = Array.from({length: BINS}, (_, i) =>
    Math.round(minV + ((maxV - minV) * (i + 0.5)) / BINS)
  );

  const raw = labels.map(x =>
    x > 0 ? Math.exp(-((Math.log(x) - mu) ** 2)/(2*sig*sig)) / (x*sig) : 0
  );

  const mxH = Math.max(...raw);
  const counts = raw.map(h => +((h/mxH)*100).toFixed(1));

  const bgColors = labels.map(v =>
    v < totalP10 ? "rgba(255,77,106,.5)"
    : v < totalP50 ? "rgba(0,200,255,.5)"
    : "rgba(240,165,0,.45)"
  );

  // === Plugin for P-lines ===
  const pLinePlugin = {
    id: 'resDist_plines',
    afterDatasetsDraw(chart) {
      const {ctx, chartArea: {top, bottom}, scales: {x}} = chart;
      [
        {v: totalP10, c:"#FF4D6A", t:"P10 " + totalP10},
        {v: totalP50, c:"#00E5A0", t:"P50 " + totalP50},
        {v: totalP90, c:"#F0A500", t:"P90 " + totalP90},
      ].forEach(ln => {
        const idx = labels.findIndex(l => l >= ln.v);
        if (idx < 0) return;
        const px = x.getPixelForValue(idx);
        ctx.save();
        ctx.strokeStyle = ln.c;
        ctx.lineWidth = 1.5;
        ctx.setLineDash([4,3]);
        ctx.beginPath();
        ctx.moveTo(px, top);
        ctx.lineTo(px, bottom);
        ctx.stroke();
        ctx.setLineDash([]);
        ctx.fillStyle = ln.c;
        ctx.font = "bold 9px Arial";
        ctx.textAlign = "center";
        ctx.fillText(ln.t, px, top - 4);
        ctx.restore();
      });
    }
  };

  // === Destroy previous chart if exists ===
  if (window._resDistChart) window._resDistChart.destroy();

  window._resDistChart = new Chart(canvas, {
    type: "bar",
    data: {
      labels,
      datasets: [{
        data: counts,
        backgroundColor: bgColors,
        borderWidth: 0,
        barPercentage: 1,
        categoryPercentage: 1
      }]
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      layout: {padding: {top:16}},
      plugins: {
        legend: {display:false},
        tooltip: {
          backgroundColor:"rgba(26,29,46,.93)",
          titleFont: {size:11, weight:"bold"},
          bodyFont: {size:10},
          padding:10,
          cornerRadius:8,
          callbacks: {
            title: items => "Resource ≈ " + items[0].label + " MMboe",
            label: item => {
              const v = parseInt(item.label);
              const zone = v < totalP10 ? "🔴 Below P10" :
                          v < totalP50 ? "🔵 P10–P50" :
                          v < totalP90 ? "🟠 P50–P90" : "⬆ Above P90";
              return ["  Zone: " + zone];
            },
            afterBody: () => ["", "  P10: "+totalP10+" MMboe", "  P50: "+totalP50+" MMboe", "  P90: "+totalP90+" MMboe"]
          }
        }
      },
      scales: {
        x: {
          ticks: {maxTicksLimit:6, font:{size:7}, color:"#8896A5"},
          grid: {display:false}
        },
        y: {display:false, beginAtZero:true}
      },
      animation:{duration:500}
    },
    plugins: [pLinePlugin]
  });
}

// ============================================================
// BASIN TABLE
// ============================================================
function renderBasinTable(data) {
  filteredBasins = data;
  document.getElementById("basin-count").textContent =
    `Basin Catalogue — ${data.length} Records`;
  document.getElementById("basin-tbody").innerHTML = data
    .map((b) => {
      const c =
        b.score >= 70
          ? "var(--green)"
          : b.score >= 40
            ? "var(--amber)"
            : "var(--red)";
      const tl = b.score >= 70 ? "tl-g" : b.score >= 40 ? "tl-a" : "tl-r";
      const tlText =
        b.score >= 70 ? "HIGH" : b.score >= 40 ? "MEDIUM" : "LOW";
      const hcBadge =
        b.hc === "Oil" ? "bg" : b.hc === "Gas" ? "be" : "bc";
      return `<tr style="cursor:pointer" onclick="focusBasinOnMap('${b.name}')">
        <td style="color:var(--t1);font-weight:600">${b.name}</td>
        <td>${b.country}</td>
        <td>${b.tectonic}</td>
        <td>${b.age}</td>
        <td><span class="badge ${hcBadge}">${b.hc}</span></td>
        <td>${b.area.toLocaleString()}</td>
        <td>${b.plays}</td>
        <td><div class="sbar"><div class="sbar-track"><div class="sbar-fill" style="width:${b.score}%;background:${c}"></div></div><span class="sval" style="color:${c}">${b.score}</span></div></td>
        <td><span class="tl ${tl}">${tlText}</span></td>
        <td><button class="btn-view" onclick="showBasinDetail('${b.name}')">Details</button></td>
      </tr>`;
    })
    .join("");
}

function filterBasins() {
  const q = document.getElementById("basin-search").value.toLowerCase();
  const region = document.getElementById("basin-region").value;
  const tecto = document.getElementById("basin-tecto").value;
  const hc = document.getElementById("basin-hc").value;
  const status = document.getElementById("basin-status").value;
  let data = BASINS.filter((b) => {
    if (
      q &&
      !b.name.toLowerCase().includes(q) &&
      !b.country.toLowerCase().includes(q) &&
      !b.age.toLowerCase().includes(q)
    )
      return false;
    if (region && b.region !== region) return false;
    if (tecto && b.tectonic !== tecto) return false;
    if (hc && b.hc !== hc) return false;
    if (status && b.status !== status) return false;
    return true;
  });
  renderBasinTable(data);
  if (data.length === 0) toast("No basins match your filters", "warning");
}

function resetBasinFilters() {
  [
    "basin-search",
    "basin-region",
    "basin-tecto",
    "basin-hc",
    "basin-status",
  ].forEach((id) => (document.getElementById(id).value = ""));
  renderBasinTable(BASINS);
}

function sortBasins(col) {
  if (sortState.col === col) sortState.dir *= -1;
  else {
    sortState.col = col;
    sortState.dir = 1;
  }
  const sorted = [...filteredBasins].sort((a, b) => {
    let av = a[col],
      bv = b[col];
    if (typeof av === "string")
      return av.localeCompare(bv) * sortState.dir;
    return (av - bv) * sortState.dir;
  });
  renderBasinTable(sorted);
}

function showBasinDetail(name) {
  const b = BASINS.find((x) => x.name === name);
  if (!b) return;
  const c =
    b.score >= 70
      ? "var(--green)"
      : b.score >= 40
        ? "var(--amber)"
        : "var(--red)";
  openModal(`
<div class="modal-title">${b.name}</div>
<div class="modal-sub">${b.country} &nbsp;·&nbsp; ${b.region} &nbsp;·&nbsp; ${b.tectonic}</div>
<div style="display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-bottom:16px">
<div style="background:var(--bg4);border-radius:5px;padding:10px;text-align:center">
  <div style="font-size:10px;color:var(--t3);text-transform:uppercase;letter-spacing:1px;margin-bottom:3px">Score</div>
  <div style="font-size:26px;font-weight:700;color:${c}">${b.score}</div>
</div>
<div style="background:var(--bg4);border-radius:5px;padding:10px;text-align:center">
  <div style="font-size:10px;color:var(--t3);text-transform:uppercase;letter-spacing:1px;margin-bottom:3px">Plays</div>
  <div style="font-size:26px;font-weight:700;color:var(--cyan)">${b.plays}</div>
</div>
<div style="background:var(--bg4);border-radius:5px;padding:10px;text-align:center">
  <div style="font-size:10px;color:var(--t3);text-transform:uppercase;letter-spacing:1px;margin-bottom:3px">Area km²</div>
  <div style="font-size:18px;font-weight:700;color:var(--gold)">${b.area.toLocaleString()}</div>
</div>
</div>
<table><tbody>
<tr><td style="color:var(--t3);font-size:10px">HC Phase</td><td style="color:var(--t1)">${b.hc}</td></tr>
<tr><td style="color:var(--t3);font-size:10px">Geological Age</td><td style="color:var(--t1)">${b.age}</td></tr>
<tr><td style="color:var(--t3);font-size:10px">Exploration Status</td><td style="color:var(--t1)">${b.status}</td></tr>
</tbody></table>
<div style="display:flex;gap:8px;margin-top:16px">
<button class="btn" onclick="closeModal();goTo('analogues',null)">Find Analogues →</button>
<button class="btn2" onclick="closeModal();goTo('screening',null)">Screen This Basin →</button>
</div>
`);
}

// ============================================================
// CUSTOM PENALTY WEIGHTS ENGINE
// ============================================================

// Default weights — mirrors the standard EDAFY scoring

// ════════════════════════════════════════════════════════════════
// CENTRAL AI ENGINE — OpenAI / Claude unified interface
// ════════════════════════════════════════════════════════════════

// ── Config state (persisted to localStorage) ──────────────────
const _AI_STORAGE_KEY = "edafy_ai_config";

function _aiLoadConfig() {
  try {
    return JSON.parse(localStorage.getItem(_AI_STORAGE_KEY) || "{}");
  } catch (e) {
    return {};
  }
}

function _aiSaveConfig(cfg) {
  try {
    localStorage.setItem(_AI_STORAGE_KEY, JSON.stringify(cfg));
  } catch (e) {}
}

let _aiCfg = _aiLoadConfig();

// ── Getters ────────────────────────────────────────────────────
function aiGetProvider() {
  return _aiCfg.provider || "claude";
}
function aiGetKey() {
  return _aiCfg.key || "";
}
function aiGetModel() {
  return _aiCfg.model || "gpt-4o";
}
function aiGetTemperature() {
  return parseFloat(_aiCfg.temperature ?? 0.3);
}
function aiGetMaxTokens() {
  return parseInt(_aiCfg.maxTokens ?? 800);
}
function aiGetTone() {
  return _aiCfg.tone || "technical";
}
function aiGetSystemPrompt() {
  return _aiCfg.systemPrompt || "";
}
function aiIsConfigured() {
  return !!aiGetKey() || aiGetProvider() === "claude";
}

// ── Default system prompts ─────────────────────────────────────
const AI_SYSTEM_PROMPTS = {
  technical:
    "You are an expert petroleum exploration geologist AI embedded in the EDAFY Geo-Basin Intelligence Platform. Provide concise, technical, actionable insights. Use <strong> tags for key terms. Keep responses to 3-4 sentences unless asked for more.",
  concise:
    "You are a petroleum AI assistant. Give bullet-point answers. Use <strong> for key terms. Maximum 4 bullets.",
  executive:
    "You are a petroleum exploration AI assistant. Provide executive-level summaries — focus on decisions, risks, and commercial implications. 2-3 sentences, no jargon.",
  educational:
    "You are a petroleum geology teacher. Explain clearly, define technical terms, and use analogies where helpful. Aim for 4-5 sentences.",
};

function _aiGetSystemPrompt(override) {
  if (override) return override;
  const custom = aiGetSystemPrompt();
  if (custom) return custom;
  return AI_SYSTEM_PROMPTS[aiGetTone()] || AI_SYSTEM_PROMPTS.technical;
}

// ── Central callAI function ────────────────────────────────────
async function callAI(prompt, systemPromptOverride, optMaxTokens) {
  const provider = aiGetProvider();
  const key = aiGetKey();
  const maxTok = optMaxTokens || aiGetMaxTokens();
  const sysPmt = _aiGetSystemPrompt(systemPromptOverride);
  const temp = aiGetTemperature();

  // ── OpenAI ──
  if (provider === "openai") {
    if (!key) {
      return "[AI not configured — go to AI Configuration in the sidebar to add your OpenAI API key]";
    }
    try {
      const res = await fetch(
        "https://api.openai.com/v1/chat/completions",
        {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            Authorization: "Bearer " + key,
          },
          body: JSON.stringify({
            model: aiGetModel(),
            max_tokens: maxTok,
            temperature: temp,
            messages: [
              { role: "system", content: sysPmt },
              { role: "user", content: prompt },
            ],
          }),
        },
      );
      const data = await res.json();
      if (data.error) {
        console.error("OpenAI error:", data.error);
        return (
          "[OpenAI error: " + (data.error.message || "unknown") + "]"
        );
      }
      return data.choices?.[0]?.message?.content || null;
    } catch (e) {
      return "[OpenAI request failed: " + e.message + "]";
    }
  }

  // ── Claude ──
  if (provider === "claude") {
    try {
      const claudeModel =
        _aiCfg.claudeModel || "claude-haiku-4-5-20251001";
      const res = await fetch("https://api.anthropic.com/v1/messages", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "anthropic-version": "2023-06-01",
          "anthropic-dangerous-direct-browser-access": "true",
          "x-api-key": _aiCfg.claudeKey || _aiCfg.key || "",
        },
        body: JSON.stringify({
          model: claudeModel,
          max_tokens: maxTok,
          system: sysPmt,
          messages: [{ role: "user", content: prompt }],
        }),
      });
      const data = await res.json();
      if (data.error)
        return (
          "[Claude error: " + (data.error.message || "unknown") + "]"
        );
      return data.content?.[0]?.text || null;
    } catch (e) {
      return "[Claude request failed: " + e.message + "]";
    }
  }

  return null;
}

// ── Backwards compatibility shim ──────────────────────────────
// All old callClaudeAI calls now route through callAI
async function callClaudeAI(prompt, systemPrompt) {
  return callAI(prompt, systemPrompt);
}

// ════════════════════════════════════════════════════════════════
// AI CONFIG UI FUNCTIONS
// ════════════════════════════════════════════════════════════════

function aiSelectProvider(provider) {
  _aiCfg.provider = provider;
  _aiSaveConfig(_aiCfg);

  // Update card styles
  const openaiCard = document.getElementById("ai-prov-openai-card");
  const claudeCard = document.getElementById("ai-prov-claude-card");
  if (openaiCard) {
    openaiCard.style.border =
      provider === "openai"
        ? "2px solid var(--purple)"
        : "2px solid transparent";
    openaiCard.style.background =
      provider === "openai" ? "rgba(124,58,237,.04)" : "#F8FAFF";
  }
  if (claudeCard) {
    claudeCard.style.border =
      provider === "claude"
        ? "2px solid var(--purple)"
        : "2px solid transparent";
    claudeCard.style.background =
      provider === "claude" ? "rgba(124,58,237,.04)" : "#F8FAFF";
  }

  // Update model selector options
  const modelSel = document.getElementById("ai-model-select");
  const keyLabel = document.getElementById("ai-key-label");
  const keyInput = document.getElementById("ai-api-key-input");
  if (modelSel) {
    if (provider === "openai") {
      modelSel.innerHTML = `
  <option value="gpt-4o">GPT-4o (recommended)</option>
  <option value="gpt-4o-mini">GPT-4o-mini (fast & cheap)</option>
  <option value="gpt-4-turbo">GPT-4-turbo</option>
  <option value="gpt-3.5-turbo">GPT-3.5-turbo (legacy)</option>`;
      modelSel.value = _aiCfg.model || "gpt-4o";
    } else {
      modelSel.innerHTML = `
  <option value="claude-sonnet-4-20250514">Claude Sonnet 4 (recommended)</option>
  <option value="claude-haiku-4-5-20251001">Claude Haiku (fast)</option>
  <option value="claude-opus-4-6">Claude Opus 4 (powerful)</option>`;
      modelSel.value = _aiCfg.claudeModel || "claude-sonnet-4-20250514";
    }
  }
  if (keyLabel)
    keyLabel.firstChild.textContent =
      provider === "openai"
        ? "OpenAI API Key"
        : "Anthropic API Key (optional in claude.ai)";
  if (keyInput)
    keyInput.placeholder =
      provider === "openai"
        ? "sk-..."
        : "sk-ant-... (leave blank inside claude.ai)";

  aiUpdateBadge();
}

function aiKeyPreview() {
  const input = document.getElementById("ai-api-key-input");
  const status = document.getElementById("ai-key-status");
  if (!input || !status) return;
  const val = input.value.trim();
  if (!val) {
    status.textContent = "No key entered";
    status.style.color = "var(--t3)";
    return;
  }
  status.textContent =
    val.length > 8
      ? "Key entered (" + val.length + " chars) — press Save to apply"
      : "Key too short";
  status.style.color = val.length > 8 ? "var(--amber)" : "var(--red)";
}

function aiSaveKey() {
  const input = document.getElementById("ai-api-key-input");
  if (!input) return;
  const val = input.value.trim();
  if (!val) {
    toast("Enter an API key first", "warn");
    return;
  }
  if (val.length < 10) {
    toast("Key appears too short", "warn");
    return;
  }
  _aiCfg.key = val;
  const prov = aiGetProvider();
  if (prov === "claude") _aiCfg.claudeKey = val;
  _aiSaveConfig(_aiCfg);
  // Mask display
  input.value = val.slice(0, 4) + "••••••••" + val.slice(-4);
  input.type = "password";
  const status = document.getElementById("ai-key-status");
  if (status) {
    status.textContent = "✅ Key saved (" + val.length + " chars)";
    status.style.color = "var(--green)";
  }
  aiUpdateBadge();
  toast("✅ API key saved", "success");
}

function aiToggleKeyVisibility() {
  const input = document.getElementById("ai-api-key-input");
  if (!input) return;
  input.type = input.type === "password" ? "text" : "password";
}

function aiSaveSettings() {
  const model = document.getElementById("ai-model-select")?.value;
  const temp = document.getElementById("ai-temp-val")?.textContent;
  const maxTok = document.getElementById("ai-max-tokens")?.value;
  const tone = document.getElementById("ai-tone")?.value;
  const sysPmt = document.getElementById("ai-system-prompt")?.value;
  const prov = aiGetProvider();
  if (model) {
    if (prov === "claude") _aiCfg.claudeModel = model;
    else _aiCfg.model = model;
  }
  if (temp) _aiCfg.temperature = parseFloat(temp);
  if (maxTok) _aiCfg.maxTokens = parseInt(maxTok);
  if (tone) _aiCfg.tone = tone;
  if (sysPmt !== undefined) _aiCfg.systemPrompt = sysPmt;
  _aiSaveConfig(_aiCfg);
  aiUpdateBadge();
}

function aiClearKey() {
  if (!confirm("Clear the saved API key?")) return;
  delete _aiCfg.key;
  delete _aiCfg.claudeKey;
  _aiSaveConfig(_aiCfg);
  const input = document.getElementById("ai-api-key-input");
  if (input) {
    input.value = "";
    input.type = "password";
  }
  const status = document.getElementById("ai-key-status");
  if (status) {
    status.textContent = "Key cleared";
    status.style.color = "var(--t3)";
  }
  aiUpdateBadge();
  toast("API key cleared", "info");
}

function aiUpdateBadge() {
  const badge = document.getElementById("ai-provider-badge");
  const navBadge = document.getElementById("nav-aiconfig");
  if (!badge) return;
  const prov = aiGetProvider();
  const hasKey = !!aiGetKey();
  const configured = hasKey || prov === "claude";
  badge.textContent = configured
    ? prov === "openai"
      ? "OpenAI · " + aiGetModel()
      : "Claude · " + (_aiCfg.claudeModel || "Sonnet")
    : "NOT CONFIGURED";
  badge.style.background = configured
    ? "rgba(0,135,90,.12)"
    : "rgba(124,58,237,.1)";
  badge.style.color = configured ? "var(--green)" : "var(--purple)";
}

async function aiTestConnection() {
  const statusEl = document.getElementById("ai-test-status");
  const outputEl = document.getElementById("ai-test-output");
  const card = document.getElementById("ai-test-card");
  if (statusEl) {
    statusEl.textContent = "⏳ Testing…";
    statusEl.style.color = "var(--amber)";
  }
  if (card) card.style.display = "block";
  if (outputEl)
    outputEl.innerHTML =
      '<div style="color:var(--purple);display:flex;align-items:center;gap:8px"><div style="width:8px;height:8px;border-radius:50%;background:var(--purple);animation:pulse 1s infinite"></div>Sending test prompt to ' +
      aiGetProvider() +
      "…</div>";

  const result = await callAI(
    "In exactly one sentence, confirm you are ready to assist with petroleum exploration analysis for the EDAFY platform.",
    "You are an AI assistant for petroleum exploration. Confirm readiness in one sentence.",
    200,
  );

  if (statusEl) {
    const ok = result && !result.startsWith("[");
    statusEl.textContent = ok ? "✅ Connected" : "❌ Failed";
    statusEl.style.color = ok ? "var(--green)" : "var(--red)";
  }
  if (outputEl) {
    const ok = result && !result.startsWith("[");
    outputEl.innerHTML = ok
      ? `<div style="color:var(--green);font-weight:600;margin-bottom:6px">✅ Connection successful</div><div style="color:var(--t2)">\${result}</div><div style="font-size:10px;color:var(--t3);margin-top:8px">Provider: \${aiGetProvider()} · Model: \${aiGetProvider() === "claude" ? (_aiCfg.claudeModel || "claude-haiku-4-5-20251001") : aiGetModel()} · Tokens: \${aiGetMaxTokens()}</div>`
      : `<div style="color:var(--red);font-weight:600;margin-bottom:6px">❌ Connection failed</div><div style="color:var(--t2);font-family:monospace;font-size:10px">\${result || 'No response received'}</div><div style="font-size:10px;color:var(--t3);margin-top:8px">Check your API key and network connection.</div>`;
  }
}

// ── Restore config on page load ────────────────────────────────
function aiRestoreConfig() {
  const cfg = _aiCfg;
  // Provider
  if (cfg.provider) {
    const radio = document.getElementById("ai-radio-" + cfg.provider);
    if (radio) radio.checked = true;
    aiSelectProvider(cfg.provider);
  }
  // Key (masked)
  if (cfg.key) {
    const input = document.getElementById("ai-api-key-input");
    if (input) {
      const k = cfg.key;
      input.value = k.slice(0, 4) + "••••••••" + k.slice(-4);
    }
    const status = document.getElementById("ai-key-status");
    if (status) {
      status.textContent = "✅ Key saved";
      status.style.color = "var(--green)";
    }
  }
  // Model
  if (cfg.model) {
    const sel = document.getElementById("ai-model-select");
    if (sel)
      sel.value =
        cfg.provider === "claude"
          ? cfg.claudeModel || "claude-sonnet-4-20250514"
          : cfg.model;
  }
  // Temperature
  if (cfg.temperature !== undefined) {
    const slider = document.querySelector(
      "#sec-aiconfig input[type=range]",
    );
    if (slider) {
      slider.value = Math.round(cfg.temperature * 10);
    }
    const val = document.getElementById("ai-temp-val");
    if (val) val.textContent = cfg.temperature.toFixed(1);
  }
  // Max tokens
  if (cfg.maxTokens) {
    const sel = document.getElementById("ai-max-tokens");
    if (sel) sel.value = cfg.maxTokens;
  }
  // Tone
  if (cfg.tone) {
    const sel = document.getElementById("ai-tone");
    if (sel) sel.value = cfg.tone;
  }
  // System prompt
  if (cfg.systemPrompt) {
    const ta = document.getElementById("ai-system-prompt");
    if (ta) ta.value = cfg.systemPrompt;
  }
  aiUpdateBadge();
}

