function onWeightChange(key, val) {
  const v = Math.max(0, parseInt(val) || 0);
  const numEl = document.getElementById("wtn-" + key);
  if (numEl) numEl.value = v;
  WT[key] = v;
  updateWeightBar(key, v);
  markCustom();
  updateWeightSummary();
}

function onWeightChangeNum(key, val) {
  const slider = document.getElementById("wt-" + key);
  const v = Math.max(0, parseInt(val) || 0);
  if (slider) {
    slider.value = Math.min(v, parseInt(slider.max));
  }
  WT[key] = v;
  updateWeightBar(key, v);
  markCustom();
  updateWeightSummary();
}

function updateWeightBar(key, v) {
  const bar = document.getElementById("wtb-" + key);
  const slider = document.getElementById("wt-" + key);
  if (!bar || !slider) return;
  const pct = Math.min(100, (v / parseInt(slider.max)) * 100);
  bar.style.width = pct + "%";
}

