// ============================================================
// FUZZY MATCHING ENGINE
// ============================================================

// Levenshtein edit distance
function levenshtein(a, b) {
  if (!a || !b) return Math.max((a || "").length, (b || "").length);
  a = a.toLowerCase();
  b = b.toLowerCase();
  const m = a.length,
    n = b.length;
  const d = Array.from({ length: m + 1 }, (_, i) => {
    const r = new Array(n + 1);
    r[0] = i;
    return r;
  });
  for (let j = 1; j <= n; j++) d[0][j] = j;
  for (let i = 1; i <= m; i++)
    for (let j = 1; j <= n; j++)
      d[i][j] = Math.min(
        d[i - 1][j] + 1,
        d[i][j - 1] + 1,
        d[i - 1][j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1),
      );
  return d[m][n];
}

// Normalised string similarity 0–1
function stringSim(a, b) {
  if (!a || !b) return 0;
  const dist = levenshtein(a, b);
  return 1 - dist / Math.max(a.length, b.length);
}

// Trigram Jaccard similarity
function trigrams(s) {
  s = "  " + (s || "").toLowerCase() + " ";
  const t = new Set();
  for (let i = 0; i < s.length - 2; i++) t.add(s.slice(i, i + 3));
  return t;
}
function trigramSim(a, b) {
  const tA = trigrams(a),
    tB = trigrams(b);
  if (!tA.size || !tB.size) return 0;
  let inter = 0;
  tA.forEach((t) => {
    if (tB.has(t)) inter++;
  });
  return inter / (tA.size + tB.size - inter);
}

// Combined fuzzy score 0–1: blends exact inclusion + token overlap + trigram + Levenshtein
function fuzzyMatch(candidate, target) {
  if (!candidate || !target) return 0;
  const c = candidate.toLowerCase().trim(),
    t = target.toLowerCase().trim();
  if (c === t) return 1.0;
  if (c.includes(t) || t.includes(c)) return 1.0;
  // Token overlap (handles "Fluvio-Deltaic" vs "Deltaic", "Deep Marine" vs "Deepwater")
  const cToks = c.split(/[\s\-_\/,]+/).filter(Boolean);
  const tToks = t.split(/[\s\-_\/,]+/).filter(Boolean);
  const tokenHits = tToks.filter((tt) =>
    cToks.some(
      (ct) =>
        ct.includes(tt) || tt.includes(ct) || stringSim(ct, tt) >= 0.78,
    ),
  );
  const tokenScore = tokenHits.length / Math.max(tToks.length, 1);
  const triScore = trigramSim(c, t);
  const levScore = stringSim(c, t);
  return Math.min(
    1,
    tokenScore * 0.45 + triScore * 0.35 + levScore * 0.2,
  );
}

// Best fuzzy score against a synonym list
function fuzzyMatchSynonyms(candidate, synonyms) {
  if (!candidate || !synonyms?.length) return 0;
  return Math.max(...synonyms.map((s) => fuzzyMatch(candidate, s)));
}

// Convert a 0–1 fuzzy score into a graduated penalty
// matchScore≈1 → no penalty, ≥threshold → soft penalty, <threshold → heavy/full penalty
function fuzzyPenalty(matchScore, maxPenalty, threshold) {
  if (matchScore >= 0.95) return 0;
  if (matchScore >= threshold)
    return Math.round(maxPenalty * (1 - matchScore) * 0.6);
  if (matchScore >= 0.35) return Math.round(maxPenalty * 0.75);
  return maxPenalty;
}

// Geological age proximity — ages that are adjacent get partial credit
const AGE_ORDER = [
  "quaternary",
  "pliocene",
  "miocene",
  "oligocene",
  "eocene",
  "paleocene",
  "cretaceous",
  "jurassic",
  "triassic",
  "permian",
  "carboniferous",
  "devonian",
  "silurian",
  "ordovician",
  "cambrian",
];
function ageIndex(term) {
  const t = term.toLowerCase().split(/[\s\-–]+/)[0];
  // Prefer exact match first, then substring
  let idx = AGE_ORDER.findIndex((x) => x === t);
  if (idx >= 0) return idx;
  idx = AGE_ORDER.findIndex((x) => x.startsWith(t) || t.startsWith(x));
  if (idx >= 0) return idx;
  return AGE_ORDER.findIndex((x) => x.includes(t) || t.includes(x));
}
function ageSim(a, b) {
  if (!a || !b) return 0;
  const al = a.toLowerCase().split(/[\s\-–]+/)[0];
  const bl = b.toLowerCase().split(/[\s\-–]+/)[0];
  if (al === bl) return 1.0;
  if (al.includes(bl) || bl.includes(al)) return 1.0;
  const iA = ageIndex(a);
  const iB = ageIndex(b);
  if (iA < 0 || iB < 0) return fuzzyMatch(a, b); // fallback to string sim
  const dist = Math.abs(iA - iB);
  if (dist === 1) return 0.7; // adjacent period → 70%
  if (dist === 2) return 0.4; // two apart → 40%
  return Math.max(0, 0.2 - dist * 0.03);
}

