function runSearch() {
  const btn = document.getElementById("search-btn");
  btn.textContent = "⬡ Searching…";
  btn.disabled = true;
  loadBar();
  setTimeout(() => {
    btn.textContent = "⬡ Run Search";
    btn.disabled = false;

    // Read all search criteria
    const lith = document.getElementById("s-lith").value;
    const dep = document.getElementById("s-dep").value;
    const age = document.getElementById("s-age").value;
    const hc = document.getElementById("s-hc").value;
    const drive = document.getElementById("s-drive").value;
    const tecto = document.getElementById("s-tecto").value;
    const dmin = parseFloat(document.getElementById("s-dmin").value) || 0;
    const dmax =
      parseFloat(document.getElementById("s-dmax").value) || 99999;
    const apimin =
      parseFloat(document.getElementById("s-apimin").value) || 0;
    const apimax =
      parseFloat(document.getElementById("s-apimax").value) || 100;
    const minsim =
      parseFloat(document.getElementById("s-minsim").value) || 0;

    // ── Advanced filter values (only used if advanced panel open) ──
    const adv = document.getElementById("s-adv-toggle")?.checked;
    const porMin = adv
      ? parseFloat(document.getElementById("s-pormin")?.value) || 0
      : 0;
    const porMax = adv
      ? parseFloat(document.getElementById("s-pormax")?.value) || 100
      : 100;
    const permMin = adv
      ? parseFloat(document.getElementById("s-permmin")?.value) || 0
      : 0;
    const permMax = adv
      ? parseFloat(document.getElementById("s-permmax")?.value) || 1e9
      : 1e9;
    const ntgMin = adv
      ? parseFloat(document.getElementById("s-ntgmin")?.value) || 0
      : 0;
    const rfMin = adv
      ? parseFloat(document.getElementById("s-rfmin")?.value) || 0
      : 0;
    const swMax = adv
      ? parseFloat(document.getElementById("s-swmax")?.value) || 1
      : 1;
    const pcMax = adv
      ? parseFloat(document.getElementById("s-pcmax")?.value) || 99
      : 99;
    const preg = adv
      ? document.getElementById("s-preg")?.value || ""
      : "";
    const kero = adv
      ? document.getElementById("s-kero")?.value || ""
      : "";
    const tocMin = adv
      ? parseFloat(document.getElementById("s-tocmin")?.value) || 0
      : 0;
    const roMin = adv
      ? parseFloat(document.getElementById("s-romin")?.value) || 0
      : 0;
    const roMax = adv
      ? parseFloat(document.getElementById("s-romax")?.value) || 99
      : 99;
    const oilfam = adv
      ? document.getElementById("s-oilfam")?.value || ""
      : "";
    const charge = adv
      ? document.getElementById("s-charge")?.value || ""
      : "";
    const h2sMax = adv
      ? parseFloat(document.getElementById("s-h2smax")?.value) || 1e6
      : 1e6;
    const co2Max = adv
      ? parseFloat(document.getElementById("s-co2max")?.value) || 100
      : 100;
    const sulMax = adv
      ? parseFloat(document.getElementById("s-sulmax")?.value) || 100
      : 100;
    const stress = adv
      ? document.getElementById("s-stress")?.value || ""
      : "";
    const sandProd = adv
      ? document.getElementById("s-sandprod")?.value || ""
      : "";
    const hfMin = adv
      ? parseFloat(document.getElementById("s-hfmin")?.value) || 0
      : 0;
    const hfMax = adv
      ? parseFloat(document.getElementById("s-hfmax")?.value) || 9999
      : 9999;
    const protect = adv
      ? document.getElementById("s-protect")?.value || ""
      : "";
    const hydrate = adv
      ? document.getElementById("s-hydrate")?.value || ""
      : "";
    const npvMin = adv
      ? parseFloat(document.getElementById("s-npvmin")?.value) || -1e9
      : -1e9;
    const fiscal = adv
      ? document.getElementById("s-fiscal")?.value || ""
      : "";

    // Compute live similarity score for each analogue
    function computeSim(a) {
      // ─────────────────────────────────────────────────────────────────────
      // Weighted Penalty Scoring  —  score = 100 − Σ penalties
      // All penalty magnitudes come from getW(key) so users can customise
      // each dimension via the ⚖ Custom Penalty Weights panel.
      // ─────────────────────────────────────────────────────────────────────
      let score = 100;

      // ── Core geological criteria ─────────────────────────────────────────
      // When fuzzy logic is enabled, categorical fields use graduated penalties
      // instead of binary match/no-match, and geological age uses stratigraphic
      // proximity scoring.

      // Track fuzzy match breakdown for result cards
      const _fb = {};

      // 1. Lithology match (fuzzy: synonym + trigram + Levenshtein)
      if (a.lith && getW("lith") > 0) {
        const lithMap = {
          Sandstone: [
            "sandstone",
            "sand",
            "ss",
            "siliciclastic",
            "clastic",
            "arenite",
            "quartzarenite",
            "greywacke",
          ],
          Carbonate: [
            "carbonate",
            "limestone",
            "chalk",
            "dolomite",
            "lime",
            "reef",
            "calcarenite",
            "grainstone",
            "packstone",
          ],
          Chalk: ["chalk", "calcareous", "cretaceous chalk"],
          Conglomerate: [
            "conglomerate",
            "gravel",
            "breccia",
            "rudite",
            "fanglomerate",
          ],
          Mixed: ["mixed", "hybrid", "heterolithic", "interbedded"],
        };
        const targets = lithMap[lith] || [lith.toLowerCase()];
        if (_fuzzyEnabled) {
          const fScore = fuzzyMatchSynonyms(a.lith, targets);
          _fb.lith = fScore;
          score -= fuzzyPenalty(fScore, getW("lith"), _fuzzyThreshold);
        } else {
          const hit = targets.some((t) =>
            a.lith.toLowerCase().includes(t),
          );
          _fb.lith = hit ? 1 : 0;
          if (!hit) score -= getW("lith");
        }
      }

      // 2. Depositional environment (fuzzy: synonym + token overlap)
      if (a.dep && getW("dep") > 0) {
        const depMap = {
          Deltaic: [
            "delt",
            "fan delta",
            "fluvio-delt",
            "delta front",
            "delta plain",
            "prodelta",
          ],
          Fluvial: [
            "fluvi",
            "fluvial",
            "channel",
            "alluvial",
            "braided",
            "meandering",
          ],
          "Shallow Marine": [
            "shallow",
            "shoreface",
            "shelf",
            "tidal",
            "coastal",
            "barrier",
            "nearshore",
            "lagoon",
          ],
          "Deep Marine": [
            "deep",
            "turbidite",
            "deepwater",
            "submarine",
            "basin floor",
            "abyssal",
          ],
          Reef: [
            "reef",
            "carbonate build",
            "mound",
            "bioherm",
            "biostrome",
          ],
          Turbidite: ["turbid", "turbidite", "fan", "lobe", "contourite"],
          Lacustrine: ["lacus", "lake", "lacustrine", "playa"],
          Aeolian: ["aeol", "eolian", "dune", "erg", "desert"],
        };
        const targets = depMap[dep] || [dep.toLowerCase()];
        if (_fuzzyEnabled) {
          const fScore = fuzzyMatchSynonyms(a.dep, targets);
          _fb.dep = fScore;
          score -= fuzzyPenalty(fScore, getW("dep"), _fuzzyThreshold);
        } else {
          const hit = targets.some((t) =>
            a.dep.toLowerCase().includes(t),
          );
          _fb.dep = hit ? 1 : 0;
          if (!hit) score -= getW("dep");
        }
      }

      // 3. Geological age (fuzzy: stratigraphic proximity)
      if (a.age && getW("age") > 0) {
        if (_fuzzyEnabled) {
          const fScore = ageSim(a.age, age);
          _fb.age = fScore;
          score -= fuzzyPenalty(fScore, getW("age"), _fuzzyThreshold);
        } else {
          const aAge = a.age.toLowerCase(),
            sAge = age.toLowerCase();
          const hit =
            aAge.includes(sAge) ||
            sAge.includes(aAge.split("–")[0].trim());
          _fb.age = hit ? 1 : 0;
          if (!hit) score -= getW("age");
        }
      }

      // 4. HC phase (fuzzy: token + string similarity)
      if (a.hc && getW("hc") > 0) {
        const aHc = a.hc.toLowerCase(),
          sHc = hc.toLowerCase();
        if (sHc === "any") {
          _fb.hc = 1;
        } else if (_fuzzyEnabled) {
          const fScore = fuzzyMatch(aHc, sHc);
          _fb.hc = fScore;
          score -= fuzzyPenalty(fScore, getW("hc"), _fuzzyThreshold);
        } else {
          const hit = aHc.includes(sHc) || sHc.includes(aHc);
          _fb.hc = hit ? 1 : 0;
          if (!hit) score -= getW("hc");
        }
      }

      // 5. Drive mechanism (fuzzy: token + string similarity)
      if (drive !== "Any" && a.drive && getW("drive") > 0) {
        if (_fuzzyEnabled) {
          const fScore = fuzzyMatch(a.drive, drive);
          _fb.drive = fScore;
          score -= fuzzyPenalty(fScore, getW("drive"), _fuzzyThreshold);
        } else {
          const aDrive = a.drive.toLowerCase(),
            sDrive = drive.toLowerCase();
          const hit =
            aDrive.includes(sDrive.split(" ")[0]) ||
            sDrive.includes(aDrive.split(" ")[0]);
          _fb.drive = hit ? 1 : 0;
          if (!hit) score -= getW("drive");
        }
      }

      // 6. Tectonic setting (fuzzy: token + string similarity)
      if (tecto !== "Any" && getW("tecto") > 0) {
        const basin = BASINS.find((b) => b.name === a.basin);
        if (basin?.tectonic) {
          if (_fuzzyEnabled) {
            const fScore = fuzzyMatch(basin.tectonic, tecto);
            _fb.tecto = fScore;
            score -= fuzzyPenalty(fScore, getW("tecto"), _fuzzyThreshold);
          } else {
            const bTecto = basin.tectonic.toLowerCase(),
              sTecto = tecto.toLowerCase();
            const hit =
              bTecto.includes(sTecto.split(" ")[0]) ||
              sTecto.includes(bTecto.split(" ")[0]);
            _fb.tecto = hit ? 1 : 0;
            if (!hit) score -= getW("tecto");
          }
        }
      }

      // 7. Depth range (proportional penalty)
      const depthV = a.depth || 0;
      if (getW("depth") > 0) {
        if (depthV < dmin && dmin > 0)
          score -= Math.min(
            getW("depth"),
            ((dmin - depthV) / dmin) * getW("depth"),
          );
        else if (depthV > dmax && dmax > 0)
          score -= Math.min(
            getW("depth"),
            ((depthV - dmax) / dmax) * getW("depth"),
          );
      }

      // 8. API gravity (proportional penalty)
      const apiV = a.api || 30;
      if (getW("api") > 0) {
        if (apiV < apimin && apimin > 0)
          score -= Math.min(
            getW("api"),
            ((apimin - apiV) / apimin) * getW("api"),
          );
        else if (apiV > apimax && apimax > 0)
          score -= Math.min(
            getW("api"),
            ((apiV - apimax) / apimax) * getW("api"),
          );
      }

      // ── Advanced subsurface (only applied if Advanced Filters toggled on) ──
      if (adv) {
        // Porosity
        if (a.por > 0 && getW("por") > 0) {
          if (a.por < porMin || a.por > porMax) score -= getW("por");
          else
            score += Math.min(
              Math.round(getW("por") * 0.5),
              (1 -
                Math.abs(
                  (a.por - (porMin + porMax) / 2) /
                    ((porMax - porMin) / 2 || 1),
                )) *
                Math.round(getW("por") * 0.5),
            );
        }
        // Permeability
        if (
          a.perm > 0 &&
          getW("perm") > 0 &&
          (a.perm < permMin || a.perm > permMax)
        )
          score -= getW("perm");
        // NTG floor
        if (a.ntg > 0 && getW("ntg") > 0 && a.ntg < ntgMin)
          score -= getW("ntg");
        // Recovery Factor floor
        if (a.rf > 0 && getW("rf") > 0 && a.rf < rfMin)
          score -= getW("rf");
        // Water Saturation ceiling
        if (a.sw && getW("sw") > 0 && a.sw > swMax) score -= getW("sw");
        // Pressure regime
        if (
          preg &&
          getW("preg") > 0 &&
          a.geo?.pressure_regime &&
          !a.geo.pressure_regime
            .toLowerCase()
            .includes(preg.split(" ")[0].toLowerCase())
        )
          score -= getW("preg");
        if (pcMax < 99 && a.geo?.pressure_coeff > pcMax)
          score -= Math.round(getW("preg") * 0.7);
        // Kerogen type (fuzzy-enabled)
        if (kero && getW("kero") > 0 && a.geochem?.kerogen_type) {
          if (_fuzzyEnabled) {
            const fScore = fuzzyMatch(a.geochem.kerogen_type, kero);
            score -= fuzzyPenalty(fScore, getW("kero"), _fuzzyThreshold);
          } else {
            if (
              !a.geochem.kerogen_type
                .toLowerCase()
                .includes(kero.toLowerCase().split("/")[0])
            )
              score -= getW("kero");
          }
        }
        // TOC floor
        if (
          tocMin > 0 &&
          getW("toc") > 0 &&
          a.geochem?.toc &&
          a.geochem.toc < tocMin
        )
          score -= getW("toc");
        // Vitrinite Ro range
        if (a.geochem?.ro_vitrinite && getW("ro") > 0) {
          if (roMin > 0 && a.geochem.ro_vitrinite < roMin)
            score -= getW("ro");
          if (roMax < 99 && a.geochem.ro_vitrinite > roMax)
            score -= getW("ro");
        }
        // Oil family (fuzzy-enabled)
        if (oilfam && getW("oilfam") > 0 && a.geochem?.oil_family) {
          if (_fuzzyEnabled) {
            const fScore = fuzzyMatch(a.geochem.oil_family, oilfam);
            score -= fuzzyPenalty(
              fScore,
              getW("oilfam"),
              _fuzzyThreshold,
            );
          } else {
            if (
              !a.geochem.oil_family
                .toLowerCase()
                .includes(oilfam.toLowerCase())
            )
              score -= getW("oilfam");
          }
        }
        // Charge volume
        if (
          charge &&
          getW("charge") > 0 &&
          a.geochem?.charge_volume &&
          a.geochem.charge_volume !== charge
        )
          score -= getW("charge");
        // H2S — safety critical
        if (getW("h2s") > 0 && a.fluid?.h2s_ppm > h2sMax)
          score -= getW("h2s");
        // CO2
        if (getW("co2") > 0 && a.fluid?.co2_pct > co2Max)
          score -= getW("co2");
        // Sulfur
        if (getW("sul") > 0 && a.geochem?.sulfur_pct > sulMax)
          score -= getW("sul");
        // Stress regime (fuzzy-enabled)
        if (
          stress &&
          getW("stress") > 0 &&
          a.geomechanics?.stress_regime
        ) {
          if (_fuzzyEnabled) {
            const fScore = fuzzyMatch(
              a.geomechanics.stress_regime,
              stress,
            );
            score -= fuzzyPenalty(
              fScore,
              getW("stress"),
              _fuzzyThreshold,
            );
          } else {
            if (
              !a.geomechanics.stress_regime
                .toLowerCase()
                .includes(stress.toLowerCase())
            )
              score -= getW("stress");
          }
        }
        // Sand production risk
        if (
          sandProd &&
          getW("sandprod") > 0 &&
          a.geomechanics?.sand_production_risk &&
          a.geomechanics.sand_production_risk !== sandProd
        )
          score -= getW("sandprod");
        // Heat flow
        if (a.thermal?.surface_heat_flow_mw_m2 && getW("hf") > 0) {
          if (hfMin > 0 && a.thermal.surface_heat_flow_mw_m2 < hfMin)
            score -= getW("hf");
          if (hfMax < 9999 && a.thermal.surface_heat_flow_mw_m2 > hfMax)
            score -= getW("hf");
        }
        // Fiscal regime (fuzzy-enabled)
        if (fiscal && getW("fiscal") > 0 && a.commercial?.fiscal_regime) {
          if (_fuzzyEnabled) {
            const fScore = fuzzyMatch(a.commercial.fiscal_regime, fiscal);
            score -= fuzzyPenalty(
              fScore,
              getW("fiscal"),
              _fuzzyThreshold,
            );
          } else {
            if (
              !a.commercial.fiscal_regime
                .toLowerCase()
                .includes(fiscal.toLowerCase())
            )
              score -= getW("fiscal");
          }
        }
        // NPV floor
        if (
          npvMin > -1e9 &&
          getW("npv") > 0 &&
          a.commercial?.npv_10_musd < npvMin
        )
          score -= getW("npv");
        // Protected area
        if (getW("protect") > 0) {
          if (
            protect === "no" &&
            a.environmental?.protected_area_flag === "Yes"
          )
            score -= getW("protect");
          if (
            protect === "yes" &&
            a.environmental?.protected_area_flag !== "Yes"
          )
            score -= Math.round(getW("protect") * 0.25);
        }
        // Hydrate risk
        if (
          hydrate &&
          getW("hydrate") > 0 &&
          a.environmental?.hydrate_risk &&
          a.environmental.hydrate_risk !== hydrate
        )
          score -= getW("hydrate");
      }

      // ── Above-ground penalties (always applied when weights > 0) ────────────
      // These apply regardless of the advanced toggle — they are a separate axis.

      // Country risk tier
      const countryTier = (
        document.getElementById("wts-country")?.value || ""
      ).toLowerCase();
      if (
        countryTier &&
        getW("country") > 0 &&
        a.commercial?.country_risk
      ) {
        const aRisk = a.commercial.country_risk.toLowerCase();
        if (countryTier.includes("low") && !aRisk.includes("low"))
          score -= getW("country");
        else if (
          countryTier.includes("moderate") &&
          (aRisk.includes("high") || aRisk.includes("very"))
        )
          score -= Math.round(getW("country") * 0.6);
        else if (countryTier.includes("high") && aRisk.includes("very"))
          score -= Math.round(getW("country") * 0.4);
      }

      // Infrastructure proximity
      const infraKm =
        parseFloat(document.getElementById("wts-infra-km")?.value) || 0;
      if (
        infraKm > 0 &&
        getW("infra") > 0 &&
        a.commercial?.infra_distance_km
      ) {
        const diff = a.commercial.infra_distance_km - infraKm;
        if (diff > 0)
          score -= Math.min(
            getW("infra"),
            (diff / infraKm) * getW("infra"),
          );
      }

      // Social licence
      const socialReq = (
        document.getElementById("wts-social")?.value || ""
      ).toLowerCase();
      if (
        socialReq &&
        getW("social") > 0 &&
        a.environmental?.community_sentiment
      ) {
        const sent = a.environmental.community_sentiment.toLowerCase();
        if (socialReq.includes("supportive") && !sent.includes("support"))
          score -= getW("social");
        else if (socialReq.includes("neutral") && sent.includes("oppos"))
          score -= getW("social");
        else if (socialReq.includes("exclude") && sent.includes("oppos"))
          score -= getW("social");
      }

      // Regulatory approval speed
      const regReq = (
        document.getElementById("wts-regspeed")?.value || ""
      ).toLowerCase();
      if (
        regReq &&
        getW("regspeed") > 0 &&
        a.commercial?.regulatory_approval_months
      ) {
        const months = a.commercial.regulatory_approval_months;
        if (regReq.includes("fast") && months > 6)
          score -= getW("regspeed");
        else if (regReq.includes("moderate") && months > 18)
          score -= Math.round(getW("regspeed") * 0.5);
      }

      // Export route availability
      const exportMode = (
        document.getElementById("wts-export")?.value || ""
      ).toLowerCase();
      if (
        exportMode &&
        getW("export") > 0 &&
        a.commercial?.export_route
      ) {
        if (
          !a.commercial.export_route
            .toLowerCase()
            .includes(exportMode.split(" ")[0])
        )
          score -= getW("export");
      }

      // Local content requirements (high-weight countries penalise if content reqs > 50%)
      if (
        getW("localcnt") > 0 &&
        a.commercial?.local_content_requirement_pct
      ) {
        if (a.commercial.local_content_requirement_pct > 70)
          score -= Math.round(getW("localcnt") * 0.8);
        else if (a.commercial.local_content_requirement_pct > 50)
          score -= Math.round(getW("localcnt") * 0.4);
      }

      // ── Basin Context Score (from Screening → Analogue bridge) ─────────────
      // If screening has been run, analogues from high-ranked basins get a bonus
      // and analogues from low-ranked basins get a small penalty.
      let _basinCtx = null;
      if (_usbEnabled && leaderboardData.length > 0 && a.basin) {
        _basinCtx = getBasinContextScore(a.basin);
        if (_basinCtx.bonus !== 0) score += _basinCtx.bonus;
      }

      return {
        score: Math.max(0, Math.min(100, Math.round(score))),
        _fb,
        _basinCtx,
      };
    }

    // Compute similarity for all analogues, filter by hard constraints + minsim
    const scored = ANALOGUES.map((a) => {
      const r = computeSim(a);
      return { ...a, sim: r.score, _fb: r._fb, _basinCtx: r._basinCtx };
    });

    // Hard filters — wider tolerance when fuzzy logic is active
    const _ft = _fuzzyEnabled ? 1.15 : 1.0; // fuzzy tolerance multiplier
    searchResults = scored
      .filter((a) => {
        const depthOk =
          !a.depth ||
          (a.depth >= dmin * (0.7 / _ft) &&
            a.depth <= dmax * (1.3 * _ft));
        const apiOk =
          !a.api ||
          (a.api >= apimin * (0.7 / _ft) &&
            a.api <= apimax * (1.3 * _ft));
        // Advanced hard filters
        const porOk =
          !adv ||
          !a.por ||
          (a.por >= porMin * (0.8 / _ft) &&
            a.por <= porMax * (1.2 * _ft));
        const permOk =
          !adv ||
          !a.perm ||
          (a.perm >= permMin * (0.5 / _ft) &&
            a.perm <= permMax * (2 * _ft));
        const h2sOk =
          !adv || !a.fluid?.h2s_ppm || a.fluid.h2s_ppm <= h2sMax * 1.5;
        const protOk =
          !adv ||
          protect !== "no" ||
          a.environmental?.protected_area_flag !== "Yes";
        return (
          a.sim >= minsim &&
          depthOk &&
          apiOk &&
          porOk &&
          permOk &&
          h2sOk &&
          protOk
        );
      })
      .sort((a, b) => {
        // Use custom ranking formula if enabled, otherwise sort by sim
        if (
          typeof _anaComputeRankScore === "function" &&
          _anaFmEnabled &&
          _anaFmMode !== "similarity"
        ) {
          const ra = _anaComputeRankScore(a);
          const rb = _anaComputeRankScore(b);
          return rb - ra;
        }
        return b.sim - a.sim;
      });

    // Re-rank (attach rankScore for display)
    searchResults = searchResults.map((a, i) => ({
      ...a,
      rank: i + 1,
      rankScore:
        typeof _anaComputeRankScore === "function" &&
        _anaFmEnabled &&
        _anaFmMode !== "similarity"
          ? _anaComputeRankScore(a)
          : a.sim,
    }));
    renderAnalogueResults(searchResults);
    document.getElementById("ana-results-area").style.display = "grid";

    const fuzzyTag = _fuzzyEnabled ? " [Fuzzy]" : "";
    const matchMsg =
      searchResults.length > 0
        ? `Found ${searchResults.length} analogues${fuzzyTag} — top match: ${searchResults[0].name} (${searchResults[0].sim}%)`
        : "No analogues match your criteria. Try relaxing the filters or lowering the Min Similarity Score.";
    toast(matchMsg, searchResults.length > 0 ? "success" : "warning");

    selectedAnalogues.clear();
    // Unlock comparison and similarity tabs
    _searchHasRun = true;
    const cmTab = document.getElementById("ana-tab-compare");
    const simTab = document.getElementById("ana-tab-similarity");
    if (cmTab) {
      cmTab.style.opacity = "";
      cmTab.title = "";
    }
    if (simTab) {
      simTab.style.opacity = "";
      simTab.title = "";
    }
  }, 800);
}

// Select an analogue directly from the crossplot data table — highlights it on the chart
// and syncs the banner + detail panel without leaving the crossplot view
function selectAnalogueFromCrossplot(rank) {
  const a = searchResults.find((x) => x.rank === rank);
  if (!a) return;

  // Toggle off if already selected
  if (currentAnalogue?.rank === rank) {
    currentAnalogue = null;
    // Clear banner
    const banner = document.getElementById("cp-analogue-banner");
    if (banner) banner.style.display = "none";
    renderCrossplot();
    return;
  }

  currentAnalogue = a;

  // Update crossplot banner
  const banner = document.getElementById("cp-analogue-banner");
  if (banner) {
    banner.style.display = "flex";
    const c =
      a.sim >= 80
        ? "var(--green)"
        : a.sim >= 65
          ? "var(--amber)"
          : "var(--red)";
    document.getElementById("cp-analogue-name").textContent = a.name;
    document.getElementById("cp-analogue-meta").textContent =
      `${a.basin} · ${a.lith} · ${a.age} · ${a.dep}`;
    const simEl = document.getElementById("cp-analogue-sim");
    simEl.textContent = a.sim + "% match";
    simEl.style.color = c;
  }

  // Also sync the search-panel detail card (visible when user goes back)
  document.getElementById("ana-detail-name").textContent = a.name;
  document.getElementById("ana-detail-sub").textContent =
    `${a.basin} · ${a.dep} · ${a.age} · ${a.lith}`;
  const matchBadge = document.getElementById("ana-match-badge");
  const matchVal = document.getElementById("ana-match-val");
  if (matchBadge && matchVal) {
    const c =
      a.sim >= 80
        ? "var(--green)"
        : a.sim >= 65
          ? "var(--amber)"
          : "var(--red)";
    matchBadge.style.display = "block";
    matchVal.textContent = a.sim + "%";
    matchVal.style.color = c;
  }

  // Highlight the card in the search results strip
  document
    .querySelectorAll(".ana-hcard")
    .forEach((el) => el.classList.remove("selected"));
  document.getElementById("ana-" + rank)?.classList.add("selected");

  // Redraw crossplot immediately — selected point glows and is labelled
  renderCrossplot();
}

// When user changes an axis, restore cached target for that axis or recalculate from medians
function onCrossplotAxisChange() {
  const xKey = document.getElementById("cp-x")?.value || "por";
  const yKey = document.getElementById("cp-y")?.value || "perm";

  function medianVal(key) {
    if (!searchResults || !searchResults.length) return null;
    const vals = searchResults
      .map((a) => +a[key])
      .filter((v) => !isNaN(v) && v > 0)
      .sort((a, b) => a - b);
    return vals.length ? vals[Math.floor(vals.length / 2)] : null;
  }

  // Restore or recalculate X target
  const txEl = document.getElementById("cp-tx");
  const tyEl = document.getElementById("cp-ty");
  if (txEl) {
    const cached = _cpTargets[xKey];
    const fresh = cached ?? medianVal(xKey);
    txEl.value = fresh != null ? fresh.toFixed(fresh < 10 ? 2 : 1) : "";
    if (fresh != null) _cpTargets[xKey] = fresh;
  }
  if (tyEl) {
    const cached = _cpTargets[yKey];
    const fresh = cached ?? medianVal(yKey);
    tyEl.value = fresh != null ? fresh.toFixed(fresh < 10 ? 2 : 1) : "";
    if (fresh != null) _cpTargets[yKey] = fresh;
  }
  renderCrossplot();
}

// Per-axis target store — so changing axes doesn't carry over stale values
const _cpTargets = {};

function autoFillTarget() {
  if (!searchResults || !searchResults.length) {
    toast("Run a search first to auto-fill target", "warning");
    return;
  }
  const xKey = document.getElementById("cp-x")?.value || "por";
  const yKey = document.getElementById("cp-y")?.value || "perm";
  function median(key) {
    const vals = searchResults
      .map((a) => +a[key])
      .filter((v) => !isNaN(v) && v > 0)
      .sort((a, b) => a - b);
    return vals.length ? vals[Math.floor(vals.length / 2)] : null;
  }
  const tx = median(xKey),
    ty = median(yKey);
  if (tx != null) {
    document.getElementById("cp-tx").value = tx.toFixed(tx < 10 ? 2 : 1);
    _cpTargets[xKey] = tx;
  }
  if (ty != null) {
    document.getElementById("cp-ty").value = ty.toFixed(ty < 10 ? 2 : 1);
    _cpTargets[yKey] = ty;
  }
  renderCrossplot();
  toast(
    `Target set to median of ${searchResults.length} search results`,
    "success",
  );
}

function clearSearchFilters() {
  // Reset core filters
  ["s-dmin", "s-dmax", "s-apimin", "s-apimax", "s-minsim"].forEach(
    (id) => {
      const el = document.getElementById(id);
      if (el)
        el.value =
          id === "s-dmin"
            ? "2500"
            : id === "s-dmax"
              ? "4500"
              : id === "s-apimin"
                ? "28"
                : id === "s-apimax"
                  ? "38"
                  : "60";
    },
  );
  ["s-lith", "s-dep", "s-age", "s-hc", "s-drive", "s-tecto"].forEach(
    (id) => {
      const el = document.getElementById(id);
      if (el) el.selectedIndex = 0;
    },
  );
  // Reset advanced filters
  const advIds = [
    "s-pormin",
    "s-pormax",
    "s-permmin",
    "s-permmax",
    "s-ntgmin",
    "s-rfmin",
    "s-phiemin",
    "s-swmax",
    "s-pcmax",
    "s-mwmin",
    "s-mwmax",
    "s-tocmin",
    "s-romin",
    "s-romax",
    "s-h2smax",
    "s-co2max",
    "s-sulmax",
    "s-pbmin",
    "s-ucsmin",
    "s-hfmin",
    "s-hfmax",
    "s-tgradmin",
    "s-burialmax",
    "s-npvmin",
  ];
  advIds.forEach((id) => {
    const el = document.getElementById(id);
    if (el) el.value = "";
  });
  [
    "s-preg",
    "s-kero",
    "s-oilfam",
    "s-charge",
    "s-stress",
    "s-sandprod",
    "s-fracdns",
    "s-protect",
    "s-hydrate",
    "s-fiscal",
  ].forEach((id) => {
    const el = document.getElementById(id);
    if (el) el.selectedIndex = 0;
  });
  const toggle = document.getElementById("s-adv-toggle");
  if (toggle) {
    toggle.checked = false;
    document.getElementById("s-adv-panel").style.display = "none";
  }
  toast("Search filters cleared", "info");
}

function renderAnalogueResults(results) {
  document.getElementById("ana-count-lbl").textContent =
    `Ranked Analogues — ${results.length} matches`;
  if (results.length === 0) {
    document.getElementById("ana-results-list").innerHTML =
      '<div style="color:var(--t3);font-size:11px;padding:20px;text-align:center;width:100%">No analogues match your criteria. Try adjusting the filters.</div>';
    return;
  }
  document.getElementById("ana-results-list").innerHTML = results
    .map((a) => {
      const c =
        a.sim >= 80
          ? "var(--green)"
          : a.sim >= 65
            ? "var(--amber)"
            : "var(--red)";
      const geoFlag = a.geo?.pressure_coeff >= 1.3 ? "" : "";
      const chemFlag = a.geochem?.sulfur_pct > 1 ? "" : "";

      // ── Fuzzy match quality badges ──
      let fuzzyBadges = "";
      if (_fuzzyEnabled && a._fb) {
        const fb = a._fb;
        const badge = (key, label) => {
          const v = fb[key];
          if (v === undefined) return "";
          if (v >= 0.95)
            return `<span style="background:rgba(0,229,160,.12);color:var(--green);font-size:7px;padding:1px 4px;border-radius:3px" title="${label}: exact match">${label} ✓</span>`;
          if (v >= 0.6)
            return `<span style="background:rgba(168,85,247,.12);color:rgba(168,85,247,.9);font-size:7px;padding:1px 4px;border-radius:3px" title="${label}: fuzzy ${Math.round(v * 100)}%">${label} ≈${Math.round(v * 100)}%</span>`;
          if (v >= 0.35)
            return `<span style="background:rgba(240,165,0,.1);color:var(--amber);font-size:7px;padding:1px 4px;border-radius:3px" title="${label}: weak ${Math.round(v * 100)}%">${label} ~${Math.round(v * 100)}%</span>`;
          return "";
        };
        const badges = [
          badge("lith", "Lith"),
          badge("dep", "Dep"),
          badge("age", "Age"),
          badge("hc", "HC"),
          badge("drive", "Drv"),
          badge("tecto", "Tec"),
        ].filter(Boolean);
        if (badges.length)
          fuzzyBadges = `<div style="display:flex;flex-wrap:wrap;gap:2px;margin-bottom:4px">${badges.join("")}</div>`;
      }

      return `
        <div class="ana-hcard" id="ana-${a.rank}" onclick="selectAnalogue(${a.rank})">
          <div style="display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:6px">
            <div style="font-size:10px;font-weight:700;color:var(--t3)">#${a.rank}</div>
            <div style="text-align:right">
              <div style="font-size:16px;font-weight:700;color:${c};line-height:1">${a.sim}%</div>
              <div style="font-size:7px;color:var(--t3);letter-spacing:.5px">${_fuzzyEnabled ? "FUZZY" : "MATCH"}</div>
            </div>
          </div>
          <div style="font-size:10px;font-weight:700;color:var(--t1);line-height:1.3;margin-bottom:4px">${a.name.replace(" — ", '<br><span style="color:var(--t3);font-weight:400">').replace(/$/, "</span>")}</div>
          <div style="font-size:10px;color:var(--t3);margin-bottom:7px">${a.age} · ${a.depth}m</div>
          ${fuzzyBadges}
          ${a._basinCtx && a._basinCtx.basinRank ? `<div style="display:flex;align-items:center;gap:4px;margin-bottom:4px"><span style="background:${a._basinCtx.bonus > 0 ? "rgba(0,135,90,.08)" : a._basinCtx.bonus < 0 ? "rgba(220,38,38,.08)" : "rgba(100,116,139,.06)"};color:${a._basinCtx.bonus > 0 ? "var(--green)" : a._basinCtx.bonus < 0 ? "var(--red)" : "var(--t3)"};font-size:7px;padding:1px 5px;border-radius:3px" title="Basin #${a._basinCtx.basinRank} (composite ${a._basinCtx.basinComposite}) → ${a._basinCtx.bonus > 0 ? "+" : a._basinCtx.bonus < 0 ? "" : "+"}${a._basinCtx.bonus} pts">🔗 Basin #${a._basinCtx.basinRank} ${a._basinCtx.bonus > 0 ? "↑" + a._basinCtx.bonus : a._basinCtx.bonus < 0 ? "↓" + Math.abs(a._basinCtx.bonus) : ""}</span></div>` : ""}
          <div style="display:flex;flex-wrap:wrap;gap:3px;margin-bottom:6px">
            <span style="background:rgba(0,200,255,.1);color:var(--cyan);font-size:10px;padding:1px 5px;border-radius:3px">φ ${a.por}%</span>
            <span style="background:rgba(240,165,0,.1);color:var(--gold);font-size:10px;padding:1px 5px;border-radius:3px">k ${a.perm}</span>
            <span style="background:rgba(0,229,160,.1);color:var(--green);font-size:10px;padding:1px 5px;border-radius:3px">RF ${a.rf}%</span>
          </div>
          ${geoFlag || chemFlag ? `<div style="font-size:10px;color:var(--amber)">${geoFlag ? "⚠ Overpressure " : ""}${chemFlag ? "☣ High S" : ""}</div>` : ""}
          <div style="display:flex;justify-content:space-between;align-items:center;margin-top:4px;padding-top:5px;border-top:1px solid rgba(0,200,255,.06)">
            <span style="font-size:10px;color:var(--t3)">${a.hc}</span>
            <input type="checkbox" style="accent-color:var(--cyan);width:11px;height:11px" onclick="event.stopPropagation();toggleCompare(${a.rank},event)" title="Compare">
          </div>
        </div>
      `;
    })
    .join("");

  // Populate similarity analysis dropdown
  const simSel = document.getElementById("sim-analogue-select");
  if (simSel) {
    simSel.innerHTML =
      '<option value="">— Pick from search results —</option>' +
      results
        .map(
          (a) =>
            `<option value="${a.rank}">#${a.rank} ${a.name} (${a.sim}%)</option>`,
        )
        .join("");
    if (currentAnalogue) simSel.value = String(currentAnalogue.rank);
  }

  //  Live: update Analogue Source Summary KPIs whenever results change 
  setTimeout(function() {
    if (typeof syncAnalogueSourceSummary === 'function') syncAnalogueSourceSummary(results);
  }, 60);
}

let currentAnalogue = null;
/* 
  syncAnalogueSourceSummary  — reads live searchResults and updates
  all 6 KPI tiles in the Analogue Source Summary card instantly.
  Called automatically after every analogue search + on Re-sync click.
*/
function syncAnalogueSourceSummary(resultsOverride) {
  const pool = resultsOverride ||
    (typeof searchResults !== 'undefined' && searchResults && searchResults.length > 0
      ? searchResults : (typeof ANALOGUES !== 'undefined' ? ANALOGUES : []));

  // Take top 5 by similarity
  const top = pool.slice(0, 5);
  if (!top.length) return;

  const avg = (key, scale) => {
    const vals = top.map(a => parseFloat(a[key])).filter(v => !isNaN(v) && v > 0);
    if (!vals.length) return null;
    const mean = vals.reduce((s,v) => s+v, 0) / vals.length;
    return scale ? (mean * scale) : mean;
  };

  const por = avg('por');
  const ntg = avg('ntg');
  const rf  = avg('rf');
  const sw  = avg('sw');
  const sim = avg('sim');
  const n   = top.length;

  // Update KPI tiles
  const set = (id, val, decimals, suffix) => {
    const el = document.getElementById(id);
    if (el && val != null) {
      const prev = el.textContent;
      el.textContent = val.toFixed(decimals) + (suffix||'');
      // Flash animation on change
      if (prev !== el.textContent) {
        el.style.transition = 'color 0.15s';
        el.style.color = 'var(--brand)';
        setTimeout(() => { el.style.color = ''; }, 600);
      }
    }
  };

  set('ana-sum-por',   por,          1, '%');
  set('ana-sum-ntg',   ntg,          0, '%');
  set('ana-sum-rf',    rf,           0, '%');
  set('ana-sum-sw',    sw != null ? (sw <= 1 ? sw * 100 : sw) : null, 1, '%');
  set('ana-sum-sim',   sim,          0, '%');

  const countEl = document.getElementById('ana-sum-count');
  if (countEl) countEl.textContent = n;

  // Update banner text and source label
  const banner = document.getElementById('ana-sum-banner');
  if (banner) {
    const names = top.map(a => a.name.split(' — ')[0]).join(', ');
    banner.innerHTML = `Parameters auto-populated from <strong>top ${n} analogues</strong> by similarity score.<br>
      <span style="color:var(--t3);font-size:10px">${names}</span>`;
    banner.style.background = 'var(--bg3)';
    banner.style.borderColor = 'rgba(5,150,105,.3)';
  }
  const srcLabel = document.getElementById('ana-sum-source');
  if (srcLabel) srcLabel.textContent = `Updated · ${top[0]?.name?.split(' — ')[0] || ''} top match`;

  // Show toast only on explicit Re-sync click (not automatic)
  if (!resultsOverride) {
    if (typeof toast === 'function') toast('Analogue Source Summary synced (' + n + ' analogues)', 'success');
  }

  // Also push into Volumetrics vi-* fields (Wire 8 reinforcement)
  if (por) { const e = document.getElementById('vi-phi'); if(e && !e._userEdited) { e.value = (por/100).toFixed(3); e.dispatchEvent(new Event('input',{bubbles:true})); } }
  if (ntg) { const e = document.getElementById('vi-ntg'); if(e && !e._userEdited) { e.value = (ntg/100).toFixed(3); e.dispatchEvent(new Event('input',{bubbles:true})); } }
  if (rf)  { const e = document.getElementById('vi-rf');  if(e && !e._userEdited) { e.value = (rf/100).toFixed(3);  e.dispatchEvent(new Event('input',{bubbles:true})); } }
  if (sw)  { const e = document.getElementById('vi-sw');  if(e && !e._userEdited) { e.value = (sw <= 1 ? sw : sw/100).toFixed(3);  e.dispatchEvent(new Event('input',{bubbles:true})); } }

  if (typeof calcVolume === 'function') setTimeout(calcVolume, 80);
}

let currentDetailTab = "reservoir";

function selectAnalogue(rank) {
  document
    .querySelectorAll(".ana-item")
    .forEach((el) => el.classList.remove("selected"));
  document.getElementById("ana-" + rank)?.classList.add("selected");
  const a = searchResults.find((x) => x.rank === rank);
  if (!a) return;
  currentAnalogue = a;
  currentDetailTab = "reservoir";

  // Update header
  document.getElementById("ana-detail-name").textContent = a.name;
  document.getElementById("ana-detail-sub").textContent =
    `${a.basin} · ${a.dep} · ${a.age} · ${a.lith}`;
  // ── Basin screening context link ──
  const subEl = document.getElementById("ana-detail-sub");
  if (a._basinCtx && a._basinCtx.basinRank) {
    subEl.innerHTML = `${a.basin} · ${a.dep} · ${a.age} · ${a.lith} <span onclick="event.stopPropagation();switchScreenTab('profiles',document.querySelectorAll('#screen-tabs .tab')[2]);setTimeout(()=>{document.getElementById('bp-basin-select').value='${a.basin}';renderBasinProfile('${a.basin}')},50);goTo('screening',null)" style="cursor:pointer;background:rgba(124,58,237,.08);color:var(--purple);font-size:10px;padding:1px 6px;border-radius:3px;margin-left:4px" title="View basin profile (screening rank #${a._basinCtx.basinRank}, composite ${a._basinCtx.basinComposite})">Basin #${a._basinCtx.basinRank}</span>`;
  }
  const badge = document.getElementById("ana-match-badge");
  const c =
    a.sim >= 80
      ? "var(--green)"
      : a.sim >= 65
        ? "var(--amber)"
        : "var(--red)";
  badge.style.display = "block";
  matchVal.textContent = a.sim + "%";
  matchVal.style.color = c;

  // ── Propagate analogue name to Crossplot banner ──
  const cpBanner = document.getElementById("cp-analogue-banner");
  if (cpBanner) {
    cpBanner.style.display = "flex";
    const cpName = document.getElementById("cp-analogue-name");
    const cpMeta = document.getElementById("cp-analogue-meta");
    const cpSim = document.getElementById("cp-analogue-sim");
    if (cpName) cpName.textContent = a.name;
    if (cpMeta)
      cpMeta.textContent = `${a.basin} · ${a.lith} · ${a.age} · ${a.dep}`;
    if (cpSim) {
      cpSim.textContent = a.sim + "% match";
      cpSim.style.color = c;
    }
  }

  // ── Propagate analogue name to Comparison banner ──
  const cmpBanner = document.getElementById("cmp-analogue-banner");
  if (cmpBanner) {
    cmpBanner.style.display = "block";
    const cmpName = document.getElementById("cmp-analogue-name");
    const cmpSub = document.getElementById("cmp-analogue-sub");
    const cmpScore = document.getElementById("cmp-analogue-score");
    if (cmpName) cmpName.textContent = a.name;
    if (cmpSub)
      cmpSub.textContent = `${a.basin} · ${a.lith} · ${a.age} · ${a.depth} mTVDSS`;
    if (cmpScore) {
      cmpScore.textContent = a.sim + "% match";
      cmpScore.style.color = c;
    }
  }

  // ── Update comparison table title if already visible ──
  const cmpTitle = document.getElementById("cmp-table-title");
  if (cmpTitle)
    cmpTitle.textContent = `Comparison — ${a.name} vs Selected Analogues`;

  // ── Sync similarity panel dropdown ──
  const simSel = document.getElementById("sim-analogue-select");
  if (simSel) simSel.value = String(rank);
  // If similarity panel is visible, re-render it
  if (
    document.getElementById("ana-similarity-panel")?.style.display ===
    "block"
  ) {
    renderSimilarityAnalysis(a);
  }

  // Reset sub-tabs
  document
    .querySelectorAll(".dtab")
    .forEach((t) => t.classList.remove("on"));
  document.querySelector(".dtab")?.classList.add("on");

  renderDetailTab("reservoir", a);
}

function switchDetailTab(tab, el) {
  document
    .querySelectorAll(".dtab")
    .forEach((t) => t.classList.remove("on"));
  el.classList.add("on");
  currentDetailTab = tab;
  if (currentAnalogue) renderDetailTab(tab, currentAnalogue);
}

