// ---- Helper renderers ----
function statCell(lbl, val, colorClass) {
  return `<div class="stat-cell"><div class="stat-lbl">${lbl}</div><div class="stat-val ${colorClass}">${val}</div></div>`;
}

function mudWindowBar(g) {
  const lo = 8,
    hi = 18;
  const toW = (v) => (((v - lo) / (hi - lo)) * 100).toFixed(1);
  const ppW = toW(g.ppg);
  const ecdW = toW(g.ecd);
  const minW = toW(g.mudweight_min);
  const maxW = toW(g.mudweight_max);
  return `
<div style="position:relative;height:20px;background:var(--bg);border-radius:4px;overflow:hidden">
<div style="position:absolute;left:${minW}%;width:${maxW - minW}%;height:100%;background:rgba(0,229,160,.2);border-left:2px solid var(--green);border-right:2px solid var(--amber)"></div>
<div style="position:absolute;left:${ppW}%;top:2px;width:2px;height:16px;background:var(--cyan)" title="Pore pressure equivalent"></div>
<div style="position:absolute;left:${ecdW}%;top:2px;width:2px;height:16px;background:var(--gold)" title="ECD"></div>
</div>
<div style="display:flex;justify-content:space-between;font-size:10px;color:var(--t3);margin-top:3px"><span>8 ppg</span><span>← Safe drilling window →</span><span>18 ppg</span></div>`;
}

function gasCompositionBar(f) {
  const comps = [
    { name: "C₁ (Methane)", val: f.c1_pct || 0, color: "#00C8FF" },
    { name: "C₂ (Ethane)", val: f.c2_pct || 0, color: "#00E5A0" },
    { name: "C₃ (Propane)", val: f.c3_pct || 0, color: "#F0A500" },
    { name: "CO₂", val: f.co2_pct || 0, color: "#FF4D6A" },
    { name: "N₂", val: f.n2_pct || 0, color: "#7FA8C9" },
  ].filter((c) => c.val > 0);
  const total = comps.reduce((s, c) => s + c.val, 0);
  return `<div style="display:flex;height:14px;border-radius:4px;overflow:hidden;margin-bottom:6px">
${comps.map((c) => `<div style="width:${(c.val / 100) * 100}%;background:${c.color};min-width:${c.val > 0 ? "2px" : "0"}" title="${c.name}: ${c.val}%"></div>`).join("")}
</div>
<div style="display:flex;flex-wrap:wrap;gap:8px">${comps.map((c) => `<span style="font-size:10px;color:${c.color};display:flex;align-items:center;gap:3px"><span style="width:6px;height:6px;background:${c.color};border-radius:50%;display:inline-block"></span>${c.name} ${c.val}%</span>`).join("")}</div>`;
}

function mineralPieBar(minerals) {
  const groups = [
    {
      name: "Framework",
      color: "#00C8FF",
      names: ["Quartz", "Feldspar", "Rock Fragments"],
    },
    {
      name: "Clay",
      color: "#F0A500",
      names: ["Kaolinite", "Illite", "Smectite", "Chlorite"],
    },
    {
      name: "Cement",
      color: "#C0E0FF",
      names: ["Calcite Cement", "Dolomite"],
    },
    {
      name: "Accessory",
      color: "#FF4D6A",
      names: ["Pyrite", "Mica / Other"],
    },
  ];
  return `<div style="display:flex;height:10px;border-radius:4px;overflow:hidden">
${groups
.map((g) => {
  const pct = minerals
    .filter((m) => g.names.includes(m.name))
    .reduce((s, m) => s + m.val, 0);
  return `<div style="width:${pct}%;background:${g.color};min-width:${pct > 0 ? "2px" : "0"}" title="${g.name}: ${pct}%"></div>`;
})
.join("")}
</div>
<div style="display:flex;gap:10px;margin-top:5px;flex-wrap:wrap">${groups
.map((g) => {
const pct = minerals
  .filter((m) => g.names.includes(m.name))
  .reduce((s, m) => s + m.val, 0);
return `<span style="font-size:10px;color:${g.color}">${g.name}: ${pct.toFixed(0)}%</span>`;
})
.join("")}</div>`;
}

function diagenesisScore(d) {
  let score = 5;
  if (d.compaction?.includes("Low")) score += 2;
  if (d.compaction?.includes("Moderate")) score += 0;
  if (d.compaction?.includes("High") && !d.compaction.includes("Very"))
    score -= 1;
  if (d.compaction?.includes("Very High")) score -= 2;
  if (
    d.cementation?.includes("Low") ||
    d.cementation?.includes("Very Low")
  )
    score += 1;
  if (d.cementation?.includes("High")) score -= 1;
  if (
    d.dissolution?.includes("Extensive") ||
    d.dissolution?.includes("Present")
  )
    score += 1;
  if (d.chlorite_coat === "Present") score += 1;
  if (d.qovergrowths === "Extensive") score -= 1;
  if (d.kaolinite_pore === "Present") score -= 0.5;
  return Math.max(1, Math.min(10, Math.round(score)));
}

function toggleCompare(rank, e) {
  if (e.target.checked) {
    if (selectedAnalogues.size >= 5) {
      toast("Max 5 analogues for comparison", "warning");
      e.target.checked = false;
      return;
    }
    selectedAnalogues.add(rank);
  } else {
    selectedAnalogues.delete(rank);
  }
}

// legacy shim
function _legacySwitchAnalogueTab(tab) {
  switchAnalogueTab(tab, null);
}

