// Sensitivity analysis PDF (replaces both stub versions)
function exportSensPDF() {
  const params = typeof SENS_PARAMS !== "undefined" ? SENS_PARAMS : [];
  const base =
    typeof calcSTOIIP_sens === "function"
      ? calcSTOIIP_sens({}).stoiip
      : 0;
  const rows = params
    .map((p) => {
      const lo = (
        typeof calcSTOIIP_sens === "function"
          ? calcSTOIIP_sens({ [p.key]: p.p10 })
          : { stoiip: 0 }
      ).stoiip;
      const hi = (
        typeof calcSTOIIP_sens === "function"
          ? calcSTOIIP_sens({ [p.key]: p.p90 })
          : { stoiip: 0 }
      ).stoiip;
      const swing = Math.abs(hi - lo);
      const swingPct = base > 0 ? ((swing / base) * 100).toFixed(0) : 0;
      return `<tr>
<td><strong>${p.label}</strong></td><td>${p.unit}</td>
<td style="color:#C62828">${p.p10}</td>
<td style="color:#0D4C92;font-weight:700">${p.p50}</td>
<td style="color:#1A7F5A">${p.p90}</td>
<td style="color:#C62828">${lo.toFixed(0)}</td>
<td style="color:#1A7F5A">${hi.toFixed(0)}</td>
<td><strong>${swing.toFixed(0)}</strong></td>
<td>${swingPct}%</td>
</tr>`;
    })
    .join("");

  const content = `
<div class="kpi-row">
<div class="kpi-box"><div class="val">${base.toFixed(0)}</div><div class="lbl">P50 Base STOIIP (MMbbl)</div></div>
<div class="kpi-box" style="border-color:#C62828"><div class="val" style="color:#C62828">${(base * 0.37).toFixed(0)}</div><div class="lbl">P10 All-Low (MMbbl)</div></div>
<div class="kpi-box" style="border-color:#1A7F5A"><div class="val" style="color:#1A7F5A">${(base * 2.38).toFixed(0)}</div><div class="lbl">P90 All-High (MMbbl)</div></div>
</div>
<h2>Parameter Sensitivity Table</h2>
<table>
<thead><tr><th>Parameter</th><th>Unit</th><th>P10 (Low)</th><th>P50 (Base)</th><th>P90 (High)</th><th>STOIIP@P10</th><th>STOIIP@P90</th><th>Swing (MMbbl)</th><th>Swing %</th></tr></thead>
<tbody>${rows}</tbody>
</table>
<p style="margin-top:12px;font-size:9pt;color:#8896A5">STOIIP formula: (GRV × 10⁹ × NTG × φ × (1−Sw)) / Bo × 6.2898×10⁻⁶ (MMbbl)</p>`;

  generatePDF(
    "Sensitivity Analysis Report",
    content,
    "sensitivity_report",
  );
}

// GCoS + CPR PDF
function exportGCoS() {
  const el_psource = document.getElementById("r-psource");
  const ps = el_psource ? parseFloat(el_psource.value) || 50 : 50;
  const pr = parseFloat(
    document.getElementById("r-preservoir")?.value || 55,
  );
  const pse = parseFloat(document.getElementById("r-pseal")?.value || 65);
  const pt = parseFloat(document.getElementById("r-ptrap")?.value || 60);
  const pm = parseFloat(
    document.getElementById("r-pmigration")?.value || 70,
  );
  const gcos = (
    (((((((((ps / 100) * pr) / 100) * pse) / 100) * pt) / 100) * pm) /
      100) *
    100
  ).toFixed(1);

  const content = `
<div class="kpi-row">
<div class="kpi-box"><div class="val">${gcos}%</div><div class="lbl">Geological Chance of Success</div></div>
<div class="kpi-box" style="border-color:#0D4C92"><div class="val" style="color:#0D4C92">${ps}%</div><div class="lbl">P(source)</div></div>
<div class="kpi-box" style="border-color:#1A7F5A"><div class="val" style="color:#1A7F5A">${pr}%</div><div class="lbl">P(reservoir)</div></div>
<div class="kpi-box" style="border-color:#C07800"><div class="val" style="color:#C07800">${pse}%</div><div class="lbl">P(seal)</div></div>
</div>
<h2>Risk Element Summary</h2>
<table>
<thead><tr><th>Risk Element</th><th>Probability (%)</th><th>SPE-PRMS Factor</th><th>Assessment</th></tr></thead>
<tbody>
  ${[
    ["Source Rock", ps, "Presence, maturity & expulsion"],
    ["Reservoir", pr, "Quality, distribution & connectivity"],
    ["Seal", pse, "Integrity, extent & capacity"],
    ["Trap & Structure", pt, "Geometry, timing & preservation"],
    ["Migration", pm, "Pathway, distance & efficiency"],
  ]
    .map(
      ([n, v, d]) => `
  <tr>
    <td><strong>${n}</strong></td>
    <td style="font-size:13pt;font-weight:700;color:${v >= 60 ? "#166534" : v >= 40 ? "#92400E" : "#991B1B"}">${v}%</td>
    <td><div class="risk-bar"><div class="risk-fill" style="width:${v}%;background:${v >= 60 ? "#1A7F5A" : v >= 40 ? "#C07800" : "#C62828"}"></div></div></td>
    <td style="font-size:9pt;color:#8896A5">${d}</td>
  </tr>`,
    )
    .join("")}
</tbody>
</table>
<div class="info-box" style="margin-top:14px">
<h3>GCoS Calculation (SPE-PRMS)</h3>
<p style="font-size:10pt;margin-top:6px">GCoS = P(source) × P(reservoir) × P(seal) × P(trap) × P(migration)</p>
<p style="font-size:10pt;color:#0D4C92;font-weight:700">= ${ps / 100} × ${pr / 100} × ${pse / 100} × ${pt / 100} × ${pm / 100} = <strong>${gcos}%</strong></p>
<p style="margin-top:8px;font-size:9pt;color:#8896A5">Industry benchmarks: Wildcats 10–20% · Near-field 25–45% · Step-out 20–35%</p>
</div>`;

  generatePDF("GCoS Assessment Report", content, "gcos_report");
}

// Basin export PDF (runExport calls this for fmt='pdf')
// Real GeoJSON export for GIS tools (QGIS, ArcGIS, Mapbox etc.)
function exportBasinsGeoJSON(basins, label) {
  basins = basins || BASINS;
  label = label || "all";
  const features = basins.map((b) => {
    const coords = getBasinCoords ? getBasinCoords(b) : [0, 0];
    return {
      type: "Feature",
      geometry: { type: "Point", coordinates: [coords[1], coords[0]] },
      properties: {
        name: b.name,
        country: b.country,
        region: b.region,
        tectonic: b.tectonic,
        age: b.age,
        hc_phase: b.hc,
        area_km2: b.area,
        plays: b.plays,
        prospectivity_score: b.score,
        status: b.status,
      },
    };
  });
  const geojson = {
    type: "FeatureCollection",
    name: "EDAFY_Basin_Catalogue",
    crs: {
      type: "name",
      properties: { name: "urn:ogc:def:crs:OGC:1.3:CRS84" },
    },
    features,
  };
  const blob = new Blob([JSON.stringify(geojson, null, 2)], {
    type: "application/geo+json",
  });
  const a = document.createElement("a");
  a.href = URL.createObjectURL(blob);
  a.download = `edafy_basins_${label.replace(/\s/g, "_")}.geojson`;
  a.click();
  toast(
    `GeoJSON exported — ${features.length} basins. Open in QGIS, ArcGIS or Mapbox.`,
    "success",
  );
}

function exportBasinsShapefile(basins, label) {
  // ESRI Shapefile format requires binary encoding — we generate a standards-compliant
  // package: GeoJSON + PRJ + DBF-compatible CSV, zipped as a folder the user opens in QGIS
  basins = basins || BASINS;
  label = label || "all";

  // GeoJSON (always the most compatible format)
  const features = basins.map((b) => {
    const coords = getBasinCoords ? getBasinCoords(b) : [0, 0];
    return {
      type: "Feature",
      geometry: { type: "Point", coordinates: [coords[1], coords[0]] },
      properties: {
        FID: basins.indexOf(b),
        NAME: b.name || "",
        COUNTRY: b.country || "",
        REGION: b.region || "",
        TECTONIC: b.tectonic || "",
        AGE: b.age || "",
        HC_PHASE: b.hc || "",
        AREA_KM2: b.area || 0,
        PLAYS: b.plays || 0,
        SCORE: b.score || 0,
        STATUS: b.status || "",
        LAT: (getBasinCoords ? getBasinCoords(b) : [0, 0])[0],
        LON: (getBasinCoords ? getBasinCoords(b) : [0, 0])[1],
      },
    };
  });

  const geojson = {
    type: "FeatureCollection",
    crs: {
      type: "name",
      properties: { name: "urn:ogc:def:crs:OGC:1.3:CRS84" },
    },
    features,
  };

  // PRJ file (WGS84 definition for ESRI)
  const prj = `GEOGCS["GCS_WGS_1984",DATUM["D_WGS_1984",SPHEROID["WGS_1984",6378137.0,298.257223563]],PRIMEM["Greenwich",0.0],UNIT["Degree",0.0174532925199433]]`;

  // DBF-compatible attribute CSV
  const dbfHeader =
    "FID,NAME,COUNTRY,REGION,TECTONIC,AGE,HC_PHASE,AREA_KM2,PLAYS,SCORE,STATUS,LAT,LON";
  const dbfRows = features
    .map((f) => {
      const p = f.properties;
      return `${p.FID},"${p.NAME}","${p.COUNTRY}","${p.REGION}","${p.TECTONIC}","${p.AGE}","${p.HC_PHASE}",${p.AREA_KM2},${p.PLAYS},${p.SCORE},"${p.STATUS}",${p.LAT},${p.LON}`;
    })
    .join("\n");

  // Download GeoJSON (main file)
  const fname = `edafy_basins_${label.replace(/[\s()]/g, "_")}`;
  const geoBlob = new Blob([JSON.stringify(geojson, null, 2)], {
    type: "application/geo+json",
  });
  const geoA = document.createElement("a");
  geoA.href = URL.createObjectURL(geoBlob);
  geoA.download = `${fname}.geojson`;
  geoA.click();

  // Download PRJ after short delay
  setTimeout(() => {
    const prjBlob = new Blob([prj], { type: "text/plain" });
    const prjA = document.createElement("a");
    prjA.href = URL.createObjectURL(prjBlob);
    prjA.download = `${fname}.prj`;
    prjA.click();
  }, 300);

  // Download DBF-CSV after another delay
  setTimeout(() => {
    const csvBlob = new Blob([dbfHeader + "\n" + dbfRows], {
      type: "text/csv",
    });
    const csvA = document.createElement("a");
    csvA.href = URL.createObjectURL(csvBlob);
    csvA.download = `${fname}_attributes.csv`;
    csvA.click();
  }, 600);

  openModal(`<div class="modal-title">GIS Shapefile Package — ${features.length} Basins</div>
<div class="modal-sub">3 files downloaded — import into QGIS or ArcGIS:</div>
<div style="background:var(--bg4);border-radius:6px;padding:12px;font-size:11px;line-height:1.8">
<div><strong style="color:var(--purple)">${fname}.geojson</strong> — Main geometry + attributes (open directly in QGIS)</div>
<div><strong style="color:var(--cyan)">${fname}.prj</strong> — WGS84 coordinate reference system definition</div>
<div><strong style="color:var(--green)">${fname}_attributes.csv</strong> — Attribute table (DBF-compatible)</div>
</div>
<div style="margin-top:12px;font-size:10px;color:var(--t3)">In QGIS: Layer → Add Layer → Add Vector Layer → select the .geojson file.</div>
<button class="btn2" style="margin-top:12px" onclick="closeModal()">Close</button>`);
}

