function exportChart() {
  const canvas = document.getElementById("cp-canvas");
  if (!canvas) {
    toast("No cross-plot canvas found", "warning");
    return;
  }
  // Ensure cross-plot is rendered
  renderCrossplot();
  const xKey = document.getElementById("cp-x")?.value || "por";
  const yKey = document.getElementById("cp-y")?.value || "perm";
  const xLabel =
    {
      por: "Porosity",
      perm: "Permeability",
      rf: "RecoveryFactor",
      ntg: "NTG",
    }[xKey] || xKey;
  const yLabel =
    {
      por: "Porosity",
      perm: "Permeability",
      rf: "RecoveryFactor",
      ntg: "NTG",
    }[yKey] || yKey;
  // Create a white-background copy if needed
  const exportCanvas = document.createElement("canvas");
  exportCanvas.width = canvas.width;
  exportCanvas.height = canvas.height;
  const ctx = exportCanvas.getContext("2d");
  ctx.fillStyle = "#FFFFFF";
  ctx.fillRect(0, 0, exportCanvas.width, exportCanvas.height);
  ctx.drawImage(canvas, 0, 0);
  exportCanvas.toBlob((blob) => {
    if (!blob) {
      toast(
        "Could not generate PNG — try switching to cross-plot tab first",
        "warning",
      );
      return;
    }
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `edafy_crossplot_${xLabel}_vs_${yLabel}_${Date.now()}.png`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
    toast("Cross-plot exported as PNG", "success");
  }, "image/png");
}
