// ============================================================
// CROSSPLOT
// ============================================================
function setupCrossplot() {
  renderCrossplot();
}

function renderCrossplot() {
  const canvas = document.getElementById("cp-canvas");
  if (!canvas) return;
  const ctx = canvas.getContext("2d");

  const xKey = document.getElementById("cp-x")?.value || "por";
  const yKey = document.getElementById("cp-y")?.value || "perm";
  const colorBy = document.getElementById("cp-col")?.value || "lith";
  const showMode = document.getElementById("cp-show")?.value || "all";

  // ── axis label map ──
  const AXIS_LABELS = {
    por: "Porosity (%)",
    perm: "Permeability (mD)",
    rf: "Recovery Factor (%)",
    ntg: "Net-to-Gross (%)",
    depth: "Depth (mTVDSS)",
    api: "API Gravity (°)",
    gor: "GOR (scf/bbl)",
    gross_pay: "Gross Pay (m)",
    net_pay: "Net Pay (m)",
    temp: "Temperature (°C)",
    sw: "Water Saturation (frac)",
  };

  // ── colour palettes ──
  const LITH_COLORS = {
    Sandstone: "#00C8FF",
    Carbonate: "#F0A500",
    Chalk: "#00E5A0",
    Mixed: "#FF4D6A",
    Conglomerate: "#FFAA00",
    Shale: "#9B8EC4",
    Other: "#7FA8C9",
  };
  const HC_COLORS = {
    Oil: "#F0A500",
    Gas: "#00C8FF",
    Condensate: "#00E5A0",
    "Oil & Gas": "#FF9E4A",
  };
  const SIM_COLOR = (v) =>
    v >= 80 ? "#00E5A0" : v >= 65 ? "#F0A500" : "#FF4D6A";

  // ── which analogues to plot ──
  let pool;
  if (showMode === "top5") pool = searchResults.slice(0, 5);
  else if (showMode === "top10") pool = searchResults.slice(0, 10);
  else if (showMode === "selected")
    pool = [...selectedAnalogues]
      .map((r) => searchResults.find((a) => a.rank === r))
      .filter(Boolean);
  else pool = searchResults;

  if (!pool.length) {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = "#4A5568";
    ctx.font = "12px Segoe UI";
    ctx.textAlign = "center";
    ctx.fillText(
      "No search results — run a search first",
      canvas.width / 2,
      canvas.height / 2,
    );
    return;
  }

  // ── build plot points from real analogue data ──
  const data = pool
    .map((a) => {
      let xv = a[xKey];
      let yv = a[yKey];
      // Map short keys to actual fields
      if (xKey === "depth") xv = a.depth;
      if (xKey === "api") xv = a.api;
      if (xKey === "gor") xv = a.gor;
      if (xKey === "gross_pay") xv = a.gross_pay;
      if (xKey === "net_pay") xv = a.net_pay;
      if (xKey === "temp") xv = a.temp;
      if (xKey === "sw") xv = a.sw;
      if (yKey === "depth") yv = a.depth;
      if (yKey === "api") yv = a.api;
      if (yKey === "gor") yv = a.gor;
      if (yKey === "gross_pay") yv = a.gross_pay;
      if (yKey === "net_pay") yv = a.net_pay;
      if (yKey === "temp") yv = a.temp;
      if (yKey === "sw") yv = a.sw;

      if (xv === undefined || xv === null || isNaN(+xv)) return null;
      if (yv === undefined || yv === null || isNaN(+yv)) return null;

      let colorKey;
      if (colorBy === "lith") colorKey = a.lith;
      else if (colorBy === "basin") colorKey = a.basin;
      else if (colorBy === "age") colorKey = a.age;
      else if (colorBy === "hc") colorKey = a.hc;
      else if (colorBy === "sim") colorKey = "_sim_";

      return {
        x: +xv,
        y: +yv,
        name: a.name,
        sim: a.sim,
        rank: a.rank,
        lith: a.lith,
        hc: a.hc,
        colorKey,
        isSelected: currentAnalogue?.rank === a.rank,
      };
    })
    .filter(Boolean);

  if (!data.length) {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = "#4A5568";
    ctx.font = "12px Segoe UI";
    ctx.textAlign = "center";
    ctx.fillText(
      "No data available for selected axes",
      canvas.width / 2,
      canvas.height / 2,
    );
    return;
  }

  // ── colour assignment ──
  const colorMap = {};
  const FALLBACK_PALETTE = [
    "#00C8FF",
    "#F0A500",
    "#00E5A0",
    "#FF4D6A",
    "#FFAA00",
    "#9B8EC4",
    "#7FA8C9",
    "#FF9E4A",
    "#4FD1C5",
    "#F687B3",
  ];
  let palIdx = 0;
  data.forEach((d) => {
    if (d.colorKey === "_sim_") return;
    if (!colorMap[d.colorKey]) {
      const preset =
        d.lith && LITH_COLORS[d.colorKey]
          ? LITH_COLORS[d.colorKey]
          : HC_COLORS[d.colorKey]
            ? HC_COLORS[d.colorKey]
            : FALLBACK_PALETTE[palIdx++ % FALLBACK_PALETTE.length];
      colorMap[d.colorKey] = preset;
    }
  });

  // ── canvas layout ──
  const W = canvas.width,
    H = canvas.height;
  const pad = { l: 56, r: 24, t: 28, b: 52 };
  const xs = data.map((d) => d.x),
    ys = data.map((d) => d.y);
  const xRange = Math.max(...xs) - Math.min(...xs) || 1;
  const yRange = Math.max(...ys) - Math.min(...ys) || 1;
  const xMin = Math.min(...xs) - xRange * 0.12,
    xMax = Math.max(...xs) + xRange * 0.12;
  const yMin = Math.min(...ys) - yRange * 0.12,
    yMax = Math.max(...ys) + yRange * 0.12;
  const px = (v) =>
    pad.l + ((v - xMin) / (xMax - xMin)) * (W - pad.l - pad.r);
  const py = (v) =>
    H - pad.b - ((v - yMin) / (yMax - yMin)) * (H - pad.t - pad.b);

  ctx.clearRect(0, 0, W, H);
  ctx.fillStyle = "#FFFFFF";
  ctx.fillRect(0, 0, W, H);

  // ── grid ──
  ctx.strokeStyle = "rgba(13,76,146,0.07)";
  ctx.lineWidth = 1;
  for (let i = 1; i <= 5; i++) {
    const gx = pad.l + (i * (W - pad.l - pad.r)) / 6;
    ctx.beginPath();
    ctx.moveTo(gx, pad.t);
    ctx.lineTo(gx, H - pad.b);
    ctx.stroke();
    const gy = pad.t + (i * (H - pad.t - pad.b)) / 6;
    ctx.beginPath();
    ctx.moveTo(pad.l, gy);
    ctx.lineTo(W - pad.r, gy);
    ctx.stroke();
    // tick labels
    ctx.fillStyle = "#9AA8C0";
    ctx.font = "9px Segoe UI";
    ctx.textAlign = "center";
    const xTick = xMin + (i * (xMax - xMin)) / 6;
    ctx.fillText(
      xTick >= 1000
        ? (xTick / 1000).toFixed(1) + "k"
        : xTick.toFixed(xTick < 10 ? 1 : 0),
      gx,
      H - pad.b + 12,
    );
    ctx.textAlign = "right";
    const yTick = yMin + (i * (yMax - yMin)) / 6;
    ctx.fillText(
      yTick >= 1000
        ? (yTick / 1000).toFixed(1) + "k"
        : yTick.toFixed(yTick < 10 ? 1 : 0),
      pad.l - 6,
      gy + 3,
    );
  }

  // ── axes ──
  ctx.strokeStyle = "rgba(13,76,146,0.35)";
  ctx.lineWidth = 1.5;
  ctx.beginPath();
  ctx.moveTo(pad.l, pad.t);
  ctx.lineTo(pad.l, H - pad.b);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(pad.l, H - pad.b);
  ctx.lineTo(W - pad.r, H - pad.b);
  ctx.stroke();

  // ── trend line (linear regression) ──
  const n = data.length;
  if (n >= 3) {
    const xm = data.reduce((s, d) => s + d.x, 0) / n;
    const ym = data.reduce((s, d) => s + d.y, 0) / n;
    const num = data.reduce((s, d) => s + (d.x - xm) * (d.y - ym), 0);
    const den = data.reduce((s, d) => s + (d.x - xm) ** 2, 0);
    if (den > 0) {
      const slope = num / den,
        intercept = ym - slope * xm;
      ctx.strokeStyle = "rgba(13,76,146,0.22)";
      ctx.lineWidth = 1.5;
      ctx.setLineDash([5, 4]);
      ctx.beginPath();
      ctx.moveTo(px(xMin), py(slope * xMin + intercept));
      ctx.lineTo(px(xMax), py(slope * xMax + intercept));
      ctx.stroke();
      ctx.setLineDash([]);
    }
  }

  // ── plot points ──
  data.forEach((d) => {
    const c =
      colorBy === "sim"
        ? SIM_COLOR(d.sim)
        : colorMap[d.colorKey] || "#7FA8C9";
    const r = d.isSelected ? 8 : 5;
    // Glow for selected
    if (d.isSelected) {
      ctx.fillStyle = c + "30";
      ctx.beginPath();
      ctx.arc(px(d.x), py(d.y), 14, 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.fillStyle = c + (d.isSelected ? "FF" : "CC");
    ctx.beginPath();
    ctx.arc(px(d.x), py(d.y), r, 0, Math.PI * 2);
    ctx.fill();
    ctx.strokeStyle = c;
    ctx.lineWidth = d.isSelected ? 2 : 0.8;
    ctx.stroke();
    // Label selected analogue
    if (d.isSelected) {
      ctx.fillStyle = "#2D3748";
      ctx.font = "bold 9px Segoe UI";
      ctx.textAlign = "left";
      const lbl = d.name.split("—")[0].trim().substring(0, 20);
      ctx.fillText(lbl, px(d.x) + 11, py(d.y) + 4);
    }
  });

  // ── rank labels (top 3) ──
  data.slice(0, 3).forEach((d, i) => {
    if (d.isSelected) return;
    ctx.fillStyle = "rgba(45,55,72,0.85)";
    ctx.font = "8px Segoe UI";
    ctx.textAlign = "center";
    ctx.fillText("#" + d.rank, px(d.x), py(d.y) - 8);
  });

  // ── TARGET POINT ──
  // Update label text to match current axis selection
  const txLbl = document.getElementById("cp-tx-label");
  const tyLbl = document.getElementById("cp-ty-label");
  if (txLbl)
    txLbl.textContent =
      "Target " + (AXIS_LABELS[xKey] || xKey).split(" ")[0];
  if (tyLbl)
    tyLbl.textContent =
      "Target " + (AXIS_LABELS[yKey] || yKey).split(" ")[0];

  // Read explicit user-entered target values first, then cache, then derive
  const txRaw = document.getElementById("cp-tx")?.value;
  const tyRaw = document.getElementById("cp-ty")?.value;
  const txInput = txRaw !== "" ? parseFloat(txRaw) : NaN;
  const tyInput = tyRaw !== "" ? parseFloat(tyRaw) : NaN;

  // Smart fallback: derive from search inputs or top-result median
  function deriveTarget(key) {
    const vals = pool
      .map((a) => {
        let v = a[key];
        if (key === "depth") v = a.depth;
        if (key === "api") v = a.api;
        if (key === "gor") v = a.gor;
        if (key === "gross_pay") v = a.gross_pay;
        if (key === "net_pay") v = a.net_pay;
        if (key === "temp") v = a.temp;
        if (key === "sw") v = a.sw;
        return +v;
      })
      .filter((v) => !isNaN(v) && v > 0)
      .sort((a, b) => a - b);
    if (!vals.length) return null;
    // Use median of top results as the representative target
    return vals[Math.floor(vals.length / 2)];
  }

  // Also check advanced search form ranges
  function searchFormMidpoint(key) {
    const ids = {
      por: ["s-pormin", "s-pormax"],
      perm: ["s-permmin", "s-permmax"],
      rf: ["s-rfmin", null],
      ntg: ["s-ntgmin", null],
      depth: ["s-dmin", "s-dmax"],
      api: ["s-apimin", "s-apimax"],
      sw: [null, "s-swmax"],
    };
    const pair = ids[key];
    if (!pair) return null;
    const mn = pair[0]
      ? parseFloat(document.getElementById(pair[0])?.value)
      : NaN;
    const mx = pair[1]
      ? parseFloat(document.getElementById(pair[1])?.value)
      : NaN;
    const mnOk = !isNaN(mn) && mn > 0 && mn < 99999;
    const mxOk = !isNaN(mx) && mx > 0 && mx < 99999;
    if (mnOk && mxOk) return (mn + mx) / 2;
    if (mnOk) return mn;
    if (mxOk) return mx;
    return null;
  }

  const tX = !isNaN(txInput)
    ? txInput
    : (_cpTargets[xKey] ??
      searchFormMidpoint(xKey) ??
      deriveTarget(xKey));
  const tY = !isNaN(tyInput)
    ? tyInput
    : (_cpTargets[yKey] ??
      searchFormMidpoint(yKey) ??
      deriveTarget(yKey));

  if (
    tX !== null &&
    tX !== undefined &&
    tY !== null &&
    tY !== undefined
  ) {
    // Clamp to plot area — still show even if slightly outside data range
    const clampX = Math.max(xMin, Math.min(xMax, tX));
    const clampY = Math.max(yMin, Math.min(yMax, tY));
    const tpx = px(clampX),
      tpy = py(clampY);
    const onPlot = tX >= xMin && tX <= xMax && tY >= yMin && tY <= yMax;
    // Outer glow
    ctx.fillStyle = "rgba(255,77,106,0.15)";
    ctx.beginPath();
    ctx.arc(tpx, tpy, 16, 0, Math.PI * 2);
    ctx.fill();
    // Crosshair dashed lines
    ctx.strokeStyle = "rgba(255,77,106,0.35)";
    ctx.lineWidth = 1;
    ctx.setLineDash([4, 3]);
    ctx.beginPath();
    ctx.moveTo(tpx, pad.t);
    ctx.lineTo(tpx, H - pad.b);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(pad.l, tpy);
    ctx.lineTo(W - pad.r, tpy);
    ctx.stroke();
    ctx.setLineDash([]);
    // Outer ring
    ctx.strokeStyle = "#FF4D6A";
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.arc(tpx, tpy, 9, 0, Math.PI * 2);
    ctx.stroke();
    // Inner fill
    ctx.fillStyle = "#FF4D6A";
    ctx.beginPath();
    ctx.arc(tpx, tpy, 4, 0, Math.PI * 2);
    ctx.fill();
    // Label box
    const lblX = tpx + 13,
      lblY = tpy - 4;
    ctx.fillStyle = "rgba(255,77,106,0.9)";
    ctx.font = "bold 9px Segoe UI";
    ctx.textAlign = "left";
    ctx.fillText("TARGET", lblX, lblY);
    ctx.fillStyle = "rgba(80,20,20,0.7)";
    ctx.font = "8px Segoe UI";
    const fmt = (v) =>
      v >= 1000 ? (v / 1000).toFixed(1) + "k" : v.toFixed(v < 10 ? 1 : 0);
    ctx.fillText(`${fmt(tX)}, ${fmt(tY)}`, lblX, lblY + 10);
    if (!onPlot) {
      ctx.fillStyle = "rgba(255,77,106,0.6)";
      ctx.font = "8px Segoe UI";
      ctx.fillText("(extrapolated)", lblX, lblY + 20);
    }
  }

  // ── axis labels ──
  ctx.fillStyle = "#4A5568";
  ctx.font = "bold 11px Segoe UI";
  ctx.textAlign = "center";
  ctx.fillText(AXIS_LABELS[xKey] || xKey, W / 2, H - 10);
  ctx.save();
  ctx.translate(15, H / 2);
  ctx.rotate(-Math.PI / 2);
  ctx.fillText(AXIS_LABELS[yKey] || yKey, 0, 0);
  ctx.restore();

  // ── update title ──
  const titleEl = document.getElementById("cp-chart-title");
  if (titleEl)
    titleEl.textContent = `${(AXIS_LABELS[xKey] || xKey).split(" ")[0]} vs ${(AXIS_LABELS[yKey] || yKey).split(" ")[0]} — ${data.length} Analogues`;
  const srcEl = document.getElementById("cp-data-source");
  if (srcEl)
    srcEl.textContent = `Colored by: ${colorBy} · Showing: ${pool.length} search results · Real measured values`;

  // ── update analogue banner ──
  if (currentAnalogue) {
    const banner = document.getElementById("cp-analogue-banner");
    if (banner) banner.style.display = "flex";
    const nameEl = document.getElementById("cp-analogue-name");
    const metaEl = document.getElementById("cp-analogue-meta");
    const simEl = document.getElementById("cp-analogue-sim");
    if (nameEl) nameEl.textContent = currentAnalogue.name;
    if (metaEl)
      metaEl.textContent = `${currentAnalogue.basin} · ${currentAnalogue.lith} · ${currentAnalogue.age}`;
    const sc =
      currentAnalogue.sim >= 80
        ? "var(--green)"
        : currentAnalogue.sim >= 65
          ? "var(--amber)"
          : "var(--red)";
    if (simEl) {
      simEl.textContent = currentAnalogue.sim + "% match";
      simEl.style.color = sc;
    }
  }

  // ── update table header ──
  const hx = document.getElementById("cp-h-x"),
    hy = document.getElementById("cp-h-y");
  if (hx) hx.textContent = (AXIS_LABELS[xKey] || xKey).split(" ")[0];
  if (hy) hy.textContent = (AXIS_LABELS[yKey] || yKey).split(" ")[0];
  const ptCount = document.getElementById("cp-point-count");
  if (ptCount)
    ptCount.textContent =
      data.length + " data points · click a row to highlight";

  // ── update data table — rows are clickable to select/highlight ──
  document.getElementById("cp-tbody").innerHTML = data
    .map((d) => {
      const c2 =
        d.sim >= 80
          ? "var(--green)"
          : d.sim >= 65
            ? "var(--amber)"
            : "var(--red)";
      const isActive = currentAnalogue?.rank === d.rank;
      const rowBg = isActive
        ? "background:rgba(13,76,146,.13);outline:1px solid rgba(13,76,146,.3);"
        : "cursor:pointer;";
      const fmt = (v) =>
        v >= 1000
          ? (v / 1000).toFixed(1) + "k"
          : v.toFixed(v < 10 ? 2 : 1);
      return `<tr style="${rowBg}" onclick="selectAnalogueFromCrossplot(${d.rank})" title="Click to highlight on chart">
<td style="color:var(--t1);max-width:130px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-weight:${isActive ? "700" : "400"}">
  ${isActive ? '<span style="color:var(--purple);margin-right:4px">▶</span>' : ""}${d.name}
</td>
<td style="font-weight:${isActive ? "700" : "400"}">${fmt(d.x)}</td>
<td style="font-weight:${isActive ? "700" : "400"}">${fmt(d.y)}</td>
<td style="color:${c2};font-weight:700">${d.sim}%</td>
<td><span class="badge bc" style="font-size:10px">${(d.lith || "—").slice(0, 4)}</span></td>
</tr>`;
    })
    .join("");

  // ── legend ──
  const legendEl = document.getElementById("cp-legend");
  if (legendEl) {
    if (colorBy === "sim") {
      legendEl.innerHTML = ["≥80% (High)", "65-79% (Med)", "<65% (Low)"]
        .map(
          (l, i) =>
            `<span style="display:flex;align-items:center;gap:4px;color:var(--t2)"><span style="width:8px;height:8px;border-radius:50%;background:${["#00E5A0", "#F0A500", "#FF4D6A"][i]};display:inline-block"></span>${l}</span>`,
        )
        .join("");
    } else {
      const keys = [...new Set(data.map((d) => d.colorKey))];
      legendEl.innerHTML = keys
        .map(
          (k) =>
            `<span style="display:flex;align-items:center;gap:4px;color:var(--t2)"><span style="width:8px;height:8px;border-radius:50%;background:${colorMap[k] || "#7FA8C9"};display:inline-block"></span>${k || "—"}</span>`,
        )
        .join("");
    }
    if (currentAnalogue) {
      legendEl.innerHTML += `<span style="display:flex;align-items:center;gap:4px;color:var(--purple);font-weight:700;margin-left:8px">⊙ Active: ${currentAnalogue.name.split("—")[0].trim()}</span>`;
    }
    // Always show target in legend if it was plotted
    if (
      tX !== null &&
      tX !== undefined &&
      tY !== null &&
      tY !== undefined
    ) {
      const fmt = (v) =>
        v >= 1000
          ? (v / 1000).toFixed(1) + "k"
          : v.toFixed(v < 10 ? 1 : 0);
      legendEl.innerHTML += `<span style="display:flex;align-items:center;gap:5px;color:var(--red);font-weight:700;margin-left:8px"><span style="width:10px;height:10px;border-radius:50%;border:2px solid #FF4D6A;display:inline-block"></span>Target (${(AXIS_LABELS[xKey] || xKey).split(" ")[0]}: ${fmt(tX)}, ${(AXIS_LABELS[yKey] || yKey).split(" ")[0]}: ${fmt(tY)})</span>`;
    }
  }
}

// exportChart defined above

// ============================================================
// PARAMETER LIBRARY
// ============================================================

// Populate pf-basin, pf-lith, pf-drive from live data and pre-select global basin
function pfBasinInit() {
  const basins   = window.BASINS    || (typeof BASINS    !== "undefined" ? BASINS    : []);
  const analogues= window.ANALOGUES || (typeof ANALOGUES !== "undefined" ? ANALOGUES : []);

  // ── Basin dropdown ───────────────────────────────────────────
  const basinSel = document.getElementById("pf-basin");
  if (basinSel && basinSel.options.length <= 1 && basins.length > 0) {
    basins.forEach(b => {
      const opt = document.createElement("option");
      opt.value = b.name;
      opt.textContent = b.name + (b.country ? " — " + b.country : "");
      basinSel.appendChild(opt);
    });
  }
  if (basinSel && window._globalBasin) basinSel.value = window._globalBasin;

  // ── Lithology dropdown — derive unique values from ANALOGUES + BASINS ──
  const lithSel = document.getElementById("pf-lith");
  if (lithSel && lithSel.options.length <= 1) {
    const lithSet = new Set();
    // From ANALOGUES
    analogues.forEach(a => { if (a.lith && a.lith !== "Unknown") lithSet.add(a.lith); });
    // From BASINS (some have lith field)
    basins.forEach(b => { if (b.lith && b.lith !== "Unknown") lithSet.add(b.lith); });
    // Hardcoded full list from STRAT_DATA and ingested records as fallback
    [
      "Sandstone","Carbonate","Chalk","Shale","Evaporite",
      "Sandstone / Carbonate","Sandstone / Shale","Sandstone / Siltstone",
      "Shale / Carbonate","Shale / Lacustrine","Shale / Limestone",
      "Shale / Marl","Carbonate / Shale","Igneous / Metamorphic"
    ].forEach(v => lithSet.add(v));
    Array.from(lithSet).sort().forEach(v => {
      const opt = document.createElement("option");
      opt.value = v; opt.textContent = v;
      lithSel.appendChild(opt);
    });
  }

  // ── Drive mechanism dropdown — derive from ANALOGUES ────────
  const driveSel = document.getElementById("pf-drive");
  if (driveSel && driveSel.options.length <= 1) {
    const driveSet = new Set();
    analogues.forEach(a => { if (a.drive && a.drive !== "Unknown") driveSet.add(a.drive); });
    // Full list from data
    ["Water Drive","Solution Gas","Gas Cap","Combination",
      "Depletion Drive","Gravity Drainage","Compaction Drive"
    ].forEach(v => driveSet.add(v));
    Array.from(driveSet).sort().forEach(v => {
      const opt = document.createElement("option");
      opt.value = v; opt.textContent = v;
      driveSel.appendChild(opt);
    });
  }
  renderDists();
}

function renderDists() {
  const html = Object.entries(PARAM_DATA)
    .map(([key, d]) => {
      const heights = generateDistShape(d.shape);
      return `
        <div class="card">
          <div class="ch"><span class="ct">${d.label}</span><span style="font-size:10px;color:var(--t3)">${d.records.toLocaleString()} records</span></div>
          <div class="cb">
            <div class="dist-wrap" id="dw-${key}">${heights
              .map(
                (h, i) =>
                  `<div class="dbar" style="height:${h}%;background:${i === 7 ? d.color : d.color + "70"}" title="${(d.p10 + ((d.p90 - d.p10) * i) / 14).toFixed(1)} ${d.unit}"></div>`,
              )
              .join("")}</div>
            <div id="myval-line-${key}"></div>
            <div class="pcts">
              <div class="pct-g"><div class="pct-lbl">P10</div><div class="pct-v" style="color:var(--red)">${d.p10}</div></div>
              <div class="pct-g"><div class="pct-lbl">P50</div><div class="pct-v" style="color:${d.color}">${d.p50}</div></div>
              <div class="pct-g"><div class="pct-lbl">P90</div><div class="pct-v" style="color:var(--gold)">${d.p90}</div></div>
              <div class="pct-g"><div class="pct-lbl">Mean</div><div class="pct-v">${d.mean}</div></div>
            </div>
          </div>
        </div>
      `;
    })
    .join("");
  document.getElementById("dists-grid").innerHTML = html;
}

function generateDistShape(shape) {
  const n = 15;
  return Array.from({ length: n }, (_, i) => {
    const t = i / (n - 1);
    if (shape === "normal")
      return Math.round(Math.max(5, 95 * Math.exp(-8 * (t - 0.5) ** 2)));
    if (shape === "lognormal")
      return Math.round(Math.max(5, 90 * Math.exp(-12 * (t - 0.3) ** 2)));
    if (shape === "bimodal")
      return Math.round(
        Math.max(
          5,
          65 * Math.exp(-15 * (t - 0.3) ** 2) +
            55 * Math.exp(-12 * (t - 0.75) ** 2),
        ),
      );
    return Math.round(30 + 50 * Math.sin(t * Math.PI));
  });
}

function updateDists() {
  toast("Distributions updated for selected filters", "success");
  renderDists();
  drawMyVal();
}

function drawMyVal() {
  const val = parseFloat(document.getElementById("pf-myval").value);
  const param = document.getElementById("pf-param").value;
  const d = PARAM_DATA[param];
  if (!val || !d) return;
  const pct = Math.min(
    100,
    Math.max(0, ((val - d.p10) / (d.p90 - d.p10)) * 100),
  );
  const ptile = Math.round(pct * 0.8 + 10);
  const el = document.getElementById(`myval-line-${param}`);
  if (el)
    el.innerHTML = `<div style="margin:4px 0 6px;padding:4px 8px;background:rgba(255,77,106,.08);border:1px solid rgba(255,77,106,.25);border-radius:3px;font-size:10px;color:var(--red)">Your value: ${val} ${d.unit} — ~${ptile}th percentile of analogue set</div>`;
}

function renderMCInit() {
  // Initialize MC bars with default values
  const wrap = document.getElementById("mc-bars-wrap");
  if (!wrap) return;
  if (wrap.innerHTML) return; // already initialized
  wrap.innerHTML = renderMCBars({ p10: 142, p50: 387, p90: 920 });
  renderMCHistogram(142, 387, 920);
}

function showMC() {
  switchRiskTab("mc", document.querySelectorAll("#risk-tabs .tab")[1]);
}

function renderMCConfigReadonly() {
  const el = document.getElementById("mc-config-readonly");
  if (!el) return;
  const fields = [
    [
      "GRV (km³)",
      document.getElementById("mc-grv")?.value || "90/145/230",
    ],
    ["NTG P50", document.getElementById("mc-ntg-p50")?.value || "0.62"],
    [
      "Porosity P50",
      document.getElementById("mc-phi-p50")?.value || "0.18",
    ],
    ["Sw", document.getElementById("mc-sw")?.value || "0.28"],
    ["Bo", document.getElementById("mc-bo")?.value || "1.32"],
    ["RF P50", document.getElementById("mc-rf-p50")?.value || "0.35"],
    [
      "NTG Dist.",
      document.getElementById("mc-ntg")?.value?.split(" ")[0] ||
        "Analogue",
    ],
    [
      "φ Dist.",
      document.getElementById("mc-phi")?.value?.split(" ")[0] ||
        "Analogue",
    ],
    [
      "RF Dist.",
      document.getElementById("mc-rf")?.value?.split(" ")[0] ||
        "Analogue",
    ],
    ["Iterations", document.getElementById("mc-iter")?.value || "10,000"],
  ];
  el.innerHTML = fields
    .map(
      ([k, v]) => `
        <div style="padding:5px 7px;background:var(--bg4);border-radius:4px;border:1px solid var(--b1)">
        <div style="font-size:10px;color:var(--t3);text-transform:uppercase;letter-spacing:.5px">${k}</div>
        <div style="font-weight:600;color:var(--t1);font-size:10px;margin-top:1px">${v}</div>
        </div>
      `,
    )
    .join("");
}

function pushDistsToRisk() {
  // Push analogue-derived P50s from PARAM_DATA into Parameter Store fields
  const d = PARAM_DATA;
  const phi = document.getElementById("mc-phi-p50");
  const ntg = document.getElementById("mc-ntg-p50");
  const rf = document.getElementById("mc-rf-p50");
  if (phi) phi.value = (d.por.p50 / 100).toFixed(2);
  if (ntg) ntg.value = (d.ntg.p50 / 100).toFixed(2);
  if (rf) rf.value = (d.rf.p50 / 100).toFixed(2);
  syncRiskFromMC();
  calcVolume();
  toast(
    "P50 values from Distributions pushed to Risk & Uncertainty",
    "success",
  );
}

