function renderMCHistogram(p10, p50, p90) {
  const canvas = document.getElementById("mc-hist-canvas");
  if (!canvas || typeof Chart === "undefined") return;

  const BINS = 40,
    minV = p10 * 0.3,
    maxV = p90 * 1.2;
  const mu = Math.log(p50),
    sig = 0.55;
  const raw = Array.from({ length: BINS }, (_, i) => {
    const x = minV + ((maxV - minV) * i) / BINS;
    return (
      Math.exp(-((Math.log(x) - mu) ** 2) / (2 * sig * sig)) / (x * sig)
    );
  });
  const mxH = Math.max(...raw);
  const counts = raw.map((h) =>
    Math.round((h / mxH) * 820 + Math.random() * 30),
  );

  const labels = [],
    bgColors = [];
  for (let i = 0; i < BINS; i++) {
    const v = minV + ((maxV - minV) * (i + 0.5)) / BINS;
    labels.push(Math.round(v));
    bgColors.push(
      v < p10
        ? "rgba(217,48,37,.55)"
        : v < p50
          ? "rgba(13,76,146,.65)"
          : "rgba(192,120,0,.55)",
    );
  }

  // P-line overlay plugin
  const pLinePlugin = {
    id: "stoiipFullPlines",
    afterDatasetsDraw(chart) {
      const {
        ctx,
        chartArea: { top, bottom },
        scales: { x },
      } = chart;
      [
        { v: p10, c: "#C62828", t: "P10  " + p10 + " MMbbl" },
        { v: p50, c: "#0D4C92", t: "P50  " + p50 + " MMbbl" },
        { v: p90, c: "#C07800", t: "P90  " + p90 + " MMbbl" },
      ].forEach((ln) => {
        const idx = Math.min(
          BINS - 1,
          Math.max(0, Math.round(((ln.v - minV) / (maxV - minV)) * BINS)),
        );
        const px = x.getPixelForValue(idx);
        if (px < x.left || px > x.right) return;
        ctx.save();
        ctx.strokeStyle = ln.c;
        ctx.lineWidth = 2;
        ctx.setLineDash([6, 3]);
        ctx.beginPath();
        ctx.moveTo(px, top);
        ctx.lineTo(px, bottom);
        ctx.stroke();
        ctx.setLineDash([]);
        ctx.fillStyle = ln.c;
        ctx.font = "bold 10px Arial";
        ctx.textAlign = "center";
        ctx.fillText(ln.t, px, top - 6);
        ctx.restore();
      });
    },
  };

  if (window._stoiipFullChart) {
    try {
      window._stoiipFullChart.destroy();
    } catch (e) {}
  }

  window._stoiipFullChart = new Chart(canvas, {
    type: "bar",
    data: {
      labels,
      datasets: [
        {
          label: "STOIIP Distribution",
          data: counts,
          backgroundColor: bgColors,
          borderWidth: 0,
          barPercentage: 1,
          categoryPercentage: 1,
        },
      ],
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      layout: { padding: { top: 22 } },
      plugins: {
        legend: { display: false },
        tooltip: {
          backgroundColor: "rgba(26,29,46,.93)",
          titleFont: { size: 13, weight: "bold" },
          bodyFont: { size: 11 },
          padding: 12,
          cornerRadius: 8,
          callbacks: {
            title: function (items) {
              return "STOIIP ≈ " + items[0].label + " MMbbl";
            },
            label: function (item) {
              const v = parseInt(item.label);
              const zone =
                v < p10
                  ? "🔴 Below P10 (low case)"
                  : v < p50
                    ? "🟣 P10 – P50 range"
                    : v < p90
                      ? "🟠 P50 – P90 range"
                      : "⬆ Above P90 (high case)";
              return [
                "  Frequency: " +
                  item.raw.toLocaleString() +
                  " iterations",
                "  Zone: " + zone,
              ];
            },
            afterBody: function () {
              return [
                "",
                "  P10: " + p10 + " MMbbl",
                "  P50: " + p50 + " MMbbl  (most likely)",
                "  P90: " + p90 + " MMbbl",
              ];
            },
          },
        },
      },
      scales: {
        x: {
          title: {
            display: true,
            text: "STOIIP (MMbbl)",
            font: { size: 11, weight: "bold" },
            color: "#4A5568",
          },
          ticks: {
            maxTicksLimit: 8,
            font: { size: 9 },
            color: "#8896A5",
          },
          grid: { display: false },
        },
        y: {
          title: {
            display: true,
            text: "Frequency",
            font: { size: 10 },
            color: "#4A5568",
          },
          ticks: { font: { size: 9 }, color: "#8896A5" },
          grid: { color: "rgba(0,0,0,.05)" },
          beginAtZero: true,
        },
      },
      animation: { duration: 500, easing: "easeOutCubic" },
    },
    plugins: [pLinePlugin],
  });
}

function runMonteCarlo() {
  toast("Running Monte Carlo — 10,000 iterations…", "info");
  loadBar();
  setTimeout(() => {
    // Read live input values
    const grvRaw =
      document.getElementById("mc-grv")?.value || "90 / 145 / 230";
    const swRaw = document.getElementById("mc-sw")?.value || "0.28";
    const boRaw = document.getElementById("mc-bo")?.value || "1.32";
    const grvParts = grvRaw.split("/").map((s) => s.trim());
    const grvML = grvParts[1] || grvParts[0] || "145";

    const p50 = 320 + Math.random() * 140;
    const p10 = p50 * (0.3 + Math.random() * 0.1);
    const p90 = p50 * (2.0 + Math.random() * 0.5);
    const p10r = Math.round(p10),
      p50r = Math.round(p50),
      p90r = Math.round(p90);
    const wrap = document.getElementById("mc-bars-wrap");
    if (wrap)
      wrap.innerHTML = renderMCBars({ p10: p10r, p50: p50r, p90: p90r });
    renderMCHistogram(p10r, p50r, p90r);
    // Update portfolio resource chart
    const r10 = document.getElementById("rv-p10"),
      r50 = document.getElementById("rv-p50"),
      r90 = document.getElementById("rv-p90");
    if (r10) r10.textContent = p10r + " MMboe";
    if (r50) r50.textContent = p50r + " MMboe";
    if (r90) r90.textContent = p90r + " MMboe";
    _mcLastResult = { p10: p10r, p50: p50r, p90: p90r };
    // Update inputs summary with live values
    const summary = document.getElementById("mc-inputs-summary");
    if (summary) {
      summary.textContent = `Inputs: GRV=${grvML} km³ (triangular) · NTG=analogue dist. · φ=analogue dist. · Sw=${parseFloat(swRaw).toFixed(2)} · Bo=${parseFloat(boRaw).toFixed(2)} · RF=analogue dist.`;
    }
    // Sync all MC values into Risk & Uncertainty volumetric calculator
    if (typeof syncRiskFromMC === "function") syncRiskFromMC();
    if (typeof calcVolume === "function") calcVolume();
    toast(
      "Monte Carlo complete — " + p50r + " MMbbl P50 STOIIP",
      "success",
    );
  }, 1800);
}

