// SCREENING
// ============================================================
function renderScreenCriteria() {
  SCREEN_CRITERIA.forEach((c) => {
    screenVals[c.key] = c.val;
  });
  document.getElementById("screen-criteria").innerHTML =
    SCREEN_CRITERIA.map(
      (c) =>
        `<div style="background:var(--bg4);border:1px solid var(--b1);border-radius:6px;padding:11px 13px">
          <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:7px">
            <span style="font-size:10px;letter-spacing:1px;text-transform:uppercase;color:var(--t2)">${c.label}</span>
            <span style="font-size:14px;font-weight:700;color:var(--cyan)" id="sw-${c.key}">${c.val}%</span>
          </div>
          <input type="range" class="slider" min="0" max="50" value="${c.val}" oninput="updateScreen('${c.key}',+this.value)">
          </div>
          `,
    ).join("");
}

// ── Unified Scoring Bridge (USB) — links Analogue ↔ Screening ──────────────
let _usbEnabled = true; // bridge active by default
let _usbBlend = 0.4; // 40% analogue evidence, 60% basin prior

// Derive screening sub-scores from actual analogue reservoir data
function computeAnalogueInformedScores(basin) {
  // Find all analogues matching this basin
  const basinAnalogues = ANALOGUES.filter((a) => {
    if (a.basin === basin.name) return true;
    // Also match by geological similarity (same tectonic + age overlap)
    const b2 = BASINS.find((x) => x.name === a.basin);
    if (b2 && b2.tectonic === basin.tectonic && b2.hc === basin.hc)
      return true;
    return false;
  });

  if (basinAnalogues.length === 0) return null;

  // ── Source Rock Quality (from geochem data) ──
  const srcScores = basinAnalogues.map((a) => {
    if (!a.geochem) return 50;
    let s = 40; // baseline
    // TOC contribution (0-4%+ → 0-30 pts)
    s += Math.min(30, ((a.geochem.toc || 0) / 4) * 30);
    // Ro maturity window contribution (0.6-1.3 ideal → up to 20 pts)
    const ro = a.geochem.ro_vitrinite || 0;
    if (ro >= 0.6 && ro <= 1.3) s += 20;
    else if (ro >= 0.4 && ro <= 1.6) s += 10;
    // Kerogen type contribution
    const kt = (a.geochem.kerogen_type || "").toLowerCase();
    if (kt.includes("i") && !kt.includes("ii"))
      s += 15; // Type I best
    else if (kt.includes("ii") && !kt.includes("iii"))
      s += 12; // Type II good
    else if (kt.includes("ii/iii") || kt.includes("ii-iii")) s += 8;
    else if (kt.includes("iii")) s += 4;
    // Expulsion efficiency bonus
    s += Math.min(10, ((a.geochem.expulsion_eff || 0) / 100) * 10);
    return Math.min(100, Math.round(s));
  });

  // ── Reservoir Quality (from reservoir properties) ──
  const resScores = basinAnalogues.map((a) => {
    let s = 30; // baseline
    // Porosity contribution (0-35% → 0-25 pts)
    s += Math.min(25, ((a.por || 0) / 35) * 25);
    // Permeability contribution (log scale: 1-1000+ mD → 0-25 pts)
    const logPerm = a.perm > 0 ? Math.log10(a.perm) : 0;
    s += Math.min(25, (logPerm / 3) * 25);
    // NTG contribution (0-100% → 0-10 pts)
    s += Math.min(10, ((a.ntg || 0) / 100) * 10);
    // Recovery factor bonus (0-60% → 0-10 pts)
    s += Math.min(10, ((a.rf || 0) / 60) * 10);
    // Depth penalty (very deep = harder)
    if ((a.depth || 0) > 4000) s -= 5;
    if ((a.depth || 0) > 5000) s -= 5;
    return Math.min(100, Math.max(0, Math.round(s)));
  });

  // ── Seal Integrity (from pressure data + depth context) ──
  const sealScores = basinAnalogues.map((a) => {
    let s = 55; // baseline — seal is harder to quantify from analogues
    if (a.geo) {
      // Overpressure indicates seal capacity
      const op = (a.geo.overpressure || "").toLowerCase();
      if (op.includes("high") || op.includes("extreme")) s += 20;
      else if (op.includes("moderate")) s += 12;
      else if (op.includes("slight")) s += 6;
      // Frac gradient — higher = better seal
      if (a.geo.frac_grad > 0.8) s += 10;
      else if (a.geo.frac_grad > 0.7) s += 5;
    }
    // Low water saturation implies good seal historically
    if (a.sw && a.sw < 0.25) s += 8;
    else if (a.sw && a.sw < 0.35) s += 4;
    return Math.min(100, Math.round(s));
  });

  // ── Charge Efficiency (from geochem + fluid data) ──
  const chargeScores = basinAnalogues.map((a) => {
    let s = 40;
    if (a.geochem) {
      // Charge volume
      const cv = (a.geochem.charge_volume || "").toLowerCase();
      if (cv.includes("very high")) s += 25;
      else if (cv.includes("high")) s += 20;
      else if (cv.includes("moderate")) s += 12;
      // Short migration distance = better charge
      const md = a.geochem.migration_dist || 50;
      if (md < 10) s += 15;
      else if (md < 20) s += 10;
      else if (md < 40) s += 5;
      // Oil family diversity indicates active charge
      if (a.geochem.oil_family) s += 5;
    }
    // High GOR indicates active gas charge
    if ((a.gor || 0) > 2000) s += 5;
    return Math.min(100, Math.round(s));
  });

  // ── Commercial Attractiveness (from fluid + reservoir economics) ──
  const commScores = basinAnalogues.map((a) => {
    let s = 40;
    // API gravity (sweet spot 28-42°)
    const api = a.api || 30;
    if (api >= 28 && api <= 42) s += 15;
    else if (api >= 20 && api <= 50) s += 8;
    // Recovery factor — direct commercial impact
    s += Math.min(15, ((a.rf || 0) / 50) * 15);
    // Low H2S = cheaper to develop
    if (!a.fluid?.h2s_ppm || a.fluid.h2s_ppm < 10) s += 10;
    else if (a.fluid.h2s_ppm < 50) s += 5;
    // Low CO2 = less processing
    if (!a.fluid?.co2_pct || a.fluid.co2_pct < 3) s += 8;
    else if (a.fluid.co2_pct < 6) s += 4;
    // Shallow depth = cheaper
    if ((a.depth || 3000) < 2500) s += 7;
    else if ((a.depth || 3000) < 3500) s += 3;
    return Math.min(100, Math.round(s));
  });

  // Aggregate each dimension (weighted mean: more recent/higher-quality analogues could get more weight)
  const avg = (arr) =>
    arr.length
      ? Math.round(arr.reduce((s, v) => s + v, 0) / arr.length)
      : null;
  return {
    source: avg(srcScores),
    reservoir: avg(resScores),
    seal: avg(sealScores),
    charge: avg(chargeScores),
    commercial: avg(commScores),
    analogueCount: basinAnalogues.length,
    analogueNames: basinAnalogues.map((a) => a.name).slice(0, 5),
  };
}

// Blend analogue-derived scores with basin-level prior
function blendScores(
  basinPrior,
  analogueDerived,
  blendWeight,
  analogueCount,
) {
  if (!analogueDerived) return basinPrior;
  // Adaptive blend: more analogues → trust analogue evidence more (Bayesian)
  const adaptiveBlend = Math.min(
    blendWeight * (1 + Math.log2(Math.max(1, analogueCount)) * 0.15),
    0.85,
  );
  const blended = {};
  for (const k of Object.keys(basinPrior)) {
    if (analogueDerived[k] != null) {
      blended[k] = Math.round(
        basinPrior[k] * (1 - adaptiveBlend) +
          analogueDerived[k] * adaptiveBlend,
      );
    } else {
      blended[k] = basinPrior[k];
    }
  }
  return blended;
}

// Compute basin-level context score for an analogue (used in Analogue Engine)
// Returns a 0-15 pt bonus/penalty based on how the analogue's basin performs in screening
function getBasinContextScore(analogueBasinName) {
  if (!leaderboardData.length)
    return { bonus: 0, basinRank: null, basinComposite: null };
  const screenBasin = leaderboardData.find(
    (b) => b.name === analogueBasinName,
  );
  if (!screenBasin)
    return { bonus: 0, basinRank: null, basinComposite: null };
  // High-ranked basins give a small bonus to their analogues; low-ranked basins penalise slightly
  let bonus = 0;
  if (screenBasin.composite >= 75) bonus = 5;
  else if (screenBasin.composite >= 60) bonus = 3;
  else if (screenBasin.composite >= 45) bonus = 1;
  else if (screenBasin.composite < 30) bonus = -3;
  else if (screenBasin.composite < 40) bonus = -1;
  return {
    bonus,
    basinRank: screenBasin.rank,
    basinComposite: screenBasin.composite,
  };
}

function updateScreen(key, val) {
  screenVals[key] = val;
  document.getElementById("sw-" + key).textContent = val + "%";
}

function runScreening() {
  const btn = document.getElementById("screen-btn");
  const status = document.getElementById("screen-status");
  btn.textContent = "Running screening…";
  btn.disabled = true;
  status.textContent = _usbEnabled
    ? "Scoring 612 basins (analogue-informed)…"
    : "Scoring 612 basins…";
  loadBar();
  let prog = 0;
  const iv = setInterval(() => {
    prog += Math.random() * 15;
    if (prog >= 100) {
      clearInterval(iv);
      btn.textContent = "Run Screening — 612 Basins";
      btn.disabled = false;

      leaderboardData = BASINS.map((b) => {
        // Basin-level prior scores (deterministic from basin properties)
        const seed = b.name.length + b.score;
        const R = (base, off) =>
          Math.max(
            10,
            Math.min(
              100,
              Math.round(base + ((seed * 17 + off * 31) % 21) - 10),
            ),
          );
        const basinPrior = {
          source: R(b.score * 0.95, 1),
          reservoir: R(b.score * 0.98, 2),
          seal: R(b.score * 0.88, 3),
          charge: R(b.score * 0.92, 4),
          commercial: R(b.score * 0.85, 5),
          country: R(b.score * 0.96, 6),
        };

        let finalScores = basinPrior;
        let analogueEvidence = null;

        // ── Unified Scoring Bridge ──
        if (_usbEnabled) {
          analogueEvidence = computeAnalogueInformedScores(b);
          if (analogueEvidence) {
            finalScores = blendScores(
              basinPrior,
              analogueEvidence,
              _usbBlend,
              analogueEvidence.analogueCount,
            );
            // Country risk stays basin-level (not derivable from analogues)
            finalScores.country = basinPrior.country;
          }
        }

        return {
          ...b,
          scores: finalScores,
          _analogueEvidence: analogueEvidence,
          _basinPrior: basinPrior,
          _usbActive: _usbEnabled && !!analogueEvidence,
        };
      })
        .map((b) => {
          const w = screenVals;
          const tot = Object.values(w).reduce((s, v) => s + v, 0) || 1;
          const composite = Math.round(
            Object.entries(b.scores).reduce(
              (s, [k, v]) => s + (v * (w[k] || 15)) / tot,
              0,
            ),
          );
          return { ...b, composite };
        })
        .sort((a, b) => b.composite - a.composite)
        .map((b, i) => ({ ...b, rank: i + 1 }));

      const usbCount = leaderboardData.filter((b) => b._usbActive).length;
      status.textContent = _usbEnabled
        ? `${leaderboardData.length} basins scored · ${usbCount} analogue-informed`
        : `${leaderboardData.length} basins scored`;
      // Update Run Screening button to show re-run
      btn.textContent = "Re-run Screening";
      // Show results immediately
      document.getElementById("lb-not-run").style.display = "none";
      document.getElementById("screen-results").style.display = "block";
      renderLeaderboard();
      // If BSF formula is active, re-apply it
      if (_bsfAppliedToLb && typeof lbReapplyFormula === "function") lbReapplyFormula();
      toast(
        _usbEnabled
          ? `Screening complete — ${leaderboardData.length} basins ranked · ${usbCount} with analogue evidence`
          : `Screening complete — ${leaderboardData.length} basins ranked`,
        "success",
      );
    } else {
      status.textContent = `Scoring ${Math.round(prog * 6.12)} of 612 basins…`;
    }
  }, 60);
}

function renderLeaderboard() {
  if (!leaderboardData.length) return;
  // Apply formula builder scoring on every render
  // BUT: if BSS was applied, preserve BSS composite scores — don't overwrite them
  const hasAnyBss = Object.values(_bssBasinActiveVars || {}).some(bv => Object.values(bv || {}).some(Boolean));
  leaderboardData = leaderboardData
    .map((b) => ({
      ...b,
      composite: (hasAnyBss && b._bssApplied) ? b.composite : lbComputeScore(b.scores || {})
    }))
    .sort((a, b) => b.composite - a.composite)
    .map((b, i) => ({ ...b, rank: i + 1 }));
  document.getElementById("lb-not-run").style.display = "none";
  document.getElementById("screen-results").style.display = "block";
  document.getElementById("screen-result-title").textContent =
    `Basin Leaderboard — ${leaderboardData.length} Basins Ranked`;
  // Init formula builder sliders if not yet done
  if (!document.getElementById("lb-weight-sliders")?.children.length)
    lbRenderSliders();
  // Update BSF active banner
  const bsfBanner = document.getElementById("lb-bsf-banner");
  if (bsfBanner) bsfBanner.style.display = _bsfAppliedToLb ? "flex" : "none";
  // Update BSF formula summary in banner
  const bsfSumEl = document.getElementById("lb-bsf-formula-summary");
  if (bsfSumEl && _bsfAppliedToLb && typeof bsfBuildFormulaStr === "function") {
    bsfSumEl.textContent = bsfBuildFormulaStr();
  }
  // Update re-rank label
  const lastRanked = document.getElementById("lb-last-ranked");
  if (lastRanked) {
    lastRanked.textContent = `${leaderboardData.length} basins ranked · ${new Date().toLocaleTimeString()} · ${_bsfAppliedToLb ? "∑ BSF formula active" : "Leaderboard formula active"}`;
  }
  // Update BSF lb-badge in formula panel
  const bsfBadge = document.getElementById("bsf-lb-badge");
  if (bsfBadge) {
    bsfBadge.style.display = _bsfAppliedToLb ? "inline-block" : "none";
    if (_bsfAppliedToLb) bsfBadge.textContent = "✓ Active on Leaderboard";
  }
  renderLbKpis();
  renderLeaderboardTable(leaderboardData);
}

function renderLbKpis() {
  const high = leaderboardData.filter((b) => b.composite >= 70).length;
  const med = leaderboardData.filter(
    (b) => b.composite >= 40 && b.composite < 70,
  ).length;
  const low = leaderboardData.filter((b) => b.composite < 40).length;
  const avgGcos = Math.round(
    leaderboardData
      .slice(0, 5)
      .reduce((s, b) => s + estimateGCoS(b.scores), 0) /
      Math.min(5, leaderboardData.length),
  );
  document.getElementById("lb-kpis").innerHTML = `
    <div class="kpi e" style="text-align:center">
      <div class="kpi-lbl">High Priority</div>
      <div class="kpi-val" style="">${high}</div>
      <div class="kpi-sub">Score ≥ 70</div>
    </div>
    <div class="kpi g" style="text-align:center">
      <div class="kpi-lbl">Medium Priority</div>
      <div class="kpi-val" style="color:">${med}</div>
      <div class="kpi-sub">Score 40–69</div>
    </div>
    <div class="kpi r" style="text-align:center">
      <div class="kpi-lbl">Low Priority</div>
      <div class="kpi-val" style="">${low}</div>
      <div class="kpi-sub">Score < 40</div>
    </div>
    <div class="kpi c" style="text-align:center">
      <div class="kpi-lbl">Avg GCoS (Top 5)</div>
      <div class="kpi-val" style="">${avgGcos}%</div>
      <div class="kpi-sub">Geological success est.</div>
    </div>
  `;
}

function estimateGCoS(scores) {
  // GCoS = Ps × Pr × Pse × Pt × Pm  (5 independent probabilities)
  const s = scores || {};
  const ps = Math.min((s.source || 50) / 100, 0.95);
  const pr = Math.min((s.reservoir || 50) / 100, 0.95);
  const pse = Math.min((s.seal || 50) / 100, 0.95);
  const pt = Math.min((s.charge || 50) / 100, 0.95);
  const pm = Math.min(((s.commercial || 50) / 100) * 0.9, 0.95);
  return Math.round(ps * pr * pse * pt * pm * 100);
}

function renderLeaderboardTable(data) {
  const tierF = document.getElementById("lb-tier-filter")?.value || "";
  let filtered = data;
  if (tierF) {
    filtered = data.filter((b) => {
      if (tierF === "HIGH") return b.composite >= 70;
      if (tierF === "MED") return b.composite >= 40 && b.composite < 70;
      if (tierF === "LOW") return b.composite < 40;
      return true;
    });
  }
  const show = filtered.slice(0, 20);
  const ct = document.getElementById("lb-showing-count");
  if (ct)
    ct.textContent = `Showing ${show.length} of ${filtered.length} basins`;
  document.getElementById("screen-tbody").innerHTML = show
    .map((b) => {
      const c =
        b.composite >= 70
          ? "var(--green)"
          : b.composite >= 40
            ? "var(--amber)"
            : "var(--red)";
      const tl =
        b.composite >= 70 ? "tl-g" : b.composite >= 40 ? "tl-a" : "tl-r";
      const tlTxt =
        b.composite >= 70
          ? "🟢 HIGH"
          : b.composite >= 40
            ? "🟡 MEDIUM"
            : "🔴 LOW";
      const gcos = estimateGCoS(b.scores);
      const rankIcon =
        b.rank === 1
          ? "🥇"
          : b.rank === 2
            ? "🥈"
            : b.rank === 3
              ? "🥉"
              : "";
      return `
        <tr onclick="switchScreenTab('profiles',document.querySelectorAll('#screen-tabs .tab')[2]);setTimeout(()=>{document.getElementById('bp-basin-select').value='${b.name}';renderBasinProfile('${b.name}')},50)" style="cursor:pointer" title="View full profile for ${b.name}">
          <td><span style="font-weight:700;color:${b.rank <= 3 ? "var(--gold)" : "var(--t3)"}">${rankIcon || b.rank}</span></td>
          <td><span style="font-weight:700;color:var(--purple)">${b.name}</span></td>
          <td style="color:var(--t2)">${b.country}</td>
          <td style="color:var(--t3);font-size:10px">${b.region}</td>
          <td><div style="display: flex; align-items: center; justify-content: center; white-space: nowrap;"><span class="badge ${b.hc === "Gas" ? "bc" : b.hc === "Oil & Gas" ? "bg" : "be"}">${b.hc}</span></div></td>
          ${["source", "reservoir", "seal", "charge", "commercial", "country"]
            .map((k) => {
              const v = Math.min(b.scores[k] || 0, 100);
              const col =
                v >= 70 ? "var(--green)" : v >= 40 ? "var(--amber)" : "var(--red)";
              return `<td><div style="display:flex;align-items:center;gap:5px"><div style="width:40px;height:4px;background:#E8ECF5;border-radius:2px"><div style="width:${v}%;height:100%;background:${col};border-radius:2px"></div></div><span style="font-size:10px;font-weight:700;color:${col}">${v}</span></div></td>`;
            })
            .join("")}
          <td><span style="font-size:11px;font-weight:700;color:${gcos >= 25 ? "var(--green)" : gcos >= 15 ? "var(--amber)" : "var(--red)"}">${gcos}%</span></td>
          <td><div style="display:flex;align-items:center;gap:6px"><div style="width:60px;height:6px;background:#E8ECF5;border-radius:3px"><div style="width:${b.composite}%;height:100%;background:${c};border-radius:3px"></div></div><span style="font-weight:700;color:${c}">${b.composite}</span></div></td>
          <td><span style="white-space: nowrap" class="tl ${tl}" style="font-size:10px; white-space: nowrap">${tlTxt}</span>${b._usbActive ? '<span title="Analogue-informed score (' + b._analogueEvidence.analogueCount + " analogues: " + b._analogueEvidence.analogueNames.join(", ") + ')" style="margin-left:4px;font-size:10px;background:rgba(124,58,237,.1);color:var(--purple);padding:1px 4px;border-radius:3px;cursor:help; white-space: nowrap">🔗' + b._analogueEvidence.analogueCount + "</span>" : ""}</td>
        </tr>
      `;
    })
  .join("");
}

function filterLeaderboard(q) {
  if (!leaderboardData.length) return;
  const regionF =
    document.getElementById("lb-region-filter")?.value || "";
  let filtered = leaderboardData.filter((b) => {
    const qMatch =
      !q ||
      b.name.toLowerCase().includes(q.toLowerCase()) ||
      b.region.toLowerCase().includes(q.toLowerCase()) ||
      (b.country || "").toLowerCase().includes(q.toLowerCase());
    const rMatch = !regionF || b.region === regionF;
    return qMatch && rMatch;
  });
  renderLeaderboardTable(filtered);
}

function saveScreenConfig() {
  toast("Screening configuration saved", "success");
}
function loadScreenConfig() {
  SCREEN_CRITERIA.forEach((c) => {
    screenVals[c.key] = c.val;
    const input = document.querySelector(`[oninput*="'${c.key}'"]`);
    if (input) {
      input.value = c.val;
      document.getElementById("sw-" + c.key).textContent = c.val + "%";
    }
  });
  toast("Default configuration loaded", "success");
}

function initDefaultLeaderboard() {
  // Pre-populate leaderboard with default weights so Leaderboard tab shows data on first visit
  SCREEN_CRITERIA.forEach((c) => {
    screenVals[c.key] = c.val;
  });
  leaderboardData = BASINS.map((b) => ({
    ...b,
    scores: {
      source: Math.min(
        100,
        Math.round(b.score * (0.8 + (b.name.length % 5) * 0.04)),
      ),
      reservoir: Math.min(
        100,
        Math.round(b.score * (0.85 + (b.name.length % 4) * 0.04)),
      ),
      seal: Math.min(
        100,
        Math.round(b.score * (0.75 + (b.name.length % 6) * 0.04)),
      ),
      charge: Math.min(
        100,
        Math.round(b.score * (0.82 + (b.name.length % 3) * 0.04)),
      ),
      commercial: Math.min(
        100,
        Math.round(b.score * (0.7 + (b.name.length % 7) * 0.04)),
      ),
      country: Math.min(
        100,
        Math.round(b.score * (0.9 + (b.name.length % 4) * 0.02)),
      ),
    },
  }))
    .map((b) => {
      const w = screenVals;
      const tot = Object.values(w).reduce((s, v) => s + v, 0) || 1;
      const composite = Math.round(
        Object.entries(b.scores).reduce(
          (s, [k, v]) => s + (v * (w[k] || 15)) / tot,
          0,
        ),
      );
      return { ...b, composite };
    })
    .sort((a, b) => b.composite - a.composite)
    .map((b, i) => ({ ...b, rank: i + 1 }));
}

