function parseCSV(text) {
  const lines = text
    .trim()
    .split(/\r?\n/)
    .filter((l) => l.trim());
  if (lines.length < 2) return { headers: [], rows: [] };
  // Detect delimiter
  const firstLine = lines[0];
  const delim =
    firstLine.split("\t").length > firstLine.split(",").length
      ? "\t"
      : ",";
  const parseRow = (row) => {
    const cells = [];
    let cur = "",
      inQ = false;
    for (let i = 0; i < row.length; i++) {
      const ch = row[i];
      if (ch === '"') {
        inQ = !inQ;
        continue;
      }
      if (ch === delim && !inQ) {
        cells.push(cur.trim());
        cur = "";
        continue;
      }
      cur += ch;
    }
    cells.push(cur.trim());
    return cells;
  };
  const headers = parseRow(lines[0]).map((h) =>
    h.replace(/^"|"$/g, "").toLowerCase().trim(),
  );
  const rows = lines
    .slice(1)
    .map((l) => {
      const cells = parseRow(l);
      const obj = {};
      headers.forEach(
        (h, i) =>
          (obj[h] =
            cells[i] !== undefined ? cells[i].replace(/^"|"$/g, "") : ""),
      );
      return obj;
    })
    .filter((r) => Object.values(r).some((v) => v !== ""));
  return { headers, rows };
}

function detectDataType(headers) {
  const hSet = new Set(headers.map((h) => h.toLowerCase()));
  let basinScore = 0,
    analogueScore = 0;
  Object.values(BASIN_ALIASES).forEach((aliases) =>
    aliases.forEach((a) => {
      if (hSet.has(a)) basinScore++;
    }),
  );
  Object.values(ANALOGUE_ALIASES).forEach((aliases) =>
    aliases.forEach((a) => {
      if (hSet.has(a)) analogueScore++;
    }),
  );
  if (basinScore === 0 && analogueScore === 0) return "unknown";
  return basinScore >= analogueScore ? "basin" : "analogue";
}

function autoMap(headers, aliases) {
  const mapping = {};
  const hLower = headers.map((h) => h.toLowerCase());
  Object.entries(aliases).forEach(([field, aliasList]) => {
    for (const alias of aliasList) {
      const idx = hLower.indexOf(alias);
      if (idx !== -1) {
        mapping[field] = headers[idx];
        break;
      }
    }
  });
  return mapping;
}

function handleDrop(e) {
  e.preventDefault();
  // Legacy: route to basin/analogue auto-detection
  handleFiles(e.dataTransfer.files);
}

function handleFiles(files) {
  // Legacy generic upload — auto-detect type
  [...files].forEach((file) => {
    const ext = file.name.split(".").pop().toLowerCase();
    if (!["csv", "tsv", "txt"].includes(ext)) {
      toast("Only CSV/TSV supported", "warning");
      return;
    }
    const reader = new FileReader();
    reader.onload = (ev) => {
      const { headers, rows } = parseCSV(ev.target.result);
      if (!rows.length) {
        toast(`${file.name}: empty file`, "warning");
        return;
      }
      const type = detectDataType(headers);
      const aliases = type === "basin" ? BASIN_ALIASES : ANALOGUE_ALIASES;
      const mapping = autoMap(headers, aliases);
      openMappingModal(file.name, headers, rows, type, mapping);
    };
    reader.readAsText(file);
  });
}

function openMappingModal(
  fileName,
  headers,
  rows,
  dataType,
  autoMapping,
) {
  const fields =
    dataType === "basin"
      ? [
          { f: "name", lbl: "Basin Name", req: true },
          { f: "country", lbl: "Country" },
          { f: "region", lbl: "Region" },
          { f: "tectonic", lbl: "Tectonic Setting" },
          { f: "age", lbl: "Geological Age" },
          { f: "hc", lbl: "HC Phase" },
          { f: "area", lbl: "Area (km²)" },
          { f: "plays", lbl: "Play Count" },
          { f: "score", lbl: "Prospectivity Score" },
          { f: "status", lbl: "Status" },
        ]
      : [
          { f: "name", lbl: "Formation / Name", req: true },
          { f: "basin", lbl: "Basin" },
          { f: "age", lbl: "Age" },
          { f: "lith", lbl: "Lithology" },
          { f: "dep", lbl: "Dep. Env." },
          { f: "depth", lbl: "Depth (mTVDSS)" },
          { f: "hc", lbl: "HC Phase" },
          { f: "drive", lbl: "Drive Mechanism" },
          { f: "por", lbl: "Porosity %" },
          { f: "perm", lbl: "Permeability mD" },
          { f: "rf", lbl: "Recovery Factor %" },
          { f: "ntg", lbl: "NTG %" },
          { f: "gor", lbl: "GOR scf/bbl" },
          { f: "api", lbl: "API Gravity" },
        ];
  // Store data safely — never embed rows in onclick
  _pendingTyped = {
    fileName,
    rows,
    dataType,
    fields: fields.map((x) => x.f),
  };
  const preview = rows.slice(0, 3);
  openModal(`
<div class="modal-title">Map Columns — ${fileName}</div>
<div class="modal-sub" style="margin-bottom:10px"><strong style="color:var(--cyan)">${rows.length} rows</strong> · Data type: <strong style="color:var(--brand2)">${dataType === "basin" ? "Basin Catalogue" : "Analogue Engine"}</strong></div>
<div style="background:var(--bg4);border-radius:5px;padding:8px;margin-bottom:12px;overflow-x:auto;max-height:90px">
<table style="font-size:10px"><thead><tr>${headers.map((h) => `<th style="color:var(--cyan);padding:2px 7px">${h}</th>`).join("")}</tr></thead>
<tbody>${preview.map((r) => `<tr>${headers.map((h) => `<td style="color:var(--t2);padding:2px 7px">${(r[h] || "").toString().substring(0, 30)}</td>`).join("")}</tr>`).join("")}</tbody></table>
</div>
<div style="display:grid;grid-template-columns:1fr 1fr;gap:6px;max-height:260px;overflow-y:auto;margin-bottom:14px">
${fields
  .map(
    ({ f, lbl, req }) => `
  <div style="display:flex;align-items:center;gap:6px">
    <label style="font-size:10px;color:${req ? "var(--brand2)" : "var(--t2)"};min-width:110px;flex-shrink:0">${lbl}${req ? " *" : ""}</label>
    <select class="fc" id="map-${f}" style="flex:1;padding:4px;font-size:10px">
      <option value="">— skip —</option>
      ${headers.map((h) => `<option value="${h}" ${autoMapping[f] === h ? "selected" : ""}>${h}</option>`).join("")}
    </select>
  </div>`,
  )
  .join("")}
</div>
<div style="display:flex;gap:8px">
<button class="btn" onclick="commitIngestion()">✓ Ingest ${rows.length} Records</button>
<button class="btn2" onclick="closeModal();_pendingTyped=null">Cancel</button>
</div>`);
}

function commitIngestion() {
  if (!_pendingTyped) {
    toast("No pending data", "warning");
    return;
  }
  const { fileName, rows, dataType, fields: fieldKeys } = _pendingTyped;
  _pendingTyped = null;
  const mapping = {};
  fieldKeys.forEach((f) => {
    const s = document.getElementById("map-" + f);
    if (s && s.value) mapping[f] = s.value;
  });
  if (!mapping.name) {
    toast("Please map the Name field", "warning");
    return;
  }
  closeModal();
  let accepted = 0,
    quarantined = 0,
    failed = 0;
  rows.forEach((row) => {
    try {
      const rec = {};
      fieldKeys.forEach((f) => {
        if (mapping[f]) {
          let v = row[mapping[f]];
          if (
            [
              "area",
              "plays",
              "score",
              "depth",
              "por",
              "perm",
              "rf",
              "ntg",
              "gor",
              "api",
            ].includes(f)
          ) {
            v = parseFloat(v);
            if (isNaN(v)) v = null;
          }
          rec[f] = v;
        }
      });
      if (!rec.name || !rec.name.trim()) {
        failed++;
        return;
      }
      if (dataType === "basin") {
        if (
          BASINS.find(
            (b) => b.name.toLowerCase() === rec.name.toLowerCase(),
          )
        ) {
          quarantined++;
          return;
        }
        BASINS.push({
          name: rec.name,
          country: rec.country || "Unknown",
          region: rec.region || "Unknown",
          tectonic: rec.tectonic || "Unknown",
          age: rec.age || "Unknown",
          hc: rec.hc || "Oil & Gas",
          area: rec.area || 0,
          plays: rec.plays || 0,
          score: Math.min(100, Math.max(0, rec.score || 50)),
          status: rec.status || "Active",
          _source: fileName,
        });
      } else {
        if (
          ANALOGUES.find(
            (a) => a.name.toLowerCase() === rec.name.toLowerCase(),
          )
        ) {
          quarantined++;
          return;
        }
        ANALOGUES.push({
          rank: ANALOGUES.length + 1,
          name: rec.name,
          basin: rec.basin || "Unknown",
          age: rec.age || "Unknown",
          lith: rec.lith || "Sandstone",
          dep: rec.dep || "Unknown",
          depth: rec.depth || 0,
          hc: rec.hc || "Oil",
          drive: rec.drive || "Unknown",
          por: rec.por || 0,
          perm: rec.perm || 0,
          rf: rec.rf || 0,
          ntg: rec.ntg || 0,
          gor: rec.gor || 0,
          api: rec.api || 0,
          sim: 75,
          _source: fileName,
        });
      }
      accepted++;
    } catch (e) {
      failed++;
    }
  });
  if (dataType === "basin") {
    renderBasinTable(BASINS);
    renderTopBasins();
  }
  refreshPortfolioKPIs();
  const accEl = document.getElementById("ing-accepted");
  if (accEl)
    accEl.textContent = (
      parseInt(accEl.textContent.replace(/,/g, "")) + accepted
    ).toLocaleString();
  // Add to governance queue for review
  INGESTED_FILES.push({
    id: "FILE-" + Date.now(),
    name: fileName,
    records: accepted,
    datasetType: dataType === "basin" ? "Basin" : "Analogue",
    source: "Manual Upload",
    age: "Just now",
    status: "pending",
    loadedNames:
      dataType === "basin"
        ? [...BASINS].slice(-accepted).map((b) => b.name)
        : [...ANALOGUES].slice(-accepted).map((a) => a.name),
  });
  _refreshGovQueue();
  AUDIT_ENTRIES.unshift({
    time: now(),
    user: _userTag(),
    action: `Upload queued for governance: ${fileName} · ${accepted} ${dataType} records · ${quarantined} dupes · ${failed} failed`,
    status: failed > 0 ? "PARTIAL" : "PENDING",
    type: "Governance",
  });
  renderAuditLog(AUDIT_ENTRIES);
  addHistoryRow(fileName, accepted, quarantined);
  toast(
    `${accepted} ${dataType} records ingested from ${fileName}${quarantined ? ` · ${quarantined} dupes skipped` : ""}`,
    accepted > 0 ? "success" : "warning",
  );
}

function addHistoryRow(fileName, accepted, quarantined) {
  const wrap = document.getElementById("upload-history");
  if (!wrap) return;
  const div = document.createElement("div");
  div.style.cssText =
    "display:flex;align-items:center;gap:9px;padding:7px 9px;background:var(--bg4);border-radius:4px;margin-bottom:5px;font-size:10px";
  div.innerHTML = `<span style="color:${accepted > 0 ? "var(--green)" : "var(--amber)"}">${accepted > 0 ? "✓" : "⚠"}</span><span style="color:var(--t1);flex:1">${fileName}</span><span style="color:var(--t3)">${accepted} accepted${quarantined ? ` · ${quarantined} dupes` : ""} · Just now</span>`;
  // Insert after the header row
  const header = wrap.querySelector(".ing-hist-header");
  if (header) header.after(div);
  else wrap.prepend(div);
}

