function handleDropTyped(e, key) {
  e.preventDefault();
  document.getElementById("dz-" + key)?.classList.remove("drag-over");
  handleFilesTyped(e.dataTransfer.files, key);
}

function handleFilesTyped(files, key) {
  [...files].forEach((file) => {
    const ext = file.name.split(".").pop().toLowerCase();
    if (!["csv", "tsv", "txt"].includes(ext)) {
      toast(`Only CSV/TSV files supported`, "warning");
      return;
    }
    // Show parsing state
    addFileRowTyped(key, file.name, "parsing");
    const reader = new FileReader();
    reader.onload = (e) =>
      processTypedFile(e.target.result, file.name, key);
    reader.readAsText(file);
  });
}

function addFileRowTyped(key, name, state) {
  const wrap = document.getElementById("files-" + key);
  if (!wrap) return;
  const id = "frow-" + key + "-" + name.replace(/\W/g, "");
  let el = document.getElementById(id);
  if (!el) {
    el = document.createElement("div");
    el.id = id;
    wrap.prepend(el);
  }
  const colors = {
    parsing: "var(--amber)",
    ok: "var(--green)",
    error: "var(--red)",
  };
  const icons = { parsing: "⏳", ok: "✅", error: "❌" };
  const labels = { parsing: "Parsing…", ok: "Ingested", error: "Error" };
  el.style.cssText = `display:flex;align-items:center;gap:10px;padding:10px 14px;
  background:${state === "ok" ? "rgba(0,135,90,.06)" : state === "error" ? "rgba(217,48,37,.06)" : "rgba(192,120,0,.05)"};
  border:1px solid ${state === "ok" ? "rgba(0,135,90,.2)" : state === "error" ? "rgba(217,48,37,.2)" : "rgba(192,120,0,.2)"};
  border-radius:8px;margin-bottom:8px;animation:fadeUp .3s ease`;
  el.innerHTML = `
    <span style="font-size:20px;flex-shrink:0">${icons[state]}</span>
    <div style="flex:1;min-width:0">
    <div style="font-size:11px;font-weight:600;color:var(--t1);white-space:nowrap;overflow:hidden;text-overflow:ellipsis"> ${name}</div>
    <div style="font-size:10px;color:var(--t3);margin-top:2px">${new Date().toLocaleTimeString()}</div>
    </div>
    <span style="font-size:10px;font-weight:700;color:${colors[state]};flex-shrink:0">${labels[state]}</span>
  `;
}

function processTypedFile(text, fileName, key) {
  const { headers, rows } = parseCSV(text);
  if (!rows.length) {
    addFileRowTyped(key, fileName, "error");
    toast(`${fileName}: file is empty`, "warning");
    return;
  }
  openTypedMappingModal(fileName, headers, rows, key);
}

function openTypedMappingModal(fileName, headers, rows, key) {
  const m = ING_META[key];
  // Store safely — never embed rows JSON in onclick
  _pendingTyped = { fileName, rows, key, fields: m.fields };
  const preview = rows.slice(0, 3);
  const autoMapping = {};
  m.fields.forEach((f) => {
    const hLow = headers.map((h) =>
      h.toLowerCase().replace(/[\s\-]/g, "_"),
    );
    const fNorm = f.toLowerCase();
    let idx = hLow.indexOf(fNorm);
    if (idx < 0)
      idx = hLow.findIndex(
        (h) =>
          h.startsWith(fNorm.split("_")[0]) ||
          fNorm.startsWith(h.split("_")[0]),
      );
    if (idx >= 0) autoMapping[f] = headers[idx];
  });
  openModal(`
<div class="modal-title" style="display:flex;align-items:center;gap:8px">
<span style="color:${m.color}">${m.icon}</span> Map Columns — ${m.label}
</div>
<div class="modal-sub" style="margin-bottom:10px">
<strong style="color:var(--cyan)">${rows.length} rows</strong> detected in <strong>${fileName}</strong>
</div>
<div style="background:var(--bg4);border-radius:5px;padding:8px;margin-bottom:12px;overflow-x:auto;max-height:100px">
<div style="font-size:10px;color:var(--t3);letter-spacing:1px;text-transform:uppercase;margin-bottom:4px">Preview</div>
<table style="font-size:10px;min-width:100%">
  <thead><tr>${headers.map((h) => `<th style="color:${m.color};padding:2px 7px;white-space:nowrap">${h}</th>`).join("")}</tr></thead>
  <tbody>${preview.map((r) => `<tr>${headers.map((h) => `<td style="color:var(--t2);padding:2px 7px;white-space:nowrap">${(r[h] || "").toString().substring(0, 30)}</td>`).join("")}</tr>`).join("")}</tbody>
</table>
</div>
<div style="font-size:10px;color:var(--t3);text-transform:uppercase;letter-spacing:1px;margin-bottom:6px">Map Your Columns → EDAFY Fields</div>
<div style="display:grid;grid-template-columns:1fr 1fr;gap:6px;max-height:280px;overflow-y:auto;margin-bottom:14px">
${m.fields
  .map(
    (f) => `
  <div style="display:flex;align-items:center;gap:6px">
    <span style="font-size:10px;font-family:monospace;color:${m.required.includes(f) ? "var(--brand2)" : "var(--t2)"};min-width:160px;flex-shrink:0">${f}${m.required.includes(f) ? "*" : ""}</span>
    <select class="fc" id="tmap-${f}" style="flex:1;padding:4px 7px;font-size:10px">
      <option value="">— skip —</option>
      ${headers.map((h) => `<option value="${h}" ${autoMapping[f] === h ? "selected" : ""}>${h}</option>`).join("")}
    </select>
  </div>`,
  )
  .join("")}
</div>
<div style="display:flex;gap:8px">
<button class="btn" onclick="commitTypedIngestion()">✓ Ingest ${rows.length} Records</button>
<button class="btn2" onclick="closeModal();_pendingTyped=null">Cancel</button>
</div>
`);
}

function commitTypedIngestion() {
  if (!_pendingTyped) {
    toast("No pending data", "warning");
    return;
  }
  const { fileName, rows, key, fields: fieldKeys } = _pendingTyped;
  _pendingTyped = null;
  const mapping = {};
  fieldKeys.forEach((f) => {
    const sel = document.getElementById("tmap-" + f);
    if (sel && sel.value) mapping[f] = sel.value;
  });
  const m = ING_META[key];
  if (m.required.some((r) => !mapping[r])) {
    toast(
      `Please map required fields: ${m.required.join(", ")}`,
      "warning",
    );
    return;
  }
  closeModal();

  let accepted = 0,
    skipped = 0,
    failed = 0;
  rows.forEach((row) => {
    try {
      const rec = {};
      fieldKeys.forEach((f) => {
        if (mapping[f]) rec[f] = row[mapping[f]];
      });
      const name = rec.analogue_name || rec.name || "";
      if (!name) {
        failed++;
        return;
      }

      // Find matching analogue by name (fuzzy)
      let target = ANALOGUES.find(
        (a) =>
          a.name.toLowerCase().includes(name.toLowerCase()) ||
          name
            .toLowerCase()
            .includes(a.name.toLowerCase().split("—")[0].trim()),
      );
      if (!target) {
        // Create a stub analogue if not found
        target = {
          rank: ANALOGUES.length + 1,
          name,
          basin: rec.basin || "Unknown",
          age: "Unknown",
          lith: "Unknown",
          dep: "Unknown",
          depth: 0,
          hc: "Oil",
          drive: "Unknown",
          por: 0,
          perm: 0,
          rf: 0,
          ntg: 0,
          gor: 0,
          api: 0,
          sim: 70,
        };
        ANALOGUES.push(target);
      }

      // Merge the typed data into the appropriate sub-object
      if (key === "reservoir") {
        const n = (v) => parseFloat(v) || 0;
        target.depth = n(rec.depth_mtvdss) || target.depth;
        target.por = n(rec.porosity_pct) || target.por;
        target.perm = n(rec.permeability_md) || target.perm;
        target.rf = n(rec.recovery_factor_pct) || target.rf;
        target.ntg = n(rec.ntg_pct) || target.ntg;
        target.gor = n(rec.gor_scf_bbl) || target.gor;
        target.api = n(rec.api_gravity) || target.api;
        target.gross_pay = n(rec.gross_pay_m) || target.gross_pay;
        target.net_pay = n(rec.net_pay_m) || target.net_pay;
        target.temp = n(rec.temperature_c) || target.temp;
        target.pres_res =
          n(rec.reservoir_pressure_bar) || target.pres_res;
        target.sw = n(rec.water_saturation) || target.sw;
        target.bo = n(rec.bo_rb_stb) || target.bo;
        target.visc = n(rec.viscosity_cp) || target.visc;
        if (rec.hc_phase) target.hc = rec.hc_phase;
        if (rec.drive_mechanism) target.drive = rec.drive_mechanism;
        if (rec.lithology) target.lith = rec.lithology;
        if (rec.dep_env) target.dep = rec.dep_env;
        if (rec.age) target.age = rec.age;
        if (rec.basin) target.basin = rec.basin;
      } else if (key === "geopressure") {
        const n = (v) => parseFloat(v) || null;
        target.geo = target.geo || {};
        if (rec.pore_pressure_gradient_psi_ft)
          target.geo.pres_grad = n(rec.pore_pressure_gradient_psi_ft);
        if (rec.overburden_gradient_psi_ft)
          target.geo.obstr_grad = n(rec.overburden_gradient_psi_ft);
        if (rec.fracture_gradient_psi_ft)
          target.geo.frac_grad = n(rec.fracture_gradient_psi_ft);
        if (rec.ppg_equivalent) target.geo.ppg = n(rec.ppg_equivalent);
        if (rec.ecd_ppg) target.geo.ecd = n(rec.ecd_ppg);
        if (rec.pressure_coefficient)
          target.geo.pressure_coeff = n(rec.pressure_coefficient);
        if (rec.pressure_regime)
          target.geo.pressure_regime = rec.pressure_regime;
        if (rec.overpressure_mechanism)
          target.geo.overpressure_mech = rec.overpressure_mechanism;
        if (rec.mudweight_min_ppg)
          target.geo.mudweight_min = n(rec.mudweight_min_ppg);
        if (rec.mudweight_max_ppg)
          target.geo.mudweight_max = n(rec.mudweight_max_ppg);
      } else if (key === "geochem") {
        const n = (v) => parseFloat(v) || null;
        target.geochem = target.geochem || {};
        if (rec.source_formation)
          target.geochem.source_fm = rec.source_formation;
        if (rec.kerogen_type)
          target.geochem.kerogen_type = rec.kerogen_type;
        if (rec.toc_pct) target.geochem.toc = n(rec.toc_pct);
        if (rec.vitrinite_reflectance_ro)
          target.geochem.ro_vitrinite = n(rec.vitrinite_reflectance_ro);
        if (rec.hydrogen_index_mg_hc_g_toc)
          target.geochem.hindex = n(rec.hydrogen_index_mg_hc_g_toc);
        if (rec.oxygen_index_mg_co2_g_toc)
          target.geochem.oindex = n(rec.oxygen_index_mg_co2_g_toc);
        if (rec.tmax_c) target.geochem.tmax = n(rec.tmax_c);
        if (rec.expulsion_efficiency_pct)
          target.geochem.expulsion_eff = n(rec.expulsion_efficiency_pct);
        if (rec.charge_volume)
          target.geochem.charge_volume = rec.charge_volume;
        if (rec.migration_distance_km)
          target.geochem.migration_dist = n(rec.migration_distance_km);
        if (rec.oil_family) target.geochem.oil_family = rec.oil_family;
        if (rec.sulfur_pct) target.geochem.sulfur_pct = n(rec.sulfur_pct);
        if (rec.c15_plus_pct)
          target.geochem.c15_plus = n(rec.c15_plus_pct);
        if (rec.predicted_api)
          target.geochem.api_pred = n(rec.predicted_api);
      } else if (key === "mineral") {
        const n = (v) => parseFloat(v) || 0;
        target.mineral = target.mineral || {};
        [
          "quartz",
          "feldspar",
          "rock_fragments",
          "kaolinite",
          "illite",
          "smectite",
          "chlorite",
          "calcite_cement",
          "dolomite",
          "pyrite",
          "siderite",
          "mica",
        ].forEach((min) => {
          const col = min + "_pct";
          if (rec[col] !== undefined) target.mineral[min] = n(rec[col]);
        });
        if (rec.clay_total_pct)
          target.mineral.clay_total = n(rec.clay_total_pct);
        if (rec.cement_type) target.mineral.cement_type = rec.cement_type;
      } else if (key === "fluid") {
        const n = (v) => parseFloat(v) || null;
        target.fluid = target.fluid || {};
        if (rec.oil_density_g_cc)
          target.fluid.oil_density = n(rec.oil_density_g_cc);
        if (rec.gas_specific_gravity)
          target.fluid.gas_sg = n(rec.gas_specific_gravity);
        if (rec.fvf_oil_rb_stb)
          target.fluid.fvf_oil = n(rec.fvf_oil_rb_stb);
        if (rec.bubble_point_bar)
          target.fluid.pb = n(rec.bubble_point_bar);
        if (rec.solution_gor_scf_stb)
          target.fluid.rs = n(rec.solution_gor_scf_stb);
        if (rec.z_factor) target.fluid.z_factor = n(rec.z_factor);
        if (rec.brine_salinity_ppm)
          target.fluid.brine_sal = n(rec.brine_salinity_ppm);
        if (rec.wor) target.fluid.wor = n(rec.wor);
        if (rec.h2s_ppm) target.fluid.h2s_ppm = n(rec.h2s_ppm);
        if (rec.co2_pct) target.fluid.co2_pct = n(rec.co2_pct);
        if (rec.n2_pct) target.fluid.n2_pct = n(rec.n2_pct);
        if (rec.c1_methane_pct)
          target.fluid.c1_pct = n(rec.c1_methane_pct);
        if (rec.c2_ethane_pct) target.fluid.c2_pct = n(rec.c2_ethane_pct);
        if (rec.c3_propane_pct)
          target.fluid.c3_pct = n(rec.c3_propane_pct);
      } else if (key === "diagenesis") {
        target.diagenesis = target.diagenesis || {};
        const strFields = [
          "burial_grade",
          "compaction",
          "cementation",
          "dissolution",
          "quartz_overgrowths",
          "chlorite_coating",
          "kaolinite_pore_fill",
          "authigenic_clay",
          "grain_coating",
        ];
        strFields.forEach((f) => {
          if (rec[f])
            target.diagenesis[
              f
                .replace("quartz_overgrowths", "qovergrowths")
                .replace("chlorite_coating", "chlorite_coat")
                .replace("kaolinite_pore_fill", "kaolinite_pore")
            ] = rec[f];
        });
        if (rec.fluid_inclusion_th_c)
          target.diagenesis.fluid_inclusion_th =
            parseFloat(rec.fluid_inclusion_th_c) || null;
      }
      target._source = fileName;
      accepted++;
    } catch (e) {
      failed++;
    }
  });

  // Update loaded records display
  const loadedEl = document.getElementById("ing-" + key + "-loaded");
  if (loadedEl)
    loadedEl.innerHTML = `<div style="padding:8px 10px;background:rgba(0,229,160,.07);border:1px solid rgba(0,229,160,.2);border-radius:5px;font-size:10px;color:var(--green)">✓ ${accepted} records merged into ${ING_META[key].label} dataset${failed ? ` · ${failed} failed` : ""}</div>`;

  addFileRowTyped(key, fileName, accepted > 0 ? "ok" : "error");

  // Update counters
  const accEl = document.getElementById("ing-accepted");
  if (accEl)
    accEl.textContent = (
      parseInt(accEl.textContent.replace(/,/g, "")) + accepted
    ).toLocaleString();

  // Audit
  INGESTED_FILES.push({
    id: "FILE-" + Date.now(),
    name: fileName,
    records: accepted,
    datasetType: ING_META[key].label,
    source: "Manual Upload — " + ING_META[key].label + " Tab",
    age: "Just now",
    status: "pending",
    loadedNames: [],
  });
  renderGovQueue();
  AUDIT_ENTRIES.unshift({
    time: now(),
    user: _userTag(),
    action: `${ING_META[key].label} upload queued: ${fileName} · ${accepted} records pending governance review`,
    status: "PENDING",
    type: "Governance",
  });
  renderAuditLog(AUDIT_ENTRIES);
  renderIngHistoryLive(fileName, accepted, 0);

  toast(
    `${ING_META[key].label}: ${accepted} analogues updated from ${fileName}`,
    "success",
  );
  refreshPortfolioKPIs();
  if (accepted > 0)
    setTimeout(
      () =>
        toast(
          "→ Open Analogue Engine and click any result to see updated data",
          "info",
        ),
      1500,
    );
}

