function renderExpFieldToggles() {
  const el = document.getElementById("exp-field-toggles");
  if (!el) return;
  el.innerHTML = EXPORT_FIELDS.map(
    (f) => `
<label style="display:flex;align-items:center;gap:5px;font-size:10px;font-weight:600;cursor:${f.always ? "default" : "pointer"};user-select:none;
padding:4px 9px;background:${_expFieldState[f.key] ? "rgba(13,76,146,.1)" : "var(--bg4)"};
border:1px solid ${_expFieldState[f.key] ? "rgba(13,76,146,.3)" : "#E2E8F0"};border-radius:14px;transition:all .15s;color:${_expFieldState[f.key] ? "var(--purple)" : "var(--t3)"}">
<input type="checkbox" ${_expFieldState[f.key] ? "checked" : ""} ${f.always ? "disabled" : ""} style="display:none"
  onchange="_expFieldState['${f.key}']=this.checked;renderExpFieldToggles()">
${_expFieldState[f.key] ? "✓" : ""} ${f.label}
</label>`,
  ).join("");
}

function renderExpCompleteness() {
  const el = document.getElementById("exp-completeness");
  if (!el) return;
  el.innerHTML = EXPORT_FIELDS.map((f) => {
    const filled = BASINS.filter(
      (b) =>
        b[f.key] !== undefined && b[f.key] !== "" && b[f.key] !== null,
    ).length;
    const pct = Math.round((filled / Math.max(BASINS.length, 1)) * 100);
    const col =
      pct >= 90
        ? "var(--green)"
        : pct >= 60
          ? "var(--amber)"
          : "var(--red)";
    return `<div style="display:flex;align-items:center;gap:8px;margin-bottom:7px">
<div style="width:90px;font-size:10px;color:var(--t2);flex-shrink:0">${f.label}</div>
<div style="flex:1;height:6px;background:#E8ECF5;border-radius:3px;overflow:hidden">
  <div style="height:100%;width:${pct}%;background:${col};border-radius:3px;transition:width .4s"></div>
</div>
<div style="width:32px;font-size:10px;font-weight:600;color:${col};text-align:right">${pct}%</div>
</div>`;
  }).join("");
}

const _expHistory = [];
function addExportHistory(format, selection, type) {
  _expHistory.unshift({
    format,
    selection,
    type,
    time: new Date().toLocaleTimeString(),
  });
  renderExpHistory();
}
function renderExpHistory() {
  const el = document.getElementById("exp-history");
  if (!el) return;
  if (!_expHistory.length) {
    el.innerHTML = `<div style="font-size:10px;color:var(--t3);padding:8px 0;text-align:center">No exports yet in this session</div>`;
    return;
  }
  el.innerHTML = `<table><thead><tr><th>Time</th><th>Format</th><th>Selection</th><th>Status</th></tr></thead><tbody>
${_expHistory
.map(
  (e) => `<tr>
<td style="font-size:10px;color:var(--t3)">${e.time}</td>
<td><span class="tl tl-c" style="font-size:10px">${e.type}</span></td>
<td style="font-size:10px">${e.selection}</td>
<td><span class="tl tl-g" style="font-size:10px">✓ Complete</span></td>
</tr>`,
)
.join("")}
</tbody></table>`;
}

function runExport(fmt) {
  const filter =
    document.getElementById("exp-basin-filter")?.value || "all";
  let basins = [...BASINS];
  if (filter === "mature")
    basins = basins.filter((b) => b.status === "Mature");
  if (filter === "active")
    basins = basins.filter((b) => b.status === "Active");
  if (filter === "frontier")
    basins = basins.filter((b) => b.status === "Frontier");
  if (filter === "highscore")
    basins = basins.filter((b) => b.score >= 70);

  const fields = EXPORT_FIELDS.filter((f) => _expFieldState[f.key]).map(
    (f) => f.key,
  );
  const label =
    filter === "all"
      ? `All Basins (${basins.length})`
      : filter === "highscore"
        ? `High prospectivity (${basins.length})`
        : `${filter} basins (${basins.length})`;

  if (fmt === "csv") {
    const header = fields
      .map((k) => EXPORT_FIELDS.find((f) => f.key === k)?.label || k)
      .join(",");
    const rows = basins.map((b) =>
      fields.map((k) => `"${b[k] || ""}"`).join(","),
    );
    const csv = [header, ...rows].join("\n");
    const blob = new Blob([csv], { type: "text/csv" });
    const a = document.createElement("a");
    a.href = URL.createObjectURL(blob);
    a.download = `edafy_basins_${filter}_${Date.now()}.csv`;
    a.click();
    toast(
      `CSV exported — ${basins.length} basins, ${fields.length} fields`,
      "success",
    );
    addExportHistory("CSV", label, "CSV");
  } else if (fmt === "json") {
    const data = basins.map((b) =>
      Object.fromEntries(fields.map((k) => [k, b[k]])),
    );
    const blob = new Blob(
      [
        JSON.stringify(
          {
            basins: data,
            exported: new Date().toISOString(),
            count: basins.length,
          },
          null,
          2,
        ),
      ],
      { type: "application/json" },
    );
    const a = document.createElement("a");
    a.href = URL.createObjectURL(blob);
    a.download = `edafy_basins_${filter}.json`;
    a.click();
    toast(`JSON exported — ${basins.length} basins`, "success");
    addExportHistory("JSON", label, "JSON");
  } else if (fmt === "excel") {
    if (typeof XLSX !== "undefined") {
      const wsData = [
        fields.map(
          (k) => EXPORT_FIELDS.find((f) => f.key === k)?.label || k,
        ),
        ...basins.map((b) => fields.map((k) => b[k] || "")),
      ];
      const ws = XLSX.utils.aoa_to_sheet(wsData);
      const wb = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(wb, ws, "Basin Catalogue");
      XLSX.writeFile(wb, `edafy_basins_${filter}_${Date.now()}.xlsx`);
      toast(
        `Excel exported — ${basins.length} basins, ${fields.length} fields`,
        "success",
      );
    } else {
      exportTable("basin-table", "basins");
    }
    addExportHistory("Excel", label, "XLSX");
  } else if (fmt === "gis") {
    exportBasinsGeoJSON(basins, label);
    addExportHistory("GIS GeoJSON", label, "GeoJSON");
  } else if (fmt === "shapefile") {
    exportBasinsShapefile(basins, label);
    addExportHistory("GIS Shapefile", label, "SHP");
  } else if (fmt === "pdf") {
    exportBasinsPDF(basins, label);
    addExportHistory("Basin Reports", label, "PDF");
  } else if (fmt === "api") {
    const url = `https://api.afed.digital/edafy/basins?filter=${filter}&fields=${fields.join(",")}`;
    openModal(`<div class="modal-title">API Endpoint</div>
<div style="margin-bottom:10px;font-size:11px;color:var(--t2)">Use this URL to stream basin data into your pipeline. Authentication via API key header.</div>
<div style="background:#1A1D2E;border-radius:6px;padding:12px;font-family:monospace;font-size:10px;color:#00E5A0;word-break:break-all">${url}</div>
<div style="margin-top:12px;font-size:10px;color:var(--t3)">Header: <code>X-EDAFY-Key: &lt;your-api-key&gt;</code></div>
<button class="btn2" style="margin-top:10px" onclick="navigator.clipboard.writeText('${url}');toast('URL copied','success')">Copy URL</button>`);
    addExportHistory("API URL", label, "API");
  }
}

