// Economic parameters pulled from active DCF result or ECON_DB
function _sensGetEcon() {
  // 1st priority: live DCF result
  if (typeof econLastResult !== "undefined" && econLastResult)
    return econLastResult;
  // 2nd: current econ inputs
  const g = (id) => +(document.getElementById("econ-" + id)?.value || 0);
  if (g("price") > 0)
    return {
      price: g("price"),
      capex: g("capex"),
      opex: g("opex"),
      discount: g("discount"),
      royalty: g("royalty"),
      tax: g("tax"),
      govtake: g("govtake"),
      years: g("years") || 20,
      npv: null,
      irr: null,
    };
  // 3rd: defaults
  return {
    price: 75,
    capex: 450,
    opex: 12,
    discount: 10,
    royalty: 12.5,
    tax: 30,
    govtake: 45,
    years: 20,
  };
}

// ── Core calculators ──────────────────────────────────────────
function calcSTOIIP_sens(overrides) {
  const get = (key) =>
    overrides[key] !== undefined
      ? overrides[key]
      : +document.getElementById("vi-" + key)?.value ||
        SENS_PARAMS.find((p) => p.key === key)?.p50 ||
        0;
  const grv = get("grv"),
    ntg = get("ntg"),
    phi = get("phi"),
    sw = get("sw"),
    bo = get("bo"),
    rf = get("rf");
  const hcPV = grv * 1e9 * ntg * phi * (1 - sw);
  const stoiip = Math.max(0, Math.round((hcPV / bo) * 6.2898e-6));
  return { stoiip, eur: Math.max(0, Math.round(stoiip * rf)) };
}

function calcNPV_sens(stoiip, overrides) {
  const e = _sensGetEcon();
  const ov = overrides || {};
  const price = ov.price ?? e.price ?? 75; // $/bbl
  const capex = ov.capex ?? e.capex ?? 450; // $M
  const opex_bbl = ov.opex ?? e.opex ?? 12; // $/bbl
  const disc = (ov.discount ?? e.discount ?? 10) / 100;
  const royalty = (ov.royalty ?? e.royalty ?? 12.5) / 100;
  const tax = (ov.tax ?? e.tax ?? 30) / 100;
  const govtake = (ov.govtake ?? e.govtake ?? 45) / 100;
  const years = ov.years ?? e.years ?? 20;
  const rf = SENS_PARAMS.find((p) => p.key === "rf")?.p50 ?? 0.35;
  // stoiip is in MMbbl; vol = recoverable MMbbl
  const vol = stoiip * rf; // MMbbl
  const rev = vol * price; // $M  (MMbbl × $/bbl = $M)
  const opexT = vol * opex_bbl; // $M
  const royT = rev * royalty; // $M
  const taxableI = (rev - royT - opexT) * (1 - govtake);
  const netInc = taxableI * (1 - tax); // $M/yr gross
  const df = disc > 0 ? (1 - Math.pow(1 + disc, -years)) / disc : years;
  return Math.round(netInc * df - capex);
}

// ── Tab switcher ──────────────────────────────────────────────
function switchSensTab(tab, el) {
  ["tornado", "spider", "npv", "scenario"].forEach((t) => {
    const p = document.getElementById(`sens-${t}-panel`);
    if (p) p.style.display = t === tab ? "block" : "none";
  });

  // Highlight active tab
  document
    .querySelectorAll("#sens-tabs .tab")
    .forEach((t) => t.classList.remove("on"));
  if (el) el.classList.add("on");

  // ✅ Update breadcrumb
  const bc = document.getElementById("breadcrumb-section");
  if (bc) bc.textContent = el?.textContent.trim() || "";

  // Tab-specific functions
  if (tab === "tornado") {
    buildSensParamTable();
    renderTornado();
    renderSensKpis();
  }
  if (tab === "spider") {
    renderSpider();
  }
  if (tab === "npv") {
    renderNPVvsPrice();
  }
  if (tab === "scenario") {
    renderSensScenarioTable();
    renderSensScenarioChart();
  }
}

// ── KPI strip ─────────────────────────────────────────────────
function renderSensKpis() {
  const base = calcSTOIIP_sens({}).stoiip;
  const loAll = calcSTOIIP_sens(
    Object.fromEntries(SENS_PARAMS.map((p) => [p.key, p.p10])),
  ).stoiip;
  const hiAll = calcSTOIIP_sens(
    Object.fromEntries(SENS_PARAMS.map((p) => [p.key, p.p90])),
  ).stoiip;
  const impacts = SENS_PARAMS.map((p) => ({
    label: p.label,
    swing: Math.abs(
      calcSTOIIP_sens({ [p.key]: p.p90 }).stoiip -
        calcSTOIIP_sens({ [p.key]: p.p10 }).stoiip,
    ),
  })).sort((a, b) => b.swing - a.swing);
  const top = impacts[0];
  const npvLo = calcNPV_sens(loAll);
  const npvHi = calcNPV_sens(hiAll);

  const sv = (id, v) => {
    const e = document.getElementById(id);
    if (e) e.textContent = v;
  };
  sv("sk-stoiip", base.toLocaleString() + " MMbbl");
  sv("sk-lo", loAll.toLocaleString() + " MMbbl");
  sv("sk-hi", hiAll.toLocaleString() + " MMbbl");
  sv("sk-top", top.label);
  sv("sk-top-sub", `±${top.swing.toLocaleString()} MMbbl swing`);
  sv(
    "sk-npv",
    `$${npvLo.toLocaleString()} – $${npvHi.toLocaleString()}M`,
  );
}

// ── Param table ───────────────────────────────────────────────
function buildSensParamTable() {
  // Populate the editable table in Sensitivities section
  const tbody = document.getElementById("sens-param-tbody");
  const base = calcSTOIIP_sens({}).stoiip;

  const editableRows = SENS_PARAMS.map((p, idx) => {
    const lo = calcSTOIIP_sens({ [p.key]: p.p10 }).stoiip;
    const hi = calcSTOIIP_sens({ [p.key]: p.p90 }).stoiip;
    const swing = hi - lo;
    const swPct = base > 0 ? Math.round((swing / base) * 100) : 0;
    const barW = Math.min(100, swPct);
    return `
      <tr style="border-bottom:1px solid var(--b2)">
        <td style="padding:6px 8px">
          <div style="font-size:10px;font-weight:600;color:var(--t1)">${p.label}</div>
          <div style="height:3px;background:#E8ECF5;border-radius:2px;margin-top:3px;width:60px">
            <div style="height:3px;width:${barW}%;background:var(--purple);border-radius:2px"></div>
          </div>
          <div style="font-size:10px;color:var(--t3)">${p.unit}</div>
        </td>
        <td style="padding:4px 3px">
          <input type="number" value="${p.p10}" step="${p.key === "grv" ? 5 : 0.01}"
            style="width:65px;border:1px solid rgba(198,40,40,.3);border-radius:4px;padding:3px 5px;font-size:10px;color:var(--red);font-weight:600;background:rgba(217,48,37,.03)"
            oninput="SENS_PARAMS[${idx}].p10=parseFloat(this.value)||0;updateSensAll()">
        </td>
        <td style="padding:4px 3px">
          <input type="number" value="${p.p50}" step="${p.key === "grv" ? 5 : 0.01}"
            style="width:65px;border:1px solid rgba(13,76,146,.3);border-radius:4px;padding:3px 5px;font-size:10px;color:var(--purple);font-weight:600;background:rgba(13,76,146,.03)"
            oninput="SENS_PARAMS[${idx}].p50=parseFloat(this.value)||0;updateSensAll()">
        </td>
        <td style="padding:4px 3px">
          <input type="number" value="${p.p90}" step="${p.key === "grv" ? 5 : 0.01}"
            style="width:65px;border:1px solid rgba(26,127,90,.3);border-radius:4px;padding:3px 5px;font-size:10px;color:var(--green);font-weight:600;background:rgba(0,135,90,.03)"
            oninput="SENS_PARAMS[${idx}].p90=parseFloat(this.value)||0;updateSensAll()">
        </td>
        <td style="padding:4px 6px;text-align:center">
          <div style="font-size:10px;font-weight:700;color:var(--purple)">±${swPct}%</div>
          <div style="font-size:10px;color:var(--t3)">${swing.toLocaleString()}</div>
        </td>
      </tr>
    `;
  });

  if (tbody) tbody.innerHTML = editableRows.join("");

  // Also populate the read-only display table in sec-risk
  const riskTbody = document.getElementById("risk-sens-param-tbody");
  if (riskTbody) {
    riskTbody.innerHTML = SENS_PARAMS.map(p => {
      const lo    = calcSTOIIP_sens({ [p.key]: p.p10 }).stoiip;
      const hi    = calcSTOIIP_sens({ [p.key]: p.p90 }).stoiip;
      const swing = hi - lo;
      const swPct = base > 0 ? Math.round((swing / base) * 100) : 0;
      return `
        <tr style="border-bottom:1px solid var(--b2)">
          <td style="padding:6px 8px;font-size:10px;font-weight:600;color:var(--t1)">${p.label}</td>
          <td style="padding:6px 8px;font-size:10px;color:var(--t3)">${p.unit}</td>
          <td style="padding:6px 8px;text-align:center;font-size:10px;color:var(--red);font-weight:700">${p.p10}</td>
          <td style="padding:6px 8px;text-align:center;font-size:10px;color:var(--purple);font-weight:700">${p.p50}</td>
          <td style="padding:6px 8px;text-align:center;font-size:10px;color:var(--green);font-weight:700">${p.p90}</td>
          <td style="padding:6px 8px;text-align:center;font-size:10px;color:var(--t2)">${lo.toLocaleString()}</td>
          <td style="padding:6px 8px;text-align:center;font-size:10px;color:var(--t2)">${hi.toLocaleString()}</td>
          <td style="padding:6px 8px;text-align:center;font-size:10px;font-weight:700;color:var(--purple)">±${swPct}%</td>
        </tr>
      `;
    }).join("");
  }
}

function updateSensAll() {
  buildSensParamTable();
  renderTornado();
  if (
    document.getElementById("sens-spider-panel")?.style.display !== "none"
  )
    renderSpider();
  if (document.getElementById("sens-npv-panel")?.style.display !== "none")
    renderNPVvsPrice();
  if (
    document.getElementById("sens-scenario-panel")?.style.display !==
    "none"
  ) {
    renderSensScenarioTable();
    renderSensScenarioChart();
  }
  renderSensKpis();
}

// ── Data source sync ──────────────────────────────────────────
function initSensParams() {
  syncSensFromVolumetric(true);
}

function syncSensFromVolumetric(silent) {
  let synced = 0;
  SENS_PARAMS.forEach((p) => {
    const el = document.getElementById(p.voiKey);
    if (!el) return;
    const v = parseFloat(el.value);
    if (isNaN(v)) return;
    const swing = p.key === "sw" ? 0.3 : p.key === "bo" ? 0.12 : 0.3;
    p.p50 = v;
    p.p10 = parseFloat(
      (p.inverse ? v * (1 + swing) : v * (1 - swing)).toFixed(4),
    );
    p.p90 = parseFloat(
      (p.inverse ? v * (1 - swing) : v * (1 + swing)).toFixed(4),
    );
    synced++;
  });
  const badge = document.getElementById("sens-source-badge");
  if (badge) {
    badge.textContent = "Volumetrics";
    badge.style.background = "rgba(124,58,237,.1)";
    badge.style.color = "#7C3AED";
  }
  updateSensAll();
  if (!silent)
    toast(`${synced} parameters synced from Volumetrics`, "success");
}

function syncSensFromEconomics() {
  const e = _sensGetEcon();
  if (!e.price) {
    toast("Run Economics DCF first", "warning");
    return;
  }
  // Update NPV display in scenario table
  updateSensAll();
  const badge = document.getElementById("sens-source-badge");
  if (badge) {
    badge.textContent = "Economics (DCF)";
    badge.style.background = "rgba(26,127,90,.1)";
    badge.style.color = "#1A7F5A";
  }
  toast("NPV parameters synced from Economics DCF", "success");
}

function loadSensFromBasin(basinName) {
  if (!basinName) return;
  const key = "basin:" + basinName;
  const d = typeof ECON_DB !== "undefined" ? ECON_DB[key] : null;
  if (!d) return;
  // Map ECON_DB rf → sens rf p50
  const rfParam = SENS_PARAMS.find((p) => p.key === "rf");
  if (rfParam) {
    rfParam.p50 = d.rf / 100;
    rfParam.p10 = parseFloat((rfParam.p50 * 0.7).toFixed(3));
    rfParam.p90 = parseFloat((rfParam.p50 * 1.4).toFixed(3));
  }
  // Map phi if available analogue
  const badge = document.getElementById("sens-source-badge");
  if (badge) {
    badge.textContent = basinName;
    badge.style.background = "rgba(13,76,146,.1)";
    badge.style.color = "var(--sb2)";
  }
  updateSensAll();
  toast(`Sensitivity params updated from ${basinName}`, "success");
}

function populateBasinProfileDropdown() {
  const sel = document.getElementById('sens-basin-select');
  if (!sel || typeof BASINS === 'undefined') return;

  // 1. Start with the default placeholder
  let html = '<option value="">Choose a basin to view exploration profile…</option>';

  // 2. Generate an option for every basin in your data
  BASINS.forEach(b => {
    html += `<option value="${b.name}">${b.name}</option>`;
  });

  // 3. Inject it into the DOM
  sel.innerHTML = html;
}

// Run this once when the page loads
populateBasinProfileDropdown();

