function addSensParam() {
  const name = prompt("Parameter label:", "New Param");
  if (!name) return;
  const key =
    name.toLowerCase().replace(/\s+/g, "_").slice(0, 8) +
    "_" +
    SENS_PARAMS.length;
  const p50 = parseFloat(prompt("P50 (base) value:", "1.0"));
  if (isNaN(p50)) return;
  SENS_PARAMS.push({
    key,
    label: name,
    unit: "",
    p10: +(p50 * 0.7).toFixed(3),
    p50,
    p90: +(p50 * 1.3).toFixed(3),
    voiKey: "",
    inverse: false,
    custom: true,
  });
  updateSensAll();
}

// ── TAB 1: TORNADO ────────────────────────────────────────────
function renderTornado() {
  const canvas = document.getElementById("sens-tornado-canvas");
  if (!canvas) return;
  if (typeof Chart === "undefined") return;

  const metric =
    document.getElementById("sens-tornado-metric")?.value || "stoiip";
  const base =
    metric === "stoiip"
      ? calcSTOIIP_sens({}).stoiip
      : metric === "eur"
        ? calcSTOIIP_sens({}).eur
        : calcNPV_sens(calcSTOIIP_sens({}).stoiip);
  if (!base) return;

  const sensData = SENS_PARAMS.map((p) => {
    const lo =
      metric === "stoiip"
        ? calcSTOIIP_sens({ [p.key]: p.p10 }).stoiip
        : metric === "eur"
          ? calcSTOIIP_sens({ [p.key]: p.p10 }).eur
          : calcNPV_sens(calcSTOIIP_sens({ [p.key]: p.p10 }).stoiip);
    const hi =
      metric === "stoiip"
        ? calcSTOIIP_sens({ [p.key]: p.p90 }).stoiip
        : metric === "eur"
          ? calcSTOIIP_sens({ [p.key]: p.p90 }).eur
          : calcNPV_sens(calcSTOIIP_sens({ [p.key]: p.p90 }).stoiip);
    return { label: p.label, lo, hi, swing: Math.abs(hi - lo) };
  }).sort((a, b) => b.swing - a.swing);

  const labels = sensData.map((d) => d.label);
  const loDeltas = sensData.map((d) => Math.round(d.lo - base));
  const hiDeltas = sensData.map((d) => Math.round(d.hi - base));
  const unit = metric === "npv" ? "$M" : "MMbbl";

  if (window._tornadoChart) {
    try {
      window._tornadoChart.destroy();
    } catch (e) {}
  }
  window._tornadoChart = new Chart(canvas, {
    type: "bar",
    data: {
      labels,
      datasets: [
        {
          label: `Low Case (P10)`,
          data: loDeltas,
          backgroundColor: "rgba(198,40,40,.7)",
          borderColor: "#C62828",
          borderWidth: 1,
          borderRadius: 3,
          barPercentage: 0.65,
        },
        {
          label: `High Case (P90)`,
          data: hiDeltas,
          backgroundColor: "rgba(26,127,90,.7)",
          borderColor: "#1A7F5A",
          borderWidth: 1,
          borderRadius: 3,
          barPercentage: 0.65,
        },
      ],
    },
    options: {
      indexAxis: "y",
      responsive: true,
      maintainAspectRatio: false,
      plugins: {
        legend: {
          position: "top",
          labels: { font: { size: 9 }, boxWidth: 12, padding: 8 },
        },
        tooltip: {
          backgroundColor: "rgba(26,29,46,.95)",
          padding: 12,
          cornerRadius: 8,
          callbacks: {
            title: (items) => items[0].label,
            label: (item) => {
              const d = sensData[item.dataIndex];
              const isLo = item.datasetIndex === 0;
              const val = isLo ? d.lo : d.hi;
              const delta = isLo
                ? loDeltas[item.dataIndex]
                : hiDeltas[item.dataIndex];
              return `  ${isLo ? "Low (P10)" : "High (P90)"}: ${Math.round(val).toLocaleString()} ${unit}  (Δ ${delta > 0 ? "+" : ""}${delta.toLocaleString()})`;
            },
            afterBody: (items) => {
              const d = sensData[items[0].dataIndex];
              return [
                "",
                `  Base (P50): ${Math.round(base).toLocaleString()} ${unit}`,
                `  Total swing: ${Math.round(d.swing).toLocaleString()} ${unit}`,
              ];
            },
          },
        },
      },
      scales: {
        x: {
          title: {
            display: true,
            text: `Δ from P50 Base (${unit})`,
            font: { size: 10, weight: "bold" },
            color: "#4A5568",
          },
          ticks: {
            font: { size: 9 },
            color: "#8896A5",
            callback: (v) => (v > 0 ? "+" : "") + v.toLocaleString(),
          },
          grid: { color: "rgba(0,0,0,.06)" },
        },
        y: {
          ticks: { font: { size: 10, weight: "bold" }, color: "#2D3748" },
          grid: { display: false },
        },
      },
      animation: { duration: 400 },
    },
  });
}

// ── TAB 2: SPIDER ─────────────────────────────────────────────
function renderSpider() {
  const canvas = document.getElementById("sens-spider-canvas");
  if (!canvas) return;
  if (typeof Chart === "undefined") return;

  const base = calcSTOIIP_sens({}).stoiip;
  if (!base) return;

  // For each parameter sweep −30%→+30% relative to P50, compute STOIIP % of base
  const steps = 7;
  const xLabels = [
    "-30%",
    "-20%",
    "-10%",
    "Base",
    "+10%",
    "+20%",
    "+30%",
  ];
  const colors = [
    "#C62828",
    "#C07800",
    "#0D4C92",
    "#1A7F5A",
    "#7C3AED",
    "#0891B2",
  ];

  const datasets = SENS_PARAMS.map((p, i) => {
    const data = xLabels.map((_, si) => {
      const pct = (si - 3) / 10; // −0.3 → +0.3
      const val = p.inverse ? p.p50 * (1 - pct) : p.p50 * (1 + pct);
      const stoi = calcSTOIIP_sens({ [p.key]: val }).stoiip;
      return +((stoi / base) * 100).toFixed(1);
    });
    return {
      label: p.label,
      data,
      borderColor: colors[i % colors.length],
      backgroundColor: "transparent",
      borderWidth: 2,
      pointRadius: 4,
      pointBackgroundColor: colors[i % colors.length],
      pointBorderColor: "#fff",
      pointBorderWidth: 1.5,
      pointHoverRadius: 7,
      tension: 0.25,
    };
  });

  if (window._spiderChart) {
    try {
      window._spiderChart.destroy();
    } catch (e) {}
  }
  window._spiderChart = new Chart(canvas, {
    type: "line",
    data: { labels: xLabels, datasets },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      interaction: { mode: "index", intersect: false },
      plugins: {
        legend: {
          position: "top",
          labels: { font: { size: 9 }, boxWidth: 14, padding: 8 },
        },
        tooltip: {
          backgroundColor: "rgba(26,29,46,.95)",
          padding: 10,
          cornerRadius: 8,
          callbacks: {
            title: (items) => `Parameter variation: ${items[0].label}`,
            label: (item) => {
              const pct = (item.dataIndex - 3) * 10;
              const abs = Math.round((base * item.raw) / 100);
              return `  ${item.dataset.label}: ${item.raw}% of base  (${abs.toLocaleString()} MMbbl,  ${pct > 0 ? "+" : ""}${pct}%)`;
            },
          },
        },
      },
      scales: {
        y: {
          title: {
            display: true,
            text: "STOIIP as % of P50 Base",
            font: { size: 10, weight: "bold" },
            color: "#4A5568",
          },
          ticks: {
            font: { size: 9 },
            color: "#8896A5",
            callback: (v) => v + "%",
          },
          grid: {
            color: (ctx) =>
              ctx.tick.value === 100
                ? "rgba(13,76,146,.25)"
                : "rgba(0,0,0,.05)",
            lineWidth: (ctx) => (ctx.tick.value === 100 ? 2 : 1),
          },
        },
        x: {
          ticks: { font: { size: 10, weight: "bold" }, color: "#2D3748" },
          grid: { color: "rgba(0,0,0,.04)" },
        },
      },
      animation: { duration: 400 },
    },
  });

  // Elasticity ranking
  const elBody = document.getElementById("sens-elasticity-body");
  if (elBody) {
    const elast = SENS_PARAMS.map((p) => {
      const hiVal = p.inverse ? p.p50 * 0.7 : p.p50 * 1.3;
      const loVal = p.inverse ? p.p50 * 1.3 : p.p50 * 0.7;
      const hiS = calcSTOIIP_sens({ [p.key]: hiVal }).stoiip;
      const loS = calcSTOIIP_sens({ [p.key]: loVal }).stoiip;
      return { label: p.label, e: Math.abs(((hiS - loS) / base) * 100) };
    }).sort((a, b) => b.e - a.e);
    elBody.innerHTML = elast
      .map((e, i) => {
        const bar = Math.round((e.e / elast[0].e) * 90);
        const col = i === 0 ? "#C62828" : i === 1 ? "#C07800" : "#0D4C92";
        return `<div style="margin-bottom:8px">
  <div style="display:flex;justify-content:space-between;font-size:10px;margin-bottom:2px">
    <span style="font-weight:600;color:var(--t1)">${e.label}</span>
    <span style="color:${col};font-weight:700">${e.e.toFixed(1)}%</span>
  </div>
  <div style="height:5px;background:#E2E8F0;border-radius:3px">
    <div style="height:5px;width:${bar}%;background:${col};border-radius:3px"></div>
  </div>
</div>`;
      })
      .join("");
  }
}

// ── TAB 3: NPV vs PRICE ───────────────────────────────────────
function renderNPVvsPrice() {
  const canvas = document.getElementById("sens-npv-canvas");
  if (!canvas) return;
  if (typeof Chart === "undefined") return;

  const pLo = +(document.getElementById("sens-price-lo")?.value || 30);
  const pHi = +(document.getElementById("sens-price-hi")?.value || 130);
  const step = (pHi - pLo) / 20;
  const prices = Array.from({ length: 21 }, (_, i) =>
    Math.round(pLo + i * step),
  );

  const base = calcSTOIIP_sens({}).stoiip;
  const loAll = calcSTOIIP_sens(
    Object.fromEntries(SENS_PARAMS.map((p) => [p.key, p.p10])),
  ).stoiip;
  const hiAll = calcSTOIIP_sens(
    Object.fromEntries(SENS_PARAMS.map((p) => [p.key, p.p90])),
  ).stoiip;

  const npvBase = prices.map((pr) => calcNPV_sens(base, { price: pr }));
  const npvLo = prices.map((pr) => calcNPV_sens(loAll, { price: pr }));
  const npvHi = prices.map((pr) => calcNPV_sens(hiAll, { price: pr }));

  // Breakeven price (where base NPV crosses 0)
  let breakeven = null;
  for (let i = 1; i < npvBase.length; i++) {
    if (npvBase[i - 1] <= 0 && npvBase[i] > 0) {
      const frac = -npvBase[i - 1] / (npvBase[i] - npvBase[i - 1]);
      breakeven = +(
        prices[i - 1] +
        frac * (prices[i] - prices[i - 1])
      ).toFixed(1);
      break;
    }
  }

  // Live spot price line
  const livePrice = window._liveSpot?.brent;

  if (window._npvPriceChart) {
    try {
      window._npvPriceChart.destroy();
    } catch (e) {}
  }
  window._npvPriceChart = new Chart(canvas, {
    type: "line",
    data: {
      labels: prices.map((p) => "$" + p),
      datasets: [
        {
          label: "P90 High Case",
          data: npvHi,
          borderColor: "#1A7F5A",
          backgroundColor: "rgba(26,127,90,.06)",
          borderWidth: 2,
          fill: "+1",
          tension: 0.3,
          pointRadius: 0,
          pointHoverRadius: 5,
        },
        {
          label: "P50 Base Case",
          data: npvBase,
          borderColor: "#0D4C92",
          backgroundColor: "rgba(13,76,146,.08)",
          borderWidth: 3,
          fill: false,
          tension: 0.3,
          pointRadius: 0,
          pointHoverRadius: 6,
          borderDash: [],
        },
        {
          label: "P10 Low Case",
          data: npvLo,
          borderColor: "#C62828",
          backgroundColor: "rgba(198,40,40,.06)",
          borderWidth: 2,
          fill: "-1",
          tension: 0.3,
          pointRadius: 0,
          pointHoverRadius: 5,
        },
      ],
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      interaction: { mode: "index", intersect: false },
      plugins: {
        legend: {
          position: "top",
          labels: { font: { size: 9 }, boxWidth: 14, padding: 10 },
        },
        tooltip: {
          backgroundColor: "rgba(26,29,46,.95)",
          padding: 12,
          cornerRadius: 8,
          callbacks: {
            title: (items) => `Oil Price: ${items[0].label}/bbl`,
            label: (item) =>
              `  ${item.dataset.label}: $${item.raw.toLocaleString()}M NPV₁₀`,
          },
        },
        annotation: livePrice
          ? {
              annotations: {
                spotLine: {
                  type: "line",
                  xMin: "$" + Math.round(livePrice),
                  xMax: "$" + Math.round(livePrice),
                  borderColor: "#C07800",
                  borderWidth: 2,
                  borderDash: [5, 3],
                  label: {
                    display: true,
                    content: "Live Brent $" + livePrice.toFixed(0),
                    backgroundColor: "rgba(192,120,0,.85)",
                    font: { size: 9 },
                  },
                },
              },
            }
          : {},
      },
      scales: {
        x: {
          title: {
            display: true,
            text: "Oil / Gas Price ($/bbl)",
            font: { size: 10, weight: "bold" },
            color: "#4A5568",
          },
          ticks: {
            font: { size: 9 },
            color: "#8896A5",
            maxTicksLimit: 10,
          },
        },
        y: {
          title: {
            display: true,
            text: "NPV₁₀ ($M)",
            font: { size: 10, weight: "bold" },
            color: "#4A5568",
          },
          ticks: {
            font: { size: 9 },
            color: "#8896A5",
            callback: (v) => "$" + v.toLocaleString() + "M",
          },
          grid: {
            color: (ctx) =>
              ctx.tick.value === 0
                ? "rgba(198,40,40,.4)"
                : "rgba(0,0,0,.05)",
            lineWidth: (ctx) => (ctx.tick.value === 0 ? 2 : 1),
          },
        },
      },
      animation: { duration: 400 },
    },
  });

  // Breakeven panel
  const bb = document.getElementById("sens-breakeven-body");
  if (bb) {
    const currentPrice =
      livePrice || +(document.getElementById("econ-price")?.value || 75);
    const npvAtCurrent = calcNPV_sens(base, { price: currentPrice });
    bb.innerHTML = `
      <div style="margin-bottom:10px;padding:10px;background:rgba(26,127,90,.06);border-radius:8px;border-left:3px solid #1A7F5A">
        <div style="font-size:10px;color:var(--t3);margin-bottom:2px">Breakeven Price (P50 Base)</div>
        <div style="font-size:22px;font-weight:800;color:${breakeven ? "#1A7F5A" : "#C62828"}">${breakeven ? "$" + breakeven + "/bbl" : "Uneconomic"}</div>
      </div>
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:6px;margin-bottom:10px">
        <div style="padding:8px;background:#F8FAFC;border-radius:6px">
          <div style="font-size:10px;color:var(--t3)">Current Oil Price</div>
          <div style="font-size:14px;font-weight:700;color:${livePrice ? "#059669" : "#64748B"}">${livePrice ? "$" + livePrice.toFixed(2) : "$" + currentPrice}/bbl</div>
          <div style="font-size:10px;color:var(--t3)">${livePrice ? "Live Brent" : "Manual input"}</div>
        </div>
        <div style="padding:8px;background:#F8FAFC;border-radius:6px">
          <div style="font-size:10px;color:var(--t3)">NPV at Current Price</div>
          <div style="font-size:14px;font-weight:700;color:${npvAtCurrent >= 0 ? "#1A7F5A" : "#C62828"}">${npvAtCurrent >= 0 ? "+" : ""}$${npvAtCurrent.toLocaleString()}M</div>
          <div style="font-size:10px;color:var(--t3)">${npvAtCurrent >= 0 ? "Viable" : "Sub-economic"}</div>
        </div>
      </div>
      <div style="font-size:10px;font-weight:700;color:var(--t2);margin-bottom:5px">NPV at Key Prices</div>
    ${[40, 50, 60, 70, 80, 90, 100, 120]
    .map((pr) => {
      const npv = calcNPV_sens(base, { price: pr });
      const col = npv >= 0 ? "#1A7F5A" : "#C62828";
      return `<div style="display:flex;justify-content:space-between;padding:4px 6px;border-bottom:1px solid #F1F5F9;font-size:10px">
      <span style="color:var(--t2)">$${pr}/bbl</span>
      <span style="font-weight:700;color:${col}">${npv >= 0 ? "+" : ""}$${npv.toLocaleString()}M</span>
    </div>`;
  })
  .join("")}`;
  }
}

