function fileGovAction(id, action) {
  const idx = INGESTED_FILES.findIndex((f) => f.id === id);
  if (idx < 0) return;
  const f = INGESTED_FILES[idx];
  if (action === "accept") {
    toast(
      `File "${f.name}" accepted — ${f.records} records now visible in application`,
      "success",
    );
    AUDIT_ENTRIES.unshift({
      time: now(),
      user: _userTag(),
      action: `File accepted: ${f.name} · ${f.records} ${f.datasetType} records published`,
      status: "ACCEPTED",
      type: "Governance",
    });
    // Data already loaded — mark as published
    f.status = "accepted";
  } else if (action === "reject") {
    toast(
      `File "${f.name}" rejected — data removed from queue`,
      "warning",
    );
    AUDIT_ENTRIES.unshift({
      time: now(),
      user: _userTag(),
      action: `File rejected: ${f.name} · ${f.records} records removed`,
      status: "REJECTED",
      type: "Governance",
    });
    // Remove data that was loaded
    if (f.datasetType === "Basin") {
      const toRemove = new Set(f.loadedNames || []);
      for (let i = BASINS.length - 1; i >= 0; i--) {
        if (toRemove.has(BASINS[i].name)) BASINS.splice(i, 1);
      }
      renderBasinTable(BASINS);
      renderTopBasins();
    } else if (f.datasetType === "Analogue") {
      const toRemove = new Set(f.loadedNames || []);
      for (let i = ANALOGUES.length - 1; i >= 0; i--) {
        if (toRemove.has(ANALOGUES[i].name)) ANALOGUES.splice(i, 1);
      }
    }
  } else if (action === "delete") {
    toast(`File "${f.name}" deleted from queue`, "info");
  }
  if (action !== "accept") INGESTED_FILES.splice(idx, 1);
  renderGovQueue();
  renderGovFilesPanel();
  renderAuditLog(AUDIT_ENTRIES);
  refreshPortfolioKPIs();
  if (action === "accept") renderPortfolioMapMarkers();
}

function govAction(id, action) {
  const msgs = {
    accept: `Record ${id} accepted and queued for publication`,
    merge: `Record ${id} merged with existing production record`,
    reject: `Record ${id} rejected and removed from queue`,
  };
  toast(msgs[action], action === "reject" ? "error" : "success");
  const idx = GOV_QUEUE.findIndex((r) => r.id === id);
  if (idx > -1) {
    GOV_QUEUE.splice(idx, 1);
    renderGovQueue();
    AUDIT_ENTRIES.unshift({
      time: now(),
      user: _userTag(),
      action: `Governance: ${action.toUpperCase()} — ${id}`,
      status: action.toUpperCase(),
      type: "Governance",
    });
    renderAuditLog(AUDIT_ENTRIES);
    // Update queue count
    document.querySelector(".sb-notif span").textContent =
      `${GOV_QUEUE.length} record${GOV_QUEUE.length !== 1 ? "s" : ""} need review`;
    document.querySelector(".notif-count").textContent = GOV_QUEUE.length;
  }
}

