function pushVolToTC() {
  if (!_lastVolResult) {
    toast("Run a calculation first", "warning");
    return;
  }
  const v = _lastVolResult;
  // Set initial rate from recoverable / 20yr life / 365 days, with ramp
  const qi = Math.round(((v.recoverable * 1e6) / 20 / 365) * 1.8);
  const el = document.getElementById("tc-qi");
  if (el) el.value = qi;
  goTo("typecurves", null);
  setTimeout(() => renderTCCurve(), 200);
  toast(
    "Initial rate set to " + qi + " bbl/d from volumetrics",
    "success",
  );
}

// ── Store last vol result for the Results & Export panel ──
let _lastVolResult = null;
let _volAnalogueSource = null;

function renderVolResultsPanel() {
  const v = _lastVolResult;
  if (!v) return;

  const unit = v.unit;
  const hasMC = volMCResults && volMCResults.length > 0;
  const pct = (p) =>
    hasMC
      ? volMCResults[Math.floor((volMCResults.length * p) / 100)]
      : null;

  // Timestamp
  const ts = document.getElementById("vol-res-timestamp");
  if (ts) ts.textContent = "Calculated: " + new Date().toLocaleString();

  // ── KPIs ──
  const kpis = document.getElementById("vol-res-kpis");
  if (kpis) {
    const p10 = hasMC ? pct(10) : v.inPlace * 0.37;
    const p50 = hasMC ? pct(50) : v.inPlace;
    const p90 = hasMC ? pct(90) : v.inPlace * 2.38;
    const mean = hasMC
      ? volMCResults.reduce((s, x) => s + x, 0) / volMCResults.length
      : v.inPlace;
    kpis.innerHTML = [
      [
        "In-Place (" + (volType === "oil" ? "STOIIP" : "GIIP") + ")",
        v.inPlace.toFixed(1),
        unit,
        "var(--purple)",
      ],
      ["P90 (Low Case)", p10.toFixed(1), unit, "var(--red)"],
      ["P50 (Base Case)", p50.toFixed(1), unit, "var(--amber)"],
      ["P10 (High Case)", p90.toFixed(1), unit, "var(--green)"],
      [
        "Recoverable (EUR)",
        v.recoverable.toFixed(1),
        unit,
        "var(--cyan)",
      ],
    ]
      .map(
        ([lbl, val, u, col]) =>
          `<div class="kpi" style="text-align:center;border-left:3px solid ${col}">
            <div class="kpi-lbl">${lbl}</div>
            <div class="kpi-val" style="color:${col}">${val}</div>
            <div class="kpi-sub">${u}${hasMC ? " (MC)" : ""}</div>
          </div>`,
      )
      .join("");
  }

  // ── Summary body ──
  const body = document.getElementById("vol-summary-body");
  if (body) {
    const p = v.inputs;
    const p10 = hasMC ? pct(10) : v.inPlace * 0.37;
    const p50 = hasMC ? pct(50) : v.inPlace;
    const p90 = hasMC ? pct(90) : v.inPlace * 2.38;
    body.innerHTML = `
<div style="padding: 12px 12px 14px">
  <div style="font-size:10px;text-transform:uppercase;letter-spacing:1px;color:var(--t3);margin-bottom:2px">Calculation Method</div>
  <span class="badge ${hasMC ? "be" : "bg"}">${hasMC ? "Monte Carlo (" + volMCResults.length.toLocaleString() + " iterations)" : "Deterministic"}</span>
  <span class="badge bg">${volType === "oil" ? "Oil (STOIIP)" : "Gas (GIIP)"}</span>
  ${v.analogueSource ? '<span class="badge bc">Analogue-loaded: ' + v.analogueSource + "</span>" : ""}
</div>

<table>
  <thead><tr><th>Parameter</th><th>Value</th><th>Unit</th></tr></thead>
  <tbody>
    <tr><td>Gross Rock Volume (GRV)</td><td style="font-weight:700">${p.grv.toFixed(0)}</td><td>10⁶ m³</td></tr>
    <tr><td>Net-to-Gross (NTG)</td><td style="font-weight:700">${(p.ntg * 100).toFixed(1)}%</td><td>fraction</td></tr>
    <tr><td>Porosity (φ)</td><td style="font-weight:700">${(p.por * 100).toFixed(1)}%</td><td>fraction</td></tr>
    <tr><td>Water Saturation (Sw)</td><td style="font-weight:700">${(p.sw * 100).toFixed(1)}%</td><td>fraction</td></tr>
    <tr><td>Formation Volume Factor</td><td style="font-weight:700">${p.fvf.toFixed(3)}</td><td>${volType === "oil" ? "Bo (rb/stb)" : "Bg (rcf/scf)"}</td></tr>
    <tr><td>Recovery Factor (RF)</td><td style="font-weight:700">${(p.rf * 100).toFixed(1)}%</td><td>fraction</td></tr>
  </tbody>
</table>

<div style="margin: 14px 12px 12px; background:linear-gradient(135deg,rgba(124,58,237,.04),rgba(0,229,160,.04));border:1px solid rgba(124,58,237,.15);border-radius:8px">
  <div style="font-size:10px;text-transform:uppercase;letter-spacing:1px;color:var(--purple);padding: 12px;font-weight:600">Resource Estimates</div>
  <table>
    <thead><tr><th>Case</th><th>${volType === "oil" ? "STOIIP" : "GIIP"} (${unit})</th><th>Recoverable (${unit})</th><th>Source</th></tr></thead>
    <tbody>
      <tr style="background:rgba(217,48,37,.03)"><td style="font-weight:700;color:var(--red)">P90 (Low)</td><td>${p10.toFixed(1)}</td><td>${(p10 * p.rf).toFixed(1)}</td><td>${hasMC ? "MC" : "Scalar ×0.37"}</td></tr>
      <tr style="background:rgba(13,76,146,.03)"><td style="font-weight:700;color:var(--purple)">P50 (Base)</td><td>${p50.toFixed(1)}</td><td>${(p50 * p.rf).toFixed(1)}</td><td>${hasMC ? "MC" : "Deterministic"}</td></tr>
      <tr style="background:rgba(0,229,160,.03)"><td style="font-weight:700;color:var(--green)">P10 (High)</td><td>${p90.toFixed(1)}</td><td>${(p90 * p.rf).toFixed(1)}</td><td>${hasMC ? "MC" : "Scalar ×2.38"}</td></tr>
      <tr style="background:rgba(8,145,178,.03)"><td style="font-weight:700;color:var(--cyan)">Mean</td><td>${(hasMC ? volMCResults.reduce((s, x) => s + x, 0) / volMCResults.length : v.inPlace).toFixed(1)}</td><td>${((hasMC ? volMCResults.reduce((s, x) => s + x, 0) / volMCResults.length : v.inPlace) * p.rf).toFixed(1)}</td><td>${hasMC ? "MC" : "Deterministic"}</td></tr>
    </tbody>
  </table>
</div>`;
  }

  // ── Sensitivity table ──
  const sens = document.getElementById("vol-res-sensitivity");
  if (sens) {
    const p = v.inputs;
    const base = v.recoverable;
    // Compute ±20% impact on each parameter
    const params = [
      { name: "GRV", key: "grv", pctRange: 30 },
      { name: "NTG", key: "ntg", pctRange: 25 },
      { name: "Porosity (φ)", key: "por", pctRange: 20 },
      {
        name: "Water Saturation (Sw)",
        key: "sw",
        pctRange: 15,
        invert: true,
      },
      { name: "Recovery Factor (RF)", key: "rf", pctRange: 20 },
      { name: "FVF (Bo/Bg)", key: "fvf", pctRange: 10, invert: true },
    ];
    sens.innerHTML = `<table><thead><tr><th>Parameter</th><th>Base Value</th><th>Range (±)</th><th>Low Case</th><th>High Case</th><th>Δ Impact</th><th>Tornado</th></tr></thead><tbody>
      ${params
        .map((dim) => {
          const lo = { ...p },
            hi = { ...p };
          lo[dim.key] = p[dim.key] * (1 - dim.pctRange / 100);
          hi[dim.key] = p[dim.key] * (1 + dim.pctRange / 100);
          const rLo = calcSTOIIP(lo).recoverable;
          const rHi = calcSTOIIP(hi).recoverable;
          const delta = Math.abs(rHi - rLo);
          const maxDelta = base * 1.5; // for bar scaling
          const barLo = Math.min(rLo, rHi),
            barHi = Math.max(rLo, rHi);
          const leftPct = Math.max(0, (barLo / maxDelta) * 50);
          const widthPct = Math.max(2, ((barHi - barLo) / maxDelta) * 50);
          return `<tr>
          <td style="font-weight:600">${dim.name}</td>
          <td>${typeof p[dim.key] === "number" && p[dim.key] < 1 ? (p[dim.key] * 100).toFixed(1) + "%" : p[dim.key].toFixed(1)}</td>
          <td>±${dim.pctRange}%</td>
          <td style="color:var(--red)">${rLo.toFixed(1)}</td>
          <td style="color:var(--green)">${rHi.toFixed(1)}</td>
          <td style="font-weight:700;color:var(--purple)">${delta.toFixed(1)} ${v.unit}</td>
          <td style="width:120px">
            <div style="position:relative;height:12px;background:#E8ECF5;border-radius:3px">
              <div style="position:absolute;left:0;width:${widthPct}%;height:100%;background:linear-gradient(90deg,var(--red),var(--green));border-radius:3px;opacity:.6">
              </div>
            </div>
          </td>
        </tr>`;
        })
        .join("")}
      </tbody></table>
    `;
  }
}

