// ── Tab switching ──────────────────────────────────────────────
function switchEconTab(tab, el) {
  ["dcf", "sensitivity", "compare", "pricedeck"].forEach((t) => {
    const p = document.getElementById("econ-" + t + "-panel");
    if (p) p.style.display = t === tab ? "block" : "none";
  });

  // Highlight active tab
  if (el) {
    el.parentElement
      .querySelectorAll(".tab")
      .forEach((t) => t.classList.remove("on"));
    el.classList.add("on");
  }

  // ✅ Update breadcrumb
  const bc = document.getElementById("breadcrumb-section");
  if (bc) bc.textContent = el?.textContent.trim() || "";

  // Tab-specific functions
  if (tab === "sensitivity" && econLastResult) {
    drawEconTornado();
    drawEconNPVvsPrice();
    updateBreakevenPanel();
  }
  if (tab === "compare") {
    renderEconComparisons();
  }
  if (tab === "pricedeck") {
    drawPriceDeckMain();
    renderFiscalTable();
    drawPriceDeckNPV();
    setActiveDeck(activeDeckKey);
  }
}

// ── Load from database ─────────────────────────────────────────
function loadEconFromDatabase(key) {
  if (!key) return;
  const d = ECON_DB[key];
  if (!d) return;
  const fields = [
    "volume",
    "price",
    "rf",
    "capex",
    "opex",
    "discount",
    "royalty",
    "tax",
    "years",
    "decline",
    "buildup",
    "plateau",
    "govtake",
    "abandon",
    "sustcapex",
  ];
  fields.forEach((f) => {
    const el = document.getElementById("econ-" + f);
    if (el) el.value = d[f] !== undefined ? d[f] : "";
  });
  const hct = document.getElementById("econ-hctype");
  if (hct && d.hctype) hct.value = d.hctype;
  // Show badge
  const badge = document.getElementById("econ-db-badge");
  const src = document.getElementById("econ-db-source");
  if (badge && src) {
    badge.style.display = "flex";
    src.textContent = key.split(":")[1];
  }
  econCurrentSource = key;
  toast(
    "Loaded economic parameters from: " + key.split(":")[1],
    "success",
  );
  if (econAutoRun) runEconDCF();
}

