// ── Core DCF Engine ────────────────────────────────────────────
function calcDCF(params) {
  const {
    vol,
    price,
    rf,
    capex,
    opex,
    disc,
    royalty,
    tax,
    years,
    decline,
    buildup,
    plateau,
    govtake,
    abandon,
    sustcapex,
  } = params;
  const recoverable = (vol * rf) / 100;

  // Production profile with build-up → plateau → decline
  const prod = [];
  let q = plateau; // kboe/d plateau
  let annualPlateauTarget = plateau * 365; // kboe/yr → MMboe/yr (dividing by 1000 not needed; units consistent)
  // We'll just work in MMboe
  const plateauAnnual = (plateau * 365) / 1000; // MMboe/yr

  for (let y = 0; y < years; y++) {
    let annual;
    if (y < buildup) {
      // Linear build-up
      annual = (plateauAnnual * (y + 1)) / buildup;
    } else {
      // Decline from plateau year
      const declineYr = y - buildup;
      annual = plateauAnnual * Math.pow(1 - decline / 100, declineYr);
    }
    annual = Math.min(
      annual,
      recoverable - prod.reduce((a, b) => a + b, 0),
    );
    if (annual <= 0.01) {
      prod.push(0.01);
      break;
    }
    prod.push(annual);
  }

  // Cashflow model
  const cashflows = [];
  let cumCF = -capex,
    npv = -capex,
    payback = null;
  let totalRev = 0,
    totalGovTake = 0;
  cashflows.push({
    year: 0,
    production: 0,
    revenue: 0,
    opexY: 0,
    royaltyY: 0,
    taxY: 0,
    govY: 0,
    netCF: -capex,
    cumCF: -capex,
    discCF: -capex,
  });

  for (let y = 0; y < prod.length; y++) {
    const annProd = prod[y]; // MMboe
    const rev = annProd * 1000 * price; // $M  (1 MMboe * 1000 = kboe; * price/boe)
    // Actually: 1 MMboe = 1,000,000 boe. price in $/boe. Revenue = prod_MMboe * 1e6 * price / 1e6 = prod * price (in $M if prod in MMboe)
    const revM = annProd * price; // $M
    const royY = (revM * royalty) / 100;
    const opY = annProd * opex; // opex $/boe * MMboe → $M
    const sustY = sustcapex;
    const taxable = Math.max(0, revM - royY - opY - sustY);
    const taxY = (taxable * tax) / 100;
    const govY = royY + taxY;
    const netCF = revM - royY - opY - sustY - taxY;
    cumCF += netCF;
    totalRev += revM;
    totalGovTake += govY;
    const discFactor = 1 / Math.pow(1 + disc / 100, y + 1);
    npv += netCF * discFactor;
    if (payback === null && cumCF >= 0) payback = y + 1;
    cashflows.push({
      year: y + 1,
      production: annProd,
      revenue: revM,
      opexY: opY,
      royaltyY: royY,
      taxY,
      govY,
      netCF,
      cumCF,
      discCF: netCF * discFactor,
    });
  }
  // Abandonment in final year
  if (cashflows.length > 1) {
    const last = cashflows[cashflows.length - 1];
    const discFactor = 1 / Math.pow(1 + disc / 100, last.year);
    last.netCF -= abandon;
    last.cumCF -= abandon;
    last.discCF -= abandon * discFactor;
    npv -= abandon * discFactor;
    cumCF -= abandon;
  }

  const pi = (npv + capex) / capex;

  // IRR (Newton's method)
  let irr = disc / 100;
  for (let iter = 0; iter < 80; iter++) {
    let fv = 0,
      dfv = 0;
    cashflows.forEach((cf) => {
      const df = Math.pow(1 + irr, cf.year);
      fv += cf.netCF / df;
      dfv -= (cf.year * cf.netCF) / Math.pow(1 + irr, cf.year + 1);
    });
    if (Math.abs(dfv) < 1e-12) break;
    irr -= fv / dfv;
    if (irr < -0.99) {
      irr = -0.99;
      break;
    }
    if (irr > 10) {
      irr = 10;
      break;
    }
  }

  // Breakeven price
  let be = price;
  for (let iter = 0; iter < 60; iter++) {
    const p2 = { ...params, price: be };
    const npv2 = calcNPVonly(p2, cashflows.length - 1);
    if (Math.abs(npv2) < 0.5) break;
    be -= npv2 / (recoverable * 0.5);
    if (be < 0) {
      be = 0;
      break;
    }
  }

  const emv = npv * 0.65; // simplified risked EMV using 65% GCoS assumption

  return {
    npv,
    irr: irr * 100,
    pi,
    payback,
    cashflows,
    totalRev,
    totalGovTake,
    breakeven: Math.max(0, be),
    emv,
    recoverable,
  };
}

function calcNPVonly(params, years) {
  const {
    vol,
    price,
    rf,
    capex,
    opex,
    disc,
    royalty,
    tax,
    decline,
    buildup,
    plateau,
    sustcapex,
  } = params;
  const recoverable = (vol * rf) / 100;
  const plateauAnnual = (plateau * 365) / 1000;
  let npv = -capex;
  let cumProd = 0;
  for (let y = 0; y < years; y++) {
    let annual =
      y < buildup
        ? (plateauAnnual * (y + 1)) / buildup
        : plateauAnnual * Math.pow(1 - decline / 100, y - buildup);
    annual = Math.min(annual, recoverable - cumProd);
    if (annual <= 0) break;
    cumProd += annual;
    const revM = annual * price;
    const royY = (revM * royalty) / 100;
    const opY = annual * opex;
    const taxY = (Math.max(0, revM - royY - opY - sustcapex) * tax) / 100;
    const netCF = revM - royY - opY - sustcapex - taxY;
    npv += netCF / Math.pow(1 + disc / 100, y + 1);
  }
  return npv;
}

function getEconParams() {
  const g = (k) =>
    parseFloat(document.getElementById("econ-" + k)?.value) || 0;
  return {
    vol: g("volume"),
    price: g("price"),
    rf: g("rf"),
    capex: g("capex"),
    opex: g("opex"),
    disc: g("discount"),
    royalty: g("royalty"),
    tax: g("tax"),
    years: g("years"),
    decline: g("decline"),
    buildup: g("buildup"),
    plateau: g("plateau"),
    govtake: g("govtake"),
    abandon: g("abandon"),
    sustcapex: g("sustcapex"),
  };
}

function runEconDCF() {
  econAutoRun = true;
  const params = getEconParams();
  const res = calcDCF(params);
  econLastResult = { params, ...res };

  // KPI row 1
  const nc = res.npv >= 0 ? "var(--green)" : "var(--red)";
  document.getElementById("econ-kpis").innerHTML = `
<div class="kpi e" style="text-align:center"><div class="kpi-lbl">NPV₁₀</div><div class="kpi-val">${res.npv >= 0 ? "+" : ""}${Math.round(res.npv).toLocaleString()}</div><div class="kpi-sub">$M</div></div>
<div class="kpi g" style="text-align:center"><div class="kpi-lbl">IRR</div><div class="kpi-val">${res.irr.toFixed(1)}%</div><div class="kpi-sub">vs ${params.disc}% hurdle</div></div>
<div class="kpi c" style="text-align:center"><div class="kpi-lbl">Payback</div><div class="kpi-val">${res.payback || "—"}</div><div class="kpi-sub">${res.payback ? "years" : "N/A"}</div></div>
<div class="kpi r" style="text-align:center"><div class="kpi-lbl">PI</div><div class="kpi-val">${res.pi.toFixed(2)}</div><div class="kpi-sub">ratio</div></div>`;

  // KPI row 2
  const beColor =
    res.breakeven > params.price * 0.85
      ? "var(--red)"
      : res.breakeven > params.price * 0.65
        ? "var(--amber)"
        : "var(--green)";
  document.getElementById("econ-kpis2").innerHTML = `
<div class="kpi c" style="text-align:center"><div class="kpi-lbl">EMV (Risked)</div><div class="kpi-val" style="font-size:18px;">${res.emv >= 0 ? "+" : ""}${Math.round(res.emv).toLocaleString()}</div><div class="kpi-sub">$M · 65% GCoS</div></div>
<div class="kpi g" style="text-align:center"><div class="kpi-lbl">Breakeven</div><div class="kpi-val" style="font-size:18px;">$${res.breakeven.toFixed(0)}</div><div class="kpi-sub">/bbl (oil equiv.)</div></div>
<div class="kpi e" style="text-align:center"><div class="kpi-lbl">Total Revenue</div><div class="kpi-val" style="font-size:18px;">${(res.totalRev / 1000).toFixed(1)}B</div><div class="kpi-sub">$M (undiscounted)</div></div>
<div class="kpi r" style="text-align:center"><div class="kpi-lbl">Gov't Take</div><div class="kpi-val" style="font-size:18px;">${(res.totalGovTake / 1000).toFixed(1)}B</div><div class="kpi-sub">$M royalty + tax</div></div>`;

  document.getElementById("econ-cf-empty").style.display = "none";
  document.getElementById("econ-prod-empty").style.display = "none";
  drawEconCF(res.cashflows, params);
  drawEconProd(res.cashflows, params);
  addNotification(
    "DCF analysis: NPV₁₀ = $" +
      Math.round(res.npv).toLocaleString() +
      "M · IRR = " +
      res.irr.toFixed(1) +
      "% · Breakeven $" +
      res.breakeven.toFixed(0) +
      "/bbl",
    res.npv > 0 ? "success" : "warning",
  );
}

function saveEconScenario() {
  if (!econLastResult) {
    toast("Run DCF analysis first", "warning");
    return;
  }
  const source = econCurrentSource
    ? " (" + econCurrentSource.split(":")[1] + ")"
    : "";
  const name = "Scenario " + (econScenarios.length + 1) + source;
  econScenarios.push({ name, ...econLastResult });
  toast(
    "Saved: " + name + " — switch to Scenario Comparison tab",
    "success",
  );
}

//  Cash Flow Chart 
function drawEconCF(cfs, params) {
  const canvas = document.getElementById("econ-cf-canvas");
  if (!canvas) return;
  const ctx = canvas.getContext("2d");
  const DPR = window.devicePixelRatio || 1;
  const W   = canvas.parentElement.clientWidth;
  const H   = 300;
  canvas.width  = W * DPR;
  canvas.height = H * DPR;
  canvas.style.width  = W + "px";
  canvas.style.height = H + "px";
  ctx.scale(DPR, DPR);

  //  Layout margins 
  const ML = 64, MR = 20, MT = 48, MB = 36;
  const PW = W - ML - MR, PH = H - MT - MB;

  //  Background 
  ctx.fillStyle = window.edafyCanvasBgColor ? window.edafyCanvasBgColor() : "#FFFFFF";
  ctx.fillRect(0, 0, W, H);

  //  Title + legend 
  ctx.fillStyle = window.edafyChartColors ? window.edafyChartColors().tickBold : "#1E293B";
  ctx.font = "bold 11px Arial";
  ctx.textAlign = "left";
  ctx.fillText("CASH FLOW PROFILE", ML, 20);

  // Legend items
  const legend = [
    { color: "rgba(74,185,143,0.55)", border: "#1A7F5A", type: "rect", label: "Net CF" },
    { color: "rgba(232,100,100,0.45)", border: "#C62828", type: "rect", label: "Negative CF" },
    { color: "#0D4C92", type: "line", label: "Cumulative" },
  ];
  let lx = W - MR;
  ctx.font = "9px Arial";
  [...legend].reverse().forEach(l => {
    const tw = ctx.measureText(l.label).width;
    lx -= tw + 6;
    ctx.fillStyle = window.edafyChartColors ? window.edafyChartColors().tickBold : "#475569";
    ctx.fillText(l.label, lx, 20);
    lx -= 24;
    if (l.type === "rect") {
      ctx.fillStyle = l.color;
      ctx.strokeStyle = l.border;
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.roundRect ? ctx.roundRect(lx, 11, 18, 9, 2) : (() => { ctx.rect(lx, 11, 18, 9); })();
      ctx.fill(); ctx.stroke();
    } else {
      ctx.strokeStyle = l.color;
      ctx.lineWidth = 2.5;
      ctx.beginPath();
      ctx.moveTo(lx, 15); ctx.lineTo(lx + 18, 15);
      ctx.stroke();
    }
    lx -= 8;
  });

  //  Value range 
  const netVals = cfs.map(c => c.netCF);
  const cumVals = cfs.map(c => c.cumCF);
  const allV    = [...netVals, ...cumVals];
  const rawMin  = Math.min(...allV);
  const rawMax  = Math.max(...allV);
  // Pad 8% each side
  const pad  = (rawMax - rawMin) * 0.08 || 50;
  const minV = rawMin - pad;
  const maxV = rawMax + pad;
  const range = maxV - minV;
  const yS = v => MT + PH - ((v - minV) / range) * PH;
  const y0 = yS(0);

  //  Format Y label 
  const fmtY = v => {
    const abs = Math.abs(v);
    if (abs >= 1e9) return (v/1e9).toFixed(1) + "B";
    if (abs >= 1e6) return (v/1e6).toFixed(1) + "B";  // values are already $M
    if (abs >= 1000) return (v/1000).toFixed(1) + "B";
    return v.toFixed(0);
  };
  // Better: values are in $M, so 1000 = 1B
  const fmtYM = v => {
    const abs = Math.abs(v);
    if (abs >= 1000) return (v/1000).toFixed(1) + "B";
    return v.toFixed(0);
  };

  //  Grid lines 
  const GRID_STEPS = 6;
  ctx.font = "8px Arial";
  ctx.textAlign = "right";
  for (let i = 0; i <= GRID_STEPS; i++) {
    const val = minV + (i / GRID_STEPS) * range;
    const yg  = yS(val);
    ctx.beginPath();
    ctx.moveTo(ML, yg); ctx.lineTo(ML + PW, yg);
    ctx.strokeStyle = "rgba(226,232,240,0.85)";
    ctx.lineWidth = 1;
    ctx.setLineDash([]);
    ctx.stroke();
    ctx.fillStyle = window.edafyChartColors ? window.edafyChartColors().tick : "#94A3B8";
    ctx.fillText(fmtYM(val), ML - 6, yg + 3);
  }

  // Y-axis label "$M"
  ctx.save();
  ctx.translate(14, MT + PH / 2);
  ctx.rotate(-Math.PI / 2);
  ctx.fillStyle = window.edafyChartColors ? window.edafyChartColors().tick : "#94A3B8";
  ctx.font = "bold 8px Arial";
  ctx.textAlign = "center";
  ctx.fillText("$M", 0, 0);
  ctx.restore();

  //  Zero line 
  ctx.beginPath();
  ctx.moveTo(ML, y0); ctx.lineTo(ML + PW, y0);
  ctx.strokeStyle = "rgba(148,163,184,0.6)";
  ctx.lineWidth = 1.2;
  ctx.setLineDash([]);
  ctx.stroke();

  //  Bars 
  const N  = cfs.length;
  const bw = Math.max(4, (PW / N) * 0.55);
  cfs.forEach((cf, i) => {
    const cx  = ML + (i + 0.5) / N * PW;
    const bx  = cx - bw / 2;
    const isNeg = cf.netCF < 0;
    const barH = Math.abs(cf.netCF) / range * PH;
    const by   = isNeg ? y0 : yS(cf.netCF);
    ctx.fillStyle   = isNeg ? "rgba(220,80,80,0.38)"   : "rgba(74,185,143,0.50)";
    ctx.strokeStyle = isNeg ? "rgba(198,40,40,0.65)"   : "rgba(26,127,90,0.70)";
    ctx.lineWidth   = 0.8;
    ctx.beginPath();
    const r2 = Math.min(3, bw / 4);
    if (ctx.roundRect) {
      ctx.roundRect(bx, by, bw, barH, isNeg ? [0,0,r2,r2] : [r2,r2,0,0]);
    } else {
      ctx.rect(bx, by, bw, barH);
    }
    ctx.fill();
    ctx.stroke();
  });

  //  Payback marker 
  const pb = params?.payback || econLastResult?.payback;
  if (pb && pb > 0 && pb <= N) {
    const xpb = ML + (pb - 0.5) / N * PW;
    ctx.beginPath();
    ctx.moveTo(xpb, MT); ctx.lineTo(xpb, MT + PH);
    ctx.strokeStyle = "rgba(192,120,0,0.75)";
    ctx.lineWidth = 1.5;
    ctx.setLineDash([5, 3]);
    ctx.stroke();
    ctx.setLineDash([]);
    // Label box
    ctx.fillStyle = "rgba(192,120,0,0.12)";
    ctx.strokeStyle = "rgba(192,120,0,0.4)";
    ctx.lineWidth = 1;
    const lbl = "Payback Y" + pb;
    ctx.font = "bold 8.5px Arial";
    const lw = ctx.measureText(lbl).width + 10;
    ctx.beginPath();
    ctx.roundRect ? ctx.roundRect(xpb + 4, MT + 2, lw, 16, 3) : ctx.rect(xpb+4, MT+2, lw, 16);
    ctx.fill(); ctx.stroke();
    ctx.fillStyle = "#C07800";
    ctx.textAlign = "left";
    ctx.fillText(lbl, xpb + 9, MT + 13);
  }

  //  Cumulative S-curve (smooth) 
  ctx.beginPath();
  ctx.strokeStyle = "#1E40AF";
  ctx.lineWidth = 2.8;
  ctx.setLineDash([]);
  // Use cardinal spline for smooth curve
  const pts = cfs.map((cf, i) => ({
    x: ML + (i + 0.5) / N * PW,
    y: yS(cf.cumCF)
  }));
  ctx.moveTo(pts[0].x, pts[0].y);
  for (let i = 0; i < pts.length - 1; i++) {
    const p0 = pts[Math.max(0, i - 1)];
    const p1 = pts[i];
    const p2 = pts[i + 1];
    const p3 = pts[Math.min(pts.length - 1, i + 2)];
    const tension = 0.4;
    const cp1x = p1.x + (p2.x - p0.x) * tension / 3;
    const cp1y = p1.y + (p2.y - p0.y) * tension / 3;
    const cp2x = p2.x - (p3.x - p1.x) * tension / 3;
    const cp2y = p2.y - (p3.y - p1.y) * tension / 3;
    ctx.bezierCurveTo(cp1x, cp1y, cp2x, cp2y, p2.x, p2.y);
  }
  ctx.stroke();

  //  X-axis year labels 
  ctx.fillStyle = window.edafyChartColors ? window.edafyChartColors().tick : "#64748B";
  ctx.font = "8px Arial";
  ctx.textAlign = "center";
  const step = Math.ceil(N / 14);
  cfs.forEach((cf, i) => {
    if (i % step === 0 || i === N - 1) {
      const x = ML + (i + 0.5) / N * PW;
      ctx.fillText("Y" + cf.year, x, H - MB + 14);
    }
  });

  //  Hover 
  canvas._cfs   = cfs;
  canvas._pts   = pts;
  canvas._mleft = ML;
  canvas._pw    = PW;
  canvas._n     = N;
  if (!canvas._bound) {
    canvas._bound = true;
    canvas.addEventListener("mousemove", e => {
      const rect = canvas.getBoundingClientRect();
      const scaleX = canvas.width / rect.width / DPR;
      const relX = (e.clientX - rect.left) * scaleX;
      const idx = Math.min(cfs.length-1, Math.max(0,
        Math.floor(((relX - canvas._mleft) / canvas._pw) * canvas._n)));
      const cf = canvas._cfs[idx];
      if (!cf) return;
      const tt = document.getElementById("econ-cf-tooltip");
      if (tt) {
        tt.style.display = "block";
        tt.style.left = (e.clientX - rect.left + 14) + "px";
        tt.style.top  = (e.clientY - rect.top  - 60) + "px";
        tt.innerHTML  = `<b>Year ${cf.year}</b><br>` +
          `Net CF: <b style="color:${cf.netCF>=0?"#6EE7B7":"#FCA5A5"}">${cf.netCF>=0?"+":""}${Math.round(cf.netCF).toLocaleString()} $M</b><br>` +
          `Cumulative: <b>${Math.round(cf.cumCF).toLocaleString()} $M</b><br>` +
          `Revenue: ${Math.round(cf.revenue||0).toLocaleString()} $M`;
      }
    });
    canvas.addEventListener("mouseleave", () => {
      const tt = document.getElementById("econ-cf-tooltip");
      if (tt) tt.style.display = "none";
    });
  }
}


//  Production & Revenue Profile Chart 
function drawEconProd(cfs, params) {
  const canvas = document.getElementById("econ-prod-canvas");
  if (!canvas) return;
  const ctx  = canvas.getContext("2d");
  const DPR  = window.devicePixelRatio || 1;
  const W    = canvas.parentElement.clientWidth;
  const H    = 220;
  canvas.width  = W * DPR;
  canvas.height = H * DPR;
  canvas.style.width  = W + "px";
  canvas.style.height = H + "px";
  ctx.scale(DPR, DPR);

  //  Margins 
  const ML = 62, MR = 68, MT = 44, MB = 32;
  const PW = W - ML - MR, PH = H - MT - MB;

  //  Background 
  ctx.fillStyle = window.edafyCanvasBgColor ? window.edafyCanvasBgColor() : "#FFFFFF";
  ctx.fillRect(0, 0, W, H);

  //  Data (skip year 0 = capex year) 
  const data  = cfs.filter(c => c.year >= 1);
  const N     = data.length;
  if (N === 0) return;

  const prodVals = data.map(c => c.production || 0);
  const revVals  = data.map(c => c.revenue   || 0);
  const opexVals = data.map(c => c.opexY     || 0);
  const maxP     = Math.max(...prodVals, 0.01);
  const maxR     = Math.max(...revVals,  0.01);

  //  Title + Legend 
  ctx.fillStyle = window.edafyChartColors ? window.edafyChartColors().tickBold : "#1E293B";
  ctx.font = "bold 10.5px Arial";
  ctx.textAlign = "left";
  ctx.fillText("PRODUCTION & REVENUE PROFILE", ML, 18);

  const legendItems = [
    { color: "rgba(13,76,146,0.18)", border: "#0D4C92",  type: "area",  label: "Production (MMboe/yr)" },
    { color: "#C07800",              border: "#C07800",   type: "line",  label: "Revenue ($M)"          },
    { color: "rgba(217,48,37,0.22)", border: "#D93025",  type: "area",  label: "OPEX ($M)"             },
  ];
  let lx = W - MR + 4;
  ctx.font = "8.5px Arial";
  [...legendItems].reverse().forEach(l => {
    const tw = ctx.measureText(l.label).width;
    lx -= (tw + 6);
    ctx.fillStyle = window.edafyChartColors ? window.edafyChartColors().tickBold : "#475569";
    ctx.textAlign = "left";
    ctx.fillText(l.label, lx, 18);
    lx -= 24;
    if (l.type === "line") {
      ctx.strokeStyle = l.color; ctx.lineWidth = 2;
      ctx.setLineDash([5, 3]);
      ctx.beginPath(); ctx.moveTo(lx, 13); ctx.lineTo(lx + 18, 13); ctx.stroke();
      ctx.setLineDash([]);
    } else {
      ctx.fillStyle = l.color;
      ctx.strokeStyle = l.border; ctx.lineWidth = 1;
      ctx.beginPath();
      if (ctx.roundRect) ctx.roundRect(lx, 8, 18, 9, 2);
      else ctx.rect(lx, 8, 18, 9);
      ctx.fill(); ctx.stroke();
    }
    lx -= 10;
  });

  //  Grid 
  const STEPS = 5;
  ctx.font = "7.5px Arial";
  for (let i = 0; i <= STEPS; i++) {
    const f  = i / STEPS;
    const yg = MT + f * PH;
    ctx.beginPath(); ctx.moveTo(ML, yg); ctx.lineTo(ML + PW, yg);
    ctx.strokeStyle = "rgba(226,232,240,0.9)"; ctx.lineWidth = 1;
    ctx.setLineDash([]); ctx.stroke();

    // Left axis: production (MMboe)
    const pVal = (1 - f) * maxP;
    ctx.fillStyle = "#0D4C92"; ctx.textAlign = "right";
    ctx.fillText(pVal >= 100 ? pVal.toFixed(0) : pVal.toFixed(1), ML - 5, yg + 3);

    // Right axis: revenue ($M)
    const rVal = (1 - f) * maxR;
    const rFmt = rVal >= 1000 ? "$" + (rVal/1000).toFixed(1) + "B" : "$" + rVal.toFixed(0) + "M";
    ctx.fillStyle = "#C07800"; ctx.textAlign = "left";
    ctx.fillText(rFmt, ML + PW + 5, yg + 3);
  }

  //  Y-axis labels 
  ctx.save();
  ctx.translate(11, MT + PH/2); ctx.rotate(-Math.PI/2);
  ctx.fillStyle = "#0D4C92"; ctx.font = "bold 8px Arial"; ctx.textAlign = "center";
  ctx.fillText("MMboe/yr", 0, 0);
  ctx.restore();

  ctx.save();
  ctx.translate(W - 10, MT + PH/2); ctx.rotate(Math.PI/2);
  ctx.fillStyle = "#C07800"; ctx.font = "bold 8px Arial"; ctx.textAlign = "center";
  ctx.fillText("Revenue ($M)", 0, 0);
  ctx.restore();

  //  OPEX area (behind everything) 
  ctx.beginPath();
  data.forEach((d, i) => {
    const x = ML + (i + 0.5) / N * PW;
    const y = MT + PH - (opexVals[i] / maxR) * PH;
    if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
  });
  ctx.lineTo(ML + (N - 0.5) / N * PW, MT + PH);
  ctx.lineTo(ML + 0.5 / N * PW, MT + PH);
  ctx.closePath();
  ctx.fillStyle = "rgba(217,48,37,0.12)"; ctx.fill();
  // OPEX border
  ctx.beginPath();
  data.forEach((d, i) => {
    const x = ML + (i + 0.5) / N * PW;
    const y = MT + PH - (opexVals[i] / maxR) * PH;
    if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
  });
  ctx.strokeStyle = "rgba(217,48,37,0.5)"; ctx.lineWidth = 1;
  ctx.setLineDash([3, 3]); ctx.stroke(); ctx.setLineDash([]);

  //  Production filled area 
  // Build smooth path points using catmull-rom
  const prodPts = data.map((d, i) => ({
    x: ML + (i + 0.5) / N * PW,
    y: MT + PH - (prodVals[i] / maxP) * PH
  }));

  // Fill
  ctx.beginPath();
  ctx.moveTo(prodPts[0].x, prodPts[0].y);
  for (let i = 0; i < prodPts.length - 1; i++) {
    const p0 = prodPts[Math.max(0, i-1)];
    const p1 = prodPts[i];
    const p2 = prodPts[i+1];
    const p3 = prodPts[Math.min(prodPts.length-1, i+2)];
    const t  = 0.35;
    ctx.bezierCurveTo(
      p1.x + (p2.x - p0.x)*t/3, p1.y + (p2.y - p0.y)*t/3,
      p2.x - (p3.x - p1.x)*t/3, p2.y - (p3.y - p1.y)*t/3,
      p2.x, p2.y
    );
  }
  ctx.lineTo(prodPts[prodPts.length-1].x, MT + PH);
  ctx.lineTo(prodPts[0].x, MT + PH);
  ctx.closePath();
  // Gradient fill
  const grad = ctx.createLinearGradient(0, MT, 0, MT + PH);
  grad.addColorStop(0,   "rgba(13,76,146,0.28)");
  grad.addColorStop(0.7, "rgba(13,76,146,0.06)");
  grad.addColorStop(1,   "rgba(13,76,146,0.01)");
  ctx.fillStyle = grad;
  ctx.fill();

  // Production stroke
  ctx.beginPath();
  ctx.moveTo(prodPts[0].x, prodPts[0].y);
  for (let i = 0; i < prodPts.length - 1; i++) {
    const p0 = prodPts[Math.max(0, i-1)];
    const p1 = prodPts[i];
    const p2 = prodPts[i+1];
    const p3 = prodPts[Math.min(prodPts.length-1, i+2)];
    const t  = 0.35;
    ctx.bezierCurveTo(
      p1.x + (p2.x - p0.x)*t/3, p1.y + (p2.y - p0.y)*t/3,
      p2.x - (p3.x - p1.x)*t/3, p2.y - (p3.y - p1.y)*t/3,
      p2.x, p2.y
    );
  }
  ctx.strokeStyle = "#0D4C92"; ctx.lineWidth = 2.2;
  ctx.setLineDash([]); ctx.stroke();

  //  Revenue dashed line (right axis scale) 
  const revPts = data.map((d, i) => ({
    x: ML + (i + 0.5) / N * PW,
    y: MT + PH - (revVals[i] / maxR) * PH
  }));
  ctx.beginPath();
  ctx.moveTo(revPts[0].x, revPts[0].y);
  for (let i = 0; i < revPts.length - 1; i++) {
    const p0 = revPts[Math.max(0, i-1)];
    const p1 = revPts[i];
    const p2 = revPts[i+1];
    const p3 = revPts[Math.min(revPts.length-1, i+2)];
    const t  = 0.35;
    ctx.bezierCurveTo(
      p1.x + (p2.x - p0.x)*t/3, p1.y + (p2.y - p0.y)*t/3,
      p2.x - (p3.x - p1.x)*t/3, p2.y - (p3.y - p1.y)*t/3,
      p2.x, p2.y
    );
  }
  ctx.strokeStyle = "#C07800"; ctx.lineWidth = 2;
  ctx.setLineDash([6, 3]); ctx.stroke(); ctx.setLineDash([]);

  // Data point dots on production peak
  const peakIdx = prodVals.indexOf(maxP);
  ctx.beginPath();
  ctx.arc(prodPts[peakIdx].x, prodPts[peakIdx].y, 4, 0, Math.PI * 2);
  ctx.fillStyle = "#0D4C92"; ctx.fill();
  ctx.strokeStyle = "#fff"; ctx.lineWidth = 1.5; ctx.stroke();
  // Peak label
  ctx.fillStyle = "#0D4C92"; ctx.font = "bold 8px Arial"; ctx.textAlign = "center";
  ctx.fillText("Peak " + maxP.toFixed(1), prodPts[peakIdx].x, prodPts[peakIdx].y - 8);

  //  X-axis year labels 
  ctx.fillStyle = window.edafyChartColors ? window.edafyChartColors().tick : "#64748B"; ctx.font = "8px Arial"; ctx.textAlign = "center";
  const step = Math.ceil(N / 12);
  data.forEach((d, i) => {
    if (i % step === 0 || i === N - 1) {
      ctx.fillText("Y" + d.year, ML + (i + 0.5) / N * PW, H - MB + 16);
    }
  });

  //  Hover tooltip 
  canvas._data = data; canvas._n = N;
  canvas._ml = ML; canvas._pw = PW; canvas._mt = MT; canvas._ph = PH;
  if (!canvas._bound) {
    canvas._bound = true;
    canvas.addEventListener("mousemove", e => {
      const rect = canvas.getBoundingClientRect();
      const sx = canvas.width / rect.width / DPR;
      const relX = (e.clientX - rect.left) * sx;
      const idx = Math.min(canvas._n - 1, Math.max(0,
        Math.floor(((relX - canvas._ml) / canvas._pw) * canvas._n)));
      const d  = canvas._data[idx];
      if (!d) return;
      const tt = document.getElementById("econ-prod-tooltip") ||
                  (() => {
                    const el = document.createElement("div");
                    el.id = "econ-prod-tooltip";
                    el.style.cssText = "position:absolute;display:none;background:rgba(27,37,55,.93);color:#fff;" +
                      "font-size:10px;padding:7px 11px;border-radius:6px;pointer-events:none;z-index:99;" +
                      "line-height:1.7;box-shadow:0 4px 14px rgba(0,0,0,.3)";
                    canvas.parentElement.appendChild(el);
                    return el;
                  })();
      tt.style.display = "block";
      tt.style.left = (e.clientX - rect.left + 14) + "px";
      tt.style.top  = (e.clientY - rect.top  - 70) + "px";
      tt.innerHTML  = `<b>Year ${d.year}</b><br>` +
        `Production: <b style="color:#7DD3FC">${(d.production||0).toFixed(2)} MMboe/yr</b><br>` +
        `Revenue:    <b style="color:#FCD34D">$${Math.round(d.revenue||0).toLocaleString()}M</b><br>` +
        `OPEX:       <b style="color:#FCA5A5">$${Math.round(d.opexY||0).toLocaleString()}M</b>`;
    });
    canvas.addEventListener("mouseleave", () => {
      const tt = document.getElementById("econ-prod-tooltip");
      if (tt) tt.style.display = "none";
    });
  }
}

// ── Tornado Chart ──────────────────────────────────────────────
let econTornadoChart = null;

function drawEconTornado() {
  const canvas = document.getElementById("econ-tornado-canvas");
  if (!canvas) return;

  if (!econLastResult) return;

  document.getElementById("econ-tornado-empty").style.display = "none";

  const baseParams = econLastResult.params;
  const baseNPV = econLastResult.npv;

  const swing =
    (parseFloat(document.getElementById("econ-sens-swing")?.value) || 20) / 100;

  const checks = document.querySelectorAll(
    "#econ-sens-checks input[type=checkbox]"
  );

  const allParams = [
    { id: "price", label: "Oil/Gas Price", delta: swing },
    { id: "volume", label: "Resource Volume", delta: swing },
    { id: "capex", label: "CAPEX", delta: swing },
    { id: "opex", label: "OPEX ($/boe)", delta: swing },
    { id: "rf", label: "Recovery Factor", delta: swing },
    { id: "decline", label: "Decline Rate", delta: swing },
    { id: "discount", label: "Discount Rate", delta: swing },
    { id: "royalty", label: "Royalty Rate", delta: swing },
  ];

  const enabled = {};
  checks.forEach((c) => {
    const k = c.getAttribute("data-param");
    if (k) enabled[k] = c.checked;
  });

  // ✅ Build rows
  const rows = allParams
    .filter((p) => enabled[p.id] !== false)
    .map((p) => {
      const lo = { ...baseParams };
      const hi = { ...baseParams };

      lo[p.id] = baseParams[p.id] * (1 - p.delta);
      hi[p.id] = baseParams[p.id] * (1 + p.delta);

      const npvLo = calcDCF(lo).npv;
      const npvHi = calcDCF(hi).npv;

      return {
        label: p.label,
        lo: Math.min(npvLo, npvHi),
        hi: Math.max(npvLo, npvHi),
        swing: Math.abs(npvHi - npvLo),
      };
    })
    .sort((a, b) => b.swing - a.swing);

  const labels = rows.map((r) => r.label);

  // ✅ Convert to tornado format (centered at base)
  const lowData = rows.map((r) => r.lo - baseNPV); // negative
  const highData = rows.map((r) => r.hi - baseNPV); // positive

  // ❌ destroy old
  if (econTornadoChart) econTornadoChart.destroy();

  // ✅ Plugin for vertical base line
  const baseLinePlugin = {
    id: "baseLine",
    afterDraw(chart) {
      const { ctx, chartArea, scales } = chart;
      const x = scales.x.getPixelForValue(0);

      ctx.save();
      ctx.setLineDash([6, 4]);
      ctx.strokeStyle = "#0D4C92";
      ctx.lineWidth = 2;

      ctx.beginPath();
      ctx.moveTo(x, chartArea.top);
      ctx.lineTo(x, chartArea.bottom);
      ctx.stroke();

      ctx.restore();
    },
  };

  econTornadoChart = new Chart(canvas, {
    type: "bar",
    data: {
      labels: labels,
      datasets: [
        {
          label: "Low",
          data: lowData,
          backgroundColor: "rgba(198,40,40,0.7)",
          borderColor: "rgba(198,40,40,0.7)",
          borderWidth: 1,
        },
        {
          label: "High",
          data: highData,
          backgroundColor: "rgba(26,127,90,0.7)",
          borderColor: "rgba(26,127,90,0.7)",
          borderWidth: 1,
        },
      ],
    },
    options: {
      indexAxis: "y", // 🔥 horizontal bars (tornado style)
      responsive: true,
      maintainAspectRatio: false,
      plugins: {
        legend: { display: false },
        tooltip: {
          callbacks: {
            label(ctx) {
              const i = ctx.dataIndex;
              const row = rows[i];

              return [
                `Low: $${Math.round(row.lo).toLocaleString()}M`,
                `High: $${Math.round(row.hi).toLocaleString()}M`,
                `Range: $${Math.round(row.swing).toLocaleString()}M`,
              ];
            },
          },
        },
      },
      scales: {
        x: {
          stacked: true,
          ticks: {
            callback: (v) =>
              Math.abs(v) >= 1000
                ? (v / 1000).toFixed(1) + "B"
                : v.toFixed(0),
            color: "#94A3B8",
          },
          grid: {
            color: "rgba(226,232,240,0.5)",
          },
        },
        y: {
          stacked: true,
          ticks: {
            color: "#334155",
          },
          grid: { display: false },
        },
      },
    },
    plugins: [baseLinePlugin],
  });
}

// ── NPV vs Price curve ─────────────────────────────────────────
let econNPVPriceChart = null;

function drawEconNPVvsPrice() {
  const canvas = document.getElementById("econ-npv-price-canvas");
  if (!canvas || !econLastResult) return;

  const base = econLastResult.params;

  // 🔢 Build data
  const priceRange = [];
  for (let p = 20; p <= 140; p += 5) priceRange.push(p);

  const npvs = priceRange.map((p) =>
    calcDCF({ ...base, price: p }).npv
  );

  if (econNPVPriceChart) econNPVPriceChart.destroy();

  // 🎯 Plugin: zero line (breakeven)
  const zeroLinePlugin = {
    id: "zeroLine",
    afterDraw(chart) {
      const { ctx, chartArea, scales } = chart;
      const y = scales.y.getPixelForValue(0);

      ctx.save();
      ctx.strokeStyle = "rgba(198,40,40,0.6)";
      ctx.lineWidth = 1.5;

      ctx.beginPath();
      ctx.moveTo(chartArea.left, y);
      ctx.lineTo(chartArea.right, y);
      ctx.stroke();

      ctx.fillStyle = "rgba(198,40,40,0.8)";
      ctx.font = "bold 10px Arial";
      ctx.fillText("Breakeven", chartArea.left + 6, y - 6);

      ctx.restore();
    },
  };

  // 🎯 Plugin: base case dot
  const basePointPlugin = {
    id: "basePoint",
    afterDatasetsDraw(chart) {
      const { ctx, scales } = chart;

      const x = scales.x.getPixelForValue(base.price);
      const y = scales.y.getPixelForValue(econLastResult.npv);

      ctx.save();

      // dot
      ctx.beginPath();
      ctx.arc(x, y, 5, 0, Math.PI * 2);
      ctx.fillStyle = "#0D4C92";
      ctx.fill();

      ctx.strokeStyle = "#fff";
      ctx.lineWidth = 2;
      ctx.stroke();

      // label
      ctx.fillStyle = "#0D4C92";
      ctx.font = "bold 10px Arial";
      ctx.textAlign = "center";
      ctx.fillText(`Base $${base.price}`, x, y - 10);

      ctx.restore();
    },
  };

  econNPVPriceChart = new Chart(canvas, {
    type: "line",
    data: {
      labels: priceRange,
      datasets: [
        {
          label: "NPV",
          data: npvs,
          borderColor: "#0D4C92",
          backgroundColor: "rgba(26,127,90,0.1)", // fill area
          fill: true,
          tension: 0.35,
          pointRadius: 0,
          borderWidth: 2.5,
        },
      ],
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      interaction: {
        mode: "index",
        intersect: false,
      },
      plugins: {
        legend: { display: false },
        tooltip: {
          backgroundColor: "rgba(27,37,55,0.95)",
          titleColor: "#fff",
          bodyColor: "#fff",
          callbacks: {
            title: (items) => `Price: $${items[0].label}/bbl`,
            label(ctx) {
              const v = ctx.raw;
              return `NPV₁₀: ${v >= 0 ? "+" : ""}$${Math.round(v).toLocaleString()}M`;
            },
          },
          enabled: false,
          external: function(context) {
            const { chart, tooltip } = context;
            const tt = document.getElementById("econ-npv-price-tooltip");
            if (!tt) return;

            if (tooltip.opacity === 0) {
              tt.style.display = "none";
              return;
            }

            const dataIndex = tooltip.dataPoints[0].dataIndex;
            const price = chart.data.labels[dataIndex];
            const value = chart.data.datasets[0].data[dataIndex];

            tt.style.display = "block";
            tt.style.left = tooltip.caretX + "px";
            tt.style.top = tooltip.caretY - 40 + "px";

            tt.innerHTML = `
              Price: <b>$${price}/bbl</b><br>
              NPV₁₀: <b style="color:${value >= 0 ? "#6EE7B7" : "#FCA5A5"}">
                ${value >= 0 ? "+" : ""}$${Math.round(value).toLocaleString()}M
              </b>
            `;
          }
        },
      },
      scales: {
        x: {
          title: {
            display: true,
            text: "Oil Price ($/bbl)",
            color: "#64748B",
            font: { size: 10 },
          },
          ticks: {
            color: "#94A3B8",
            callback: (v) => "$" + v,
          },
          grid: { display: false },
        },
        y: {
          ticks: {
            color: "#94A3B8",
            callback: (v) =>
              Math.abs(v) >= 1000
                ? (v / 1000).toFixed(1) + "B"
                : v.toFixed(0),
          },
          grid: {
            color: "rgba(226,232,240,0.7)",
          },
        },
      },
    },
    plugins: [zeroLinePlugin, basePointPlugin],
  });
}

function updateBreakevenPanel() {
  const body = document.getElementById("econ-breakeven-body");
  if (!body || !econLastResult) return;
  const { breakeven, params } = econLastResult;
  const margin = params.price - breakeven;
  const marginPct = ((margin / params.price) * 100).toFixed(1);
  const color =
    breakeven > params.price * 0.85
      ? "var(--red)"
      : breakeven > params.price * 0.65
        ? "var(--amber)"
        : "var(--green)";
  body.innerHTML = `
<div style="text-align:center;margin-bottom:12px">
<div style="font-size:10px;letter-spacing:1px;text-transform:uppercase;color:var(--t3);margin-bottom:4px">Breakeven Oil Price</div>
<div style="font-size:32px;font-weight:700;color:${color}">$${breakeven.toFixed(1)}</div>
<div style="font-size:10px;color:var(--t3)">/bbl</div>
</div>
<div style="background:var(--bg4);border-radius:6px;padding:10px;font-size:10px;color:var(--t2)">
<div style="display:flex;justify-content:space-between;margin-bottom:5px"><span>Current Price</span><b>$${params.price}/bbl</b></div>
<div style="display:flex;justify-content:space-between;margin-bottom:5px"><span>Price Margin</span><b style="color:${margin > 0 ? "var(--green)" : "var(--red)"}">$${margin.toFixed(1)} (${marginPct}%)</b></div>
<div style="display:flex;justify-content:space-between"><span>Project Viability</span><b style="color:${breakeven < params.price ? "var(--green)" : "var(--red)"}"> ${breakeven < params.price ? "✓ Viable" : "✗ Sub-economic"}</b></div>
</div>`;
}

let npvChart, irrChart; // Keep Chart.js instances for updates

function renderEconComparisons() {
  const body = document.getElementById("econ-scenarios-body");
  if (!econScenarios.length) return;

  // Table
  body.innerHTML = `
    <div style="overflow-x:auto">
      <table>
        <thead>
          <tr>
            <th>Scenario</th>
            <th>NPV₁₀ ($M)</th>
            <th>IRR (%)</th>
            <th>PI</th>
            <th>Payback (yr)</th>
            <th>Breakeven ($/bbl)</th>
            <th>Volume (MMboe)</th>
            <th>CAPEX ($M)</th>
            <th>Actions</th>
          </tr>
        </thead>
        <tbody>${econScenarios
          .map(
            (s, i) => `
          <tr>
            <td><b>${s.name}</b></td>
            <td style="color:${s.npv >= 0 ? "var(--green)" : "var(--red)"}"><b>${Math.round(s.npv).toLocaleString()}</b></td>
            <td style="color:${s.irr > s.params.disc ? "var(--green)" : "var(--red)"}">${s.irr.toFixed(1)}%</td>
            <td style="color:${s.pi > 1 ? "var(--green)" : "var(--red)"}">${s.pi.toFixed(2)}</td>
            <td>${s.payback || "N/A"}</td>
            <td style="color:${s.breakeven < s.params.price ? "var(--green)" : "var(--red)"}">$${s.breakeven.toFixed(1)}</td>
            <td>${s.recoverable.toFixed(1)}</td>
            <td>${Math.round(s.params.capex).toLocaleString()}</td>
            <td><button class="btn2" style="font-size:10px;padding:2px 6px;color:var(--red);border-color:#FCA5A5" onclick="removeEconScenario(${i})">✕</button></td>
          </tr>
          `
          )
          .join("")}
      </tbody>
      </table>
    </div>
  `;

  // Chart.js NPV
  const npvData = {
    labels: econScenarios.map(s => s.name),
    datasets: [{
      label: "NPV₁₀ ($M)",
      data: econScenarios.map(s => s.npv),
      backgroundColor: econScenarios.map(s => s.npv >= 0 ? "#1A7F5A99" : "#C6282899"),
      borderColor: econScenarios.map(s => s.npv >= 0 ? "#1A7F5A" : "#C62828"),
      borderWidth: 1
    }]
  };

  const irrData = {
    labels: econScenarios.map(s => s.name),
    datasets: [{
      label: "IRR (%)",
      data: econScenarios.map(s => s.irr),
      backgroundColor: econScenarios.map(s => s.irr > s.params.disc ? "#0D4C9299" : "#C6282899"),
      borderColor: econScenarios.map(s => s.irr > s.params.disc ? "#0D4C92" : "#C62828"),
      borderWidth: 1
    }]
  };

  const options = {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: { display: false },
      tooltip: { mode: 'index', intersect: false }
    },
    scales: {
      x: { title: { display: true, text: "Scenario" } },
      y: { beginAtZero: true }
    }
  };

  if (npvChart) npvChart.destroy();
  if (irrChart) irrChart.destroy();

  npvChart = new Chart(document.getElementById("econ-cmp-npv-canvas"), {
    type: "bar",
    data: npvData,
    options
  });

  irrChart = new Chart(document.getElementById("econ-cmp-irr-canvas"), {
    type: "bar",
    data: irrData,
    options
  });

  drawScenarioCumLine(); // Keep your cumulative line chart as is
}

