const PDECK_HIST_BRENT = [
  63.7, 26.6, 43.3, 40.9, 55.4, 64.9, 74.1, 83.7, 88.0, 104.3, 105.8,
  93.3, 85.3, 82.2, 80.1, 90.2, 77.5, 88.0, 85.0, 74.3, 76.4, 74.1, 79.6,
  74.5, 76.1, 76.4,
];
const PDECK_HIST_WTI = [
  57.5, 20.5, 40.7, 37.2, 52.2, 61.7, 71.3, 81.5, 83.2, 98.5, 100.8, 88.7,
  79.7, 77.4, 75.0, 85.8, 73.1, 83.5, 80.8, 70.2, 72.7, 70.4, 75.8, 70.1,
  72.8, 73.1,
];

// Forward curve from Feb-26 → 2035 (annual steps, consensus mid estimate)
const PDECK_FWD_YEARS = [
  2026, 2027, 2028, 2029, 2030, 2031, 2032, 2033, 2034, 2035,
];
const PDECK_FWD_BRENT = [
  76.4, 74.0, 72.5, 71.0, 70.0, 69.5, 69.0, 68.5, 68.0, 68.0,
]; // ICE strip-derived
const PDECK_FWD_WTI = [
  73.1, 70.8, 69.5, 68.0, 67.0, 66.5, 66.0, 65.5, 65.0, 65.0,
]; // NYMEX strip
const PDECK_FWD_CONS = [
  78.0, 77.5, 76.0, 75.0, 73.5, 72.0, 71.0, 70.5, 70.0, 70.0,
]; // Analyst median

// Active deck prices array used by DCF (20 yrs)
const PRICE_DECKS = {
  flat: {
    label: "Flat Real $75",
    color: "#0D4C92",
    desc: "Base case",
    prices: Array(20).fill(75),
  },
  brent: {
    label: "Brent Strip",
    color: "#0D4C92",
    desc: "ICE forward",
    prices: [...PDECK_FWD_BRENT, ...Array(10).fill(68)],
  },
  wti: {
    label: "WTI Strip",
    color: "#059669",
    desc: "NYMEX forward",
    prices: [...PDECK_FWD_WTI, ...Array(10).fill(65)],
  },
  rystad: {
    label: "Consensus Fwd",
    color: "#D97706",
    desc: "Analyst median",
    prices: [...PDECK_FWD_CONS, ...Array(10).fill(70)],
  },
};
let currentDeck = "flat";
let activeDeckKey = "flat";

function setActiveDeck(deck) {
  activeDeckKey = deck;
  currentDeck = deck;
  // Update selector button highlights
  ["flat", "brent", "wti", "rystad"].forEach((k) => {
    const btn = document.getElementById("pdeck-btn-" + k);
    const dot = document.getElementById("pdeck-dot-" + k);
    const pd = PRICE_DECKS[k];
    if (!btn) return;
    if (k === deck) {
      btn.style.border = "2px solid " + pd.color;
      btn.style.background = "rgba(13,76,146,.06)";
      btn.querySelector("div div:first-child").style.color = pd.color;
      if (dot) {
        dot.style.background = pd.color;
      }
    } else {
      btn.style.border = "1px solid #E2E8F0";
      btn.style.background = "";
      const label = btn.querySelector("div div:first-child");
      if (label) label.style.color = "var(--t2)";
      if (dot) dot.style.background = "#94A3B8";
    }
  });
  drawPriceDeckNPV();
  // Push active deck price into DCF input if user wants it
  const el = document.getElementById("econ-price");
  if (el && PRICE_DECKS[deck]) {
    el.value = PRICE_DECKS[deck].prices[0].toFixed(1);
    if (econAutoRun) runEconDCF();
  }
  toast("Active price deck → " + PRICE_DECKS[deck].label, "success");
}

// Legacy shim for old button calls
function setPriceDeck(deck) {
  setActiveDeck(deck);
}

