let priceDeckChart;

function drawPriceDeckMain() {
  const showBrent =
    document.getElementById("pdeck-show-brent")?.checked !== false;
  const showWTI =
    document.getElementById("pdeck-show-wti")?.checked !== false;
  const showCons =
    document.getElementById("pdeck-show-rystad")?.checked !== false;

  const labels = [...PDECK_HIST_LABELS, ...PDECK_FWD_YEARS.map(y => y.toString())];

  const datasets = [];

  if (showBrent) {
    const brentData = [...PDECK_HIST_BRENT, ...PDECK_FWD_BRENT.slice(1)];
    datasets.push({
      label: "Brent",
      data: brentData,
      borderColor: "#0D4C92",
      backgroundColor: "rgba(13,76,146,0.08)",
      tension: 0.25,
      fill: true,
      borderWidth: 2,
      pointRadius: 2,
      segment: {
        borderDash: ctx => ctx.p1.parsed.x >= PDECK_HIST_LABELS.length - 1 ? [6, 4] : []
      }
    });
  }

  if (showWTI) {
    const wtiData = [...PDECK_HIST_WTI, ...PDECK_FWD_WTI.slice(1)];
    datasets.push({
      label: "WTI",
      data: wtiData,
      borderColor: "#059669",
      backgroundColor: "rgba(5,150,105,0.08)",
      tension: 0.25,
      fill: false,
      borderWidth: 2,
      pointRadius: 2,
      segment: {
        borderDash: ctx => ctx.p1.parsed.x >= PDECK_HIST_LABELS.length - 1 ? [6, 4] : []
      }
    });
  }

  if (showCons) {
    // Consensus starts at 2026 (first forward year)
    const consData = Array(PDECK_HIST_LABELS.length - 1).fill(null) // pad historical years with null
      .concat(PDECK_FWD_CONS); // full forward series from 2026 onward

    datasets.push({
      label: "Consensus forward",
      data: consData,
      borderColor: "#D97706",
      backgroundColor: "rgba(217,119,6,0.08)",
      tension: 0.25,
      fill: false,
      borderWidth: 2,
      pointRadius: 2,
      segment: {
        borderDash: [9, 4] // dashed line for forward
      }
    });
  }

  if (priceDeckChart) priceDeckChart.destroy();

  priceDeckChart = new Chart(document.getElementById("econ-pdeck-canvas"), {
    type: "line",
    data: { labels, datasets },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      interaction: { mode: 'nearest', intersect: false },
      plugins: {
        tooltip: {
          callbacks: {
            label: ctx => {
              const val = ctx.raw?.toFixed(1);
              return `${ctx.dataset.label} $${val}`;
            }
          }
        },
        legend: { display: true, position: "bottom" }
      },
      scales: {
        x: {
          title: { display: true, text: "Time" },
          ticks: {
            callback: (val, idx) => {
              if (idx < PDECK_HIST_LABELS.length) {
                const lbl = PDECK_HIST_LABELS[idx];
                return lbl.startsWith("Jan") ? "20" + lbl.split("-")[1] : "";
              } else {
                const yr = PDECK_FWD_YEARS[idx - PDECK_HIST_LABELS.length];
                return (yr - 2026) % 2 === 0 ? yr : "";
              }
            }
          }
        },
        y: { title: { display: true, text: "$/bbl" }, beginAtZero: false }
      }
    }
  });
}

