let priceDeckNPVChart;

function drawPriceDeckNPV() {
  const canvas = document.getElementById("econ-pdeck-npv-canvas");
  if (!canvas || !econLastResult) return;

  const ctx = canvas.getContext("2d");

  // If no result, just show message and return
  if (!econLastResult) {
    // Clear canvas
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = "#94A3B8";
    ctx.font = '12px "Segoe UI",Arial';
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    ctx.fillText(
      "Run DCF Analysis first to see NPV across price decks",
      canvas.width / 2,
      canvas.height / 2
    );
    // Destroy old chart if exists
    if (priceDeckNPVChart) {
      priceDeckNPVChart.destroy();
      priceDeckNPVChart = null;
    }
    return;
  }
  const base = econLastResult.params;

  // Calculate deck NPV
  const deckResults = Object.entries(PRICE_DECKS).map(([key, pd]) => {
    const avgPrice = pd.prices.slice(0, 20).reduce((a, b) => a + b, 0) / 20;
    const npv = calcDCF({ ...base, price: avgPrice }).npv;
    return { key, label: pd.label, color: pd.color, avgPrice, npv };
  });

  // NPV line across $30-$120
  const priceRange = [30, 40, 50, 60, 70, 80, 90, 100, 110, 120];
  const npvLine = priceRange.map(p => calcDCF({ ...base, price: p }).npv);

  // Destroy old chart
  if (priceDeckNPVChart) priceDeckNPVChart.destroy();

  // const ctx = canvas.getContext("2d");
  priceDeckNPVChart = new Chart(ctx, {
    type: 'bar',
    data: {
      labels: deckResults.map(d => d.label),
      datasets: [
        // Bar for each deck
        {
          type: 'bar',
          label: 'NPV₁₀',
          data: deckResults.map(d => d.npv),
          backgroundColor: deckResults.map(d =>
            d.key === activeDeckKey ? d.color + 'CC' : d.color + '66'
          ),
          borderColor: deckResults.map(d => d.color),
          borderWidth: deckResults.map(d => (d.key === activeDeckKey ? 2 : 1)),
          hoverBackgroundColor: deckResults.map(d => d.color + 'DD')
        },
        // NPV sensitivity line
        {
          type: 'line',
          label: 'NPV Sensitivity',
          data: npvLine,
          borderColor: 'rgba(148,163,184,0.8)',
          borderWidth: 2,
          fill: false,
          tension: 0.25,
          pointRadius: 3,
          yAxisID: 'y'
        }
      ]
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      interaction: { mode: 'nearest', intersect: false },
      plugins: {
        tooltip: {
          callbacks: {
            label: ctx => {
              const val = ctx.raw;
              if (ctx.dataset.type === 'line') return `Price $${priceRange[ctx.dataIndex]} → $${val.toFixed(0)}M`;
              const deck = deckResults[ctx.dataIndex];
              return `${deck.label} → $${Math.round(deck.npv).toLocaleString()}M`;
            },
            afterBody: ctx => {
              const idx = ctx[0].dataIndex;
              const deck = deckResults[idx];
              return deck.key === activeDeckKey
                ? '● Currently active in DCF'
                : 'Click deck to activate →';
            }
          }
        },
        legend: { position: 'bottom' }
      },
      scales: {
        y: {
          beginAtZero: false,
          title: { display: true, text: 'NPV₁₀ ($M)' },
        }
      }
    }
  });
}

