// ============================================================
// TYPE CURVES / DECLINE CURVE ANALYSIS
// ============================================================
function switchTCTab(tab, el) {
  ["dca", "overlay", "forecast"].forEach((t) => {
    const p = document.getElementById("tc-" + t + "-panel");
    if (p) p.style.display = t === tab ? "block" : "none";
  });

  // Highlight active tab
  if (el) {
    el.parentElement
      .querySelectorAll(".tab")
      .forEach((t) => t.classList.remove("on"));
    el.classList.add("on");
  }

  // ✅ Update breadcrumb
  const bc = document.getElementById("breadcrumb-section");
  if (bc) bc.textContent = el?.textContent.trim() || "";

  // Call tab-specific functions
  if (tab === "overlay") renderTCOverlay();
  if (tab === "forecast") renderTCForecast();
}

function renderTCCurve() {
  const model =
    document.getElementById("tc-model")?.value || "Hyperbolic";
  const qi = parseFloat(document.getElementById("tc-qi")?.value) || 2500;
  const di =
    (parseFloat(document.getElementById("tc-di")?.value) || 35) /
    100 /
    12; // monthly
  const b = parseFloat(document.getElementById("tc-b")?.value) || 0.8;
  const months =
    parseInt(document.getElementById("tc-months")?.value) || 120;
  const econLimit =
    parseFloat(document.getElementById("tc-econ-limit")?.value) || 50;
  const rates = [];
  let cum = 0,
    econMonth = months;
  for (let m = 0; m < months; m++) {
    let q;
    if (model === "Exponential") q = qi * Math.exp(-di * m);
    else if (model === "Harmonic") q = qi / (1 + di * m);
    else q = qi / Math.pow(1 + b * di * m, 1 / b); // Hyperbolic
    if (q < econLimit && econMonth === months) econMonth = m;
    cum += q * 30.44; // days/month
    rates.push({ month: m, rate: Math.max(q, 0), cum });
  }
  // Draw
  const canvas = document.getElementById("tc-canvas");
  if (!canvas) return;

  const labels = rates.map(r => r.month);
  const rateData = rates.map(r => r.rate);
  const cumData = rates.map(r => r.cum);

  if (window.tcChart) window.tcChart.destroy();

  window.tcChart = new Chart(canvas, {
    type: "line",
    data: {
      labels,
      datasets: [
        {
          label: "Rate (bbl/d)",
          data: rateData,
          borderColor: "#0D4C92",
          borderWidth: 2,
          tension: 0.3,
          pointRadius: 0,
          yAxisID: "y",
        },
        {
          label: "Cumulative",
          data: cumData,
          borderColor: "#00E5A0",
          borderWidth: 2,
          tension: 0.3,
          pointRadius: 0,
          yAxisID: "y1",
        },
        {
          label: "Economic Limit",
          data: Array(labels.length).fill(econLimit),
          borderColor: "#FF4D6A",
          borderDash: [6,4],
          borderWidth: 1.5,
          pointRadius: 0,
          yAxisID: "y",
        }
      ]
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      interaction: {
        mode: "index",
        intersect: false
      },
      plugins: {
        legend: {
          position: "top",
          labels: { font: { size: 10 } }
        },
        tooltip: {
          callbacks: {
            title: (items) => `Month ${items[0].label}`,
            label: (ctx) => {
              if (ctx.dataset.yAxisID === "y")
                return `${ctx.dataset.label}: ${ctx.raw.toLocaleString()} bbl/d`;
              return `${ctx.dataset.label}: ${(ctx.raw/1e6).toFixed(2)}M bbl`;
            }
          }
        }
      },
      scales: {
        x: {
          title: {
            display: true,
            text: "Months",
            font: { size: 10, weight: "bold" }
          }
        },
        y: {
          position: "left",
          title: {
            display: true,
            text: "Rate (bbl/d)"
          }
        },
        y1: {
          position: "right",
          title: {
            display: true,
            text: "Cumulative (bbl)",
            color: "#00E5A0"
          },
          ticks: {
            callback: v => (v/1e6).toFixed(1) + "M"
          },
          grid: {
            drawOnChartArea: false
          }
        }
      }
    }
  });
  // Summary
  const eur = rates[econMonth - 1]?.cum || cum;
  document.getElementById("tc-summary").innerHTML =
    `<strong>${model}</strong> · qi=${qi} bbl/d · Di=${(di * 12 * 100).toFixed(0)}%/yr` +
    (model === "Hyperbolic" ? " · b=" + b : "") +
    `<br>EUR: <strong>${(eur / 1e6).toFixed(2)} MMbbl</strong> · Econ life: <strong>${econMonth} months</strong>`;
}

let tcChart = null;

function renderTCOverlay() {
  const canvas = document.getElementById("tc-overlay-canvas");
  if (!canvas) return;

  const months = 120;
  const labels = Array.from({ length: months }, (_, i) => i);

  const analogues = searchResults?.length
    ? searchResults.slice(0, 5)
    : ANALOGUES.slice(0, 5);

  const colors = ["#0D4C92", "#7C3AED", "#0891B2", "#D97706", "#059669"];

  const datasets = analogues.map((a, idx) => {
    const qi = (((a.perm || 200) * (a.ntg || 50)) / 100) * 1.5 + 500;
    const di = 0.02 + (a.depth || 3000) / 200000;
    const b = 0.6 + Math.random() * 0.4;

    const data = [];

    for (let m = 0; m < months; m++) {
      const q = qi / Math.pow(1 + b * di * m, 1 / b);
      data.push(Math.round(q));
    }

    return {
      label: a.name.split(" — ")[0],
      data,
      borderColor: colors[idx % colors.length],
      borderWidth: 2,
      pointRadius: 0,
      tension: 0.3,
      fill: false,
    };
  });

  if (tcChart) tcChart.destroy();

  tcChart = new Chart(canvas, {
    type: "line",
    data: {
      labels,
      datasets,
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      interaction: {
        mode: "nearest",
        intersect: false,
      },
      plugins: {
        legend: {
          position: "top",
          labels: {
            font: { size: 10 },
            boxWidth: 14,
          },
        },
        tooltip: {
          callbacks: {
            title: (items) => `Month ${items[0].label}`,
            label: (ctx) => `${ctx.dataset.label}: ${ctx.raw.toLocaleString()} bopd`,
          },
        },
      },
      scales: {
        x: {
          title: {
            display: true,
            text: "Months",
            font: { size: 10, weight: "bold" },
          },
          ticks: {
            font: { size: 9 },
          },
          grid: {
            color: "rgba(0,0,0,.05)",
          },
        },
        y: {
          title: {
            display: true,
            text: "Production Rate (bopd)",
            font: { size: 10, weight: "bold" },
          },
          ticks: {
            font: { size: 9 },
          },
          grid: {
            color: "rgba(0,0,0,.05)",
          },
        },
      },
      animation: {
        duration: 400,
      },
    },
  });
}

function renderTCForecast() {
  const canvas = document.getElementById('tc-forecast-canvas');
  const statsEl = document.getElementById('tc-forecast-stats');
  if (!canvas) return;

  /*  Read live DCA params  */
  const qi       = parseFloat(document.getElementById('tc-qi')?.value)         || 2500;
  const diYr     = parseFloat(document.getElementById('tc-di')?.value)         || 35;
  const b        = parseFloat(document.getElementById('tc-b')?.value)          || 0.8;
  const model    = document.getElementById('tc-model')?.value                  || 'Hyperbolic';
  const months   = parseInt(document.getElementById('tc-months')?.value)       || 120;
  const econLim  = parseFloat(document.getElementById('tc-econ-limit')?.value) || 50;
  const di_m     = diYr / 100 / 12;

  /*  Build cumulative curve  */
  const pts = []; let cum = 0, econMonth = months;
  for (let m = 0; m < months; m++) {
    let q;
    if (model === 'Exponential') q = qi * Math.exp(-di_m * m);
    else if (model === 'Harmonic') q = qi / (1 + di_m * m);
    else q = qi / Math.pow(1 + b * di_m * m, 1 / b);
    q = Math.max(0, q);
    if (q < econLim && econMonth === months) econMonth = m;
    cum += q * 30.44;
    pts.push({ m, rate: q, cum: cum / 1e6 }); // cum in MMbbl
  }

  /*  Build P10 / P90 bands  */
  function buildCum(qiF, diF) {
    const r = []; let c = 0;
    for (let m = 0; m < months; m++) {
      let q = qiF / Math.pow(1 + b * diF * m, 1 / b);
      c += Math.max(0, q) * 30.44;
      r.push(c / 1e6);
    }
    return r;
  }
  const p10cum = buildCum(qi * 0.6, di_m * 1.35);
  const p90cum = buildCum(qi * 1.5, di_m * 0.70);

  /*  Canvas sizing — walk up DOM to find real width even when panel was hidden  */
  let parentW = 0;
  let node = canvas.parentElement;
  while (node && parentW < 50) { parentW = node.offsetWidth || node.clientWidth || 0; node = node.parentElement; }
  canvas.width  = parentW > 50 ? parentW : 800;
  canvas.height = 320;
  const W   = canvas.width;
  const H   = canvas.height;
  const PAD = { l:62, r:26, t:34, b:48 };
  const pw  = W - PAD.l - PAD.r;
  const ph  = H - PAD.t - PAD.b;
  const ctx = canvas.getContext('2d');
  ctx.clearRect(0, 0, W, H);

  /*  Background  */
  ctx.fillStyle = window.edafyCanvasBgColor ? window.edafyCanvasBgColor() : '#F8FAFC';
  ctx.fillRect(0, 0, W, H);

  /*  Data ranges  */
  const maxCum  = Math.max(...p90cum) * 1.08;
  const maxRate = qi * 1.05;
  const nGridY = 5, nGridX = 6;

  /*  Grid lines  */
  ctx.strokeStyle = 'rgba(148,163,184,0.22)';
  ctx.lineWidth = 1;
  for (let i = 0; i <= nGridY; i++) {
    const y = PAD.t + (i / nGridY) * ph;
    ctx.beginPath(); ctx.moveTo(PAD.l, y); ctx.lineTo(PAD.l + pw, y); ctx.stroke();
  }
  for (let i = 0; i <= nGridX; i++) {
    const x = PAD.l + (i / nGridX) * pw;
    ctx.beginPath(); ctx.moveTo(x, PAD.t); ctx.lineTo(x, PAD.t + ph); ctx.stroke();
  }

  /*  Coord helpers  */
  const xOf = m  => PAD.l + (m / (months - 1)) * pw;
  const yCum = v  => PAD.t + ph - (v / maxCum)  * ph;
  const yRat = v  => PAD.t + ph - (v / maxRate) * ph;

  /*  P10–P90 band (cumulative)  */
  ctx.beginPath();
  p90cum.forEach((v, i) => i === 0 ? ctx.moveTo(xOf(i), yCum(v)) : ctx.lineTo(xOf(i), yCum(v)));
  for (let i = p10cum.length - 1; i >= 0; i--) ctx.lineTo(xOf(i), yCum(p10cum[i]));
  ctx.closePath();
  ctx.fillStyle = 'rgba(13,76,146,0.08)';
  ctx.fill();

  /*  P90 line (optimistic)  */
  ctx.beginPath();
  ctx.strokeStyle = 'rgba(13,76,146,0.35)'; ctx.lineWidth = 1.2;
  ctx.setLineDash([4, 3]);
  p90cum.forEach((v, i) => i === 0 ? ctx.moveTo(xOf(i), yCum(v)) : ctx.lineTo(xOf(i), yCum(v)));
  ctx.stroke();

  /*  P10 line (conservative)  */
  ctx.beginPath();
  ctx.strokeStyle = 'rgba(124,58,237,0.35)'; ctx.lineWidth = 1.2;
  p10cum.forEach((v, i) => i === 0 ? ctx.moveTo(xOf(i), yCum(v)) : ctx.lineTo(xOf(i), yCum(v)));
  ctx.stroke();
  ctx.setLineDash([]);

  /*  P50 cumulative (main blue)  */
  ctx.beginPath();
  ctx.strokeStyle = '#0D4C92'; ctx.lineWidth = 2.5;
  pts.forEach((p, i) => i === 0 ? ctx.moveTo(xOf(i), yCum(p.cum)) : ctx.lineTo(xOf(i), yCum(p.cum)));
  ctx.stroke();

  /*  Rate curve (right axis, green)  */
  ctx.beginPath();
  ctx.strokeStyle = '#059669'; ctx.lineWidth = 1.5;
  ctx.setLineDash([3, 2]);
  pts.forEach((p, i) => i === 0 ? ctx.moveTo(xOf(i), yRat(p.rate)) : ctx.lineTo(xOf(i), yRat(p.rate)));
  ctx.stroke();
  ctx.setLineDash([]);

  /*  Economic limit vertical  */
  if (econMonth < months) {
    const ex = xOf(econMonth);
    ctx.beginPath();
    ctx.strokeStyle = '#EF4444'; ctx.lineWidth = 1.3; ctx.setLineDash([5, 3]);
    ctx.moveTo(ex, PAD.t); ctx.lineTo(ex, PAD.t + ph); ctx.stroke();
    ctx.setLineDash([]);
    ctx.fillStyle = '#EF4444'; ctx.font = '9px system-ui'; ctx.textAlign = 'left';
    ctx.fillText('Econ limit', ex + 4, PAD.t + 12);
  }

  /*  Y-axis labels (left — cumulative)  */
  ctx.fillStyle = '#64748B'; ctx.font = '10px system-ui,sans-serif';
  for (let i = 0; i <= nGridY; i++) {
    const v = maxCum * (1 - i / nGridY);
    const y = PAD.t + (i / nGridY) * ph;
    ctx.textAlign = 'right';
    ctx.fillText(v >= 10 ? Math.round(v).toString() : v.toFixed(1), PAD.l - 6, y + 3);
  }

  /*  Y-axis labels (right — rate)  */
  ctx.fillStyle = '#059669';
  for (let i = 0; i <= nGridY; i++) {
    const v = maxRate * (1 - i / nGridY);
    const y = PAD.t + (i / nGridY) * ph;
    ctx.textAlign = 'left';
    ctx.fillText(v >= 1000 ? Math.round(v/1000)+'k' : Math.round(v).toString(), PAD.l + pw + 4, y + 3);
  }

  /*  X-axis labels  */
  ctx.fillStyle = '#64748B';
  for (let i = 0; i <= nGridX; i++) {
    const m = Math.round((i / nGridX) * (months - 1));
    ctx.textAlign = 'center';
    ctx.fillText(m.toString(), xOf(m), PAD.t + ph + 16);
  }

  /*  Axis titles  */
  ctx.fillStyle = '#475569'; ctx.textAlign = 'center';
  ctx.fillText('Time (months)', PAD.l + pw / 2, H - 8);
  ctx.save();
  ctx.translate(13, PAD.t + ph / 2); ctx.rotate(-Math.PI / 2);
  ctx.fillStyle = '#0D4C92';
  ctx.fillText('Cumulative Production (MMbbl)', 0, 0);
  ctx.restore();
  ctx.save();
  ctx.translate(W - 8, PAD.t + ph / 2); ctx.rotate(-Math.PI / 2);
  ctx.fillStyle = '#059669';
  ctx.fillText('Rate (bbl/d)', 0, 0);
  ctx.restore();

  /*  Chart title  */
  ctx.fillStyle = window.edafyChartColors ? window.edafyChartColors().tickBold : '#0A2E5C'; ctx.font = '700 11px system-ui,sans-serif';
  ctx.textAlign = 'left';
  ctx.fillText('CUMULATIVE PRODUCTION FORECAST', PAD.l, 22);

  /*  Legend  */
  const LEG = [
    { color:'#0D4C92', dash:false, label:'P50 Cumulative (MMbbl)' },
    { color:'rgba(13,76,146,0.5)', dash:true,  label:'P90 (Optimistic)' },
    { color:'rgba(124,58,237,0.5)', dash:true, label:'P10 (Conservative)' },
    { color:'#059669', dash:true,  label:'Rate (bbl/d)' },
  ];
  let lx = W - PAD.r - 10;
  ctx.font = '9px system-ui,sans-serif';
  [...LEG].reverse().forEach(leg => {
    const tw = ctx.measureText(leg.label).width;
    lx -= (tw + 26);
    ctx.strokeStyle = leg.color; ctx.lineWidth = 1.8;
    ctx.setLineDash(leg.dash ? [4,3] : []);
    ctx.beginPath(); ctx.moveTo(lx, 23); ctx.lineTo(lx + 16, 23); ctx.stroke();
    ctx.setLineDash([]);
    ctx.fillStyle = window.edafyChartColors ? window.edafyChartColors().tickBold : '#334155'; ctx.textAlign = 'left';
    ctx.fillText(leg.label, lx + 20, 27);
    lx -= 8;
  });

  /*  Border  */
  ctx.strokeStyle = 'rgba(148,163,184,0.4)'; ctx.lineWidth = 1;
  ctx.strokeRect(PAD.l, PAD.t, pw, ph);

  /*  Stats panel below chart  */
  const eur     = pts[econMonth > 0 ? Math.min(econMonth, pts.length-1) : pts.length-1]?.cum || pts[pts.length-1].cum;
  const eurP10  = p10cum[Math.min(econMonth, p10cum.length-1)] || p10cum[p10cum.length-1];
  const eurP90  = p90cum[Math.min(econMonth, p90cum.length-1)] || p90cum[p90cum.length-1];
  const peakRat = qi;
  const yr10cum = pts[Math.min(119, pts.length-1)]?.cum || eur;
  const econYrs = econMonth < months ? (econMonth / 12).toFixed(1) : (months/12).toFixed(1);

  if (statsEl) {
    statsEl.innerHTML = `
      <div style="display:grid;grid-template-columns:repeat(5,1fr);gap:6px;margin-top:6px">
        <div style="background:var(--bg4);padding:7px 8px;border-radius:5px;border:1px solid var(--b1);text-align:center">
          <div style="font-size:8px;color:var(--t3);text-transform:uppercase;margin-bottom:2px">EUR P50</div>
          <div style="font-size:15px;font-weight:700;color:#0D4C92">${eur.toFixed(1)}</div>
          <div style="font-size:8px;color:var(--t3)">MMbbl</div>
        </div>
        <div style="background:var(--bg4);padding:7px 8px;border-radius:5px;border:1px solid var(--b1);text-align:center">
          <div style="font-size:8px;color:var(--t3);text-transform:uppercase;margin-bottom:2px">EUR Range</div>
          <div style="font-size:11px;font-weight:700;color:#7C3AED">${eurP10.toFixed(1)}–${eurP90.toFixed(1)}</div>
          <div style="font-size:8px;color:var(--t3)">P10–P90 MMbbl</div>
        </div>
        <div style="background:var(--bg4);padding:7px 8px;border-radius:5px;border:1px solid var(--b1);text-align:center">
          <div style="font-size:8px;color:var(--t3);text-transform:uppercase;margin-bottom:2px">Peak Rate</div>
          <div style="font-size:15px;font-weight:700;color:#059669">${peakRat.toLocaleString()}</div>
          <div style="font-size:8px;color:var(--t3)">bbl/d</div>
        </div>
        <div style="background:var(--bg4);padding:7px 8px;border-radius:5px;border:1px solid var(--b1);text-align:center">
          <div style="font-size:8px;color:var(--t3);text-transform:uppercase;margin-bottom:2px">Econ Life</div>
          <div style="font-size:15px;font-weight:700;color:#D97706">${econYrs}</div>
          <div style="font-size:8px;color:var(--t3)">years</div>
        </div>
        <div style="background:var(--bg4);padding:7px 8px;border-radius:5px;border:1px solid var(--b1);text-align:center">
          <div style="font-size:8px;color:var(--t3);text-transform:uppercase;margin-bottom:2px">10-yr Cum</div>
          <div style="font-size:15px;font-weight:700;color:#0891B2">${yr10cum.toFixed(1)}</div>
          <div style="font-size:8px;color:var(--t3)">MMbbl</div>
        </div>
      </div>
      <div style="margin-top:6px;font-size:10px;color:var(--t3);padding:4px 8px;background:rgba(13,76,146,.04);border-radius:4px;border:1px solid rgba(13,76,146,.1)">
        <strong style="color:var(--t2)">${model}</strong> decline · qi = ${qi.toLocaleString()} bbl/d · Di = ${diYr}%/yr · b = ${b} · Econ limit = ${econLim} bbl/d
        <span style="margin-left:8px;color:var(--purple)"> Live from DCA tab — change parameters to update</span>
      </div>`;
  }

  /*  Hover tooltip  */
  if (!canvas._forecastListener) {
    canvas._forecastListener = true;
    canvas.style.cursor = 'crosshair';
    canvas.addEventListener('mousemove', function(e) {
      const rect = canvas.getBoundingClientRect();
      const mx   = (e.clientX - rect.left) * (canvas.width / rect.width);
      if (mx < PAD.l || mx > PAD.l + pw) return;
      const mIdx = Math.round(((mx - PAD.l) / pw) * (months - 1));
      const pt   = pts[Math.min(mIdx, pts.length - 1)];
      if (!pt) return;
      const p10v = p10cum[Math.min(mIdx, p10cum.length-1)];
      const p90v = p90cum[Math.min(mIdx, p90cum.length-1)];
      if (statsEl) {
        statsEl.querySelector && (statsEl.querySelector('.hover-hint') ||
          statsEl.insertAdjacentHTML('afterbegin',
            `<div class="hover-hint" style="font-size:10px;color:var(--brand);font-weight:600;margin-bottom:4px"></div>`));
        const hint = statsEl.querySelector('.hover-hint');
        if (hint) hint.textContent =
          `Month ${mIdx}: Rate ${Math.round(pt.rate).toLocaleString()} bbl/d · Cum P50 ${pt.cum.toFixed(2)} MMbbl · Range ${p10v.toFixed(2)}–${p90v.toFixed(2)} MMbbl`;
      }
    });
  }
}

function exportTCChart() {
  toast("Type curve chart exported", "success");
}

// ============================================================
// BENCHMARKING DASHBOARD
// ============================================================
function switchBMTab(tab, el) {
  ["global", "basin", "percentile"].forEach((t) => {
    const p = document.getElementById("bm-" + t + "-panel");
    if (p) p.style.display = t === tab ? "block" : "none";
  });

  el.parentElement
    .querySelectorAll(".tab")
    .forEach((t) => t.classList.remove("on"));

  el.classList.add("on");

  // ✅ Update breadcrumb
  const bc = document.getElementById("breadcrumb-section");
  if (bc) {
    bc.textContent = el.textContent.trim();
  }

  if (tab === "global") renderBenchmarks();
  if (tab === "basin") initBasinBMDropdowns();
  if (tab === "percentile") renderPercentileAnalysis();
}

let myChart = null;

function renderBenchmarks() {
  // KPIs
  const allPor = ANALOGUES.map((a) => a.por).filter(Boolean);
  const allPerm = ANALOGUES.map((a) => a.perm).filter(Boolean);
  const allRF = ANALOGUES.map((a) => a.rf).filter(Boolean);
  const allAPI = ANALOGUES.map((a) => a.api).filter(Boolean);
  const avg = (arr) =>
    arr.length
      ? (arr.reduce((s, v) => s + v, 0) / arr.length).toFixed(1)
      : "—";
  document.getElementById("bm-kpis").innerHTML = `
    <div class="kpi e" style="text-align:center"><div class="kpi-lbl">Avg Porosity</div><div class="kpi-val" style="">${avg(allPor)}%</div><div class="kpi-sub">${allPor.length} samples</div></div>
    <div class="kpi g" style="text-align:center"><div class="kpi-lbl">Avg Permeability</div><div class="kpi-val" style="">${avg(allPerm)}</div><div class="kpi-sub">mD</div></div>
    <div class="kpi c" style="text-align:center"><div class="kpi-lbl">Avg Recovery</div><div class="kpi-val" style="">${avg(allRF)}%</div><div class="kpi-sub">${allRF.length} fields</div></div>
    <div class="kpi r" style="text-align:center"><div class="kpi-lbl">Avg API</div><div class="kpi-val" style="">${avg(allAPI)}°</div><div class="kpi-sub">${allAPI.length} samples</div></div>`;
  // Chart
  const param = document.getElementById("bm-param")?.value || "por";
  const groupBy = document.getElementById("bm-group")?.value || "dep";
  const paramKey = {
    por: "por",
    perm: "perm",
    rf: "rf",
    ntg: "ntg",
    depth: "depth",
    api: "api",
  }[param];
  const groups = {};
  ANALOGUES.forEach((a) => {
    const gk = a[groupBy] || "Unknown";
    if (!groups[gk]) groups[gk] = [];
    if (a[paramKey]) groups[gk].push(a[paramKey]);
  });

  const canvas = document.getElementById("bm-canvas");
  if (!canvas) return;

  // 2. IMPORTANT: Destroy the old chart if it exists
  if (myChart) {
    myChart.destroy();
  }

  // 1. Prepare the data from the 'groups' object
  const entries = Object.entries(groups)
    .filter(([, v]) => v.length > 0)
    .slice(0, 8);

  if (!entries.length) return;

  const labels = entries.map(([group]) => group);
  const means = entries.map(([, vals]) => {
    return vals.reduce((s, v) => s + v, 0) / vals.length;
  });
  const counts = entries.map(([, vals]) => vals.length);

  const colors = [
    "#0D4C92", "#7C3AED", "#0891B2", "#D97706",
    "#059669", "#DC2626", "#64748B", "#C07800",
  ];

  // 3. Assign the new chart to the variable
  myChart = new Chart(canvas, {
    type: 'bar',
    data: {
      labels: labels,
      datasets: [{
        label: 'Mean Value',
        data: means,
        backgroundColor: colors.map(c => c + "66"),
        borderColor: colors,
        borderWidth: { left: 4 },
        barPercentage: 0.6,
      }]
    },
    options: {
      indexAxis: 'y',
      responsive: true,
      maintainAspectRatio: false,
      // ... rest of your options
    }
  });
}

// ── Multi-basin state ────────────────────────────────────────────────
let _bmBasins = [];
const BM_COLORS       = ['#7C3AED','#0D7FBF','#00875A','#C07800','#D93025','#0088CC'];
const BM_COLORS_ALPHA = ['rgba(124,58,237,.15)','rgba(13,127,191,.15)','rgba(0,135,90,.15)',
                          'rgba(192,120,0,.15)','rgba(217,48,37,.15)','rgba(0,136,204,.15)'];

function initBasinBMDropdowns() {
  const sel = document.getElementById('bm-basin-add-sel');
  if (sel && sel.options.length <= 1) {
    BASINS.forEach(b => {
      const o = document.createElement('option');
      o.value = b.name; o.textContent = b.name;
      sel.appendChild(o);
    });
  }
  if (_bmBasins.length === 0 && BASINS.length >= 2) {
    _bmBasins = [BASINS[0].name, BASINS[1].name];
    _bmRenderChips();
    renderBasinBM();
  }
}

function bmAddBasin() {
  const sel = document.getElementById('bm-basin-add-sel');
  const val = sel?.value;
  if (!val) return;
  if (_bmBasins.includes(val)) { sel.value = ''; return; }
  if (_bmBasins.length >= 6) { alert('Maximum 6 basins. Remove one first.'); return; }
  _bmBasins.push(val);
  sel.value = '';
  _bmRenderChips();
  renderBasinBM();
}

function bmRemoveBasin(name) {
  _bmBasins = _bmBasins.filter(n => n !== name);
  _bmRenderChips();
  renderBasinBM();
}

function bmClearAll() {
  _bmBasins = [];
  _bmRenderChips();
  renderBasinBM();
}

function _bmRenderChips() {
  const wrap = document.getElementById('bm-basin-chips');
  if (!wrap) return;
  if (_bmBasins.length === 0) {
    wrap.innerHTML = '<span style="font-size:10px;color:var(--t3);font-style:italic">No basins selected yet…</span>';
    return;
  }
  wrap.innerHTML = '';
  _bmBasins.forEach((name, i) => {
    const chip = document.createElement('span');
    chip.style.cssText = `display:inline-flex;align-items:center;gap:4px;padding:3px 8px 3px 9px;
      border-radius:20px;font-size:10px;font-weight:700;cursor:default;
      background:${BM_COLORS_ALPHA[i%6]};border:1px solid ${BM_COLORS[i%6]}88;
      color:${BM_COLORS[i%6]}`;
    const dot = document.createElement('span');
    dot.style.cssText = `width:6px;height:6px;border-radius:50%;background:${BM_COLORS[i%6]};flex-shrink:0;display:inline-block`;
    const label = document.createTextNode(' ' + name + ' ');
    const x = document.createElement('span');
    x.textContent = '×';
    x.title = 'Remove';
    x.style.cssText = 'margin-left:2px;cursor:pointer;opacity:.7;font-size:13px;line-height:1;font-weight:400';
    x.addEventListener('click', () => bmRemoveBasin(name));
    chip.appendChild(dot);
    chip.appendChild(label);
    chip.appendChild(x);
    wrap.appendChild(chip);
  });
}

function bmExportCSV() {
  const src = leaderboardData.length ? leaderboardData : BASINS;
  const rows = _bmBasins.map(n => src.find(b => b.name === n)).filter(Boolean);
  if (!rows.length) return;
  const keys = ['name','score','plays','area','hc','region','country'];
  const csv = [keys.join(','), ...rows.map(b => keys.map(k => JSON.stringify(b[k]??'')).join(','))].join('\n');
  const a = document.createElement('a');
  a.href = 'data:text/csv;charset=utf-8,' + encodeURIComponent(csv);
  a.download = 'basin_comparison.csv'; a.click();
}

let basinChart = null;
function renderBasinBM() {
  const src = leaderboardData.length ? leaderboardData : BASINS;
  const canvas = document.getElementById('bm-basin-canvas');
  const emptyEl = document.getElementById('bm-basin-empty');
  const tableEl = document.getElementById('bm-basin-table');
  if (!canvas) return;

  // 1. Setup Data
  const selected = _bmBasins.map(n => src.find(b => b.name === n)).filter(Boolean);

  if (selected.length < 2) {
    if (basinChart) { basinChart.destroy(); basinChart = null; }
    canvas.style.display = 'none';
    if (emptyEl) emptyEl.style.display = 'block';
    if (tableEl) tableEl.innerHTML = '';
    return;
  }

  canvas.style.display = 'block';
  if (emptyEl) emptyEl.style.display = 'none';

  const chartType = document.getElementById('bm-chart-type')?.value || 'bar';
  const metricKey = document.getElementById('bm-metric-sel')?.value || 'all';

  const ALL_DIMS = [
    { key: 'score', label: 'Prospectivity', max: 100, unit: '' },
    { key: 'plays', label: 'Play Count', max: 30, unit: '' },
    { key: 'area', label: 'Area (k km²)', max: 1200, unit: 'k', transform: v => +(v / 1000).toFixed(0) },
    { key: 'gcos', label: 'GCoS %', max: 100, unit: '%' },
    { key: 'source', label: 'Source Rock', max: 100, unit: '' },
    { key: 'reservoir', label: 'Reservoir', max: 100, unit: '' },
    { key: 'seal', label: 'Seal Quality', max: 100, unit: '' },
    { key: 'trap', label: 'Trap', max: 100, unit: '' },
    { key: 'timing', label: 'Timing', max: 100, unit: '' },
    { key: 'commercial', label: 'Commercial', max: 100, unit: '' },
  ];

  const GROUPS = {
    all: ALL_DIMS,
    prospectivity: ALL_DIMS.filter(d => ['score', 'gcos', 'commercial'].includes(d.key)),
    risk: ALL_DIMS.filter(d => ['source', 'reservoir', 'seal', 'trap', 'timing'].includes(d.key)),
    resources: ALL_DIMS.filter(d => ['plays', 'area'].includes(d.key)),
  };

  const dims = GROUPS[metricKey] || ALL_DIMS;
  const getRaw = (b, d) => +(b[d.key] ?? b.scores?.[d.key] ?? 0);

  const isRadar = chartType === 'radar';

  // 2. Prepare Chart.js Datasets
  const datasets = selected.map((b, i) => {
    const color = BM_COLORS[i % 6];

    return {
      label: b.name,
      data: dims.map(d => {
        const raw = getRaw(b, d);
        const norm = Math.min(1, raw / d.max);
        return norm * 100;
      }),

      backgroundColor: isRadar 
        ? color + '66'   // 👈 soft fill for radar
        : color,         // 👈 solid fill for bar

      borderColor: color,

      borderWidth: 2,

      // Radar only styling
      pointBackgroundColor: isRadar ? color : undefined,
    };
  });

  // 3. Destroy existing chart
  if (basinChart) {
    basinChart.destroy();
  }
  
  // Validation for Radar
  if (isRadar && dims.length < 3) {
      // Handle "Not enough metrics" error view if needed
      return;
  }

  basinChart = new Chart(canvas, {
    type: isRadar ? 'radar' : 'bar',
    data: {
      labels: dims.map(d => d.label),
      datasets: datasets
    },
    options: {
      indexAxis: isRadar ? undefined : 'y',
      responsive: true,
      maintainAspectRatio: false,
      plugins: {
        legend: { position: 'bottom', labels: { boxHeight: 2, font: { size: 10 } } },
        tooltip: {
            callbacks: {
                label: (context) => {
                    const d = dims[context.dataIndex];
                    const val = isRadar 
                        ? (context.raw / 100 * d.max) // Convert back from normalized %
                        : context.raw;
                    const display = d.transform ? d.transform(val) + d.unit : val.toFixed(0) + d.unit;
                    return `${context.dataset.label}: ${display}`;
                }
            }
        }
      },
      scales: isRadar ? {
        r: {
          min: 0,
          max: 100,
          ticks: { display: false, stepSize: 25 },
          pointLabels: { font: { size: 10, weight: 'bold' } }
        }
      } : {
        x: {
          beginAtZero: true,
          grid: { display: false },
          ticks: { font: { size: 9 }, callback: (v) => v + '%' }
        },
        y: {
          grid: { display: false },
          ticks: { font: { size: 10, weight: 'bold' } }
        }
      }
    }
  });

  // ── Stats table ─────────────────────────────────────────────────
  if (tableEl) {
    const tDims = dims.slice(0, 7);
    tableEl.innerHTML = `
      <table style="width:100%;font-size:10px;border-collapse:collapse;margin-top:4px">
        <thead>
          <tr style="background:var(--bg4)">
            <th style="padding:6px 10px;text-align:left;font-weight:700;color:var(--t2);
              border-bottom:1px solid var(--b1)">Basin</th>
            ${tDims.map(d=>`<th style="padding:6px 10px;text-align:center;font-weight:700;
              color:var(--t2);border-bottom:1px solid var(--b1)">${d.label}</th>`).join('')}
          </tr>
        </thead>
        <tbody>
          ${selected.map((b,i) => {
            const col = BM_COLORS[i%6];
            return `<tr style="border-bottom:1px solid var(--b1)">
              <td style="padding:6px 10px;font-weight:700;color:${col};white-space:nowrap">
                <span style="display:inline-block;width:7px;height:7px;border-radius:50%;
                  background:${col};margin-right:5px;vertical-align:middle"></span>${b.name}
              </td>
              ${tDims.map(d => {
                const raw = getRaw(b,d);
                const pct = raw/d.max;
                const vc  = pct>=.7?'var(--green)':pct>=.4?'var(--amber)':'var(--red)';
                const display = d.transform ? d.transform(raw)+d.unit : raw.toFixed(0)+d.unit;
                return `<td style="padding:6px 10px;text-align:center;color:${vc};font-weight:700">${display}</td>`;
              }).join('')}
            </tr>`;
          }).join('')}
        </tbody>
      </table>`;
  }
}


function renderPercentileAnalysis() {
  const body = document.getElementById("bm-pct-body");
  if (!body) return;
  const analogues = searchResults?.length ? searchResults : ANALOGUES;
  const allPor = ANALOGUES.map((a) => a.por)
    .filter(Boolean)
    .sort((a, b) => a - b);
  const allPerm = ANALOGUES.map((a) => a.perm)
    .filter(Boolean)
    .sort((a, b) => a - b);
  const allRF = ANALOGUES.map((a) => a.rf)
    .filter(Boolean)
    .sort((a, b) => a - b);
  const getPct = (val, arr) =>
    arr.length
      ? Math.round(
          (arr.filter((v) => v <= val).length / arr.length) * 100,
        )
      : "—";
  body.innerHTML = `<div style="overflow-x:auto"><table><thead><tr><th>Analogue</th><th>Porosity</th><th>Pctl</th><th>Perm</th><th>Pctl</th><th>RF</th><th>Pctl</th></tr></thead><tbody>
${analogues
.slice(0, 10)
.map((a) => {
  const ppor = getPct(a.por, allPor),
    pperm = getPct(a.perm, allPerm),
    prf = getPct(a.rf, allRF);
  const badge = (v) =>
    `<span style="font-weight:700;color:${v >= 70 ? "var(--green)" : v >= 40 ? "var(--amber)" : "var(--red)"}">P${v}</span>`;
  return `<tr><td style="font-weight:600;color:var(--purple)">${a.name}</td><td>${a.por}%</td><td>${badge(ppor)}</td><td>${a.perm} mD</td><td>${badge(pperm)}</td><td>${a.rf}%</td><td>${badge(prf)}</td></tr>`;
})
.join("")}
</tbody></table></div>`;
}

