let _bubbleChartInstance = null;

function renderRankBubble() {
  const data = getRankData();
  const maxRes = Math.max(...data.map((d) => d.resources));

  // Group by tier
  const tiers = [
    { label: "Tier 1", color: "#00875A", data: [] },
    { label: "Tier 2", color: "#0088CC", data: [] },
    { label: "Tier 3", color: "#C07800", data: [] },
    { label: "Tier 4", color: "#D93025", data: [] },
  ];
  data.forEach((d) => {
    const t = tiers.find((t) => t.label === d.tier) || tiers[3];
    t.data.push({
      x: d.gcos,
      y: d.resources,
      r: 6 + (d.resources / maxRes) * 22,
      _d: d,
    });
  });

  const datasets = tiers
    .filter((t) => t.data.length > 0)
    .map((t) => ({
      label: t.label,
      data: t.data,
      backgroundColor: t.color + "50",
      borderColor: t.color,
      borderWidth: 2,
      hoverBackgroundColor: t.color + "99",
      hoverBorderWidth: 3,
    }));

  const canvas = document.getElementById("rank-bubble-canvas");
  if (!canvas) return;

  if (_bubbleChartInstance) {
    _bubbleChartInstance.destroy();
    _bubbleChartInstance = null;
  }

  const yMax = Math.max(...data.map((d) => d.resources)) * 1.15;

  _bubbleChartInstance = new Chart(canvas, {
    type: "bubble",
    data: { datasets },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      animation: { duration: 900, easing: "easeOutQuart" },
      layout: { padding: { top: 10, right: 20, bottom: 10, left: 10 } },
      scales: {
        x: {
          min: 0,
          max: 100,
          title: {
            display: true,
            text: "Geological Chance of Success (GCoS %)",
            color: "#64748B",
            font: { size: 11 },
          },
          grid: { color: "rgba(226,232,240,.7)", lineWidth: 0.8 },
          ticks: { color: "#94A3B8", font: { size: 10 }, stepSize: 20 },
        },
        y: {
          min: 0,
          max: yMax,
          title: {
            display: true,
            text: "Estimated Resources (MMboe)",
            color: "#64748B",
            font: { size: 11 },
          },
          grid: { color: "rgba(226,232,240,.7)", lineWidth: 0.8 },
          ticks: { color: "#94A3B8", font: { size: 10 } },
        },
      },
      plugins: {
        legend: {
          display: true,
          position: "top",
          align: "end",
          labels: {
            boxWidth: 12,
            boxHeight: 12,
            borderRadius: 6,
            padding: 14,
            color: "#4A5568",
            font: { size: 11 },
          },
        },
        tooltip: {
          callbacks: {
            label: (ctx) => {
              const d = ctx.raw._d;
              return [
                `${d.name}`,
                `${d.country} · ${d.hc}`,
                `GCoS: ${d.gcos.toFixed(1)}%`,
                `Resources: ${Math.round(d.resources).toLocaleString()} MMboe`,
                `Score: ${d.score.toFixed(0)} · ${d.tier}`,
                `Click to shortlist`,
              ];
            },
          },
          backgroundColor: "rgba(15,23,42,.92)",
          titleColor: "#fff",
          bodyColor: "#94A3B8",
          borderColor: "rgba(255,255,255,.08)",
          borderWidth: 1,
          padding: 12,
          cornerRadius: 8,
          displayColors: false,
        },
      },
      onClick: (evt, elements) => {
        if (!elements.length) return;
        const el = elements[0];
        const pt =
          _bubbleChartInstance.data.datasets[el.datasetIndex].data[
            el.index
          ];
        const d = pt._d;
        if (!rankShortlist.find((s) => s.name === d.name)) {
          rankShortlist.push(d);
          toast("Added " + d.name + " to shortlist", "success");
        } else {
          toast(d.name + " already shortlisted", "info");
        }
      },
    },
    plugins: [
      {
        id: "bgGradient",
        beforeDraw(chart) {
          const {
            ctx,
            chartArea: { left, top, right, bottom },
          } = chart;
          const grad = ctx.createLinearGradient(left, top, right, bottom);
          grad.addColorStop(0, "rgba(0,229,160,.04)");
          grad.addColorStop(1, "rgba(255,77,106,.04)");
          ctx.save();
          ctx.fillStyle = grad;
          ctx.fillRect(left, top, right - left, bottom - top);
          ctx.restore();
        },
        afterDraw(chart) {
          // Basin name labels inside each bubble
          const { ctx } = chart;
          chart.data.datasets.forEach((ds, di) => {
            ds.data.forEach((pt, pi) => {
              const meta = chart.getDatasetMeta(di);
              const el = meta.data[pi];
              if (!el || !pt._d) return;
              ctx.save();
              ctx.fillStyle = "#1E293B";
              ctx.font = 'bold 8px "Segoe UI",system-ui,sans-serif';
              ctx.textAlign = "center";
              ctx.textBaseline = "middle";
              ctx.fillText(pt._d.name.substring(0, 12), el.x, el.y);
              ctx.restore();
            });
          });
        },
      },
    ],
  });
}

function renderRankShortlist() {
  const body = document.getElementById("rank-shortlist-body");
  const footer = document.getElementById("rank-shortlist-footer");
  if (!body || !footer) return;

  if (!rankShortlist.length) {
      body.innerHTML = '<div style="text-align:center;padding:28px;color:var(--t3);font-size:11px">No opportunities shortlisted yet. Click Auto-Shortlist or add from the Ranking Matrix.</div>';
      footer.style.display = "none";
      return;
  }

  // Show the footer since we have data
  footer.style.display = "flex";

  // Inject ONLY the table
  body.innerHTML = `
      <table>
          <thead>
              <tr>
                  <th>#</th><th>Opportunity</th><th>Country</th>
                  <th>Score</th><th>GCoS</th><th>Resources</th>
                  <th>Tier</th><th>HC Phase</th><th>Action</th>
              </tr>
          </thead>
          <tbody>
              ${rankShortlist.map((d, i) => `
                  <tr>
                      <td style="font-weight:700;color:var(--purple)">${i + 1}</td>
                      <td style="font-weight:600">${d.name}</td>
                      <td>${d.country}</td>
                      <td style="font-weight:700">${d.score.toFixed(0)}</td>
                      <td style="color:var(--cyan);font-weight:600">${d.gcos.toFixed(1)}%</td>
                      <td style="font-weight:700;color:var(--gold)">${d.resources.toLocaleString()} MMboe</td>
                      <td>
                          <span style="white-space:nowrap" class="tl ${d.tier === 'Tier 1' ? 'tl-g' : d.tier === 'Tier 2' ? 'tl-c' : d.tier === 'Tier 3' ? 'tl-a' : 'tl-r'}">
                              ${d.tier}
                          </span>
                      </td>
                      <td>${d.hc}</td>
                      <td><button class="btn2 danger" style="font-size:10px;padding:3px 8px" onclick="removeFromShortlist(${i})">Remove</button></td>
                  </tr>
              `).join("")}
          </tbody>
      </table>`;

  // Update the numbers in the HTML
  document.getElementById("stat-count").innerText = rankShortlist.length;
  document.getElementById("stat-resources").innerText = rankShortlist
      .reduce((s, d) => s + d.resources, 0)
      .toLocaleString();
}

function autoShortlist() {
  const data = getRankData();
  // Sort by composite ranking: score * gcos * resources
  data.sort(
    (a, b) =>
      b.score * b.gcos * b.resources - a.score * a.gcos * a.resources,
  );
  rankShortlist = data.slice(0, 10);
  renderRankShortlist();
  // Switch to shortlist tab
  switchRankTab(
    "shortlist",
    document.querySelectorAll("#sec-ranking .tab")[2],
  );
  toast(
    "Top 10 opportunities shortlisted based on composite score × GCoS × resources",
    "success",
  );
  addNotification(
    "Auto-shortlisted top 10 opportunities — highest composite: " +
      rankShortlist[0].name,
    "info",
  );
}

function removeFromShortlist(idx) {
  rankShortlist.splice(idx, 1);
  renderRankShortlist();
}

function pushShortlistToEcon() {
  if (!rankShortlist.length) {
    toast("Shortlist is empty", "warning");
    return;
  }
  const top = rankShortlist[0];
  const el = document.getElementById("econ-volume");
  if (el) el.value = Math.round(top.resources);
  goTo("economics", null);
  toast(
    "Pushed " + top.name + " (" + top.resources + " MMboe) → Economics",
    "success",
  );
}

// Init ranking when navigating to it
const _origGoTo = typeof goTo === "function" ? goTo : null;

