// ── Sub-tab switcher ──────────────────────────────────────────────────
function pfCfgTab(tab) {
  ["vars","formula"].forEach(t => {
    const panel = document.getElementById("pfcfg-panel-"+t);
    const btn   = document.getElementById("pfcfg-tab-"+t);
    if (!panel || !btn) return;
    const active = t === tab;
    panel.style.display  = active ? "block" : "none";
    btn.style.borderBottomColor = active ? "var(--purple)" : "transparent";
    btn.style.color      = active ? "var(--purple)" : "var(--t3)";
    btn.style.fontWeight = active ? "700" : "600";
  });
  if (tab === "formula") pfRenderVarChips();
  if (tab === "vars")    pfRenderBands();
}

// ── Mode change ───────────────────────────────────────────────────────
function pfModeChange(el) {
  pfMode = el.value;
  // Update label styles
  ["weighted","minmax","custom"].forEach(m => {
    const lbl = document.getElementById("pfmode-"+m);
    if (!lbl) return;
    const active = m === pfMode;
    lbl.style.background = active ? "var(--purple)" : "var(--bg4)";
    lbl.style.color      = active ? "#fff" : "var(--t3)";
  });
  // Show formula-mode note
  const note = document.getElementById("pf-formula-mode-note");
  if (note) note.style.display = pfMode === "custom" ? "none" : "block";
  renderPlayFairway();
}

// ── Weight helpers ────────────────────────────────────────────────────
function pfSyncWeights() {
  pfWeights = {};
  pfCriteria.forEach(c => { pfWeights[c.key] = c.weight; });
}

function pfUpdateWeightTotal() {
  const total = pfCriteria.reduce((s,c) => s + (+c.weight||0), 0);
  const el = document.getElementById("pf-weight-total");
  if (el) {
    el.textContent = `Total: ${total}%`;
    el.style.color = total === 100 ? "var(--green)" : (Math.abs(total-100)<10 ? "var(--amber)" : "var(--red)");
  }
}

function pfEqualWeights() {
  const w = Math.round(100 / pfCriteria.length);
  pfCriteria.forEach(c => { c.weight = w; });
  pfSyncWeights();
  pfRenderCriteriaList();
  renderPlayFairway();
  toast("Equal weights applied","success");
}

function pfCriterionColor(i) { return PF_CRITERION_COLORS[i % PF_CRITERION_COLORS.length]; }

function pfRenderCriteriaList() {
  const el = document.getElementById("pf-criteria-list");
  if (!el) return;
  el.innerHTML = pfCriteria.map((c, i) => {
    const col = c.color;(i);
    return `
    <div style="background:var(--bg4);border:1px solid var(--b1);border-left:3px solid ${col};
      border-radius:0 6px 6px 0;padding:7px 8px;margin-bottom:5px">
      <!-- Row 1: label + delete -->
      <div style="display:flex;align-items:center;gap:5px;margin-bottom:6px">
        <div style="width:7px;height:7px;border-radius:50%;background:${col};flex-shrink:0"></div>
        <input class="fc" value="${c.label}" style="flex:1;font-size:10px;font-weight:700;padding:2px 5px;border-color:transparent;background:transparent"
          onchange="pfCriteria[${i}].label=this.value;pfCriteria[${i}].key=this.value.toLowerCase().replace(/\\s+/g,'_');pfRenderVarChips();renderPlayFairway()">
        <button onclick="pfRemoveCriterion(${i})" style="background:none;border:none;color:var(--t3);cursor:pointer;font-size:13px;line-height:1;padding:0 2px" title="Remove">×</button>
      </div>
      <!-- Row 2: weight slider -->
      <div style="display:flex;align-items:center;gap:6px;margin-bottom:5px">
        <span style="font-size:7.5px;color:var(--t3);white-space:nowrap;min-width:40px">Weight</span>
        <input type="range" min="0" max="100" value="${c.weight}" style="flex:1;accent-color:${col}"
          oninput="pfCriteria[${i}].weight=+this.value;document.getElementById('pfw-${i}').textContent=this.value+'%';pfSyncWeights();pfUpdateWeightTotal();renderPlayFairway()">
        <span id="pfw-${i}" style="font-size:10px;font-weight:700;color:${col};min-width:30px;text-align:right">${c.weight}%</span>
      </div>
      <!-- Row 3: gates (collapsible) -->
      <details>
        <summary style="font-size:7.5px;color:var(--t3);cursor:pointer;list-style:none">
          ▸ Gate: [${c.min}–${c.max}]
        </summary>
        <div style="display:grid;grid-template-columns:1fr 1fr;gap:4px;margin-top:5px">
          <div>
            <div style="font-size:7px;color:var(--t3);margin-bottom:2px">Min Gate</div>
            <input class="fc" type="number" min="0" max="100" value="${c.min}" style="font-size:10px;padding:2px 5px"
              onchange="pfCriteria[${i}].min=+this.value;renderPlayFairway()">
          </div>
          <div>
            <div style="font-size:7px;color:var(--t3);margin-bottom:2px">Max Gate</div>
            <input class="fc" type="number" min="0" max="100" value="${c.max}" style="font-size:10px;padding:2px 5px"
              onchange="pfCriteria[${i}].max=+this.value;renderPlayFairway()">
          </div>
        </div>
      </details>
    </div>`;
  }).join("");
  pfUpdateWeightTotal();
}

// ── Bands ─────────────────────────────────────────────────────────────
function pfRenderBands() {
  const el = document.getElementById("pf-bands-list");
  if (!el) return;
  el.innerHTML = pfBands.map((b, i) => `
    <div style="display:flex;align-items:center;gap:6px;margin-bottom:5px;
                padding:6px 8px;background:var(--bg4);border-radius:5px;border:1px solid var(--b1);
                border-left:3px solid ${b.color}">
      <input type="color" value="${b.color}" style="width:22px;height:22px;border:1px solid var(--b1);border-radius:3px;padding:1px;cursor:pointer;flex-shrink:0"
        onchange="pfBands[${i}].color=this.value;renderPlayFairway()">
      <input class="fc" value="${b.label}" style="flex:1;font-size:10px;font-weight:600;padding:2px 5px"
        onchange="pfBands[${i}].label=this.value">
      <span style="font-size:10px;color:var(--t3)">Score ≥</span>
      <input class="fc" type="number" min="0" max="100" value="${b.min}" style="width:44px;font-size:10px;font-weight:700;padding:2px 5px;text-align:center"
        onchange="pfBands[${i}].min=+this.value;renderPlayFairway()">
      <button onclick="pfRemoveBand(${i})" style="background:none;border:none;color:var(--t3);cursor:pointer;font-size:13px;padding:0 1px" title="Remove">×</button>
    </div>`).join("");
}
function pfAddBand() {
  pfBands.push({ label:"New Band", min:50, color:"#6366f1" });
  pfRenderBands();
}
function pfRemoveBand(i) {
  if (pfBands.length <= 1) { toast("Need at least one band","warn"); return; }
  pfBands.splice(i,1);
  pfRenderBands();
  renderPlayFairway();
}

// ── Variable chips (Formula tab) ──────────────────────────────────────
function pfRenderVarChips() {
  const cont = document.getElementById("pf-var-chips");
  const testCont = document.getElementById("pf-test-vals");
  if (!cont) return;
  cont.innerHTML = pfCriteria.map((c,i) => {
    const col = pfCriterionColor(i);
    return `<button onclick="pfInsertVar('${c.key}')"
      style="font-size:10px;padding:3px 9px;border:1px solid ${col};border-radius:4px;
              cursor:pointer;background:transparent;color:${col};font-weight:700;
              font-family:monospace;transition:all .15s"
      title="${c.label} (range ${c.min}–${c.max})">${c.key}</button>`;
  }).join("");

  // Render helper buttons
  const helperCont = document.getElementById("pf-helper-btns");
  if (helperCont) {
    const helpers = [
      ["Math.min(a,b)","min"],["Math.max(a,b)","max"],["Math.pow(x,n)","pow"],
      ["Math.sqrt(x)","sqrt"],["Math.log(x)","log"],["Math.abs(x)","abs"],
      ["clamp(x,lo,hi)","clamp"],["normalise(x,mn,mx)","normalise"]
    ];
    helperCont.innerHTML = `<span style="font-size:10px;color:var(--t3);align-self:center">Helpers:</span>` +
      helpers.map(([snippet, label]) =>
        `<button onclick="pfInsertSnippet('${snippet}')"
          style="font-size:7.5px;padding:2px 6px;background:var(--bg3);border:1px solid var(--b1);
                  border-radius:3px;cursor:pointer;color:var(--t2);font-family:monospace"
          title="${snippet}">${label}</button>`
      ).join("");
  }

  // Render test value inputs
  if (testCont) {
    testCont.innerHTML = pfCriteria.map((c,i) => {
      const col = pfCriterionColor(i);
      return `<div>
        <div style="font-size:7.5px;color:${col};font-weight:700;margin-bottom:2px">${c.key}</div>
        <input type="number" min="0" max="100" step="1" value="50"
          id="pf-tval-${c.key}"
          style="width:100%;font-size:10px;padding:2px 5px;background:var(--bg3);
                  border:1px solid var(--b1);border-radius:3px;color:var(--t1)"
          oninput="pfValidateFormula()">
      </div>`;
    }).join("");
  }
  // Update formula-mode note visibility
  const note = document.getElementById("pf-formula-mode-note");
  if (note) note.style.display = pfMode === "custom" ? "none" : "block";
}

function pfInsertVar(varName) {
  const ta = document.getElementById("pf-formula-input");
  if (!ta) return;
  const s = ta.selectionStart, e = ta.selectionEnd;
  ta.value = ta.value.slice(0,s) + varName + ta.value.slice(e);
  ta.selectionStart = ta.selectionEnd = s + varName.length;
  ta.focus();
  pfValidateFormula();
  renderPlayFairway();
}
function pfInsertSnippet(snippet) {
  const ta = document.getElementById("pf-formula-input");
  if (!ta) return;
  const s = ta.selectionStart, e = ta.selectionEnd;
  ta.value = ta.value.slice(0,s) + snippet + ta.value.slice(e);
  ta.selectionStart = ta.selectionEnd = s + snippet.length;
  ta.focus();
  pfValidateFormula();
  renderPlayFairway();
}
function pfHandleFormulaKey(e) {
  if (e.key === "Tab") { e.preventDefault(); pfInsertSnippet("  "); }
  if ((e.ctrlKey||e.metaKey) && e.key === "Enter") { e.preventDefault(); pfValidateFormula(true); }
}
function pfLoadExampleFormula() {
  const ta = document.getElementById("pf-formula-input");
  if (!ta) return;
  const keys = pfCriteria.map(c=>c.key);
  const total = pfCriteria.reduce((s,c)=>s+c.weight,0)||1;
  const parts = pfCriteria.map(c=>`${c.key} * ${(c.weight/total).toFixed(2)}`).join(" +\n  ");
  ta.value = `// Weighted composite — customise weights and logic\n${parts}`;
  pfValidateFormula();
  renderPlayFairway();
}

// ── Formula validation ────────────────────────────────────────────────
function pfValidateFormula(showToast) {
  const ta    = document.getElementById("pf-formula-input");
  const errEl = document.getElementById("pf-formula-error");
  const okEl  = document.getElementById("pf-formula-ok");
  if (!ta || !errEl || !okEl) return;
  const expr = ta.value.trim();
  if (!expr) { errEl.style.display="none"; okEl.style.display="none"; return; }
  const keys   = pfCriteria.map(c => c.key);
  const testVals = keys.map(k => {
    const inp = document.getElementById("pf-tval-"+k);
    return inp ? +inp.value : 50;
  });
  const helperFns = `
    function clamp(v,lo,hi){return Math.max(lo,Math.min(hi,v));}
    function normalise(v,mn,mx){return mn===mx?0:Math.max(0,Math.min(100,(v-mn)/(mx-mn)*100));}
  `;
  try {
    const fn = new Function(...keys, helperFns + `"use strict"; return (${expr});`);
    const result = fn(...testVals);
    if (typeof result !== "number" || isNaN(result))
      throw new Error("Formula must return a number");
    errEl.style.display = "none";
    okEl.style.display  = "block";
    okEl.textContent    = `✓ Valid — test result: ${result.toFixed(1)} / 100`;
    if (showToast) toast(`Formula valid → ${result.toFixed(1)}`, "success");
  } catch(e) {
    errEl.textContent   = "⚠ " + e.message;
    errEl.style.display = "block";
    okEl.style.display  = "none";
  }
}

// ── Add / Remove criterion ────────────────────────────────────────────
function pfAddCriterion() {
  const name   = (document.getElementById("pf-new-name")?.value||"").trim();
  const weight = +(document.getElementById("pf-new-weight")?.value||10);
  const min    = +(document.getElementById("pf-new-min")?.value||0);
  const max    = +(document.getElementById("pf-new-max")?.value||100);
  if (!name) { toast("Enter a variable name","warn"); return; }
  const key   = name.toLowerCase().replace(/\s+/g,"_");
  const phase = [Math.random()*1.2+0.2, Math.random()*0.9+0.1];
  pfCriteria.push({ key, label:name, weight, min, max, phase });
  pfSyncWeights();
  if (document.getElementById("pf-new-name")) document.getElementById("pf-new-name").value="";
  pfRenderCriteriaList();
  pfRenderVarChips();
  renderPlayFairway();
  toast(`Variable "${name}" added`,"success");
}
function pfRemoveCriterion(i) {
  if (pfCriteria.length <= 1) { toast("At least one variable required","warn"); return; }
  const name = pfCriteria[i].label;
  pfCriteria.splice(i,1);
  pfSyncWeights();
  pfRenderCriteriaList();
  pfRenderVarChips();
  renderPlayFairway();
  toast(`"${name}" removed`,"info");
}

// ── Reset ─────────────────────────────────────────────────────────────
function pfResetConfig() {
  pfCriteria = [
    {key:"source",    label:"Source Rock",    weight:25,min:0,max:100,phase:[0.8,0.3]},
    {key:"reservoir", label:"Reservoir",       weight:25,min:0,max:100,phase:[0.5,0.7]},
    {key:"seal",      label:"Seal Integrity",  weight:20,min:0,max:100,phase:[0.3,0.5]},
    {key:"trap",      label:"Trap Geometry",   weight:15,min:0,max:100,phase:[0.9,0.2]},
    {key:"timing",    label:"Charge Timing",   weight:15,min:0,max:100,phase:[0.4,0.6]},
  ];
  pfBands = [
    {label:"Very High",min:80,color:"#1a8c50"},
    {label:"High",     min:65,color:"#5aaa30"},
    {label:"Moderate", min:45,color:"#c8a010"},
    {label:"Low",      min:28,color:"#d05818"},
    {label:"Very Low", min:0, color:"#b41e1e"},
  ];
  pfMode = "weighted";
  document.querySelectorAll('input[name="pfMode"]').forEach(r => { r.checked = r.value==="weighted"; });
  pfModeChange({value:"weighted"});
  pfSyncWeights();
  pfRenderCriteriaList();
  pfRenderBands();
  pfRenderVarChips();
  renderPlayFairway();
  toast("Configuration reset to defaults","info");
}

// ── Presets ───────────────────────────────────────────────────────────
function pfSavePreset() {
  const nameEl = document.getElementById("pf-preset-save-name");
  const name   = (nameEl?.value||prompt("Preset name:")||"").trim();
  if (!name) return;
  PF_PRESETS[name] = JSON.parse(JSON.stringify(pfCriteria));
  if (nameEl) nameEl.value = "";
  const cont = document.getElementById("pf-custom-presets");
  if (cont) {
    const btn = document.createElement("button");
    btn.className = "btn2";
    btn.style.cssText = "font-size:10px;padding:5px 10px";
    btn.textContent = "📋 " + name;
    btn.onclick = () => pfLoadPreset(name);
    cont.appendChild(btn);
  }
  toast(`Preset "${name}" saved`,"success");
}
function pfLoadPreset(key) {
  const preset = PF_PRESETS[key];
  if (!preset) return;
  pfCriteria = preset.map((c,i) => ({
    ...c, label:c.label||c.key, min:c.min??0, max:c.max??100,
    phase:[0.2+i*0.31, 0.15+i*0.27]
  }));
  pfSyncWeights();
  pfRenderCriteriaList();
  pfRenderVarChips();
  renderPlayFairway();
  toast(`Preset "${key}" loaded`,"success");
}

// ── Saved formulas ────────────────────────────────────────────────────
let pfSavedFormulas = [];
function pfSaveFormula() {
  const nameEl    = document.getElementById("pf-formula-save-name");
  const formulaEl = document.getElementById("pf-formula-input");
  const name      = (nameEl?.value||"").trim();
  const formula   = (formulaEl?.value||"").trim();
  if (!name)    { toast("Enter a name for the formula","warn"); return; }
  if (!formula) { toast("Formula is empty","warn"); return; }
  try {
    const keys = pfCriteria.map(c=>c.key);
    const fn = new Function(...keys, `"use strict"; return (${formula});`);
    fn(...keys.map(()=>50));
  } catch(e) { toast("Formula has a syntax error — fix before saving","error"); return; }
  const existing = pfSavedFormulas.findIndex(f=>f.name===name);
  if (existing>=0) pfSavedFormulas[existing].formula=formula;
  else pfSavedFormulas.push({name, formula});
  if (nameEl) nameEl.value = "";
  pfRenderSavedFormulas();
  toast(`Formula "${name}" saved`,"success");
}
function pfRenderSavedFormulas() {
  const wrap = document.getElementById("pf-saved-formulas-wrap");
  const list = document.getElementById("pf-saved-formulas-list");
  if (!wrap||!list) return;
  if (!pfSavedFormulas.length) { wrap.style.display="none"; return; }
  wrap.style.display = "block";
  list.innerHTML = pfSavedFormulas.map((f,i) => `
    <div style="display:flex;align-items:center;gap:6px;padding:6px 8px;
                background:var(--bg4);border:1px solid var(--b1);border-radius:5px;margin-bottom:4px">
      <div style="flex:1;min-width:0">
        <div style="font-size:10px;font-weight:700;color:var(--t1)">${f.name}</div>
        <div style="font-size:7.5px;color:var(--t3);font-family:monospace;
                    white-space:nowrap;overflow:hidden;text-overflow:ellipsis"
              title="${f.formula}">${f.formula}</div>
      </div>
      <button class="btn2" style="font-size:10px;padding:2px 7px" onclick="pfLoadFormula(${i})">Load</button>
      <button style="background:none;border:none;color:var(--t3);cursor:pointer;font-size:13px;padding:0 2px"
        onclick="pfDeleteFormula(${i})">×</button>
    </div>`).join("");
}
function pfLoadFormula(i) {
  const f = pfSavedFormulas[i]; if (!f) return;
  const el = document.getElementById("pf-formula-input");
  if (el) { el.value = f.formula; pfValidateFormula(); renderPlayFairway(); }
  toast(`Formula "${f.name}" loaded`,"success");
}
function pfDeleteFormula(i) {
  const name = pfSavedFormulas[i]?.name;
  pfSavedFormulas.splice(i,1);
  pfRenderSavedFormulas();
  toast(`Formula "${name}" deleted`,"info");
}

// ── Score computation ─────────────────────────────────────────────────
function pfComputeScore(gx, gy, basinShiftX, basinShiftY) {
  const vals = {};
  pfCriteria.forEach(c => {
    const [px,py] = c.phase || [0.5,0.5];
    vals[c.key] = (Math.sin((gx+basinShiftX)*px + (gy+basinShiftY)*py)*0.5+0.5)*100;
  });

  if (pfMode === "custom") {
    try {
      const formulaStr = document.getElementById("pf-formula-input")?.value?.trim();
      if (!formulaStr) return pfComputeWeighted(vals);
      const keys = pfCriteria.map(c=>c.key);
      const helperFns = `
        function clamp(v,lo,hi){return Math.max(lo,Math.min(hi,v));}
        function normalise(v,mn,mx){return mn===mx?0:Math.max(0,Math.min(100,(v-mn)/(mx-mn)*100));}
      `;
      const fn = new Function(...keys, helperFns + `"use strict"; return Math.min(100,Math.max(0,(${formulaStr}))); `);
      const result = fn(...keys.map(k=>vals[k]??50));
      const errEl = document.getElementById("pf-formula-error");
      if (errEl) errEl.style.display = "none";
      return isNaN(result) ? 0.5 : Math.min(1, Math.max(0, result/100));
    } catch(e) {
      const errEl = document.getElementById("pf-formula-error");
      if (errEl) { errEl.textContent = "Formula error: "+e.message; errEl.style.display="block"; }
      return 0.5;
    }
  }
  if (pfMode === "minmax") {
    let score = pfComputeWeighted(vals);
    pfCriteria.forEach(c => {
      const v = vals[c.key]??50;
      if (v < c.min || v > c.max) score *= 0.3;
    });
    return score;
  }
  return pfComputeWeighted(vals);
}

function pfComputeWeighted(vals) {
  const totalW = pfCriteria.reduce((s,c)=>s+(c.weight||0),0)||1;
  return pfCriteria.reduce((s,c)=>s+(vals[c.key]??50)*(c.weight||0),0) / (totalW*100);
}

function pfBandColor(score) {
  const sorted = [...pfBands].sort((a,b)=>b.min-a.min);
  for (const b of sorted) if (score*100 >= b.min) return b.color;
  return sorted[sorted.length-1]?.color||"#b41e1e";
}

// ── Basin filter shared across Heatmap → CRS → Lead Inventory ─────────
function pfSetBasinFilter(basinName) {
  _pfBasinFilter = basinName || null;

  // Sync dropdown
  const sel = document.getElementById('pf-basin-sel');
  if (sel) sel.value = basinName || 'All Basins';

  // Re-render heatmap (reflects highlight)
  renderPlayFairway();

  // Toast notification
  _pfBasinToast(_pfBasinFilter);

  // Tab dot badges
  _pfUpdateBadges();
}

function _pfBasinToast(name) {
  let t = document.getElementById('_pf_toast');
  if (!t) {
    t = document.createElement('div');
    t.id = '_pf_toast';
    t.style.cssText = 'position:fixed;bottom:68px;left:50%;transform:translateX(-50%);' +
      'background:rgba(124,58,237,0.93);color:#fff;font-size:10px;font-weight:700;' +
      'padding:7px 18px;border-radius:20px;z-index:99999;pointer-events:none;' +
      'transition:opacity .35s;box-shadow:0 4px 18px rgba(0,0,0,.3);white-space:nowrap';
    document.body.appendChild(t);
  }
  t.textContent = name
    ? '\u{1F4CD} ' + name + ' \u2014 CRS & Lead Inventory filtered'
    : '\u{1F30D} All Basins \u2014 filter cleared';
  t.style.opacity = '1';
  clearTimeout(t._hide);
  t._hide = setTimeout(() => t.style.opacity = '0', 2800);
}

function _pfUpdateBadges() {
  document.querySelectorAll('#sec-playfairway .tabs .tab').forEach((tab, i) => {
    if (i === 0) return;
    let dot = tab.querySelector('._pf_badge');
    if (_pfBasinFilter) {
      if (!dot) {
        dot = document.createElement('span');
        dot.className = '_pf_badge';
        dot.style.cssText = 'display:inline-block;width:6px;height:6px;border-radius:50%;' +
          'background:var(--purple);margin-left:5px;vertical-align:middle';
        tab.appendChild(dot);
      }
      dot.title = 'Filtered: ' + _pfBasinFilter;
    } else if (dot) {
      dot.remove();
    }
  });
}

function switchPFTab(tab, el) {
  ["heatmap","crs","leads"].forEach(t => {
    const p = document.getElementById("pf-"+t+"-panel");
    if (p) p.style.display = t===tab ? "block" : "none";
  });

  el.parentElement
    .querySelectorAll(".tab")
    .forEach((t) => t.classList.remove("on"));

  el.classList.add("on");

  // ✅ Update breadcrumb
  const bc = document.getElementById("breadcrumb-section");
  if (bc) {
    bc.textContent = el.textContent.trim();
  }

  if (tab === "crs") renderCRS();
  if (tab === "leads") renderLeadInventory();
}

function initPlayFairway() {
  const sel = document.getElementById("pf-basin-sel");
  if (sel && sel.options.length <= 1) {
    BASINS.forEach(b => {
      const o = document.createElement("option");
      o.value = b.name; o.textContent = b.name;
      sel.appendChild(o);
    });
  }
  // Always reset to heatmap tab on entry
  ["heatmap","crs","leads"].forEach(t => {
    const p = document.getElementById("pf-"+t+"-panel");
    if (p) p.style.display = t === "heatmap" ? "block" : "none";
  });
  pfRenderCriteriaList();
  pfCfgTab("vars");
  renderPlayFairway();
}

function renderPlayFairway() {
  const container = document.getElementById("pf-heatmap-grid");
  if (!container) return;

  const ROW_LABELS = [
    "Triassic","Jurassic","Cretaceous","Paleocene","Eocene",
    "Oligocene","Miocene","Pliocene","Pleistocene","Holocene",
    "Pre-Cambrian","Permian","Carbonif.","Devonian","Silurian","Ordovician",
  ];
  const COL_LABELS = [
    "W.Africa","E.Africa","N.Africa","Middle E.","Caspian",
    "N.Sea","NW.Europe","W.Siberia","E.Siberia","SE.Asia",
    "Australasia","S.America","N.America","Arctic","Caribbean",
    "GoM","Rockies","Andean","Barents","Labrador",
  ];

  const gridW = COL_LABELS.length, gridH = ROW_LABELS.length;
  const allBasins = leaderboardData.length ? leaderboardData : BASINS;

  const selVal = (document.getElementById("pf-basin-sel")?.value || "").trim();
  const selectedBasin = selVal ? allBasins.find(b => b.name === selVal) : null;

  let basinBias = 0, basinScoreMod = 1, basinShiftX = 0, basinShiftY = 0;
  if (selectedBasin) {
    let nameHash = 0;
    for (let i = 0; i < selectedBasin.name.length; i++)
      nameHash = (nameHash * 31 + selectedBasin.name.charCodeAt(i)) & 0xffff;
    basinBias    = (selectedBasin.score || 50) / 100;
    basinScoreMod = 0.5 + basinBias;
    basinShiftX  = (nameHash % 7) * 0.37;
    basinShiftY  = ((nameHash >> 4) % 5) * 0.41;
  }

  const basinOverlay = {};
  const overlayBasins = selectedBasin ? [selectedBasin] : allBasins.slice(0, 12);
  overlayBasins.forEach((b, i) => {
    const col = selectedBasin
      ? Math.round(gridW * 0.3 + (i % 3) * Math.round(gridW * 0.2)) % gridW
      : (i * 3 + 7) % gridW;
    const row = selectedBasin
      ? Math.round(gridH * 0.3 + (i % 3) * Math.round(gridH * 0.2)) % gridH
      : (i * 5 + 3) % gridH;
    basinOverlay[`${col}_${row}`] = b.name.substring(0, 6);
  });

  const LABEL_COL_W = 68;
  const CELL_H = 26;

  let html = `<div style="display:flex;flex-direction:column;user-select:none">`;

  html += `<div style="display:flex;margin-left:${LABEL_COL_W}px">`;
  for (let gx = 0; gx < gridW; gx++) {
    html += `<div style="flex:1;min-width:0;text-align:center;font-size:7px;font-weight:700;
      color:#64748B;padding:3px 1px 4px;letter-spacing:.2px;white-space:nowrap;
      overflow:hidden;text-overflow:ellipsis" title="${COL_LABELS[gx]}">${COL_LABELS[gx]}</div>`;
  }
  html += `</div>`;

  for (let gy = 0; gy < gridH; gy++) {
    html += `<div style="display:flex;align-items:stretch;height:${CELL_H}px">`;
    html += `<div style="width:${LABEL_COL_W}px;flex-shrink:0;display:flex;align-items:center;
      font-size:7.5px;font-weight:700;color:#475569;padding-right:5px;
      text-align:right;justify-content:flex-end;letter-spacing:.2px;
      border-right:2px solid #E2E8F0;white-space:nowrap">${ROW_LABELS[gy]}</div>`;

    for (let gx = 0; gx < gridW; gx++) {
      const raw = pfComputeScore(gx, gy, basinShiftX, basinShiftY);
      const score = selectedBasin
        ? Math.min(1, Math.max(0, raw * basinScoreMod * (0.6 + basinBias * 0.8)))
        : raw;
      const scoreInt = Math.round(score * 100);
      const bandHex  = pfBandColor(score);
      const br = parseInt(bandHex.slice(1,3),16);
      const bg2= parseInt(bandHex.slice(3,5),16);
      const bb = parseInt(bandHex.slice(5,7),16);
      const textColor = score > 0.55 ? "rgba(255,255,255,0.95)"
                      : score < 0.3  ? "rgba(255,255,255,0.92)"
                      : "rgba(0,0,0,0.75)";
      const bg = `rgb(${br},${bg2},${bb})`;
      const isBasin     = basinOverlay[`${gx}_${gy}`];
      const cellFullName = isBasin
        ? (overlayBasins.find(b => b.name.substring(0,6) === isBasin))?.name || ''
        : '';
      const isSelected   = cellFullName && cellFullName === _pfBasinFilter;

      html += `<div style="flex:1;min-width:0;background:${bg};display:flex;flex-direction:column;
        align-items:center;justify-content:center;position:relative;
        cursor:${cellFullName ? 'pointer' : 'default'};
        border:0.5px solid ${isSelected ? 'rgba(255,255,255,0.85)' : 'rgba(0,0,0,0.08)'};
        ${isSelected ? 'box-shadow:inset 0 0 0 2px rgba(255,255,255,0.7);' : ''}
        transition:filter .15s"
        title="${COL_LABELS[gx]} · ${ROW_LABELS[gy]} | Score: ${scoreInt}${cellFullName ? ' · Click to filter: ' + cellFullName : ''}"
        onmouseenter="this.style.filter='brightness(1.18)';this.style.zIndex=10"
        onmouseleave="this.style.filter='';this.style.zIndex=0"
        ${cellFullName ? 'onclick="pfSetBasinFilter(\'' + cellFullName.replace(/'/g,"\\'") + '\')"' : ''}>`;

      if (isBasin) {
        html += `<div style="font-size:5.5px;font-weight:900;color:#fff;background:rgba(0,0,0,.22);border-radius:2px;padding:1px 2px;line-height:1;margin-bottom:1px;white-space:nowrap">${isBasin}</div>`;
        html += `<div style="font-size:5.5px;font-weight:400;color:#fff;background:rgba(0,0,0,.18);border-radius:2px;padding:1px 2px;line-height:1;white-space:nowrap">${scoreInt}</div>`;
      } else {
        html += `<div style="font-size:5.5px;font-weight:400;color:${textColor};line-height:1">${scoreInt}</div>`;
      }

      html += `</div>`;
    }
    html += `</div>`;
  }

  const sortedBands = [...pfBands].sort((a, b) => a.min - b.min);
  const gradStops = sortedBands
    .map((b, i) => `${b.color} ${Math.round((i / (sortedBands.length - 1)) * 100)}%`)
    .join(",");
  html += `<div style="display:flex;align-items:center;gap:10px;padding:8px ${LABEL_COL_W+4}px 6px;border-top:1px solid var(--b1);margin-top:2px">
    <span style="font-size:10px;font-weight:700;color:#94A3B8;letter-spacing:.5px">PROSPECTIVITY</span>
    <div style="flex:1;height:8px;border-radius:4px;background:linear-gradient(to right,${gradStops});border:1px solid rgba(0,0,0,.1)"></div>
    <div style="display:flex;gap:10px">
      ${sortedBands.map(b => `<span style="font-size:10px;font-weight:700;color:${b.color}">${b.label}</span>`).join("")}
    </div>
  </div>`;

  html += `</div>`;
  container.innerHTML = html;
}

// ══════════════════════════════════════════════════════════════
// SHARED CRS/LEADS INFRASTRUCTURE
// ══════════════════════════════════════════════════════════════

// Active CRS filter — set when user clicks a segment in CRS tab
let _activeCrsFilter = null; // null = show all; string segId = filter to that segment
let _pfBasinFilter   = null;  // basin name from heatmap dropdown/cell click

// Shared: get element scores for a basin (leaderboard or estimated)
function _pfGetScores(b) {
  if (b.scores) return b.scores;
  const seed = b.name.length + (b.score || 50);
  const R = (base, off) => Math.max(10, Math.min(100,
    Math.round(base + ((seed * 17 + off * 31) % 21) - 10)));
  return {
    source:     R(b.score * 0.95, 1),
    reservoir:  R(b.score * 0.98, 2),
    seal:       R(b.score * 0.88, 3),
    charge:     R(b.score * 0.92, 4),
    commercial: R(b.score * 0.85, 5),
    country:    R(b.score * 0.96, 6),
  };
}

// Shared: build CRS definitions from current pfBands thresholds
function _pfCrsDefs() {
  const sorted  = [...pfBands].sort((a, b) => b.min - a.min);
  const FAV     = sorted.length >= 2 ? sorted[1].min : 60;
  const PROVEN  = sorted[0]?.min ?? 75;
  return [
    { id:'A', name:'Proven Kitchen + Reservoir',
      desc:'Both source and reservoir score in the top band — highest geological confidence',
      hex:'#00C882', rgb:'0,200,130', risk:'Low',     confidence: 1.25,
      test: s => s.source >= PROVEN && s.reservoir >= PROVEN },
    { id:'B', name:'Strong Source, Unproven Reservoir',
      desc:'Excellent source rock; reservoir needs validation — charge risk is low',
      hex:'#00C8FF', rgb:'0,200,255', risk:'Low–Med', confidence: 1.10,
      test: s => s.source >= FAV && s.reservoir >= 45 && s.reservoir < PROVEN },
    { id:'C', name:'Reservoir + Seal Fairway',
      desc:'Good reservoir-seal pairing; source kitchen unproven — migration risk remains',
      hex:'#3B82F6', rgb:'59,130,246', risk:'Medium', confidence: 0.95,
      test: s => s.reservoir >= FAV && s.seal >= FAV && s.source < FAV },
    { id:'D', name:'Charge-Dominated Play',
      desc:'High charge efficiency; reservoir quality variable — migration is the key driver',
      hex:'#7C3AED', rgb:'124,58,237', risk:'Medium', confidence: 0.90,
      test: s => s.charge >= FAV && s.source >= 50 && s.reservoir < FAV },
    { id:'E', name:'Seal Risk Dominant',
      desc:'Source and reservoir are favourable; seal integrity is the limiting factor',
      hex:'#F0A500', rgb:'240,165,0',  risk:'Med–High', confidence: 0.75,
      test: s => s.source >= FAV && s.reservoir >= FAV && s.seal < FAV },
    { id:'F', name:'Commercial / Country Gated',
      desc:'Strong geology but commercial or country risk caps the investment case',
      hex:'#E88C00', rgb:'232,140,0',  risk:'Med–High', confidence: 0.70,
      test: s => (s.source+s.reservoir+s.seal)/3 >= FAV &&
                  (s.commercial < FAV || s.country < FAV) },
    { id:'G', name:'Frontier — All Elements Uncertain',
      desc:'Low confidence across all elements — early-stage exploration only',
      hex:'#EF4444', rgb:'239,68,68',  risk:'High',   confidence: 0.50,
      test: s => (s.source+s.reservoir+s.seal+s.charge)/4 < FAV },
  ];
}

// Shared: classify a basin into its best-matching CRS segment
function _pfClassifyBasin(b) {
  const s    = _pfGetScores(b);
  const defs = _pfCrsDefs();
  for (const seg of defs) {
    if (seg.test(s)) return { seg, s };
  }
  return { seg: defs[defs.length - 1], s };
}

// CRS-adjusted GCoS: raw multiplicative chain × segment confidence factor
// clamped 1–95%
function _leadGCoS(scores, crsConfidence) {
  if (!scores) return 0;
  const ps  = Math.min((scores.source      || 50) / 100, 0.95);
  const pr  = Math.min((scores.reservoir   || 50) / 100, 0.95);
  const pse = Math.min((scores.seal        || 50) / 100, 0.95);
  const pt  = Math.min((scores.charge      || 50) / 100, 0.95);
  const pm  = Math.min(((scores.commercial || 50) / 100) * 0.9, 0.95);
  const raw = ps * pr * pse * pt * pm;
  const adj = raw * (crsConfidence ?? 1.0);
  return Math.min(95, Math.max(1, Math.round(adj * 100)));
}

function _leadPlayType(b) {
  const t = (b.tectonic || '').toLowerCase();
  if (t.includes('fold') || t.includes('foreland'))   return 'Structural';
  if (t.includes('passive') || t.includes('deltaic')) return 'Stratigraphic';
  if (t.includes('rift') || t.includes('intracratonic')) return 'Combination';
  return ['Structural','Stratigraphic','Combination'][b.name.length % 3];
}

function _leadP50(b, comp) {
  const scoreFrac = (comp || b.score || 50) / 100;
  const areaMmb   = (b.area || 50000) * scoreFrac * 0.0008;
  const playMult  = Math.sqrt(b.plays || 5) / Math.sqrt(10);
  return Math.round(areaMmb * playMult);
}

function _leadTier(comp) {
  if (comp >= 70) return 'HIGH';
  if (comp >= 40) return 'MED';
  return 'LOW';
}

// Build the full enriched lead record for a basin
function _buildLead(b, i) {
  const scores = _pfGetScores(b);
  const { seg } = _pfClassifyBasin(b);
  const comp  = b.composite || b.score || 0;
  const gcos  = _leadGCoS(scores, seg.confidence);
  const p50   = _leadP50(b, comp);
  return {
    id:      `L-${String(b.rank || i + 1).padStart(3, '0')}`,
    basin:   b.name, country: b.country, region: b.region,
    hc:      b.hc, status: b.status, tectonic: b.tectonic,
    type:    _leadPlayType(b),
    comp, gcos, p10: Math.round(p50 * 3.2), p50,
    p90:     Math.round(p50 * 0.3),
    scores, tier: _leadTier(comp),
    plays:   b.plays || 0, area: b.area || 0,
    rank:    b.rank || i + 1,
    crsId:   seg.id, crsName: seg.name,
    crsHex:  seg.hex, crsRgb: seg.rgb, crsRisk: seg.risk,
    crsConf: seg.confidence,
  };
}

// ══════════════════════════════════════════════════════════════
// COMMON RISK SEGMENTS
// ══════════════════════════════════════════════════════════════
function renderCRS() {
  const body = document.getElementById('pf-crs-body');
  if (!body) return;

  const allBasins = leaderboardData.length ? leaderboardData : BASINS;

  // Populate region filter once
  const regionSel = document.getElementById('crs-region-filter');
  if (regionSel && regionSel.options.length <= 1) {
    [...new Set(BASINS.map(b => b.region))].sort().forEach(r => {
      const o = document.createElement('option');
      o.value = r; o.textContent = r;
      regionSel.appendChild(o);
    });
  }

  const hcFilter     = document.getElementById('crs-hc-filter')?.value || '';
  const regionFilter = document.getElementById('crs-region-filter')?.value || '';
  const defs         = _pfCrsDefs();
  const sorted       = [...pfBands].sort((a, b) => b.min - a.min);
  const FAV          = sorted.length >= 2 ? sorted[1].min : 60;
  const PROVEN       = sorted[0]?.min ?? 75;

  let filtered = allBasins.filter(b => {
    if (hcFilter       && b.hc     !== hcFilter)       return false;
    if (regionFilter   && b.region !== regionFilter)   return false;
    if (_pfBasinFilter && b.name   !== _pfBasinFilter) return false;
    return true;
  });

  // Group by segment using shared classifier
  const groups = {};
  defs.forEach(seg => { groups[seg.id] = { seg, basins: [] }; });
  filtered.forEach((b, i) => {
    const { seg, s } = _pfClassifyBasin(b);
    groups[seg.id].basins.push({ ...b, _elemScores: s, _lead: _buildLead(b, i) });
  });

  const hasLb      = leaderboardData.length > 0;
  const dataSource = hasLb
    ? `<span style="color:var(--green)">● Live — screening engine (${leaderboardData.length} basins)</span>`
    : `<span style="color:var(--amber)">● Estimated — run Basin Screening for analogue-informed scores</span>`;
  const riskColor  = r => r === 'Low' ? 'var(--green)' : r.includes('High') ? 'var(--red)' : 'var(--amber)';
  const elColors   = {source:'var(--green)',reservoir:'var(--blue)',seal:'var(--cyan)',
                      charge:'var(--purple)',commercial:'var(--amber)',country:'var(--red)'};

  body.innerHTML = `
    ${_pfBasinFilter ? `
      <div style="padding:7px 14px;background:rgba(124,58,237,0.08);
        border-bottom:1px solid rgba(124,58,237,0.28);font-size:10px;font-weight:700;
        color:var(--purple);display:flex;align-items:center;gap:8px">
        \u{1F4CD} Basin: ${_pfBasinFilter}
        <button onclick="pfSetBasinFilter('')" style="margin-left:auto;font-size:10px;
          padding:2px 9px;background:rgba(124,58,237,.12);border:1px solid rgba(124,58,237,.3);
          border-radius:4px;cursor:pointer;color:var(--purple)">\u2715 Clear</button>
      </div>
    ` : ''}
      <div style="padding:8px 14px;background:var(--bg4);border-bottom:1px solid var(--b1);
        font-size:10px;color:var(--t3);display:flex;align-items:center;gap:8px;flex-wrap:wrap">
        ${dataSource}
        <span style="color:var(--t3)">·</span>
        <span>Favourable \u2265${FAV} · Proven \u2265${PROVEN}</span>
        <span style="margin-left:auto;color:var(--purple);font-weight:600">
          Click a segment to filter Lead Inventory \u2192
        </span>
      </div>
    ${defs.map(seg => {
      const group  = groups[seg.id];
      const basins = group.basins;
      if (!basins.length) return '';

      const totalArea = basins.reduce((s, b) => s + (b.area || 0), 0);
      const avgScore  = Math.round(basins.reduce((s, b) => s + (b.composite || b.score || 0), 0) / basins.length);
      const avgGcos   = Math.round(basins.reduce((s, b) => s + b._lead.gcos, 0) / basins.length);
      const totalP50  = basins.reduce((s, b) => s + b._lead.p50, 0);
      const confPct   = Math.round(seg.confidence * 100);
      const confCol   = seg.confidence >= 1.1 ? 'var(--green)' : seg.confidence >= 0.9 ? 'var(--amber)' : 'var(--red)';
      const areaFmt   = totalArea > 999999
        ? (totalArea / 1e6).toFixed(1) + 'M' : (totalArea / 1000).toFixed(0) + 'k';

      return `
      <div style="border-bottom:1px solid var(--b1)">
        <details>
          <summary 
            style="display:flex;align-items:center;gap:10px;padding:11px 14px;
            cursor:pointer;list-style:none;background:var(--bg3);user-select:none"
            onmouseover="this.style.background='var(--bg4)'"
            onmouseout="this.style.background='var(--bg3)'">
            <div style="width:4px;height:44px;border-radius:2px;background:${seg.hex};flex-shrink:0"></div>
            <div style="flex:1;min-width:0">
              <div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap">
                <span style="font-size:10px;font-weight:700;color:var(--t1)">CRS-${seg.id}: ${seg.name}</span>
                <span style="font-size:10px;padding:2px 7px;border-radius:3px;font-weight:700;
                        background:${riskColor(seg.risk)}22;color:${riskColor(seg.risk)};
                        border:1px solid ${riskColor(seg.risk)}44">${seg.risk} Risk</span>
                <span style="font-size:10px;padding:2px 7px;border-radius:3px;font-weight:700;
                        background:${confCol}18;color:${confCol};border:1px solid ${confCol}33"
                      title="GCoS confidence multiplier — how much CRS membership adjusts lead probability">
                  GCoS ×${seg.confidence.toFixed(2)}
                </span>
              </div>
              <div style="font-size:10px;color:var(--t3);margin-top:2px">${seg.desc}</div>
            </div>
            <!-- Stats -->
            <div style="display:flex;gap:14px;flex-shrink:0;text-align:center">
              <div><div style="font-size:15px;font-weight:800;color:${seg.hex}">${basins.length}</div>
                    <div style="font-size:7px;color:var(--t3)">Basins</div></div>
              <div><div style="font-size:15px;font-weight:800;color:var(--t1)">${avgScore}</div>
                    <div style="font-size:7px;color:var(--t3)">Avg Score</div></div>
              <div><div style="font-size:15px;font-weight:800;color:var(--cyan)">${avgGcos}%</div>
                    <div style="font-size:7px;color:var(--t3)">Avg GCoS</div></div>
              <div><div style="font-size:15px;font-weight:800;color:var(--purple)">${totalP50.toLocaleString()}</div>
                    <div style="font-size:7px;color:var(--t3)">P50 MMboe</div></div>
              <div><div style="font-size:13px;font-weight:800;color:var(--t2)">${areaFmt}</div>
                    <div style="font-size:7px;color:var(--t3)">km²</div></div>
            </div>
            <!-- View Leads button — stops propagation so it doesn't toggle <details> -->
            <button
              onclick="event.stopPropagation();event.preventDefault();crsFilterToLeads('${seg.id}')"
              style="flex-shrink:0;padding:5px 11px;font-size:10px;font-weight:700;
              background:rgba(${seg.rgb},0.12);color:${seg.hex};border:1px solid rgba(${seg.rgb},0.33);
              border-radius:5px;cursor:pointer;white-space:nowrap;transition:all .15s"
              onmouseover="this.style.background='rgba(${seg.rgb},0.25)'"
              onmouseout="this.style.background='rgba(${seg.rgb},0.12)'">
              View ${basins.length} Leads
            </button>
            <span id="arrow-icon" style="font-size:12px;color:var(--t3);flex-shrink:0;margin-left:4px">&darr;</span>
          </summary>

          <!-- Basin rows -->
          <div style="background:var(--bg2)">
            ${[...basins].sort((a, b) => (b.composite||b.score||0) - (a.composite||a.score||0))
              .map(b => {
                const s    = b._elemScores;
                const lead = b._lead;
                const comp = b.composite || b.score || 0;
                const topEl  = Object.entries(s).sort((a, b2) => b2[1] - a[1])[0];
                const weakEl = Object.entries(s).sort((a, b2) => a[1] - b2[1])[0];
                return `
                <div style="display:grid;grid-template-columns:190px 1fr 110px;gap:10px;
                            align-items:center;padding:8px 14px 8px 26px;
                            border-bottom:1px solid rgba(${seg.rgb},0.12)">
                  <div>
                    <div style="font-size:10px;font-weight:700;color:var(--t1)">${b.name}</div>
                    <div style="font-size:10px;color:var(--t3)">${b.country} · ${b.region}</div>
                    <div style="font-size:7.5px;color:var(--t3);margin-top:1px">${b.hc} · ${b.status} · ${lead.type}</div>
                  </div>
                  <!-- Element score mini-bars -->
                  <div style="display:grid;grid-template-columns:repeat(6,1fr);gap:3px">
                    ${['source','reservoir','seal','charge','commercial','country'].map(k => {
                      const v   = Math.round(s[k] || 0);
                      const col = elColors[k];
                      const lbl = {source:'Src',reservoir:'Res',seal:'Sl',charge:'Chg',commercial:'Com',country:'Cty'}[k];
                      return `<div style="text-align:center">
                        <div style="font-size:6.5px;color:var(--t3);margin-bottom:1px">${lbl}</div>
                        <div style="height:26px;background:var(--bg4);border-radius:2px;position:relative;overflow:hidden">
                          <div style="position:absolute;bottom:0;width:100%;height:${v}%;background:${col}33;border-top:2px solid ${col}"></div>
                        </div>
                        <div style="font-size:7px;font-weight:700;color:${col};margin-top:1px">${v}</div>
                      </div>`;
                    }).join('')}
                  </div>
                  <!-- Right summary -->
                  <div style="text-align:right">
                    <div style="font-size:18px;font-weight:800;color:${seg.hex};line-height:1">${Math.round(comp)}</div>
                    <div style="font-size:7px;color:var(--t3)">composite</div>
                    <div style="font-size:10px;font-weight:700;color:var(--cyan);margin-top:3px">${lead.gcos}% GCoS</div>
                    <div style="font-size:7px;color:${elColors[topEl[0]]||'var(--t3)'};margin-top:2px">▲ ${topEl[0]}: ${Math.round(topEl[1])}</div>
                    <div style="font-size:7px;color:${elColors[weakEl[0]]||'var(--t3)'}">▼ ${weakEl[0]}: ${Math.round(weakEl[1])}</div>
                  </div>
                </div>`;
              }).join('')}
          </div>
        </details>
      </div>`;
    }).join('')}`;
}

// Called from "View N Leads →" button — set filter and jump to leads tab
function crsFilterToLeads(segId) {
  _activeCrsFilter = segId;
  // Switch to Leads tab
  const leadsTab = document.querySelector('.tab[onclick*="leads"]');
  if (leadsTab) {
    leadsTab.click();
  } else {
    switchPFTab('leads', document.querySelector('[onclick*="switchPFTab"]'));
  }
}

// ══════════════════════════════════════════════════════════════
// LEAD INVENTORY
// ══════════════════════════════════════════════════════════════
function renderLeadInventory() {
  const body  = document.getElementById('pf-leads-body');
  const kpiEl = document.getElementById('leads-kpis');
  if (!body) return;

  const allBasins = leaderboardData.length ? leaderboardData : BASINS;
  const hasLb     = leaderboardData.length > 0;
  const defs      = _pfCrsDefs();
  const crsMap    = Object.fromEntries(defs.map(d => [d.id, d]));

  const tierFilter = document.getElementById('leads-tier-filter')?.value || '';
  const typeFilter = document.getElementById('leads-type-filter')?.value || '';

  // Build all leads with CRS membership and CRS-adjusted GCoS
  let leads = allBasins.map((b, i) => _buildLead(b, i));

  // Apply filters — basin from heatmap, CRS segment, dropdowns
  if (_pfBasinFilter)   leads = leads.filter(l => l.basin  === _pfBasinFilter);
  if (_activeCrsFilter) leads = leads.filter(l => l.crsId  === _activeCrsFilter);
  if (tierFilter)       leads = leads.filter(l => l.tier   === tierFilter);
  if (typeFilter)       leads = leads.filter(l => l.type   === typeFilter);
  leads.sort((a, b) => b.comp - a.comp);

  // ── KPI strip ──────────────────────────────────────────────
  const activeSeg  = _activeCrsFilter ? crsMap[_activeCrsFilter] : null;
  const high       = leads.filter(l => l.tier === 'HIGH').length;
  const med        = leads.filter(l => l.tier === 'MED').length;
  const low        = leads.filter(l => l.tier === 'LOW').length;
  const totalP50   = leads.reduce((s, l) => s + l.p50, 0);
  const avgGcos    = leads.length ? Math.round(leads.reduce((s, l) => s + l.gcos, 0) / leads.length) : 0;

  if (kpiEl) kpiEl.innerHTML = [
    { label:'High Priority',   val:high,                            col:'var(--green)',  sub:'Score ≥ 70' },
    { label:'Med Priority',    val:med,                             col:'var(--amber)',  sub:'Score 40–69' },
    { label:'Low / Frontier',  val:low,                             col:'var(--red)',    sub:'Score < 40' },
    { label:'Total P50 (est)', val:totalP50.toLocaleString()+'<br>MMboe', col:'var(--cyan)', sub:'Sum of P50s' },
    { label:'Avg GCoS',        val:avgGcos + '%',                   col:'var(--purple)', sub:'CRS-adjusted' },
  ].map(k => `
    <div style="flex:1;padding:10px 14px;border-right:1px solid var(--b1);text-align:center;min-width:80px">
      <div style="font-size:16px;font-weight:800;color:${k.col};line-height:1.1">${k.val}</div>
      <div style="font-size:10px;font-weight:700;color:var(--t2);margin-top:3px">${k.label}</div>
      <div style="font-size:7px;color:var(--t3)">${k.sub}</div>
    </div>`).join('') +
    `<div style="flex-shrink:0;padding:10px 14px;font-size:10px;align-self:center;color:${hasLb ? 'var(--green)' : 'var(--amber)'}">
      ${hasLb ? '● Live from screening engine' : '● Estimated — run Screening for live scores'}
    </div>`;

  // ── Basin filter banner ──────────────────────────────────────
  const basinBanner = _pfBasinFilter ? `
    <div style="display:flex;align-items:center;gap:10px;padding:8px 14px;
      background:rgba(124,58,237,0.08);border-bottom:1px solid rgba(124,58,237,0.25)">
      <div style="width:3px;height:26px;background:var(--purple);border-radius:2px;flex-shrink:0"></div>
      <div style="flex:1">
        <div style="font-size:10px;font-weight:700;color:var(--purple)">
          \u{1F4CD} Basin Filter: ${_pfBasinFilter}
        </div>
        <div style="font-size:10px;color:var(--t3);margin-top:1px">
          Showing leads for this basin — selected from Risk Overlap Heatmap
        </div>
      </div>
      <button onclick="pfSetBasinFilter('')"
        style="padding:4px 10px;font-size:10px;font-weight:700;
          background:rgba(124,58,237,.1);border:1px solid rgba(124,58,237,.3);
          border-radius:4px;cursor:pointer;color:var(--purple);white-space:nowrap">
        \u2715 Clear
      </button>
    </div>` : '';

  // ── Active CRS filter banner ───────────────────────────────
  const banner = _activeCrsFilter && activeSeg ? `
    <div style="display:flex;align-items:center;gap:10px;padding:9px 14px;
                background:rgba(${activeSeg.rgb},0.09);border-bottom:2px solid rgba(${activeSeg.rgb},0.33)">
      <div style="width:3px;height:28px;background:${activeSeg.hex};border-radius:2px;flex-shrink:0"></div>
      <div style="flex:1">
        <div style="font-size:10px;font-weight:700;color:${activeSeg.hex}">
          Filtered to CRS-${activeSeg.id}: ${activeSeg.name}
        </div>
        <div style="font-size:10px;color:var(--t3);margin-top:1px">
          ${activeSeg.desc} · GCoS multiplier: ×${activeSeg.confidence.toFixed(2)} · ${leads.length} leads shown
        </div>
      </div>
      <button onclick="_activeCrsFilter=null;renderLeadInventory()"
        style="padding:4px 10px;font-size:10px;font-weight:700;background:var(--bg4);
                border:1px solid var(--b1);border-radius:4px;cursor:pointer;color:var(--t2);
                white-space:nowrap">
        ✕ Clear CRS filter
      </button>
    </div>` : '';

  if (leads.length === 0) {
    body.innerHTML = basinBanner + banner + `<div style="padding:30px;text-align:center;font-size:10px;color:var(--t3)">No leads match the selected filters.</div>`;
    return;
  }

  const tierColors = { HIGH:'var(--green)', MED:'var(--amber)', LOW:'var(--red)' };
  const elColors   = { source:'var(--green)', reservoir:'var(--blue)', seal:'var(--cyan)',
                        charge:'var(--purple)', commercial:'var(--amber)', country:'var(--red)' };

  body.innerHTML = basinBanner + banner + `
    <table style="width:100%;border-collapse:collapse;min-width:960px">
      <thead>
        <tr style="background:var(--bg4);border-bottom:2px solid var(--b1)">
          <th style="padding:8px 10px;font-size:10px;font-weight:700;color:var(--t3);text-align:left;white-space:nowrap">#</th>
          <th style="padding:8px 10px;font-size:10px;font-weight:700;color:var(--t3);text-align:left;white-space:nowrap">Basin / Lead</th>
          <th style="padding:8px 8px;font-size:10px;font-weight:700;color:var(--t3);text-align:left;white-space:nowrap">CRS Segment</th>
          <th style="padding:8px 8px;font-size:10px;font-weight:700;color:var(--t3);text-align:left;white-space:nowrap">Play Type</th>
          <th style="padding:8px 8px;font-size:10px;font-weight:700;color:var(--t3);text-align:left;white-space:nowrap">HC</th>
          <th style="padding:8px 8px;font-size:10px;font-weight:700;color:var(--t3);text-align:center;white-space:nowrap">Composite</th>
          <th style="padding:8px 8px;font-size:10px;font-weight:700;color:var(--cyan);text-align:center;white-space:nowrap">GCoS %<br><span style="font-weight:400;font-size:7px">CRS-adjusted</span></th>
          <th style="padding:8px 8px;font-size:10px;font-weight:700;color:var(--t3);text-align:center;white-space:nowrap">P90</th>
          <th style="padding:8px 8px;font-size:10px;font-weight:700;color:var(--purple);text-align:center;white-space:nowrap">P50 MMboe</th>
          <th style="padding:8px 8px;font-size:10px;font-weight:700;color:var(--t3);text-align:center;white-space:nowrap">P10</th>
          <th style="padding:8px 8px;font-size:10px;font-weight:700;color:var(--t3);text-align:left;white-space:nowrap">Element Scores</th>
          <th style="padding:8px 8px;font-size:10px;font-weight:700;color:var(--t3);text-align:center;white-space:nowrap">Status</th>
        </tr>
      </thead>
      <tbody>
        ${leads.map((l, ri) => {
          const rowBg  = ri % 2 === 0 ? 'var(--bg3)' : 'var(--bg4)';
          const tierCol = tierColors[l.tier] || 'var(--t3)';
          const elBars  = ['source','reservoir','seal','charge','commercial','country'].map(k => {
            const v   = Math.round(l.scores[k] || 0);
            const col = elColors[k];
            const lbl = {source:'Src',reservoir:'Res',seal:'Sl',charge:'Chg',commercial:'Com',country:'Cty'}[k];
            return `<div style="text-align:center;min-width:22px">
              <div style="font-size:5.5px;color:var(--t3)">${lbl}</div>
              <div style="height:18px;background:var(--bg3);border-radius:1px;position:relative;overflow:hidden;margin:1px 0">
                <div style="position:absolute;bottom:0;width:100%;height:${v}%;background:${col}40;border-top:1.5px solid ${col}"></div>
              </div>
              <div style="font-size:6px;font-weight:700;color:${col}">${v}</div>
            </div>`;
          }).join('');
          return `
          <tr style="background:${rowBg};border-bottom:1px solid var(--b1)">
            <td style="padding:8px 10px;font-size:10px;font-weight:700;color:${tierCol}">${l.id}</td>
            <td style="padding:8px 10px">
              <div style="font-size:10px;font-weight:700;color:var(--t1)">${l.basin}</div>
              <div style="font-size:7.5px;color:var(--t3)">${l.country} · ${l.region}</div>
            </td>
            <td style="padding:8px 8px">
              <div style="display:inline-flex;align-items:center;gap:5px;padding:3px 8px;border-radius:4px;
                          background:rgba(${l.crsRgb},0.09);border:1px solid rgba(${l.crsRgb},0.25);cursor:pointer"
                    onclick="crsFilterToLeads('${l.crsId}')"
                    title="Click to filter to CRS-${l.crsId}: ${l.crsName}">
                <div style="width:6px;height:6px;border-radius:50%;background:${l.crsHex};flex-shrink:0"></div>
                <span style="font-size:10px;font-weight:700;color:${l.crsHex}">CRS-${l.crsId}</span>
              </div>
              <div style="font-size:7px;color:var(--t3);margin-top:2px;max-width:110px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis"
                    title="${l.crsName}">${l.crsName}</div>
            </td>
            <td style="padding:8px 8px">
              <span style="font-size:10px;padding:2px 6px;border-radius:3px;background:var(--bg4);
                            border:1px solid var(--b1);color:var(--t2)">${l.type}</span>
            </td>
            <td style="padding:8px 8px;font-size:10px;color:var(--t2)">${l.hc}</td>
            <td style="padding:8px 8px;text-align:center">
              <div style="font-size:16px;font-weight:800;color:${tierCol};line-height:1">${Math.round(l.comp)}</div>
              <div style="font-size:6.5px;color:var(--t3)">${l.tier}</div>
            </td>
            <td style="padding:8px 8px;text-align:center">
              <div style="font-size:13px;font-weight:800;color:var(--cyan)">${l.gcos}%</div>
              <div style="font-size:7px;color:var(--t3)">×${l.crsConf.toFixed(2)}</div>
            </td>
            <td style="padding:8px 8px;text-align:center;font-size:10px;color:var(--t3)">${l.p90.toLocaleString()}</td>
            <td style="padding:8px 8px;text-align:center;font-size:11px;font-weight:700;color:var(--purple)">${l.p50.toLocaleString()}</td>
            <td style="padding:8px 8px;text-align:center;font-size:10px;color:var(--t3)">${l.p10.toLocaleString()}</td>
            <td style="padding:8px 8px"><div style="display:flex;gap:2px;align-items:flex-end">${elBars}</div></td>
            <td style="padding:8px 8px;text-align:center">
              <span style="font-size:10px;padding:2px 7px;border-radius:3px;font-weight:700;
                background:${l.status==='Mature'?'rgba(0,200,130,.1)':l.status==='Frontier'?'rgba(239,68,68,.1)':'rgba(245,158,11,.1)'};
                color:${l.status==='Mature'?'var(--green)':l.status==='Frontier'?'var(--red)':'var(--amber)'};
                border:1px solid ${l.status==='Mature'?'rgba(0,200,130,.3)':l.status==='Frontier'?'rgba(239,68,68,.3)':'rgba(245,158,11,.3)'}"
              >${l.status}</span>
            </td>
          </tr>`;
        }).join('')}
      </tbody>
    </table>`;
}

function leadsExport() {
  const allBasins = leaderboardData.length ? leaderboardData : BASINS;
  const rows = [['Lead ID','Basin','Country','Region','CRS','CRS Name','Play Type','HC',
                  'Composite','GCoS% (CRS-adj)','GCoS ×','P90 MMboe','P50 MMboe','P10 MMboe',
                  'Source','Reservoir','Seal','Charge','Commercial','Country Risk','Status']];
  allBasins.forEach((b, i) => {
    const l = _buildLead(b, i);
    rows.push([l.id, l.basin, l.country, l.region, 'CRS-'+l.crsId, l.crsName,
                l.type, l.hc, Math.round(l.comp), l.gcos, l.crsConf.toFixed(2),
                l.p90, l.p50, l.p10,
                Math.round(l.scores.source), Math.round(l.scores.reservoir),
                Math.round(l.scores.seal),   Math.round(l.scores.charge),
                Math.round(l.scores.commercial), Math.round(l.scores.country), l.status]);
  });
  const csv = rows.map(r => r.map(v => '"' + String(v).replace(/"/g, '""') + '"').join(',')).join('\n');
  const a   = document.createElement('a');
  a.href    = 'data:text/csv;charset=utf-8,' + encodeURIComponent(csv);
  a.download = 'lead_inventory_' + new Date().toISOString().slice(0, 10) + '.csv';
  a.click();
  toast('Lead inventory exported as CSV', 'success');
}

