function addNotification(msg, type) {
  notifications.unshift({
    id: Date.now(),
    msg,
    type: type || "info",
    time: "Just now",
    read: false,
  });
  updateNotifBadge();
}

function updateNotifBadge() {
  const unread = notifications.filter((n) => !n.read).length;
  let badge = document.getElementById("notif-badge");
  if (!badge) {
    // Create badge on the notification bell
    const bell = document.getElementById("notif-bell");
    if (bell) {
      badge = document.createElement("span");
      badge.id = "notif-badge";
      badge.style.cssText =
        "position:absolute;top:-4px;right:-4px;background:var(--red);color:#fff;font-size:10px;font-weight:700;width:14px;height:14px;border-radius:50%;display:flex;align-items:center;justify-content:center";
      bell.style.position = "relative";
      bell.appendChild(badge);
    }
  }
  if (badge) {
    badge.textContent = unread;
    badge.style.display = unread > 0 ? "flex" : "none";
  }
}

function openNotifications() {
  document.getElementById("modal-content").innerHTML = `
<h2 style="margin-bottom:4px">Notifications</h2>
<div style="font-size:10px;color:var(--t3);margin-bottom:14px">${notifications.filter((n) => !n.read).length} unread</div>
<div style="max-height:400px;overflow-y:auto">
${notifications
  .map((n) => {
    const icon =
      n.type === "success" ? "✓" : n.type === "warning" ? "⚠" : "ℹ";
    const col =
      n.type === "success"
        ? "var(--green)"
        : n.type === "warning"
          ? "var(--amber)"
          : "var(--cyan)";
    return `<div style="display:flex;gap:10px;padding:10px 12px;border-bottom:1px solid #F0F4FA;background:${n.read ? "transparent" : "rgba(13,76,146,.03)"};cursor:pointer" onclick="markNotifRead(${n.id})">
    <div style="width:22px;height:22px;border-radius:50%;background:${col}15;display:flex;align-items:center;justify-content:center;flex-shrink:0;font-size:10px;color:${col}">${icon}</div>
    <div style="flex:1"><div style="font-size:10px;color:var(--t1);${n.read ? "" : "font-weight:600"}">${n.msg}</div><div style="font-size:10px;color:var(--t3);margin-top:2px">${n.time}</div></div>
    ${n.read ? "" : '<div style="width:6px;height:6px;border-radius:50%;background:var(--cyan);flex-shrink:0;margin-top:6px"></div>'}
  </div>`;
  })
  .join("")}
</div>
<div style="margin-top:12px;display:flex;gap:8px">
<button class="btn2" onclick="notifications.forEach(n=>n.read=true);updateNotifBadge();openNotifications()">Mark All Read</button>
<button class="btn2" onclick="toast('Notification preferences saved','success')">⚙ Settings</button>
</div>`;
  document.getElementById("modal").style.display = "flex";
}

function markNotifRead(id) {
  const n = notifications.find((x) => x.id === id);
  if (n) n.read = true;
  updateNotifBadge();
  openNotifications();
}

