function openWorkflowWizard() {
  const stepsHtml = WORKFLOW_STEPS.map((s, i) => {
    const done = i < workflowStep;
    const active = i === workflowStep;
    const col = done
      ? "var(--green)"
      : active
        ? "var(--cyan)"
        : "var(--t3)";
    return `<div style="display:flex;align-items:center;gap:10px;padding:10px 14px;border-radius:8px;background:${active ? "rgba(8,145,178,.06)" : "transparent"};border:1px solid ${active ? "rgba(8,145,178,.2)" : "transparent"};cursor:pointer" onclick="goToWorkflowStep(${i})">
<div style="width:28px;height:28px;border-radius:50%;background:${col}15;display:flex;align-items:center;justify-content:center;font-size:14px;flex-shrink:0">${done ? "✓" : s.icon}</div>
<div style="flex:1"><div style="font-size:11px;font-weight:${active ? 700 : 500};color:${done ? "var(--green)" : active ? "var(--t1)" : "var(--t3)"}">${s.label}</div><div style="font-size:10px;color:var(--t3)">${s.desc}</div></div>
${active ? '<span style="font-size:10px;font-weight:700;color:var(--cyan);padding:2px 8px;background:rgba(8,145,178,.1);border-radius:10px">Current</span>' : ""}
</div>`;
  }).join("");

  document.getElementById("modal-content").innerHTML = `
<h2 style="margin-bottom:4px">Exploration Workflow</h2>
<div style="font-size:10px;color:var(--t3);margin-bottom:14px">Guided step-by-step exploration evaluation pipeline</div>
<div style="display:flex;align-items:center;gap:6px;margin-bottom:14px">
<div style="flex:1;height:6px;background:#E8ECF5;border-radius:3px"><div style="width:${(workflowStep / WORKFLOW_STEPS.length) * 100}%;height:100%;background:var(--cyan);border-radius:3px;transition:width .3s"></div></div>
<span style="font-size:10px;font-weight:700;color:var(--cyan)">${Math.round((workflowStep / WORKFLOW_STEPS.length) * 100)}%</span>
</div>
${stepsHtml}
<div style="margin-top:14px;display:flex;gap:8px;justify-content:flex-end">
<button class="btn2" onclick="workflowStep=0;openWorkflowWizard()">Reset</button>
<button class="btn" onclick="goToWorkflowStep(${workflowStep})" ${workflowStep >= WORKFLOW_STEPS.length ? "disabled" : ""}>Go to Current Step →</button>
</div>`;
  document.getElementById("modal").style.display = "flex";
}

function goToWorkflowStep(idx) {
  workflowStep = Math.max(workflowStep, idx + 1);
  closeModal();
  goTo(WORKFLOW_STEPS[idx].section, null);
  toast(
    "Workflow: " +
      WORKFLOW_STEPS[idx].label +
      " — " +
      WORKFLOW_STEPS[idx].desc,
    "info",
  );
}

