  // Populate the select from BASINS, grouped by region
  function pse_populateBasinSelect() {
    const sel = document.getElementById("pse-basin-select");
    if (!sel) return;
    // Group by region
    const regions = {};
    BASINS.forEach((b) => {
      if (!regions[b.region]) regions[b.region] = [];
      regions[b.region].push(b);
    });
    // Build options
    let html = '<option value="">— Select Basin —</option>';
    Object.keys(regions)
      .sort()
      .forEach((region) => {
        html += `<optgroup label="${region}">`;
        regions[region].forEach((b) => {
          const tag = b.hc ? ` · ${b.hc}` : "";
          const statusIcon =
            b.status === "Mature"
              ? "●"
              : b.status === "Active"
                ? "◉"
                : "○";
          html += `<option value="${b.name}">${statusIcon} ${b.name}${tag}</option>`;
        });
        html += "</optgroup>";
      });
    sel.innerHTML = html;
  }

