let _pse_active_timing_basin = null;

function pse_updateRiskChart(basinName) {
  // Update basin label in card header
  const tag = document.getElementById("pse-risk-basin-tag");
  if (tag && basinName) {
    const basin =
      typeof BASINS !== "undefined"
        ? BASINS.find((b) => b.name === basinName)
        : null;
    tag.textContent =
      basinName +
      (basin ? ` · ${basin.hc} · Score ${basin.score}/100` : "");
    tag.style.fontStyle = "normal";
    tag.style.color = "var(--cyan)";
  }
  pse_syncRiskData();
  pseRisk_render(); // immediate — no throttle on explicit basin load
}

function pse_updateTimingChart(basinName) {
  _pse_active_timing_basin = basinName;
  // Update basin tag immediately — don't wait for chart render
  const tag = document.getElementById("pse-timing-basin-tag");
  if (tag && basinName) {
    const basin =
      typeof BASINS !== "undefined"
        ? BASINS.find((b) => b.name === basinName)
        : null;
    tag.textContent =
      basinName + (basin ? ` · ${basin.tectonic} · ${basin.age}` : "");
    tag.style.fontStyle = "normal";
    tag.style.color = "var(--cyan)";
  }
  pseTiming_render();
}

