let _pse_active_migration = PSE_BASIN_MIGRATION["Malay Basin"];

function pse_updateMigration(basinName) {
  const m = PSE_BASIN_MIGRATION[basinName];
  if (!m) return;
  _pse_active_migration = m;
  // Update stats footer
  const dist = document.getElementById("mig-stat-dist");
  if (dist) dist.textContent = m.dist + " km";
  const dip = document.getElementById("mig-stat-dip");
  if (dip) dip.textContent = m.dip + "°";
  const eff = document.getElementById("mig-stat-eff");
  if (eff) eff.textContent = m.eff + "%";
  const risk = document.getElementById("mig-stat-risk");
  if (risk) {
    risk.textContent = m.risk;
    risk.style.color = m.riskCol;
  }
  pseMig_render();
}

function pseMig_render() {
  const canvas = document.getElementById("chart-pse-migration");
  if (!canvas) return;
  _pse_destroy("migration");
  const mode =
    (document.getElementById("pse-mig-layer") || {}).value || "primary";

  const layers = [
    "Overburden\nShale",
    "Reservoir\nSandstone",
    "Seal\nMudstone",
    "Carrier\nBed",
    "Source\nRock",
    "Basement",
  ];
  const m = _pse_active_migration || PSE_BASIN_MIGRATION["Malay Basin"];

  const primaryEff = m.prim;
  const secondaryEff = m.sec;

  let data1, data2, label1, label2;
  if (mode === "primary") {
    data1 = primaryEff;
    data2 = null;
    label1 = "Primary (% efficiency)";
  } else if (mode === "secondary") {
    data1 = secondaryEff;
    data2 = null;
    label1 = "Secondary (% efficiency)";
  } else {
    data1 = primaryEff;
    data2 = secondaryEff;
    label1 = "Primary";
    label2 = "Secondary";
  }

  const datasets = [
    {
      label: label1,
      data: data1,
      backgroundColor: "rgba(13,148,136,0.65)",
      borderColor: "#0D9488",
      borderWidth: 2,
      borderRadius: 3,
      indexAxis: "y",
    },
  ];
  if (data2) {
    datasets.push({
      label: label2,
      data: data2,
      backgroundColor: "rgba(13,76,146,0.45)",
      borderColor: "#0D4C92",
      borderWidth: 2,
      borderRadius: 3,
      indexAxis: "y",
    });
  }

  _pseCharts["migration"] = new Chart(canvas, {
    type: "bar",
    data: { labels: layers, datasets },
    options: {
      indexAxis: "y",
      responsive: true,
      maintainAspectRatio: false,
      plugins: {
        legend: {
          labels: { font: { size: 9 }, color: "#7A8B9E", boxWidth: 10 },
        },
        tooltip: {
          callbacks: {
            label: (ctx) => `${ctx.dataset.label}: ${ctx.raw}%`,
          },
        },
      },
      scales: {
        x: {
          min: 0,
          max: 100,
          ticks: {
            font: { size: 8 },
            color: "#7A8B9E",
            callback: (v) => v + "%",
          },
          grid: { color: "rgba(255,255,255,0.06)" },
          title: {
            display: true,
            text: "Migration Efficiency (%)",
            font: { size: 9 },
            color: "#7A8B9E",
          },
        },
        y: {
          ticks: { font: { size: 8 }, color: "#A0AEC0" },
          grid: { display: false },
        },
      },
    },
  });
}

// ─────────────────────────────────────────────────────────────
// 5. TRAP & SEAL INTEGRITY — radar or horizontal bar chart
// ─────────────────────────────────────────────────────────────
const PSE_BASIN_TRAP = {
  // Each entry: [Structural Closure, Seal Capacity, Seal Geometry, Column Height, Fault Reactivation]
  "Malay Basin": [0.74, 0.68, 0.8, 0.62, 0.5],
  "Niger Delta": [0.7, 0.55, 0.65, 0.5, 0.35],
  "North Sea": [0.78, 0.72, 0.82, 0.68, 0.55],
  "Zagros Fold Belt": [0.86, 0.8, 0.88, 0.78, 0.6],
  "Permian Basin": [0.8, 0.7, 0.76, 0.65, 0.52],
  "Kutei Basin": [0.72, 0.65, 0.74, 0.6, 0.48],
  "Nile Delta": [0.65, 0.58, 0.7, 0.55, 0.42],
  "Murzuq Basin": [0.6, 0.52, 0.64, 0.48, 0.38],
  "South Caspian": [0.76, 0.68, 0.78, 0.64, 0.54],
  "Barents Sea": [0.55, 0.48, 0.6, 0.44, 0.35],
  "Browse Basin": [0.68, 0.6, 0.7, 0.54, 0.44],
  "Tarim Basin": [0.62, 0.55, 0.65, 0.5, 0.4],
  "Neuquén Basin": [0.74, 0.65, 0.76, 0.6, 0.5],
  "Sergipe-Alagoas": [0.52, 0.44, 0.56, 0.4, 0.3],
  "East Greenland": [0.45, 0.38, 0.5, 0.35, 0.28],
};

function _trapColor(s) {
  return s >= 0.7 ? "#059669" : s >= 0.5 ? "#D97706" : "#DC2626";
}
function _trapConf(s) {
  return s >= 0.7 ? "High" : s >= 0.5 ? "Medium" : "Low";
}

const PSE_TRAP_DATA = [
  {
    label: "Structural Closure",
    score: 0.78,
    conf: "High",
    color: "#059669",
  },
  {
    label: "Seal Capacity",
    score: 0.61,
    conf: "Medium",
    color: "#D97706",
  },
  { label: "Seal Geometry", score: 0.82, conf: "High", color: "#059669" },
  {
    label: "Column Height",
    score: 0.55,
    conf: "Medium",
    color: "#D97706",
  },
  {
    label: "Fault Reactivation",
    score: 0.32,
    conf: "Low",
    color: "#DC2626",
  },
];

function pse_updateTrap(basinName) {
  const scores = PSE_BASIN_TRAP[basinName];
  if (!scores) return;
  scores.forEach((s, i) => {
    PSE_TRAP_DATA[i].score = s;
    PSE_TRAP_DATA[i].color = _trapColor(s);
    PSE_TRAP_DATA[i].conf = _trapConf(s);
  });
  if (typeof pseTrap_render === "function") pseTrap_render();
}

function pseTrap_render() {
  const canvas = document.getElementById("chart-pse-trap");
  if (!canvas) return;
  _pse_destroy("trap");

  const avg =
    PSE_TRAP_DATA.reduce((s, d) => s + d.score, 0) / PSE_TRAP_DATA.length;
  const score = document.getElementById("pse-trap-score");
  const rlabel = document.getElementById("pse-trap-risk-label");
  if (score) score.textContent = avg.toFixed(2);
  if (rlabel) {
    rlabel.textContent =
      avg > 0.7 ? "Low Risk" : avg > 0.55 ? "Moderate Risk" : "High Risk";
    rlabel.style.color =
      avg > 0.7
        ? "var(--green)"
        : avg > 0.55
          ? "var(--gold)"
          : "var(--red)";
  }

  if (PSE_ANALYTICS.trapView === "radar") {
    _pseCharts["trap"] = new Chart(canvas, {
      type: "radar",
      data: {
        labels: PSE_TRAP_DATA.map((d) => d.label),
        datasets: [
          {
            label: "Integrity Score",
            data: PSE_TRAP_DATA.map((d) => +(d.score * 100).toFixed(0)),
            backgroundColor: "rgba(13,76,146,0.18)",
            borderColor: "#2B7ACC",
            borderWidth: 2,
            pointBackgroundColor: PSE_TRAP_DATA.map((d) => d.color),
            pointRadius: 5,
            pointHoverRadius: 7,
          },
          {
            label: "Threshold (60)",
            data: PSE_TRAP_DATA.map(() => 60),
            backgroundColor: "rgba(217,119,6,0.06)",
            borderColor: "#D97706",
            borderWidth: 1,
            borderDash: [5, 5],
            pointRadius: 0,
          },
        ],
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
          legend: {
            labels: { font: { size: 9 }, color: "#7A8B9E", boxWidth: 10 },
          },
          tooltip: {
            callbacks: {
              label: (ctx) => `${ctx.dataset.label}: ${ctx.raw}%`,
            },
          },
        },
        scales: {
          r: {
            min: 0,
            max: 100,
            ticks: {
              stepSize: 25,
              font: { size: 8 },
              color: "#7A8B9E",
              backdropColor: "transparent",
            },
            grid: { color: "rgba(255,255,255,0.08)" },
            pointLabels: { font: { size: 8 }, color: "#A0AEC0" },
          },
        },
      },
    });
  } else {
    _pseCharts["trap"] = new Chart(canvas, {
      type: "bar",
      data: {
        labels: PSE_TRAP_DATA.map((d) => d.label),
        datasets: [
          {
            label: "Integrity Score",
            data: PSE_TRAP_DATA.map((d) => +(d.score * 100).toFixed(0)),
            backgroundColor: PSE_TRAP_DATA.map((d) => d.color + "99"),
            borderColor: PSE_TRAP_DATA.map((d) => d.color),
            borderWidth: 2,
            borderRadius: 4,
            indexAxis: "y",
          },
          {
            label: "Target (60%)",
            data: PSE_TRAP_DATA.map(() => 60),
            backgroundColor: "rgba(217,119,6,0)",
            borderColor: "#D97706",
            borderWidth: 1,
            type: "line",
            fill: false,
            pointRadius: 0,
            borderDash: [5, 5],
          },
        ],
      },
      options: {
        indexAxis: "y",
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
          legend: {
            labels: { font: { size: 9 }, color: "#7A8B9E", boxWidth: 10 },
          },
          tooltip: {
            callbacks: {
              label: (ctx) =>
                `${ctx.dataset.label}: ${ctx.raw}${ctx.datasetIndex === 0 ? "%" : ""}`,
            },
          },
        },
        scales: {
          x: {
            min: 0,
            max: 100,
            ticks: {
              font: { size: 8 },
              color: "#7A8B9E",
              callback: (v) => v + "%",
            },
            grid: { color: "rgba(255,255,255,0.06)" },
          },
          y: {
            ticks: { font: { size: 8 }, color: "#A0AEC0" },
            grid: { display: false },
          },
        },
        onClick: (evt, els) => {
          if (els.length && els[0].datasetIndex === 0) {
            const d = PSE_TRAP_DATA[els[0].index];
            toast(
              `${d.label}: ${(d.score * 100).toFixed(0)}% — ${d.conf} confidence`,
              "info",
            );
          }
        },
      },
    });
  }
}

function pseTrap_toggleView() {
  PSE_ANALYTICS.trapView =
    PSE_ANALYTICS.trapView === "radar" ? "bar" : "radar";
  pseTrap_render();
}

