// ── GCoS Switcher ──────────────────────────────────────────
(function () {
  const CFG = {
    pse: {
      lbl: "System GCoS",
      sub: "PSE propagated",
      badge: "PSE",
      bg: "rgba(5,150,105,.2)",
    },
    bayes: {
      lbl: "Bayesian GCoS",
      sub: "Posterior probability",
      badge: "BAYES",
      bg: "rgba(124,58,237,.2)",
    },
    risk: {
      lbl: "Risk GCoS",
      sub: "Risk & Uncertainty",
      badge: "RISK",
      bg: "rgba(13,148,136,.2)",
    },
    active: {
      lbl: "Active GCoS",
      sub: "Drives Volumetrics",
      badge: "ACTV",
      bg: "rgba(184,134,11,.2)",
    },
  };
  const ORDER = ["pse", "bayes", "risk", "active"];
  let cur = "pse";
  const vals = { pse: null, bayes: null, risk: null, active: null };

  function fmt(v) {
    return v == null ? "—" : v < 0.0001 ? "<0.0001" : v.toFixed(4);
  }
  function pct(v) {
    return v == null ? "—" : (v * 100).toFixed(1) + "%";
  }

  function render() {
    const c = CFG[cur];
    const elVal = document.getElementById("pse-stat-gcos");
    const elLbl = document.getElementById("gcos-kpi-lbl");
    const elSub = document.getElementById("gcos-kpi-sub");
    const elBdg = document.getElementById("gcos-kpi-badge");
    if (elVal) {
      elVal.textContent = fmt(vals[cur]);
      elVal.style.color = c.color;
    }
    if (elLbl) elLbl.textContent = c.lbl;
    if (elSub) elSub.textContent = c.sub;
    if (elBdg) {
      elBdg.textContent = c.badge;
      elBdg.style.background = c.bg;
      elBdg.style.color = c.color;
    }
    // dots
    document.querySelectorAll(".gcos-src-dot").forEach((d) => {
      const s = d.dataset.src;
      d.style.background =
        s === cur ? CFG[s]?.color || "var(--bg4)" : "var(--bg4)";
      d.style.transform = s === cur ? "scale(1.5)" : "scale(1)";
    });
    buildRows();
  }

  function buildRows() {
    const el = document.getElementById("gcos-kpi-rows");
    if (!el) return;
    el.innerHTML = ORDER.map((s) => {
      const c2 = CFG[s],
        active = s === cur;
      return `<div onclick="window._gcosKpi_pick('${s}')"
  style="display:flex;align-items:center;gap:6px;padding:5px 6px;border-radius:4px;cursor:pointer;
          background:${active ? "rgba(13,76,146,.15)" : "transparent"};margin-bottom:1px"
  onmouseenter="this.style.background='rgba(13,76,146,.1)'"
  onmouseleave="this.style.background='${active ? "rgba(13,76,146,.15)" : "transparent"}'">
  <span style="width:7px;height:7px;border-radius:50%;flex-shrink:0;background:${c2.color}"></span>
  <span style="flex:1;font-size:10px;color:${active ? "var(--t1)" : "var(--t2)"};font-weight:${active ? 700 : 400}">${c2.lbl}</span>
  <span style="font-size:10px;font-weight:700;font-family:monospace;color:${c2.color}">${fmt(vals[s])}</span>
  <span style="font-size:10px;color:var(--t3)">${vals[s] != null ? "(" + pct(vals[s]) + ")" : s === "active" ? "← set" : "—"}</span>
</div>`;
    }).join("");
  }

  window._gcosKpi_pick = function (src) {
    cur = src;
    render();
  };

  window.gcosKpi_toggle = function (e) {
    const panel = document.getElementById("gcos-kpi-panel");
    if (!panel) return;
    if (panel.contains(e.target)) return;
    const open = panel.style.display === "block";
    panel.style.display = open ? "none" : "block";
    if (!open) buildRows();
  };

  window.gcosKpi_close = function (e) {
    e.stopPropagation();
    const p = document.getElementById("gcos-kpi-panel");
    if (p) p.style.display = "none";
  };

  window.gcosKpi_setActive = function (e) {
    e.stopPropagation();
    const v = vals[cur];
    if (v == null) {
      toast("No value yet for " + CFG[cur].lbl, "warn");
      return;
    }
    vals.active = v;
    if (window.EDAFY_bridge) {
      if (cur === "pse") EDAFY_bridge.propagateFromPSE(v, null);
      else if (cur === "bayes") EDAFY_bridge.propagateFromBayes(v);
      else if (cur === "risk") EDAFY_bridge.propagateFromRisk(v);
    }
    const chip = document.getElementById("ai-active-val");
    if (chip) chip.textContent = pct(v);
    toast(
      CFG[cur].lbl + " " + pct(v) + " → set as Active GCoS",
      "success",
    );
    render();
  };

  // Close on outside click
  document.addEventListener("click", function (e) {
    const card = document.getElementById("gcos-kpi-card");
    if (card && !card.contains(e.target)) {
      const p = document.getElementById("gcos-kpi-panel");
      if (p) p.style.display = "none";
    }
  });

  // Sync from bridge on every propagation
  function patchBridge() {
    if (!window.EDAFY_bridge) {
      setTimeout(patchBridge, 500);
      return;
    }
    const orig = EDAFY_bridge.syncDashboard.bind(EDAFY_bridge);
    EDAFY_bridge.syncDashboard = function () {
      orig();
      const s = EDAFY_bridge.getStateSummary();
      if (s.pse_gcos != null) {
        vals.pse = s.pse_gcos;
        const el = document.getElementById("ai-pse-val");
        if (el) el.textContent = pct(s.pse_gcos);
      }
      if (s.bayes_gcos != null) {
        vals.bayes = s.bayes_gcos;
      }
      if (s.risk_gcos != null) {
        vals.risk = s.risk_gcos;
        const el = document.getElementById("ai-risk-val2");
        if (el) el.textContent = pct(s.risk_gcos);
      }
      vals.active = EDAFY_bridge.getActiveGCoS();
      const ac = document.getElementById("ai-active-val");
      if (ac && vals.active != null) ac.textContent = pct(vals.active);
      render();
    };
    // Seed immediately
    const s = EDAFY_bridge.getStateSummary();
    if (s.pse_gcos != null) vals.pse = s.pse_gcos;
    if (s.bayes_gcos != null) vals.bayes = s.bayes_gcos;
    if (s.risk_gcos != null) vals.risk = s.risk_gcos;
    vals.active = EDAFY_bridge.getActiveGCoS();
    render();
  }

  // Also pick up pse_updateStats direct writes to pse-stat-gcos
  const _origPseUpd = window.pse_updateStats;
  window.pse_updateStats = function () {
    if (_origPseUpd) _origPseUpd.apply(this, arguments);
    const el = document.getElementById("pse-stat-gcos");
    if (el) {
      const v = parseFloat(el.textContent);
      if (!isNaN(v) && v > 0) {
        vals.pse = v;
        render();
      }
    }
  };

  patchBridge();
  // Fallback: re-read every 3s in case bridge patching missed something
  setInterval(() => {
    if (!window.EDAFY_bridge) return;
    const s = EDAFY_bridge.getStateSummary();
    let changed = false;
    if (s.pse_gcos != null && vals.pse !== s.pse_gcos) {
      vals.pse = s.pse_gcos;
      changed = true;
    }
    if (s.bayes_gcos != null && vals.bayes !== s.bayes_gcos) {
      vals.bayes = s.bayes_gcos;
      changed = true;
    }
    if (s.risk_gcos != null && vals.risk !== s.risk_gcos) {
      vals.risk = s.risk_gcos;
      changed = true;
    }
    const ag = EDAFY_bridge.getActiveGCoS();
    if (ag != null && vals.active !== ag) {
      vals.active = ag;
      changed = true;
    }
    if (changed) render();
  }, 3000);
})();

// ── View Mode Switcher ─────────────────────────────────────
(function () {
  const MODES = [
    {
      id: "system",
      label: "System",
      icon: "",
      sub: "All layers",
      kbd: "1",
    },
    {
      id: "risk",
      label: "Risk",
      icon: "",
      sub: "Confidence heatmap",
      kbd: "2",
    },
    {
      id: "flow",
      label: "HC Flow",
      icon: "",
      sub: "Migration animation",
      kbd: "3",
    },
    {
      id: "timing",
      label: "Temporal",
      icon: "",
      sub: "Charge timeline",
      kbd: "4",
    },
    {
      id: "critical",
      label: "Critical",
      icon: "",
      sub: "Bottleneck path",
      kbd: "5",
    },
  ];
  let cur = "system";

  function buildItems() {
    const el = document.getElementById("viewmode-kpi-items");
    if (!el) return;
    el.innerHTML = MODES.map((m) => {
      const act = m.id === cur;
      return `<div onclick="window._vmKpi_pick('${m.id}')"
  style="display:flex;align-items:center;gap:7px;padding:6px 7px;border-radius:4px;cursor:pointer;margin-bottom:1px;
          background:${act ? "rgba(124,58,237,.15)" : "transparent"}"
  onmouseenter="this.style.background='rgba(124,58,237,.1)'"
  onmouseleave="this.style.background='${act ? "rgba(124,58,237,.15)" : "transparent"}'">
  <span style="font-size:13px">${m.icon}</span>
  <span style="flex:1;font-size:10px;font-weight:${act ? 700 : 400};color:${act ? "var(--t1)" : "var(--t2)"}">${m.label}</span>
  <span style="font-size:10px;color:var(--t3);background:var(--bg4);border-radius:3px;padding:1px 4px">${m.kbd}</span>
  ${act ? `<span style="color:${m.color};font-size:10px">●</span>` : ""}
</div>`;
    }).join("");
  }

  window.vmKpi_sync = function (mode) {
    cur = mode;
    const m = MODES.find((x) => x.id === mode) || MODES[0];
    const icon = document.getElementById("vm-icon");
    const text = document.getElementById("vm-text");
    const sub  = document.getElementById("vm-sub");
    const sel  = document.getElementById("vm-select");
    if (icon) icon.textContent = m.icon;
    if (text) { text.textContent = m.label; text.style.color = m.color; }
    if (sub)  sub.textContent = m.sub;
    if (sel)  sel.value = m.id;
    buildItems();
  };

  window._vmKpi_pick = function (mode) {
    const p = document.getElementById("viewmode-kpi-panel");
    if (p) p.style.display = "none";
    if (typeof pse_setView === "function") pse_setView(mode);
    // pse_setView calls vmKpi_sync via the patched version
  };

  window.viewKpi_toggle = function (e) {
    // No-op: view mode now controlled by select dropdown
  };

  // Close on outside click
  document.addEventListener("click", function (e) {
    const card = document.getElementById("viewmode-kpi-card");
    if (card && !card.contains(e.target)) {
      const p = document.getElementById("viewmode-kpi-panel");
      if (p) p.style.display = "none";
    }
  });

  // Keyboard shortcuts 1–5 when PSE section visible
  document.addEventListener("keydown", function (e) {
    if (["INPUT", "TEXTAREA", "SELECT"].includes(e.target.tagName))
      return;
    const sec = document.getElementById("sec-petrosystem");
    if (!sec) return;
    const r = sec.getBoundingClientRect();
    if (r.bottom < 0 || r.top > window.innerHeight) return;
    const m = MODES.find((x) => x.kbd === e.key);
    if (m) {
      e.preventDefault();
      window._vmKpi_pick(m.id);
    }
  });

  // Init
  setTimeout(() => vmKpi_sync("system"), 200);
})();

// Re-render on resize to keep charts responsive
