// ══════════════════════════════════════════════════════════════
// PORTFOLIO OPTIMIZATION ENGINE
// Fully live, interactive, connected to BASINS + ECON_DB
// ══════════════════════════════════════════════════════════════

// ── Project data derived from BASINS + ECON_DB ───────────────
function _buildProjectUniverse() {
  return BASINS.map((b, i) => {
    const dbKey = b.osduId || `basin:${b.name}`;
    const econ = ECON_DB[dbKey] || {};
    const oilPrice = +(
      document.getElementById("portopt-oil-price")?.value || 75
    );

    // CAPEX: exploration entry cost ($M) — scaled to basin maturity & play count
    // Mature basins cost more (infrastructure premium); frontier cheaper to enter
    const statusMult =
      b.status === "Mature" ? 1.3 : b.status === "Active" ? 1.0 : 0.7;
    const capex =
      econ.capex ||
      Math.round(
        (80 + b.plays * 12 + Math.log10(b.area + 1) * 15) * statusMult,
      );

    // GCoS derived from prospectivity score
    const gcos = Math.max(
      5,
      Math.min(65, Math.round(b.score * 0.55 + 5)),
    );

    // NPV: simple risked revenue minus capex
    const vol = econ.volume || b.area / 1000; // MMbbl or MMmcf
    const price = b.hc === "Gas" ? econ.price || 5.5 : oilPrice;
    const rf = (econ.rf || 35) / 100;
    const opex = econ.opex || 12;
    const tax = (econ.tax || 30) / 100;
    const disc = (econ.discount || 10) / 100;
    const years = econ.years || 20;
    const recoverable = vol * rf;
    const revenue = recoverable * price * 1e6; // $
    const opexTotal = recoverable * opex * 1e6;
    const grossProfit = (revenue - opexTotal) * (1 - tax);
    const discountFactor = (1 - Math.pow(1 + disc, -years)) / disc;
    const npvUnrisked = (grossProfit * discountFactor) / 1e6 - capex; // $M
    const npvRisked = Math.round((npvUnrisked * gcos) / 100);

    // Profitability index
    const pi =
      capex > 0 ? +((npvUnrisked + capex) / capex).toFixed(2) : 0;

    // Risk score (inverted: high score = lower risk)
    const riskScore = Math.round(100 - b.score * 0.6 - gcos * 0.4);

    return {
      id: i,
      name: b.name,
      country: b.country,
      region: b.region,
      hc: b.hc,
      status: b.status,
      score: b.score,
      plays: b.plays,
      capex,
      npvUnrisked: Math.round(npvUnrisked),
      npvRisked,
      gcos,
      pi,
      riskScore,
      selected: false,
    };
  });
}

// ── Portfolio-level aggregates ────────────────────────────────
function _portfolioStats(projects) {
  const sel = projects.filter((p) => p.selected);
  const totalCapex = sel.reduce((s, p) => s + p.capex, 0);
  const totalNPV = sel.reduce((s, p) => s + p.npvRisked, 0);
  const avgGcos = sel.length
    ? Math.round(sel.reduce((s, p) => s + p.gcos, 0) / sel.length)
    : 0;
  const avgRisk = sel.length
    ? Math.round(sel.reduce((s, p) => s + p.riskScore, 0) / sel.length)
    : 0;
  return { sel, totalCapex, totalNPV, avgGcos, avgRisk };
}

// ── KPI header update ─────────────────────────────────────────
function _updatePortOptKPIs(projects) {
  const { sel, totalCapex, totalNPV, avgGcos } =
    _portfolioStats(projects);
  const sv = (id, v) => {
    const e = document.getElementById(id);
    if (e) e.textContent = v;
  };
  sv("po-kpi-universe", BASINS.length);
  sv("po-kpi-selected", sel.length);
  sv("po-kpi-capex", `$${totalCapex.toLocaleString()}M`);
  sv(
    "po-kpi-npv",
    `${totalNPV >= 0 ? "+" : ""}$${totalNPV.toLocaleString()}M`,
  );
  sv("po-kpi-gcos", `${avgGcos}%`);
}

// ── Tab switcher ──────────────────────────────────────────────
function switchPortOptTab(tab, el) {
  ["frontier", "allocation", "projects", "scenarios"].forEach((t) => {
    const p = document.getElementById(`portopt-${t}-panel`);
    if (p) p.style.display = t === tab ? "block" : "none";
  });

  // Highlight active tab
  document
    .querySelectorAll("#portopt-tabs .tab")
    .forEach((t) => t.classList.remove("on"));
  if (el) el.classList.add("on");

  // ✅ Update breadcrumb
  const bc = document.getElementById("breadcrumb-section");
  if (bc) bc.textContent = el?.textContent.trim() || "";

  // Tab-specific functions
  if (tab === "frontier") renderEfficientFrontier();
  if (tab === "allocation") renderAllocationTab();
  if (tab === "projects") renderProjectUniverse();
  if (tab === "scenarios") renderScenarios();
}

// ══════════════════════════════════════════════════════════════
// TAB 1 — EFFICIENT FRONTIER
// Generates 40 portfolio combinations, plots risk vs NPV
// ══════════════════════════════════════════════════════════════
let _poLastProjects = null;
let _poOptimalIdx = -1;
let _poFrontierPts = [];

function renderEfficientFrontier() {
  const projects = _buildProjectUniverse();
  _poLastProjects = projects;

  const budget = +(
    document.getElementById("portopt-budget")?.value || 1500
  );
  const maxSingle = +(
    document.getElementById("portopt-max-single")?.value || 400
  );
  const minProj = +(
    document.getElementById("portopt-min-proj")?.value || 3
  );
  const maxProj = +(
    document.getElementById("portopt-max-proj")?.value || 10
  );
  const minScore = +(
    document.getElementById("portopt-min-score")?.value || 40
  );
  const riskTol =
    +(document.getElementById("portopt-risk")?.value || 50) / 100;
  const divMode =
    document.getElementById("portopt-diversify")?.value || "basin";

  // Filter eligible projects
  const eligible = projects.filter(
    (p) =>
      p.score >= minScore && p.capex <= maxSingle && p.capex <= budget,
  );

  if (eligible.length < 2) {
    const ctx = document
      .getElementById("portopt-frontier-canvas")
      ?.getContext("2d");
    if (ctx) {
      ctx.clearRect(0, 0, ctx.canvas.width, ctx.canvas.height);
    }
    return;
  }

  // Generate frontier by varying risk tolerance from 0→100 in 40 steps
  const frontierPts = [];
  for (let rt = 0; rt <= 1; rt += 0.025) {
    const sorted = [...eligible].sort((a, b) => {
      const scoreA =
        (a.npvRisked / Math.max(1, a.capex)) * (1 - rt) +
        (a.gcos / 100) * rt;
      const scoreB =
        (b.npvRisked / Math.max(1, b.capex)) * (1 - rt) +
        (b.gcos / 100) * rt;
      return scoreB - scoreA;
    });

    let capexLeft = budget,
      selected = [],
      regions = new Set(),
      hcs = new Set();
    for (const p of sorted) {
      if (selected.length >= maxProj) break;
      if (p.capex > capexLeft) continue;
      if (
        divMode === "region" &&
        regions.size >= 3 &&
        !regions.has(p.region)
      )
        continue;
      if (divMode === "hc" && hcs.size >= 2 && !hcs.has(p.hc)) continue;
      selected.push(p);
      capexLeft -= p.capex;
      regions.add(p.region);
      hcs.add(p.hc);
    }
    if (selected.length < minProj) continue;

    const totalNPV = selected.reduce((s, p) => s + p.npvRisked, 0);
    const totalCapex = selected.reduce((s, p) => s + p.capex, 0);
    const avgRisk =
      selected.reduce((s, p) => s + p.riskScore, 0) / selected.length;

    frontierPts.push({
      rt,
      totalNPV,
      totalCapex,
      avgRisk,
      selected,
      n: selected.length,
    });
  }

  _poFrontierPts = frontierPts;

  // Find optimal: best NPV at given risk tolerance
  const optIdx = frontierPts.reduce((best, pt, i) => {
    const utilA =
      frontierPts[best].totalNPV * (1 - riskTol) -
      frontierPts[best].avgRisk * riskTol * 10;
    const utilB = pt.totalNPV * (1 - riskTol) - pt.avgRisk * riskTol * 10;
    return utilB > utilA ? i : best;
  }, 0);
  _poOptimalIdx = optIdx;

  // Mark selected on projects
  projects.forEach((p) => (p.selected = false));
  if (frontierPts[optIdx])
    frontierPts[optIdx].selected.forEach((p) => (p.selected = true));

  _updatePortOptKPIs(projects);
  _drawFrontierChart(frontierPts, optIdx);
}

function _drawFrontierChart(pts, optIdx) {
  const canvas = document.getElementById("portopt-frontier-canvas");
  if (!canvas) return;
  const ctx = canvas.getContext("2d");

  // Always read width from the card/parent — canvas may be in a freshly-shown section
  const card =
    canvas.closest(".card") ||
    canvas.closest(".cb") ||
    canvas.parentElement;
  const W = Math.max((card?.clientWidth || 400) - 32, 300);
  const H = 340;
  canvas.width = W;
  canvas.height = H;
  ctx.clearRect(0, 0, W, H);

  const PAD = { t: 24, b: 44, l: 62, r: 30 };
  const pw = W - PAD.l - PAD.r;
  const ph = H - PAD.t - PAD.b;

  if (!pts.length) return;

  const xs = pts.map((p) => p.avgRisk);
  const ys = pts.map((p) => p.totalNPV);
  const minX = Math.min(...xs) - 2,
    maxX = Math.max(...xs) + 2;
  const minY = Math.min(...ys) - 100,
    maxY = Math.max(...ys) + 100;

  const sx = (v) => PAD.l + ((v - minX) / (maxX - minX)) * pw;
  const sy = (v) => PAD.t + ph - ((v - minY) / (maxY - minY)) * ph;

  // Grid
  ctx.strokeStyle = "#F1F5F9";
  ctx.lineWidth = 1;
  for (let i = 0; i <= 5; i++) {
    const y = PAD.t + (ph * i) / 5;
    ctx.beginPath();
    ctx.moveTo(PAD.l, y);
    ctx.lineTo(PAD.l + pw, y);
    ctx.stroke();
    const val = maxY - ((maxY - minY) * i) / 5;
    ctx.fillStyle = "#94A3B8";
    ctx.font = "9px system-ui";
    ctx.textAlign = "right";
    ctx.fillText(`$${Math.round(val / 100) * 100}M`, PAD.l - 4, y + 3);
  }
  for (let i = 0; i <= 5; i++) {
    const x = PAD.l + (pw * i) / 5;
    ctx.beginPath();
    ctx.moveTo(x, PAD.t);
    ctx.lineTo(x, PAD.t + ph);
    ctx.stroke();
    const val = minX + ((maxX - minX) * i) / 5;
    ctx.fillStyle = "#94A3B8";
    ctx.font = "9px system-ui";
    ctx.textAlign = "center";
    ctx.fillText(Math.round(val), x, PAD.t + ph + 14);
  }

  // Axis labels
  ctx.fillStyle = "#64748B";
  ctx.font = "bold 9px system-ui";
  ctx.textAlign = "center";
  ctx.fillText(
    "Portfolio Risk Score (lower = safer)",
    PAD.l + pw / 2,
    H - 6,
  );
  ctx.save();
  ctx.translate(13, PAD.t + ph / 2);
  ctx.rotate(-Math.PI / 2);
  ctx.fillText("Expected NPV ($M)", 0, 0);
  ctx.restore();

  // Frontier curve
  ctx.beginPath();
  ctx.setLineDash([]);
  ctx.strokeStyle = "rgba(13,76,146,.25)";
  ctx.lineWidth = 1.5;
  pts.forEach((p, i) => {
    const x = sx(p.avgRisk),
      y = sy(p.totalNPV);
    i === 0 ? ctx.moveTo(x, y) : ctx.lineTo(x, y);
  });
  ctx.stroke();

  // Sub-optimal points
  pts.forEach((p, i) => {
    if (i === optIdx) return;
    const x = sx(p.avgRisk),
      y = sy(p.totalNPV);
    ctx.beginPath();
    ctx.arc(x, y, 4, 0, Math.PI * 2);
    ctx.fillStyle = "#CBD5E1";
    ctx.fill();
  });

  // Optimal point — large star
  if (pts[optIdx]) {
    const ox = sx(pts[optIdx].avgRisk),
      oy = sy(pts[optIdx].totalNPV);
    // Glow
    const grd = ctx.createRadialGradient(ox, oy, 0, ox, oy, 22);
    grd.addColorStop(0, "rgba(26,127,90,.3)");
    grd.addColorStop(1, "rgba(26,127,90,0)");
    ctx.beginPath();
    ctx.arc(ox, oy, 22, 0, Math.PI * 2);
    ctx.fillStyle = grd;
    ctx.fill();
    // Star
    _drawStar(ctx, ox, oy, 5, 10, 4, "#1A7F5A");

    // Label
    ctx.fillStyle = "#1A7F5A";
    ctx.font = "bold 9px system-ui";
    ctx.textAlign = "left";
    ctx.fillText(
      `★ Optimal: $${pts[optIdx].totalNPV.toLocaleString()}M`,
      ox + 14,
      oy + 3,
    );
  }

  // NPV=0 line
  if (minY < 0 && maxY > 0) {
    const y0 = sy(0);
    ctx.beginPath();
    ctx.setLineDash([4, 3]);
    ctx.strokeStyle = "rgba(198,40,40,.4)";
    ctx.lineWidth = 1;
    ctx.moveTo(PAD.l, y0);
    ctx.lineTo(PAD.l + pw, y0);
    ctx.stroke();
    ctx.setLineDash([]);
    ctx.fillStyle = "#C62828";
    ctx.font = "8px system-ui";
    ctx.textAlign = "left";
    ctx.fillText("NPV = 0", PAD.l + 4, y0 - 3);
  }

  // Hover tooltip
  _attachFrontierHover(canvas, pts, optIdx, sx, sy);
}

function _drawStar(ctx, cx, cy, spikes, outerR, innerR, color) {
  let rot = (Math.PI / 2) * 3,
    step = Math.PI / spikes;
  ctx.beginPath();
  ctx.moveTo(cx, cy - outerR);
  for (let i = 0; i < spikes; i++) {
    ctx.lineTo(cx + Math.cos(rot) * outerR, cy + Math.sin(rot) * outerR);
    rot += step;
    ctx.lineTo(cx + Math.cos(rot) * innerR, cy + Math.sin(rot) * innerR);
    rot += step;
  }
  ctx.closePath();
  ctx.fillStyle = color;
  ctx.fill();
  ctx.strokeStyle = "#fff";
  ctx.lineWidth = 1.5;
  ctx.stroke();
}

function _attachFrontierHover(canvas, pts, optIdx, sx, sy) {
  const tip = document.getElementById("po-frontier-tooltip");
  if (!tip) return;
  canvas.onmousemove = (e) => {
    const rect = canvas.getBoundingClientRect();
    const mx = e.clientX - rect.left,
      my = e.clientY - rect.top;
    let closest = null,
      minDist = 20;
    pts.forEach((p, i) => {
      const d = Math.hypot(sx(p.avgRisk) - mx, sy(p.totalNPV) - my);
      if (d < minDist) {
        closest = { p, i };
        minDist = d;
      }
    });
    if (closest) {
      const { p, i } = closest;
      tip.style.display = "block";
      tip.style.left = sx(p.avgRisk) + 14 + "px";
      tip.style.top = sy(p.totalNPV) - 20 + "px";
      tip.innerHTML = `
  <b style="color:${i === optIdx ? "#86EFAC" : "#94D2E0"}">${i === optIdx ? "★ Optimal" : "Portfolio"}</b><br>
  Projects: <b>${p.n}</b><br>
  CAPEX: <b>$${p.totalCapex.toLocaleString()}M</b><br>
  Risked NPV: <b style="color:${p.totalNPV >= 0 ? "#86EFAC" : "#FCA5A5"}">$${p.totalNPV.toLocaleString()}M</b><br>
  Risk Score: <b>${p.avgRisk.toFixed(0)}</b><br>
  Basins: <b style="font-size:10px">${p.selected
    .map((s) => s.name)
    .slice(0, 3)
    .join(", ")}${p.selected.length > 3 ? "…" : ""}</b>`;
    } else {
      tip.style.display = "none";
    }
  };
  canvas.onmouseleave = () => {
    tip.style.display = "none";
  };
}

// ── Optimize → switches to Allocation tab ────────────────────
function optimizePortfolio() {
  renderEfficientFrontier();
  const allTabs = document.querySelectorAll("#portopt-tabs .tab");
  switchPortOptTab("allocation", allTabs[1]);
  toast("Portfolio optimised — see Capital Allocation tab", "success");

  // Cross-module: propagate to Economics tab oil price if set
  if (_poLastProjects) {
    const oilPrice = +(
      document.getElementById("portopt-oil-price")?.value || 75
    );
    const epEl = document.getElementById("econ-price");
    if (epEl && Math.abs(+epEl.value - oilPrice) > 0.5) {
      // Don't overwrite if user has set a different price — just highlight
    }
  }
}

// ── Sync from Economics tab ───────────────────────────────────
function syncFromEconomics() {
  const epEl = document.getElementById("econ-price");
  const opEl = document.getElementById("portopt-oil-price");
  if (epEl && opEl && +epEl.value > 0) {
    opEl.value = epEl.value;
    opEl.style.background = "rgba(26,127,90,.12)";
    setTimeout(() => {
      opEl.style.background = "";
    }, 1500);
    renderEfficientFrontier();
    toast(
      `Oil price synced from Economics: $${epEl.value}/bbl`,
      "success",
    );
  } else {
    toast("No price set in Economics tab yet", "warning");
  }
  // Also sync live spot price if available
  if (window._liveSpot?.brent && opEl) {
    opEl.value = (+window._liveSpot.brent).toFixed(2);
    renderEfficientFrontier();
    toast(
      `Synced live Brent spot $${(+window._liveSpot.brent).toFixed(2)}/bbl → Portfolio`,
      "success",
    );
  }
}

// ══════════════════════════════════════════════════════════════
// TAB 2 — CAPITAL ALLOCATION
// ══════════════════════════════════════════════════════════════
function renderAllocationTab() {
  if (!_poLastProjects || _poOptimalIdx < 0) {
    renderEfficientFrontier();
    if (!_poLastProjects) return;
  }
  const pt = _poFrontierPts[_poOptimalIdx];
  if (!pt) return;
  const selected = pt.selected;

  // Badge
  const badge = document.getElementById("po-alloc-badge");
  if (badge)
    badge.textContent = `${selected.length} projects · $${pt.totalCapex.toLocaleString()}M`;

  // Table
  const tbody = document.getElementById("portopt-alloc-body");
  if (!tbody) return;

  const totalCapex = pt.totalCapex;
  const totalNPV = pt.totalNPV;
  const hcColors = {
    Oil: "#0D4C92",
    Gas: "#C07800",
    "Oil & Gas": "#059669",
  };

  tbody.innerHTML = `
    <div style="overflow-x:auto">
      <table style="width:100%;border-collapse:collapse;font-size:10px; padding-bottom: 4px">
        <thead>
          <tr style="background:#F8FAFC;border-bottom:2px solid #E2E8F0">
            <th style="padding:8px 10px;text-align:left;font-size:10px;color:var(--t3);text-transform:uppercase;letter-spacing:.5px">Basin / Project</th>
            <th style="padding:8px 6px;text-align:center;font-size:10px;color:var(--t3);text-transform:uppercase">Region</th>
            <th style="padding:8px 6px;text-align:center;font-size:10px;color:var(--t3);text-transform:uppercase">HC</th>
            <th style="padding:8px 6px;text-align:right;font-size:10px;color:var(--t3);text-transform:uppercase">CAPEX $M</th>
            <th style="padding:8px 6px;text-align:right;font-size:10px;color:var(--t3);text-transform:uppercase">Alloc %</th>
            <th style="padding:8px 6px;text-align:right;font-size:10px;color:var(--t3);text-transform:uppercase">Risked NPV $M</th>
            <th style="padding:8px 6px;text-align:right;font-size:10px;color:var(--t3);text-transform:uppercase">GCoS %</th>
            <th style="padding:8px 6px;text-align:right;font-size:10px;color:var(--t3);text-transform:uppercase">PI</th>
            <th style="padding:8px 6px;text-align:center;font-size:10px;color:var(--t3);text-transform:uppercase">Score</th>
            <th style="padding:8px 6px;text-align:center;font-size:10px;color:var(--t3);text-transform:uppercase">→ Economics</th>
          </tr>
        </thead>
        <tbody>
          ${selected
            .sort((a, b) => b.capex - a.capex)
            .map((p, i) => {
              const alloc = ((p.capex / totalCapex) * 100).toFixed(1);
              const nc = p.npvRisked >= 0 ? "#1A7F5A" : "#C62828";
              const hcC = hcColors[p.hc] || "#64748B";
              const barW = Math.round(
                (p.capex / Math.max(...selected.map((s) => s.capex))) * 80,
              );
              return `
              <tr style="border-bottom:1px solid #F1F5F9;${i % 2 === 0 ? "background:var(--bg3)" : ""}">
                <td style="padding:8px 10px">
                  <div style="font-weight:700;color:var(--t2)">${p.name}</div>
                  <div style="font-size:10px;color:var(--t3)">${p.country}</div>
                  <div style="height:3px;background:#E2E8F0;border-radius:2px;margin-top:4px;width:100%">
                    <div style="height:3px;background:${hcC};border-radius:2px;width:${barW}%"></div>
                  </div>
                </td>
                <td style="padding:8px 6px;text-align:center;font-size:10px;color:var(--t3)">${p.region}</td>
                <td style="padding:8px 6px;text-align:center; white-space: nowrap">
                  <span style="background:${hcC}22;color:${hcC};border-radius:3px;padding:1px 5px;font-size:10px;font-weight:700">${p.hc}</span>
                </td>
                <td style="padding:8px 6px;text-align:right;font-weight:700">$${p.capex.toLocaleString()}</td>
                <td style="padding:8px 6px;text-align:right;color:var(--amber);font-weight:700">${alloc}%</td>
                <td style="padding:8px 6px;text-align:right;font-weight:700;color:${nc}">${p.npvRisked >= 0 ? "+" : ""}$${p.npvRisked.toLocaleString()}</td>
                <td style="padding:8px 6px;text-align:right;color:var(--purple)">${p.gcos}%</td>
                <td style="padding:8px 6px;text-align:right">${p.pi}×</td>
                <td style="padding:8px 6px;text-align:center">
                  <span style="background:${p.score >= 70 ? "rgba(26,127,90,.12)" : p.score >= 50 ? "rgba(192,120,0,.12)" : "rgba(198,40,40,.12)"};
                    color:${p.score >= 70 ? "#1A7F5A" : p.score >= 50 ? "#C07800" : "#C62828"};
                    border-radius:3px;padding:2px 6px;font-size:10px;font-weight:700">${p.score}</span>
                </td>
                <td style="padding:8px 6px;text-align:center">
                  <button onclick="loadBasinToEconomics('${p.name}')"
                    style="background:rgba(13,76,146,.1);color:var(--sb2);border:1px solid rgba(13,76,146,.2);
                    border-radius:4px;padding:2px 7px;font-size:10px;cursor:pointer;font-weight:600">
                    Load →
                  </button>
                </td>
              </tr>
            `;
            })
            .join("")}
          <tr style="background:var(--bg3);font-weight:700;border-top:2px solid #E2E8F0">
            <td style="padding:8px 10px" colspan="3">Portfolio Total</td>
            <td style="padding:8px 6px;text-align:right">$${totalCapex.toLocaleString()}</td>
            <td style="padding:8px 6px;text-align:right;color:var(--amber)">100%</td>
            <td style="padding:8px 6px;text-align:right;color:${totalNPV >= 0 ? "#1A7F5A" : "#C62828"}">${totalNPV >= 0 ? "+" : ""}$${totalNPV.toLocaleString()}</td>
            <td colspan="4"></td>
          </tr>
        </tbody>
      </table>
    </div>
  `;

  // Donut + region bar charts
  _drawAllocDonut(selected);
  _drawRegionBar(selected);
}

let _poAllocChart = null;

function _drawAllocDonut(selected) {
  const canvas = document.getElementById("po-alloc-donut");
  if (!canvas) return;

  const ctx = canvas.getContext("2d");

  const colors = [
    "#0D4C92",
    "#059669",
    "#C07800",
    "#7C3AED",
    "#C62828",
    "#0891B2",
    "#65A30D",
    "#DB2777",
  ];

  const labels = selected.map((p) => p.name);
  const values = selected.map((p) => p.capex);
  const total = values.reduce((a, b) => a + b, 0);

  // destroy old chart
  if (_poAllocChart) {
    _poAllocChart.destroy();
  }

  _poAllocChart = new Chart(ctx, {
    type: "doughnut",
    data: {
      labels: labels,
      datasets: [
        {
          data: values,
          backgroundColor: colors,
          borderColor: "#ffffff",
          borderWidth: 2,
        },
      ],
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      cutout: "60%",
      plugins: {
        legend: {
          display: false,
        },
      },
    },
    plugins: [
      {
        id: "centerText",
        afterDraw(chart) {
          const { width } = chart;
          const { ctx } = chart;
          ctx.save();

          ctx.textAlign = "center";
          ctx.textBaseline = "middle";

          ctx.fillStyle = "#1E293B";
          ctx.font = "bold 11px system-ui";
          ctx.fillText(`$${(total / 1000).toFixed(1)}B`, width / 2, 90);

          ctx.fillStyle = "#94A3B8";
          ctx.font = "8px system-ui";
          ctx.fillText("Total CAPEX", width / 2, 104);

          ctx.restore();
        },
      },
    ],
  });

  // Custom legend (same as yours)
  const legend = document.getElementById("po-alloc-legend");

  if (legend) {
    legend.innerHTML = selected
      .map(
        (p, i) => `
        <div style="display:flex;align-items:center;gap:5px;margin-bottom:3px">
          <div style="width:8px;height:8px;border-radius:2px;background:${colors[i % colors.length]};flex-shrink:0"></div>
          <span style="color:var(--t2);font-size:10px;flex:1">${p.name}</span>
          <span style="color:var(--t3);font-size:10px">${((p.capex / total) * 100).toFixed(0)}%</span>
        </div>
      `,
      )
      .join("");
  }
}

let _poRegionChart = null;

function _drawRegionBar(selected) {
  const canvas = document.getElementById("po-region-bar");
  if (!canvas) return;

  // Group CAPEX by region
  const regionTotals = {};
  selected.forEach((p) => {
    regionTotals[p.region] = (regionTotals[p.region] || 0) + p.capex;
  });

  const entries = Object.entries(regionTotals).sort((a, b) => b[1] - a[1]);

  const labels = entries.map(([region]) =>
    region.length > 12 ? region.slice(0, 12) + "…" : region
  );

  const values = entries.map(([, val]) => val);

  const colors = [
    "#0D4C92",
    "#059669",
    "#C07800",
    "#7C3AED",
    "#C62828",
    "#0891B2",
  ];

  const ctx = canvas.getContext("2d");

  // destroy previous chart
  if (_poRegionChart) {
    _poRegionChart.destroy();
  }

  _poRegionChart = new Chart(ctx, {
    type: "bar",
    data: {
      labels: labels,
      datasets: [
        {
          label: "CAPEX ($M)",
          data: values,
          backgroundColor: colors,
          borderRadius: 4,
          barThickness: 12,
          categoryPercentage: 1,
          barPercentage: 0.9
        },
      ],
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      indexAxis: "y", // makes it horizontal
      plugins: {
        legend: {
          display: false,
        },
        tooltip: {
          callbacks: {
            label: function (ctx) {
              return "$" + ctx.raw.toLocaleString() + "M";
            },
          },
        },
        title: {
          display: true,
          text: "CAPEX by Region",
          align: "start",
          color: "#64748B",
          font: {
            size: 10,
            weight: "600",
          },
        },
      },
      scales: {
        x: {
          grid: {
            color: "#E2E8F0",
          },
          ticks: {
            color: "#64748B",
            font: { size: 8 },
            callback: (v) => "$" + v,
          },
        },
        y: {
          grid: {
            display: false,
          },
          ticks: {
            color: "#64748B",
            font: { size: 8 },
          },
        },
      },
    },
  });
}

// Load basin into economics tab
function loadBasinToEconomics(basinName) {
  const key = `basin:${basinName}`;
  if (typeof loadEconFromDatabase === "function") {
    loadEconFromDatabase(key);
    // Navigate to economics section
    const econNav = document.querySelector('[onclick*="economics"]');
    if (econNav) econNav.click();
    toast(`${basinName} → Economics loaded`, "success");
  } else {
    toast("Economics module not available", "warning");
  }
}

// Export allocation as CSV
function exportAllocation() {
  if (!_poFrontierPts[_poOptimalIdx]) {
    toast("Run Optimize first", "warning");
    return;
  }
  const sel = _poFrontierPts[_poOptimalIdx].selected;
  const rows = [
    [
      "Basin",
      "Country",
      "Region",
      "HC",
      "CAPEX_$M",
      "Alloc_%",
      "Risked_NPV_$M",
      "GCoS_%",
      "PI",
      "Score",
    ],
  ];
  const total = sel.reduce((s, p) => s + p.capex, 0);
  sel.forEach((p) =>
    rows.push([
      p.name,
      p.country,
      p.region,
      p.hc,
      p.capex,
      ((p.capex / total) * 100).toFixed(1),
      p.npvRisked,
      p.gcos,
      p.pi,
      p.score,
    ]),
  );
  const csv = rows.map((r) => r.join(",")).join("\n");
  const blob = new Blob([csv], { type: "text/csv" });
  const a = document.createElement("a");
  a.href = URL.createObjectURL(blob);
  a.download = "portfolio_allocation.csv";
  a.click();
  toast("Allocation exported as CSV", "success");
}

