function lbUpdateNormFormula() {
  const tot = Object.values(_lbWeights).reduce((s, v) => s + v, 0) || 1;
  const parts = LB_ELEMENTS.filter((el) => _lbWeights[el.key] > 0).map(
    (el) => `${el.key}×${((_lbWeights[el.key] / tot) * 100).toFixed(1)}%`,
  );
  const text = parts.join(" + ");
  const el = document.getElementById("lb-norm-formula");
  if (el) el.textContent = text;
  const pvEl = document.getElementById("lb-formula-preview-text");
  if (pvEl) pvEl.textContent = text;
}

function lbUpdateMultFormula() {
  const parts = LB_ELEMENTS.filter((el) => _lbMultEnabled[el.key]).map(
    (el) =>
      _lbMultPow[el.key] === 1
        ? el.key
        : `${el.key}^${_lbMultPow[el.key].toFixed(1)}`,
  );
  const text = parts.join(" × ");
  const el = document.getElementById("lb-mult-formula-text");
  if (el) el.textContent = text || "(select elements above)";
  const pvEl2 = document.getElementById("lb-formula-preview-text");
  if (pvEl2) pvEl2.textContent = text;
}

function lbInsertExpr(expr) {
  const ta = document.getElementById("lb-custom-expr");
  if (ta) {
    ta.value = expr;
    lbUpdateCustomPreview();
  }
}

function lbUpdateCustomPreview() {
  const expr =
    document.getElementById("lb-custom-expr")?.value?.trim() || "";
  _lbCustomExpr = expr;
  const errEl = document.getElementById("lb-custom-err");
  const prevEl = document.getElementById("lb-custom-preview");
  if (!expr) {
    if (prevEl) prevEl.textContent = "Type an expression to see a live preview…";
    if (errEl) errEl.style.display = "none";
    return;
  }
  try {
    const testVals = {
      source: 70,
      reservoir: 65,
      seal: 60,
      charge: 55,
      commercial: 50,
      country: 40,
    };
    const fn = new Function(
      "source",
      "reservoir",
      "seal",
      "charge",
      "commercial",
      "country",
      `return (${expr});`,
    );
    const result = fn(
      testVals.source,
      testVals.reservoir,
      testVals.seal,
      testVals.charge,
      testVals.commercial,
      testVals.country,
    );
    if (typeof result !== "number" || isNaN(result))
      throw new Error("Expression must return a number");
    if (prevEl) { prevEl.textContent = `Preview (with sample values 70/65/60/55/50/40): → ${result.toFixed(2)}`; prevEl.style.color = "var(--green)"; }
    if (errEl) errEl.style.display = "none";
    const pvEl3 = document.getElementById("lb-formula-preview-text");
    if (pvEl3) pvEl3.textContent = expr;
  } catch (e) {
    if (prevEl) prevEl.textContent = "";
    if (errEl) { errEl.textContent = "⚠ " + e.message; errEl.style.display = "block"; }
  }
}

// ── Active BSF formula flag (set when BSF formula is applied to leaderboard) ──
let _bsfAppliedToLb = false;

function lbComputeScore(scores) {
  // If BSF formula has been applied, delegate to bsfComputeScore using mapped keys
  if (_bsfAppliedToLb && typeof bsfComputeScore === "function") {
    const mapped = {
      src:  scores.source      ?? 50,
      res:  scores.reservoir   ?? 50,
      seal: scores.seal        ?? 50,
      chg:  scores.charge      ?? 50,
      com:  scores.commercial  ?? 50,
      cty:  scores.country     ?? 50,
    };
    return Math.round(bsfComputeScore(mapped));
  }
  const {
    source = 50,
    reservoir = 50,
    seal = 50,
    charge = 50,
    commercial = 50,
    country = 50,
  } = scores;
  if (_lbMode === "weighted") {
    const tot = Object.values(_lbWeights).reduce((s, v) => s + v, 0) || 1;
    return Math.round(
      LB_ELEMENTS.reduce(
        (s, el) => s + (scores[el.key] * (_lbWeights[el.key] || 0)) / tot,
        0,
      ),
    );
  }
  if (_lbMode === "multiplicative") {
    const active = LB_ELEMENTS.filter((el) => _lbMultEnabled[el.key]);
    if (!active.length) return 0;
    // Product of (score/100)^pow, then scale back to 0-100
    const product = active.reduce(
      (p, el) => p * Math.pow(scores[el.key] / 100, _lbMultPow[el.key]),
      1,
    );
    return Math.round(Math.pow(product, 1 / active.length) * 100);
  }
  if (_lbMode === "custom" && _lbCustomExpr) {
    try {
      const fn = new Function(
        "source",
        "reservoir",
        "seal",
        "charge",
        "commercial",
        "country",
        `return (${_lbCustomExpr});`,
      );
      const raw = fn(
        source,
        reservoir,
        seal,
        charge,
        commercial,
        country,
      );
      return Math.max(0, Math.min(100, Math.round(raw)));
    } catch (e) {
      return 0;
    }
  }
  return Math.round(
    LB_ELEMENTS.reduce(
      (s, el) => s + scores[el.key] / LB_ELEMENTS.length,
      0,
    ),
  );
}

function lbReapplyFormula() {
  if (!leaderboardData.length) {
    toast("Run screening first to generate leaderboard data", "warn");
    return;
  }
  const activeOverrides = Object.entries(_elemActiveExprs || {}).filter(
    ([, v]) => v,
  );
  leaderboardData = leaderboardData
    .map((b) => {
      // 1. Start from stored scores
      const newScores = { ...b.scores };
      // 2. Apply any active element overrides
      for (const [tabId, expr] of activeOverrides) {
        const scoreKey = _elemToScoreKey[tabId];
        if (!scoreKey) continue;
        const v = _evalElemExpr(tabId, expr, b._basinPrior || b.scores);
        if (v !== null) newScores[scoreKey] = v;
      }
      // 3. Recompute composite with (potentially overridden) scores
      return {
        ...b,
        scores: newScores,
        composite: lbComputeScore(newScores),
      };
    })
    .sort((a, b) => b.composite - a.composite)
    .map((b, i) => ({ ...b, rank: i + 1 }));
  renderLeaderboard();
  const n = activeOverrides.length;
  toast(
    "Leaderboard re-ranked" +
      (n
        ? " · " + n + " element override" + (n > 1 ? "s" : "") + " active"
        : ""),
    "success",
  );
}

// Preset loading
function lbLoadPreset() {
  const dd = document.getElementById("lb-preset-dropdown");
  const visible = dd.style.display !== "none";
  dd.style.display = visible ? "none" : "block";
  // Position near button
  if (!visible) {
    document.addEventListener(
      "click",
      function _close(e) {
        if (!dd.contains(e.target)) {
          dd.style.display = "none";
          document.removeEventListener("click", _close);
        }
      },
      { once: true },
    );
  }
}

function lbApplyPreset(name) {
  document.getElementById("lb-preset-dropdown").style.display = "none";
  const p = LB_PRESETS[name];
  if (!p) return;
  if (p.mode === "weighted" && p.weights) {
    lbSetMode("weighted");
    Object.assign(_lbWeights, p.weights);
  } else if (p.mode === "multiplicative") {
    lbSetMode("multiplicative");
    if (p.mult) Object.assign(_lbMultEnabled, p.mult);
  }
  lbRenderSliders();
  lbReapplyFormula();
  toast(`Preset "${name.replace(/_/g, " ")}" applied`, "success");
}

// Save / load persisted formulas
function lbSaveFormula() {
  const name = document
    .getElementById("lb-formula-save-name")
    ?.value?.trim();
  if (!name) {
    toast("Enter a name for this formula", "warn");
    return;
  }
  const entry = {
    name,
    mode: _lbMode,
    weights: { ..._lbWeights },
    multEnabled: { ..._lbMultEnabled },
    multPow: { ..._lbMultPow },
    customExpr: _lbCustomExpr,
  };
  _lbSavedFormulas = _lbSavedFormulas.filter((f) => f.name !== name);
  _lbSavedFormulas.push(entry);
  try {
    localStorage.setItem("lb_formulas", JSON.stringify(_lbSavedFormulas));
  } catch (e) {}
  lbRenderSavedChips();
  toast(`Formula "${name}" saved`, "success");
  const snEl = document.getElementById("lb-formula-save-name");
  if (snEl) snEl.value = "";
}

function lbLoadSavedFormula(name) {
  const f = _lbSavedFormulas.find((x) => x.name === name);
  if (!f) return;
  _lbMode = f.mode;
  Object.assign(_lbWeights, f.weights || {});
  Object.assign(_lbMultEnabled, f.multEnabled || {});
  Object.assign(_lbMultPow, f.multPow || {});
  _lbCustomExpr = f.customExpr || "";
  if (f.customExpr) {
    const ta = document.getElementById("lb-custom-expr");
    if (ta) ta.value = f.customExpr;
  }
  lbSetMode(_lbMode);
  lbRenderSliders();
  lbReapplyFormula();
  toast(`Formula "${name}" loaded`, "success");
}

function lbDeleteSavedFormula(name) {
  _lbSavedFormulas = _lbSavedFormulas.filter((f) => f.name !== name);
  try {
    localStorage.setItem("lb_formulas", JSON.stringify(_lbSavedFormulas));
  } catch (e) {}
  lbRenderSavedChips();
}

function lbRenderSavedChips() {
  const cont = document.getElementById("lb-saved-chips");
  if (!cont) return;
  if (!_lbSavedFormulas.length) {
    cont.innerHTML =
      '<span style="font-size:10px;color:var(--t3)">No saved formulas yet</span>';
    return;
  }
  cont.innerHTML = _lbSavedFormulas
    .map(
      (f) => `
<span class="lb-saved-chip" onclick="lbLoadSavedFormula('${f.name.replace(/'/g, "\\'")}')">
${f.mode === "weighted" ? "" : f.mode === "multiplicative" ? "" : ""}
${f.name}
<span class="lb-chip-del" onclick="event.stopPropagation();lbDeleteSavedFormula('${f.name.replace(/'/g, "\\'")}')">×</span>
</span>`,
    )
    .join("");
}

