//  Shared AI caller (reuse existing _aiCfg pattern) 
async function _hubAICall(systemPrompt, userPrompt, maxTok) {
  try {
    var res = await fetch('https://api.anthropic.com/v1/messages', {
      method:'POST',
      headers:{
        'Content-Type':'application/json',
        'anthropic-version':'2023-06-01',
        'anthropic-dangerous-direct-browser-access':'true',
        'x-api-key':(window._hubAiKey ? window._hubAiKey() : (function(){try{return JSON.parse(localStorage.getItem('edafy_ai_config')||'{}').claudeKey||'';}catch(e){return '';}}())),
      },
      body:JSON.stringify({
        model:'claude-sonnet-4-6',
        max_tokens:maxTok||800,
        system:systemPrompt,
        messages:[{role:'user',content:userPrompt}]
      })
    });
    var d = await res.json();
    if(d.content&&d.content[0]) return d.content[0].text;
    if(d.error) return '! '+d.error.message;
    return null;
  } catch(e) { return '! Could not reach AI — check API key in Settings.'; }
}

function _hubAiLoading(el, msg) {
  if(!el) return;
  el.innerHTML = '<div style="display:flex;align-items:center;gap:10px;padding:32px;color:var(--t3);font-size:10px">'
    +'<span style="display:inline-flex;gap:3px">'
    +'<span style="width:6px;height:6px;border-radius:50%;background:var(--cyan);animation:kg-ai-dot 1.2s ease-in-out infinite"></span>'
    +'<span style="width:6px;height:6px;border-radius:50%;background:var(--cyan);animation:kg-ai-dot 1.2s ease-in-out .24s infinite"></span>'
    +'<span style="width:6px;height:6px;border-radius:50%;background:var(--cyan);animation:kg-ai-dot 1.2s ease-in-out .48s infinite"></span>'
    +'</span><span>'+(msg||'AI thinking…')+'</span></div>';
}

function _mdToHtml(t) {
  return t.replace(/\*\*(.*?)\*\*/g,'<b>$1</b>')
    .replace(/\*(.*?)\*/g,'<em>$1</em>')
    .replace(/^#{1,3} (.+)$/gm,'<div style="font-size:11px;font-weight:700;color:var(--t1);margin:10px 0 5px;padding-bottom:3px;border-bottom:1px solid var(--b1)">$1</div>')
    .replace(/\n\n/g,'</p><p style="margin:5px 0">')
    .replace(/\n/g,'<br>');
}

