function _mercatorXY(lon, lat, W, H) {
  // Simple equirectangular projection
  var x = (lon + 180) / 360 * W;
  var latRad = lat * Math.PI / 180;
  var mercN = Math.log(Math.tan(Math.PI/4 + latRad/2));
  var y = H/2 - (mercN / (2*Math.PI)) * H * 1.2 + H*0.05;
  return {x:x, y:y};
}

