function hubMapRender() {
  var wrap = document.getElementById('hub-map-container'); if(!wrap) return;
  var canvas = document.getElementById('hub-map-canvas'); if(!canvas) return;
  var colorBy = (document.getElementById('map-color-by')||{}).value || 'score';
  var basins = window.BASINS || [];
  var W = wrap.clientWidth || 800, H = wrap.clientHeight || 480;
  canvas.width = W; canvas.height = H;
  canvas.style.width = W+'px'; canvas.style.height = H+'px';
  var ctx = canvas.getContext('2d');
  ctx.clearRect(0,0,W,H);

  // Draw ocean background
  ctx.fillStyle = '#0f1e2e';
  ctx.fillRect(0,0,W,H);

  // Draw simple world outline (just graticules)
  ctx.strokeStyle = 'rgba(255,255,255,0.04)';
  ctx.lineWidth = 0.5;
  for(var lon=-180;lon<=180;lon+=30){
    var p1=_mercatorXY(lon,-80,W,H), p2=_mercatorXY(lon,80,W,H);
    ctx.beginPath();ctx.moveTo(p1.x,p1.y);ctx.lineTo(p2.x,p2.y);ctx.stroke();
  }
  for(var lat=-60;lat<=60;lat+=30){
    ctx.beginPath();
    for(var lo=-180;lo<=180;lo+=5){
      var pp=_mercatorXY(lo,lat,W,H);
      if(lo===-180)ctx.moveTo(pp.x,pp.y);else ctx.lineTo(pp.x,pp.y);
    }
    ctx.stroke();
  }

  // Colour schemes
  var scoreColor = function(b) {
    var s=b.score||50;
    return s>=80?'#10B981':s>=60?'#F59E0B':'#EF4444';
  };
  var hcColor = function(b){
    var h=(b.hc||'').toLowerCase();
    return h.includes('oil')?'#F59E0B':h.includes('gas')?'#60A5FA':'#A78BFA';
  };
  var statusColor = function(b){
    var s=(b.status||'').toLowerCase();
    return s==='mature'?'#10B981':s==='emerging'?'#F59E0B':'#64748B';
  };
  var regionColors = {'Middle East':'#F59E0B','North America':'#60A5FA','Europe':'#A78BFA',
    'Asia Pacific':'#10B981','Africa':'#EF4444','South America':'#FB923C','Arctic':'#67E8F9'};
  var regionColor = function(b){ return regionColors[b.region]||'#64748B'; };

  var getColor = colorBy==='score'?scoreColor:colorBy==='hc'?hcColor:colorBy==='region'?regionColor:statusColor;

  // Draw basin markers
  var tt = document.getElementById('hub-map-tooltip');
  canvas._basinPositions = [];

  basins.forEach(function(b) {
    var coords = _BASIN_COORDS[b.name];
    if(!coords) return;
    var pos = _mercatorXY(coords.lon, coords.lat, W, H);
    var col = getColor(b);
    var r = 10 + (b.score||50)/12;

    // Glow
    var gr = ctx.createRadialGradient(pos.x,pos.y,r*0.3,pos.x,pos.y,r*2);
    gr.addColorStop(0,col+'55'); gr.addColorStop(1,col+'00');
    ctx.beginPath();ctx.arc(pos.x,pos.y,r*2,0,Math.PI*2);
    ctx.fillStyle=gr;ctx.fill();

    // Circle
    ctx.beginPath();ctx.arc(pos.x,pos.y,r,0,Math.PI*2);
    ctx.fillStyle=col+'cc';ctx.fill();
    ctx.strokeStyle=col;ctx.lineWidth=1.5;ctx.stroke();

    // Score label
    ctx.font='bold 8px system-ui';ctx.textAlign='center';ctx.fillStyle='#fff';
    ctx.fillText(b.score||'?',pos.x,pos.y+3);

    // Basin name
    ctx.font='8px system-ui';ctx.fillStyle='rgba(255,255,255,0.7)';
    ctx.fillText(b.name.substring(0,16),pos.x,pos.y+r+11);

    canvas._basinPositions.push({b:b, x:pos.x, y:pos.y, r:r});
  });

  // Build legend
  var legend = document.getElementById('map-legend');
  if(legend) {
    if(colorBy==='score'){
      legend.innerHTML = ['<span style="color:#10B981"> Score ≥80</span>','<span style="color:#F59E0B"> 60–79</span>','<span style="color:#EF4444"> &lt;60</span>'].join(' ');
    } else if(colorBy==='hc'){
      legend.innerHTML = '<span style="color:#F59E0B"> Oil</span> <span style="color:#60A5FA"> Gas</span> <span style="color:#A78BFA"> Both</span>';
    } else if(colorBy==='region'){
      legend.innerHTML = Object.keys(regionColors).map(function(r){return '<span style="color:'+regionColors[r]+'"> '+r+'</span>';}).join(' ');
    } else {
      legend.innerHTML = '<span style="color:#10B981"> Mature</span> <span style="color:#F59E0B"> Emerging</span> <span style="color:#64748B"> Frontier</span>';
    }
  }

  // Hover interaction
  canvas.onmousemove = function(e) {
    var rect = canvas.getBoundingClientRect();
    var mx = e.clientX-rect.left, my = e.clientY-rect.top;
    var hit = null;
    (canvas._basinPositions||[]).forEach(function(bp){
      var dx=mx-bp.x,dy=my-bp.y;
      if(Math.sqrt(dx*dx+dy*dy)<=bp.r+6) hit=bp.b;
    });
    if(hit && tt) {
      tt.style.display='block';
      tt.style.left=Math.min(mx+12,W-160)+'px';
      tt.style.top=Math.max(my-8,4)+'px';
      tt.innerHTML='<b style="color:var(--brand)">'+hit.name+'</b><br>'
        +'<span style="color:var(--t3)">'+hit.region+' · '+hit.country+'</span><br>'
        +'Score: <b style="color:'+(hit.score>=70?'#10B981':'#F59E0B')+'">'+hit.score+'/100</b> · '+hit.status+'<br>'
        +'HC: '+hit.hc+' · Plays: '+hit.plays+'<br>'
        +'Area: '+(hit.area||0).toLocaleString()+' km²<br>'
        +'<span style="color:var(--cyan);font-size:8px">Click to select basin</span>';
      canvas.style.cursor='pointer';
    } else {
      if(tt) tt.style.display='none';
      canvas.style.cursor='default';
    }
  };
  canvas.onclick = function(e) {
    var rect = canvas.getBoundingClientRect();
    var mx = e.clientX-rect.left, my = e.clientY-rect.top;
    (canvas._basinPositions||[]).forEach(function(bp){
      var dx=mx-bp.x,dy=my-bp.y;
      if(Math.sqrt(dx*dx+dy*dy)<=bp.r+6){
        var sel=document.getElementById('hub-sel-basin');
        if(sel){sel.value=bp.b.name;hubOnBasinChange();}
        hubSwitchTab('hierarchy');
      }
    });
  };
  canvas.onmouseleave=function(){if(tt)tt.style.display='none';};
}

// 
//  2. PROSPECT RANKING COPILOT
// 
function hubCopilotInit() {
  // nothing needed on init — just show the default state
}

async function hubCopilotRun() {
  var out = document.getElementById('copilot-output'); if(!out) return;
  var rankBy   = (document.getElementById('copilot-rank-by')||{}).value||'gcos';
  var focus    = (document.getElementById('copilot-focus')||{}).value||'all';
  var budget   = parseFloat((document.getElementById('copilot-budget')||{}).value||500);
  var prospects = window.PROSPECTS||[];
  var _ctx = window._hubCtx || {};
  if(focus==='basin' && _ctx.basin) {
    prospects = prospects.filter(function(p){
      var pl=(window.PLAYS||[]).find(function(x){return x.id===p.playId;});
      return pl && pl.basin===_ctx.basin;
    });
  }
  if(!prospects.length){out.innerHTML='<div style="padding:32px;text-align:center;color:var(--t3)">No prospects found for selected focus.</div>';return;}

  _hubAiLoading(out,'Ranking '+prospects.length+' prospects…');

  var prospectData = prospects.map(function(p,i){
    var pl=(window.PLAYS||[]).find(function(x){return x.id===p.playId;});
    var ps=(window.PETROLEUM_SYSTEMS||[]).find(function(x){return pl&&x.id===pl.petSysId;});
    var drillCostM = p.depthM ? Math.round(p.depthM*0.025+15) : 40; // rough cost estimate
    var emv = (p.gcos||0)*(p.p50Mmboe||0)*6 - (1-(p.gcos||0))*drillCostM; // $/bbl * MMboe rough
    return (i+1)+'. '+p.name
      +' | Basin: '+(pl?pl.basin:'?')
      +' | GCoS: '+Math.round((p.gcos||0)*100)+'%'
      +' | P50: '+(p.p50Mmboe||'?')+' MMboe'
      +' | Charge: '+Math.round((p.chargeRisk||0)*100)+'%'
      +' | Reservoir: '+Math.round((p.reservoirRisk||0)*100)+'%'
      +' | Seal: '+Math.round((p.sealRisk||0)*100)+'%'
      +' | Trap: '+Math.round((p.trapRisk||0)*100)+'%'
      +' | Est.DrillCost: ~$'+drillCostM+'M'
      +' | EMV: ~$'+Math.round(emv)+'M'
      +' | PS: '+(ps?ps.name:'?')
  }).join('\n');

  var sysP = 'You are an expert exploration portfolio manager. Rank prospects and provide written drill rationale. Use <b> for prospect names. Use <span style="color:#10B981"> for top picks, <span style="color:#EF4444"> for high-risk/low-value. Close all spans. Be specific with numbers.';
  var userP = 'PROSPECT DATA:\n'+prospectData
    +'\n\nRANKING CRITERION: '+rankBy
    +'\nBUDGET CONSTRAINT: $'+budget+'M total'
    +'\n\nProvide:\n1. A ranked drill list (1st = highest priority) with 2-sentence rationale per prospect\n2. Portfolio summary: total risked resource, budget allocation, risk diversification\n3. Top recommendation with strongest case\n4. One prospect to avoid and why\n\nFormat clearly with prospect names as headers.';

  var reply = await _hubAICall(sysP, userP, 1200);
  if(!reply){out.innerHTML='<div style="padding:32px;text-align:center;color:var(--t3)">AI unavailable — check API key in Settings.</div>';return;}

  out.innerHTML = '<div style="font-size:10px;line-height:1.7;color:var(--t1)">'
    +'<div style="display:flex;align-items:center;gap:8px;margin-bottom:14px;padding:10px;background:rgba(107,70,193,.06);border:1px solid rgba(0,200,255,.2);border-radius:6px">'
    +'<span style="font-size:18px"></span>'
    +'<div><b style="color:var(--t1)">Prospect Ranking Copilot</b> · '
    +prospects.length+' prospects · ranked by '+rankBy+' · budget $'+budget+'M</div></div>'
    +'<p style="margin:0">'+_mdToHtml(reply)+'</p></div>';
}

// 
//  3. EXPLORATION INTEL NEWS FEED
// 
function hubNewsFeedInit() {
  var sel = document.getElementById('news-basin');
  if(sel && sel.options.length===1){
    (window.BASINS||[]).forEach(function(b){
      var o=document.createElement('option');o.value=b.name;o.textContent=b.name;sel.appendChild(o);
    });
  }
}

async function hubNewsFeedRun() {
  var out = document.getElementById('newsfeed-output'); if(!out) return;
  var basin = (document.getElementById('news-basin')||{}).value||'all';
  var topic = (document.getElementById('news-topic')||{}).value||'all';
  _hubAiLoading(out,'Searching exploration intelligence…');

  var basinCtx = basin==='all'
    ? 'all basins in our portfolio: '+(window.BASINS||[]).map(function(b){return b.name;}).join(', ')
    : basin;
  var topicCtx = topic==='all'?'all exploration topics':topic;

  var sysP = 'You are an expert exploration intelligence analyst. Provide realistic, technically grounded exploration news summaries. '
    +'Format each news item as: **[HEADLINE]** followed by 2-3 sentence summary with key data points (volumes, dates, operators, well names). '
    +'Mark sentiment:  positive,  negative,  neutral. Use <b> for company and basin names. '
    +'Base all responses on realistic scenarios consistent with the basin geology described. Do not fabricate specific company announcements.';

  var userP = 'Generate 6 realistic recent exploration intelligence items for: '+basinCtx
    +'\nTopic focus: '+topicCtx
    +'\nBasin context: '+(window.BASINS||[]).filter(function(b){return basin==='all'||b.name===basin;})
      .map(function(b){return b.name+' ('+b.region+', '+b.hc+', score '+b.score+')';}).join('; ')
    +'\n\nFor each item include: sentiment indicator, headline, 2-3 sentence summary, relevance to portfolio. '
    +'Make the intelligence actionable and specific to the basin geology.';

  var reply = await _hubAICall(sysP, userP, 1000);
  if(!reply){out.innerHTML='<div style="padding:32px;text-align:center;color:var(--t3)">AI unavailable — check API key in Settings.</div>';return;}

  out.innerHTML = '<div style="font-size:10px;line-height:1.7;color:var(--t1)">'
    +'<div style="display:flex;align-items:center;gap:8px;margin-bottom:14px;padding:10px;background:rgba(107,70,193,.06);border:1px solid rgba(0,200,255,.2);border-radius:6px">'
    +'<span style="font-size:18px"></span>'
    +'<div><b style="color:var(--t1)">Exploration Intelligence Feed</b> · '+(basin==='all'?'All Basins':basin)+' · '+topicCtx+'</div>'
    +'<span style="margin-left:auto;font-size:8px;color:var(--t3)">AI-generated · not real news</span></div>'
    +'<p style="margin:0">'+_mdToHtml(reply)+'</p></div>';
}

// 
//  4. FISCAL REGIME & NPV
// 
function hubFiscalInit() {
  var sel = document.getElementById('fiscal-asset');
  if(!sel||sel.options.length>0) return;
  (window.DISCOVERIES||[]).forEach(function(d){
    var o=document.createElement('option');o.value=d.id;o.textContent=d.name;sel.appendChild(o);
  });
  (window.PROSPECTS||[]).forEach(function(p){
    var o=document.createElement('option');o.value='pr-'+p.id;o.textContent=p.name+' (Prospect)';sel.appendChild(o);
  });
  if(sel.options.length>0) hubFiscalRender();
}

function hubFiscalRender() {
  var out = document.getElementById('fiscal-output'); if(!out) return;
  var assetId = (document.getElementById('fiscal-asset')||{}).value;
  if(!assetId){out.innerHTML='<div style="padding:32px;text-align:center;color:var(--t3)">Select an asset</div>';return;}

  var fiscalType = (document.getElementById('fiscal-type')||{}).value||'psc';
  var pLow  = parseFloat((document.getElementById('fiscal-p-low')||{}).value||40);
  var pBase = parseFloat((document.getElementById('fiscal-p-base')||{}).value||70);
  var pHigh = parseFloat((document.getElementById('fiscal-p-high')||{}).value||100);
  var disc  = parseFloat((document.getElementById('fiscal-discount')||{}).value||10)/100;
  var govtTake = parseFloat((document.getElementById('fiscal-govt-take')||{}).value||65)/100;

  var disc2 = (window.DISCOVERIES||[]).find(function(d){return d.id===assetId;});
  var pros  = null;
  if(!disc2 && assetId.startsWith('pr-')){
    pros = (window.PROSPECTS||[]).find(function(p){return 'pr-'+p.id===assetId;});
  }

  var eurMmboe = disc2?(disc2.eurMmboe||0):((pros?(pros.p50Mmboe||0):0)*(pros?pros.gcos||0.5:0.5));
  var name     = disc2?disc2.name:(pros?pros.name:'?');
  var devCost  = eurMmboe*8; // rough $/boe dev cost * volume in M

  function npv(price, eur, devCostM, discRate, gTake) {
    // Very simplified: revenue stream over 15 years, declining 12% pa
    var annualEur = eur/15; // MMboe/year
    var npvVal = 0;
    for(var y=1;y<=15;y++){
      var prod = annualEur * Math.pow(0.88,y-1);
      var rev  = prod * price * 1e6;      // $ (price per bbl, 1 MMboe ≈ 1 MMbbl equiv)
      var opex = prod * 8 * 1e6;          // $8/boe opex
      var cashflow = (rev - opex) * (1 - gTake);
      if(y<=3) cashflow -= devCostM*1e6/3; // spread dev cost over 3 years
      npvVal += cashflow / Math.pow(1+discRate, y);
    }
    return npvVal/1e6; // US$M
  }

  var scenarios = [
    {label:'Low',  price:pLow,  col:'#EF4444'},
    {label:'Base', price:pBase, col:'#F59E0B'},
    {label:'High', price:pHigh, col:'#10B981'},
  ];

  var npvs = scenarios.map(function(s){return {s:s, val:Math.round(npv(s.price,eurMmboe,devCost,disc,govtTake))};});
  var bePrice = Math.round(devCost*8/((1-govtTake)*eurMmboe*15*0.55)); // rough breakeven

  var fiscalLabels = {psc:'Production Sharing Contract',royalty:'Royalty/Tax',concession:'Concession'};

  var html = '<div style="font-size:10px;color:var(--t1)">';
  // Header
  html += '<div style="display:flex;align-items:center;gap:8px;margin-bottom:14px;padding:10px;background:rgba(245,158,11,.06);border:1px solid rgba(245,158,11,.2);border-radius:6px">'
    +'<span style="font-size:18px"></span>'
    +'<div><b>'+name+'</b> · '+fiscalLabels[fiscalType]+'<br>'
    +'<span style="color:var(--t3);font-size:8.5px">EUR: '+eurMmboe.toFixed(1)+' MMboe · Dev Cost: ~$'+Math.round(devCost)+'M · Disc: '+(disc*100)+'% · Govt Take: '+(govtTake*100)+'%</span></div></div>';

  // NPV scenario table
  html += '<div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:8px;margin-bottom:14px">';
  npvs.forEach(function(n){
    html += '<div style="background:var(--bg2);border-radius:7px;padding:12px;text-align:center;border:1px solid var(--b1)">'
      +'<div style="font-size:8px;color:var(--t3);margin-bottom:4px">'+n.s.label+' ($'+n.s.price+(window._appHCType==="Gas"?"/MMBtu":"/bbl")+')</div>'
      +'<div style="font-size:18px;font-weight:800;color:'+n.s.col+'">'+(n.val>=0?'$'+n.val.toLocaleString()+'M':'($'+Math.abs(n.val).toLocaleString()+'M)')+'</div>'
      +'<div style="font-size:8px;color:var(--t3);margin-top:2px">NPV10 (post-govt)</div></div>';
  });
  html += '</div>';

  // Breakeven bar
  html += '<div style="margin-bottom:12px;background:var(--bg2);border-radius:6px;padding:10px">'
    +'<div style="font-size:10px;color:var(--t3);margin-bottom:6px">BREAKEVEN PRICE</div>'
    +'<div style="font-size:22px;font-weight:800;color:'+(bePrice<60?'#10B981':bePrice<80?'#F59E0B':'#EF4444')+'">'
    +'$'+bePrice+(window._appHCType==="Gas"?"/MMBtu":"/bbl")+'</div>'
    +'<div style="font-size:8.5px;color:var(--t3);margin-top:3px">'+(bePrice<60?'Competitive':bePrice<80?'Moderate':'High cost — needs high oil price')+'</div></div>';

  // Govt take decomposition
  html += '<div style="background:var(--bg2);border-radius:6px;padding:10px">'
    +'<div style="font-size:10px;font-weight:700;color:var(--t1);margin-bottom:8px">VALUE SPLIT — '+fiscalLabels[fiscalType].toUpperCase()+'</div>';
  var opShare = (1-govtTake)*0.85;
  var gShare  = govtTake;
  var reinvest= (1-govtTake)*0.15;
  [[' Govt Take',gShare,'#7C3AED'],['Operator Net',opShare,'#10B981'],['Reinvestment',reinvest,'#F59E0B']].forEach(function(row){
    var pct=Math.round(row[1]*100);
    html += '<div style="display:flex;align-items:center;gap:8px;margin-bottom:5px">'
      +'<div style="font-size:10px;color:var(--t2);min-width:90px">'+row[0]+'</div>'
      +'<div style="flex:1;background:var(--bg1);border-radius:3px;height:8px">'
      +'<div style="width:'+pct+'%;background:'+row[2]+';border-radius:3px;height:100%"></div></div>'
      +'<div style="font-size:10px;font-weight:700;color:'+row[2]+';min-width:30px;text-align:right">'+pct+'%</div></div>';
  });
  html += '</div></div>';

  out.innerHTML = html;
}

